/**
 * The Tail's eyes (docs: the user's pitch, Oct 2026): what a car being followed can see of the car following
 * it. Pure and headless, so the gate (npm run tail) drives exactly what the game does.
 *
 * It is the police's sight cone (game/policeBeat.ts) turned round. A patrol car looks ahead for the player; a
 * tail's target looks back, in its mirrors: a fan from its back bumper pointing the way it has come, cast
 * over the tiles ray by ray so a building, a hill or a bend in the street cuts it short exactly as it cuts a
 * patrol car's. Nothing draws it (the user: "do not actually render the backwards looking mirror cone"); the
 * player reads it from the warnings instead — the meter, the edge of the screen, the target glancing.
 *
 * Sitting in the mirror fills a suspicion meter, faster the closer you are (on the bumper, a few seconds; at
 * the far end of the mirror, half a minute); out of it, the meter drains. Two things the player does change
 * the mirror's size: the horn makes it far bigger for a few seconds (nobody fails to look round at a horn),
 * and running with the headlamps off after dark shrinks it to a little over half (one more pair of lights in
 * the mirror at night is the only thing a driver has to go on). By day the lamps barely matter.
 *
 * Besides the mirror: the windscreen sees a little way ahead (a target that doubles back meets you face on),
 * and a car right alongside is noticed through the side window. Another vehicle between the two hides the
 * follower well — keeping a van between you is how it is done.
 */
import { blocksSight, castCone, coneHas, type ConeShape } from '../policeBeat';
import type { World } from '../../world/tiles';

const DEG = Math.PI / 180;

/** The mirror's fan at rest: reach in tiles, half-angle, rays, how much the test forgives, and the warning band. */
export const MIRROR: ConeShape = { range: 9, half: 24 * DEG, rays: 13, shrink: 0.95, warn: 2.5 };
/** The windscreen's: short, since a driver watches the road ahead rather than the cars on it. */
export const SCREEN: ConeShape = { range: 5, half: 34 * DEG, rays: 11, shrink: 0.95, warn: 1 };

export const TAIL = {
  /** The horn: seconds it lasts, and how far and how wide it stretches the mirror at its loudest. */
  horn: { secs: 4, range: 1.7, half: 1.35 },
  /**
   * The headlamps: the mirror's reach with them off at full dark (`off`) and by day (`offDay`), and with them
   * on at full dark (`on`) — lit, a follower is easier to see at night than by day.
   */
  lamps: { off: 0.55, offDay: 0.9, on: 1.15 },
  /** A target pulled over to check its tail: its mirror reaches further and it watches harder. */
  check: { range: 1.25, rate: 1.4 },
  /**
   * Suspicion a second in the mirror: `base` at its far edge, up to base + close on the bumper (on the square
   * of how far in). The windscreen sees at `front` of that; right alongside (`sideR` tiles) fills at `side`.
   */
  rate: { base: 0.035, close: 0.6, front: 0.6, side: 0.28, sideR: 2.4 },
  /** Another vehicle between the two: the rate is cut to this. */
  cover: 0.35,
  /**
   * Which way the follower is going counts: a car in the mirror going the target's way is a tail; one going
   * the other way (passed on a doubling back) is just traffic, `oncoming` of the rate; one standing still,
   * `parked`. Anything moving slower than `moving` tiles a second is standing.
   */
  heading: { oncoming: 0.12, parked: 0.6, moving: 0.3 },
  /** Drained a second out of sight. */
  decay: 0.07,
  /** The target starts to glance in its mirror, and the big warning comes up. */
  glance: 0.35, warn: 0.65,
  /**
   * Lost: further than `far` tiles, or out of its sight line for `unseen` seconds while more than `near` away;
   * the hints come up at `warn` tiles and `unseenWarn` seconds.
   */
  lost: { far: 48, warn: 30, near: 14, unseen: 18, unseenWarn: 6, farSecs: 3 },
  /** Made, it bolts: on its bumper (`catchR`) for `catchSecs` seconds all told pulls it over; `escape` tiles back, it is gone. */
  bolt: { catchR: 3.2, catchSecs: 3.5, escape: 42, escapeSecs: 5 },
};

/** The mirror's shape now: the horn (`horn` 0–1 of it still ringing), the lamps and how dark it is, and a target pulled over. */
export function mirrorOf(dark: number, lightsOff: boolean, horn: number, checking: boolean, base: ConeShape = MIRROR): ConeShape {
  const d = Math.max(0, Math.min(1, dark));
  const lamps = lightsOff ? TAIL.lamps.offDay + (TAIL.lamps.off - TAIL.lamps.offDay) * d : 1 + (TAIL.lamps.on - 1) * d;
  const h = Math.max(0, Math.min(1, horn));
  const range = base.range * lamps * (1 + (TAIL.horn.range - 1) * h) * (checking ? TAIL.check.range : 1);
  const half = Math.min(80 * DEG, base.half * (1 + (TAIL.horn.half - 1) * h));
  return { ...base, range, half };
}

/** Can an eye at (ax, az, height ay) see the point (bx, bz) across w's tiles (and past its edge, into the cells beside)? */
export function seesLine(w: World, ax: number, az: number, ay: number, bx: number, bz: number): boolean {
  const dx = bx - ax, dz = bz - az, d = Math.hypot(dx, dz);
  if (d < 0.6) return true;
  const n = Math.ceil(d / 0.25);
  // the last half tile is the other car itself
  for (let k = 1; k < n - 1; k++) {
    const f = k / n;
    if (blocksSight(w, ax + dx * f, az + dz * f, ay)) return false;
  }
  return true;
}

/** Is something standing between a and b (within 0.45 of the line, and not at either end)? */
export function covered(ax: number, az: number, bx: number, bz: number, others: { x: number; z: number }[]): boolean {
  const dx = bx - ax, dz = bz - az, L2 = dx * dx + dz * dz;
  if (L2 < 1) return false;
  for (const o of others) {
    const t = ((o.x - ax) * dx + (o.z - az) * dz) / L2;
    if (t < 0.12 || t > 0.88) continue;
    const px = ax + dx * t - o.x, pz = az + dz * t - o.z;
    if (px * px + pz * pz < 0.45 * 0.45) return true;
  }
  return false;
}

/** One cone's say: where the point stands against it, and how fast it fills the meter (`mul` on the mirror's own rate). */
export function coneRate(w: World, ox: number, oz: number, oy: number, dir: number, shape: ConeShape, lens: Float32Array,
  px: number, pz: number, mul: number): { at: 'in' | 'near' | 'out'; rate: number; d: number } {
  const d = Math.hypot(px - ox, pz - oz);
  if (d > shape.range + shape.warn + 0.5) return { at: 'out', rate: 0, d };
  castCone(w, ox, oz, oy, dir, lens, shape);
  const at = coneHas(lens, ox, oz, dir, px, pz, shape);
  if (at !== 'in') return { at, rate: 0, d };
  const inward = Math.max(0, 1 - d / shape.range);
  return { at, rate: (TAIL.rate.base + TAIL.rate.close * inward * inward) * mul, d };
}

/** Where the follower stands to the target this moment. */
export type Seen = 'mirror' | 'screen' | 'side' | 'edge' | 'out';

interface CarEyes {
  /** The target, in w's frame: its middle, its height, which way it faces, and half its length. */
  w: World; x: number; z: number; y: number; heading: number; halfLen: number;
  /** The follower, in the same frame, which way it faces and how fast it is going. */
  px: number; pz: number; ph: number; pv: number;
  dark: number; lightsOff: boolean; horn: number; checking: boolean;
  /** Other vehicles about, in the same frame, for cover. */
  others: { x: number; z: number }[];
}

/**
 * How a car target sees its follower this moment: the suspicion a second it adds (0 when it can't see them),
 * where they stand (in its mirror, its windscreen, alongside, at the mirror's edge, or not at all), how far
 * from its back bumper, and the mirror's shape (for the warnings and the gate).
 */
export function carSight(e: CarEyes, lens: Float32Array): { rate: number; seen: Seen; d: number; mirror: ConeShape } {
  const mirror = mirrorOf(e.dark, e.lightsOff, e.horn, e.checking);
  const fx = Math.sin(e.heading), fz = Math.cos(e.heading);
  const eye = e.y + 0.3;
  const bx = e.x - fx * e.halfLen, bz = e.z - fz * e.halfLen;
  const nx = e.x + fx * e.halfLen, nz = e.z + fz * e.halfLen;
  const hide = covered(bx, bz, e.px, e.pz, e.others) ? TAIL.cover : 1;
  const watch = e.checking ? TAIL.check.rate : 1;
  const back = coneRate(e.w, bx, bz, eye, e.heading + Math.PI, mirror, lens, e.px, e.pz, watch * hide * followsBy(e));
  if (back.at === 'in') return { rate: back.rate, seen: 'mirror', d: back.d, mirror };
  const front = coneRate(e.w, nx, nz, eye, e.heading, SCREEN, lens, e.px, e.pz, TAIL.rate.front * hide);
  if (front.at === 'in') return { rate: front.rate, seen: 'screen', d: back.d, mirror };
  const mid = Math.hypot(e.px - e.x, e.pz - e.z);
  if (mid < TAIL.rate.sideR && seesLine(e.w, e.x, e.z, eye, e.px, e.pz)) return { rate: TAIL.rate.side * watch, seen: 'side', d: back.d, mirror };
  return { rate: 0, seen: back.at === 'near' ? 'edge' : 'out', d: back.d, mirror };
}

/**
 * How much like a tail the follower looks by its heading: 1 going the target's way, falling to
 * TAIL.heading.oncoming going the other way, TAIL.heading.parked standing still.
 */
export function followsBy(e: { heading: number; ph: number; pv: number }, parked: number = TAIL.heading.parked): number {
  const H = TAIL.heading;
  if (Math.abs(e.pv) < H.moving) return parked;
  const a = Math.cos(e.ph - e.heading) * Math.sign(e.pv);
  return a <= 0 ? H.oncoming : H.oncoming + (1 - H.oncoming) * a;
}

/** The meter after a frame: filled at `rate`, or drained when nothing is seen. */
export function stepSuspicion(s: number, rate: number, dt: number): number {
  return Math.max(0, Math.min(1, rate > 0 ? s + rate * dt : s - TAIL.decay * dt));
}
