/**
 * Manifests (docs/manifests.html): the order a driver collects and drops several loads in. A run is
 * a list of calls — pickups and drops interleaved — built by cheapest insertion over the loads the
 * driver was already choosing between, then improved by a bounded or-opt pass. The order is solved
 * for money, not distance: every load aboard loses value by the second, so the clever round is
 * rarely the shortest one.
 *
 * Pure functions over plain numbers: no THREE, no world, nothing written. scripts/manifest.ts solves
 * thousands of synthetic boards through here and asserts the invariants.
 */

/** Most calls in a run: six loads (a big hold's, orders.ts holdLoads), a pickup and a drop each. */
export const MAX_STOPS = 12;
/** Dollars a tile of extra driving an insertion must beat, times the driver's cut. */
const DETOUR_COST = 1.2;
/** A tile of driving costs this much when the or-opt pass weighs one order against another (orders.ts's DRIVE_COST). */
export const DRIVE_COST = 0.8;
/** Most a load may add to the run's length, as a share of the run so far. */
const DETOUR_CAP = 0.4;
/** DETOUR_CAP for a roomy hold (Limits.roomy): a big hold may run on further to fill. */
const ROOMY_CAP = 0.7;
/** Tiles from a drop already planned within which a new load's drop counts as the same place (alignment 1). */
const NEAR_DROP = 12;
/** Off what an added load must pay a tile, at alignment 1; and on it, at alignment -1. */
const FAVOUR = 0.35, OPPOSE = 1;
/** How far alignment stretches (1) or shrinks (-1) the most a load may add to the run. */
const BEND = 0.9;
/** Alignment from which a load is tried before the picker's better-paying ones. */
const FAVOURED = 0.5;
/** A load never falls below this share of what it was worth (cargo.ts's VALUE_FLOOR). */
export const VALUE_FLOOR = 0.35;
/** Seconds each call takes: pulling up, loading, pulling away (fit.ts's STOP_SECONDS). */
export const STOP_SECONDS = 8;
/** A road never runs straight (fit.ts's WANDER). */
export const WANDER = 1.25;
/** Or-opt passes at most. */
const PASSES = 3;

/** A load as the solver sees it: where it is collected and dropped, in world tiles, and what it pays. */
export interface Load {
  id: number;
  /** Where the goods wait (ignored for a load already aboard). */
  px: number; pz: number;
  /** Where they go. */
  dx: number; dz: number;
  units: number;
  /** What it pays now, and the value its decay is measured against. */
  value: number; value0: number;
  /** Share of value0 lost a second once aboard. */
  decay: number;
  /** The towns' levy on it, as a share. */
  tax: number;
  /** Seconds left to collect it; Infinity for no limit. */
  ttl: number;
  aboard?: boolean;
}

export interface Call { kind: 'pickup' | 'drop'; load: Load }

export interface Limits {
  /** Units the hold takes, and how many are filled before the first call. */
  capacity: number; used: number;
  /** Most loads in the run, aboard ones included. */
  maxLoads: number;
  /** Tiles a second the vehicle really averages. */
  pace: number;
  /** The player's share of every delivery. */
  cut: number;
  /**
   * A big hold (orders.ts holdLoads): a load added to the run need only pay for the driving it adds
   * (DRIVE_COST a tile), not DETOUR_COST, so the hold fills along one run instead of going out half empty.
   */
  roomy?: boolean;
}

export interface Plan {
  calls: Call[];
  /** What the run pays the player after decay, the levy and the cut. */
  net: number;
  tiles: number;
  seconds: number;
  /** Seconds from the start to each call; units aboard after it; what each drop pays (0 at a pickup, before the cut). */
  eta: number[];
  held: number[];
  pays: number[];
}

type Pt = { x: number; z: number };

const at = (c: Call): Pt => (c.kind === 'pickup' ? { x: c.load.px, z: c.load.pz } : { x: c.load.dx, z: c.load.dz });

/** What a load pays at the drop after `rode` seconds aboard. */
export function valueAfter(l: Load, rode: number): number {
  return Math.max(l.value0 * VALUE_FLOOR, l.value - l.value0 * l.decay * Math.max(0, rode));
}

/**
 * Walk a sequence of calls from `start`: its money, its length, and whether it is legal — every
 * pickup before its drop, nothing collected after its limit runs out, the hold never over.
 */
export function evaluate(start: Pt, calls: Call[], lim: Limits): Plan | null {
  let x = start.x, z = start.z, t = 0, tiles = 0, used = lim.used, net = 0;
  const picked = new Map<number, number>();
  const eta: number[] = [], held: number[] = [], pays: number[] = [];
  for (const c of calls) {
    const p = at(c);
    const d = Math.hypot(p.x - x, p.z - z) * WANDER;
    tiles += d;
    t += d / Math.max(0.05, lim.pace);
    x = p.x; z = p.z;
    const l = c.load;
    if (c.kind === 'pickup') {
      if (l.aboard || picked.has(l.id) || t > l.ttl) return null;
      used += l.units;
      if (used > lim.capacity) return null;
      picked.set(l.id, t);
      pays.push(0);
    } else {
      const from = l.aboard ? 0 : picked.get(l.id);
      if (from === undefined) return null;
      picked.delete(l.id);
      used -= l.units;
      const v = valueAfter(l, t - from);
      pays.push(v * (1 - l.tax));
      net += v * (1 - l.tax) * lim.cut;
    }
    eta.push(t);
    held.push(used);
    t += STOP_SECONDS;
  }
  // a pickup with no drop is no run at all
  if (picked.size) return null;
  return { calls, net, tiles, seconds: t, eta, held, pays };
}

/** What the or-opt pass maximises: the money, less a little for every tile, so a tie goes to the shorter round. */
const worth = (p: Plan, lim: Limits): number => p.net - DRIVE_COST * p.tiles * lim.cut;

const loadsIn = (calls: Call[]): number => new Set(calls.map((c) => c.load.id)).size;

/** Every legal place for a new load's pickup and drop in `calls`, the best by net; `from` is the first position it may go. */
function bestInsertion(start: Pt, calls: Call[], l: Load, lim: Limits, from: number): Plan | null {
  let best: Plan | null = null;
  for (let i = from; i <= calls.length; i++) {
    for (let j = i; j <= calls.length; j++) {
      const next = [...calls.slice(0, i), { kind: 'pickup' as const, load: l }, ...calls.slice(i, j), { kind: 'drop' as const, load: l }, ...calls.slice(j)];
      const p = evaluate(start, next, lim);
      if (p && (!best || p.net - DRIVE_COST * p.tiles * lim.cut > best.net - DRIVE_COST * best.tiles * lim.cut)) best = p;
    }
  }
  return best;
}

/** Take each call in turn and try it everywhere else, keeping any move that pays; `fixed` calls at the front stay put. */
function orOpt(start: Pt, plan: Plan, lim: Limits, fixed = 0): Plan {
  let cur = plan;
  for (let pass = 0; pass < PASSES; pass++) {
    let better = false;
    for (let i = fixed; i < cur.calls.length; i++) {
      const c = cur.calls[i];
      const rest = [...cur.calls.slice(0, i), ...cur.calls.slice(i + 1)];
      for (let j = fixed; j <= rest.length; j++) {
        if (j === i) continue;
        const p = evaluate(start, [...rest.slice(0, j), c, ...rest.slice(j)], lim);
        if (p && worth(p, lim) > worth(cur, lim) + 1e-6) { cur = p; better = true; break; }
      }
    }
    if (!better) break;
  }
  return cur;
}

interface SolveOpts {
  /** May this load be taken at all (every leg routes)? Asked only of a load about to be accepted. */
  ok?: (l: Load) => boolean;
  /** Calls already fixed in place at the front (a run under way): nothing is inserted before them. */
  fixed?: number;
  /** New loads go on the end only: an ace's top-up, which delays nothing already aboard. */
  tail?: boolean;
}

/**
 * Which way a load goes against the run (Oct 2026): 1 for a drop within NEAR_DROP of one already planned,
 * else how well it heads the run's way — from `start` to the middle of the drops planned — from 1 straight
 * on to -1 straight back. Half of it is where the load is dropped, seen from the start, and half the way
 * the load itself travels; going back counts in full only as far back as the run goes forward, so a short
 * hop the wrong way costs little. 0 for a run with no drops yet.
 */
export function alignment(start: Pt, calls: Call[], l: Load): number {
  return alignOf(start, calls)(l);
}

/** alignment against one run, its way worked out once for every load put to it. */
function alignOf(start: Pt, calls: Call[]): (l: Load) => number {
  const drops = calls.filter((c) => c.kind === 'drop').map((c) => c.load);
  if (!drops.length) return () => 0;
  const hx = drops.reduce((s, d) => s + d.dx, 0) / drops.length - start.x;
  const hz = drops.reduce((s, d) => s + d.dz, 0) / drops.length - start.z;
  const h = Math.hypot(hx, hz);
  const way = (x: number, z: number): number => {
    const t = Math.hypot(x, z);
    if (t < 1) return 0;
    const cos = (hx * x + hz * z) / (h * t);
    return cos >= 0 ? cos : cos * Math.min(1, t / h);
  };
  return (l) => {
    if (drops.some((d) => Math.hypot(d.dx - l.dx, d.dz - l.dz) <= NEAR_DROP)) return 1;
    if (h < 1) return 0;
    return 0.5 * way(l.dx - start.x, l.dz - start.z) + 0.5 * way(l.dx - l.px, l.dz - l.pz);
  };
}

/**
 * The run: start with `calls` (the drops of what is already aboard, or a run under way) and insert
 * candidates in the picker's order, best first — except that once the run has somewhere to go, a load
 * heading its way is tried before the rest — each where it pays most. The first load of an empty run is
 * taken as the picker would take it alone, so a manifest is never worse than a single load; every one
 * after must pay DETOUR_COST a tile of the driving it adds (a roomy hold DRIVE_COST), and may not grow the
 * run by more than DETOUR_CAP (ROOMY_CAP). Both bend with the load's alignment: one heading the run's way
 * pays up to FAVOUR less a tile (never under DRIVE_COST) and may add BEND more; one heading back pays up
 * to OPPOSE more and may add BEND less. Returns null only when there is nothing to do at all.
 */
export function solveRun(start: Pt, calls: Call[], cands: Load[], lim: Limits, opts: SolveOpts = {}): Plan | null {
  const fixed = opts.fixed ?? 0;
  let plan = evaluate(start, calls, lim);
  if (!plan) return null;
  const maxLoads = Math.min(lim.maxLoads, MAX_STOPS / 2);
  const left = [...cands];
  while (left.length) {
    if (loadsIn(plan.calls) >= maxLoads || plan.calls.length + 2 > MAX_STOPS) break;
    // once the run has somewhere to go, a load heading its way is tried before the picker's next
    const align = alignOf(start, plan.calls);
    const k = plan.calls.length ? left.findIndex((c) => align(c) >= FAVOURED) : -1;
    const l = left.splice(Math.max(0, k), 1)[0];
    if (plan.calls.some((c) => c.load.id === l.id)) continue;
    const from = opts.tail ? plan.calls.length : fixed;
    const next = bestInsertion(start, plan.calls, l, lim, from);
    if (!next) continue;
    if (plan.calls.length) {
      const gain = next.net - plan.net, added = next.tiles - plan.tiles;
      const a = align(l);
      const cost = Math.max(DRIVE_COST, (lim.roomy ? DRIVE_COST : DETOUR_COST) * (a >= 0 ? 1 - FAVOUR * a : 1 - OPPOSE * a));
      if (gain <= cost * added * lim.cut) continue;
      if (added >= (lim.roomy ? ROOMY_CAP : DETOUR_CAP) * (1 + BEND * a) * Math.max(1, plan.tiles)) continue;
    }
    if (opts.ok && !opts.ok(l)) continue;
    plan = next;
  }
  if (!plan.calls.length) return null;
  return opts.tail ? plan : orOpt(start, plan, lim, fixed);
}

/**
 * The player's own hold: the order to drop it in. Loads bound for the same place are one call.
 * Returns, for every load, which drop it is in the suggested order (1 first).
 */
export function solveOrder(start: Pt, hold: Load[], pace: number): Map<number, number> {
  const out = new Map<number, number>();
  if (!hold.length) return out;
  // one call a destination, carrying everything bound there
  const groups = new Map<string, Load[]>();
  for (const l of hold) {
    const k = `${l.dx.toFixed(2)},${l.dz.toFixed(2)}`;
    const g = groups.get(k);
    if (g) g.push(l);
    else groups.set(k, [l]);
  }
  const keys = [...groups.keys()];
  // each destination as one load aboard: its value and decay are its loads' summed
  const merged: Load[] = keys.map((k, n) => {
    const g = groups.get(k)!;
    return {
      id: n, px: 0, pz: 0, dx: g[0].dx, dz: g[0].dz, units: 0, aboard: true, ttl: Infinity, tax: 0,
      value: g.reduce((s, l) => s + l.value, 0), value0: g.reduce((s, l) => s + l.value0, 0),
      // decay a second in dollars, re-expressed against the summed value0 so valueAfter reads it right
      decay: g.reduce((s, l) => s + l.value0 * l.decay, 0) / Math.max(1e-9, g.reduce((s, l) => s + l.value0, 0)),
    };
  });
  // nearest first to start from, then or-opt for the money
  const left = [...merged], seq: Call[] = [];
  let x = start.x, z = start.z;
  while (left.length) {
    let k = 0;
    for (let i = 1; i < left.length; i++) if (Math.hypot(left[i].dx - x, left[i].dz - z) < Math.hypot(left[k].dx - x, left[k].dz - z)) k = i;
    const l = left.splice(k, 1)[0];
    seq.push({ kind: 'drop', load: l });
    x = l.dx; z = l.dz;
  }
  const lim: Limits = { capacity: Infinity, used: 0, maxLoads: Infinity, pace, cut: 1 };
  const plan = evaluate(start, seq, lim);
  const best = plan ? orOpt(start, plan, lim) : null;
  const order = best ? best.calls : seq;
  order.forEach((c, n) => { for (const l of groups.get(keys[c.load.id])!) out.set(l.id, n + 1); });
  return out;
}
