import { TRACKS, type Loop, type Soundtrack } from './music';
import { el } from '../util/dom';

const fmt = (s: number): string => {
  if (!Number.isFinite(s) || s < 0) return '0:00';
  const m = Math.floor(s / 60), r = Math.floor(s % 60);
  return `${m}:${String(r).padStart(2, '0')}`;
};

/** Line icons for the two mode buttons, drawn in the button's own colour. */
const svg = (d: string): string =>
  `<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${d}</svg>`;
const REPEAT_ICON = svg('<path d="M17 2l4 4-4 4"/><path d="M3 11V10a4 4 0 0 1 4-4h14"/><path d="M7 22l-4-4 4-4"/><path d="M21 13v1a4 4 0 0 1-4 4H3"/>');
const SHUFFLE_ICON = svg('<path d="M16 3h5v5"/><path d="M4 20L21 3"/><path d="M21 16v5h-5"/><path d="M15 15l6 6"/><path d="M4 4l5 5"/>');
const LOOP_TIP: Record<Loop, string> = {
  none: 'Loop off: stops after the last track',
  all: 'Loop all: back to the first track after the last',
  one: 'Loop one: repeats this track',
};

/** A little moving soundwave: bars that rise and fall out of step (the CSS in index.html, `.wave`). */
export const wave = (bars = 5): HTMLElement => {
  const w = el('span', 'wave');
  for (let i = 0; i < bars; i++) w.append(el('i'));
  w.setAttribute('aria-hidden', 'true');
  return w;
};

/**
 * The music player, a window of its own: opened from the equaliser in the top bar, or from Settings.
 * It names what is playing and who made it, and gives the usual controls — back, play and pause,
 * skip, shuffle and loop, a bar to scrub through the track, volume and mute — and the whole
 * playlist, any track of which plays at a click.
 */
export class MusicWindow {
  isOpen = false;
  private el = document.getElementById('music')!;
  private btn = document.getElementById('musicbtn');
  private nowCard = el('div', 'nowplaying');
  private title = el('div', 'np-title');
  private artist = el('div', 'np-artist');
  private count = el('div', 'np-count');
  private bar = el('div', 'bar');
  private fill = el('i');
  private elapsed = el('span');
  private length = el('span');
  private playBtn = el('button', 'ctl big');
  private muteBtn = el('button', 'ctl');
  private volume = el('input', 'vol');
  private volLabel = el('span', 'vol-n');
  private shuffleBtn = el('button', 'ctl mode');
  private loopBtn = el('button', 'ctl mode');
  private rows: HTMLButtonElement[] = [];
  private scrubbing = false;

  constructor(private music: Soundtrack) {
    const panel = el('div', 'panel');
    panel.innerHTML = '<header><h2>Music<span>.</span></h2><div class="keys"><kbd>Esc</kbd> close</div></header>';

    const label = el('div', 'np-label', 'Now playing');
    label.prepend(wave(4));
    this.nowCard.append(label, this.title, this.artist, this.count);

    const time = el('div', 'time');
    this.bar.append(this.fill);
    time.append(this.elapsed, this.bar, this.length);

    const controls = el('div', 'controls');
    const prev = el('button', 'ctl', '⏮');
    const next = el('button', 'ctl', '⏭');
    prev.title = 'Previous (restarts the track if it is more than a few seconds in)';
    next.title = 'Next track';
    prev.setAttribute('aria-label', 'Previous track');
    next.setAttribute('aria-label', 'Next track');
    this.shuffleBtn.innerHTML = SHUFFLE_ICON;
    this.loopBtn.innerHTML = REPEAT_ICON + '<em>1</em>';
    for (const b of [this.shuffleBtn, prev, this.playBtn, next, this.loopBtn, this.muteBtn]) { b.type = 'button'; b.tabIndex = -1; }
    prev.addEventListener('click', () => music.previous());
    next.addEventListener('click', () => music.next());
    this.playBtn.addEventListener('click', () => music.togglePause());
    this.muteBtn.addEventListener('click', () => music.toggleMute());
    this.shuffleBtn.addEventListener('click', () => music.toggleShuffle());
    this.loopBtn.addEventListener('click', () => music.cycleLoop());
    controls.append(this.shuffleBtn, prev, this.playBtn, next, this.loopBtn);

    const vol = el('div', 'volume');
    this.volume.type = 'range';
    this.volume.min = '0';
    this.volume.max = '100';
    this.volume.tabIndex = -1;
    this.volume.addEventListener('input', () => music.setVolume(Number(this.volume.value) / 100));
    vol.append(this.muteBtn, this.volume, this.volLabel);

    // scrub by clicking or dragging along the bar
    const seekAt = (clientX: number) => {
      const r = this.bar.getBoundingClientRect();
      music.seek((clientX - r.left) / r.width);
    };
    this.bar.addEventListener('mousedown', (e) => { this.scrubbing = true; seekAt(e.clientX); e.preventDefault(); });
    window.addEventListener('mousemove', (e) => { if (this.scrubbing) seekAt(e.clientX); });
    window.addEventListener('mouseup', () => { this.scrubbing = false; });

    // the playlist: a click plays that track
    const list = el('div', 'tracks');
    TRACKS.forEach((t, i) => {
      const b = el('button', 'trk');
      b.type = 'button';
      b.tabIndex = -1;
      b.title = `Play ${t.title}`;
      const n = el('span', 'trk-n', String(i + 1).padStart(2, '0'));
      n.append(wave(3));
      b.append(n, el('b', '', t.title), el('span', 'trk-a', t.artist));
      b.addEventListener('click', () => music.choose(i));
      this.rows.push(b);
      list.append(b);
    });

    // the album on Spotify: a plain https link, which the Spotify app picks up where it's installed
    const credit = el('p', 'credit');
    credit.innerHTML = 'Soundtrack by <b>a.o.huge</b> and <b>Attention</b>. ';
    const spotify = el('a', '', 'Save these songs on Spotify here!');
    spotify.href = 'https://open.spotify.com/album/3Un8EPlQ1pWlq0DYydthrJ?si=b6bgoT4-QlmnuzluigtLkA';
    spotify.target = '_blank';
    spotify.rel = 'noopener';
    spotify.tabIndex = -1;
    credit.append(spotify);

    panel.append(this.nowCard, time, controls, vol, el('h3', '', 'Tracks'), list, credit);
    this.el.append(panel);
    this.el.addEventListener('mousedown', (e) => { if (e.target === this.el) this.close(); });
    window.addEventListener('keydown', (e) => {
      if (this.isOpen && e.code === 'Escape') { this.close(); e.preventDefault(); }
    });

    // the equaliser in the top bar: dances while the music plays, opens this window
    if (this.btn) {
      // (the wave is the button's icon, before its label, as the other tool buttons' are)
      this.btn.prepend(wave(4));
      this.btn.addEventListener('click', (e) => {
        this.toggle();
        (e.currentTarget as HTMLElement).blur();
      });
    }
    music.onChange(() => {
      this.syncButton();
      if (this.isOpen) this.sync();
    });
    this.syncButton();
  }

  toggle(): void {
    if (this.isOpen) this.close();
    else this.open();
  }

  open(): void {
    this.isOpen = true;
    this.el.hidden = false;
    this.sync();
  }

  close(): void {
    this.isOpen = false;
    this.el.hidden = true;
    this.scrubbing = false;
    (document.activeElement as HTMLElement | null)?.blur?.();
  }

  private syncButton(): void {
    if (!this.btn) return;
    const m = this.music;
    this.btn.classList.toggle('on', m.playing && !m.muted && m.volume > 0);
    this.btn.title = m.playing ? `Music: ${m.track.title} · ${m.track.artist}` : 'Music (paused)';
  }

  private sync(): void {
    const m = this.music, a = m.audio;
    this.nowCard.classList.toggle('on', m.playing);
    this.title.textContent = m.track.title;
    this.artist.textContent = m.track.artist;
    this.count.textContent = `Track ${m.index + 1} of ${TRACKS.length}`;
    const d = a.duration;
    const t = a.currentTime;
    this.fill.style.width = Number.isFinite(d) && d > 0 ? `${(t / d) * 100}%` : '0%';
    this.elapsed.textContent = fmt(t);
    this.length.textContent = Number.isFinite(d) ? fmt(d) : '–:––';
    this.playBtn.textContent = m.playing ? '⏸' : '▶';
    this.playBtn.title = m.playing ? 'Pause' : 'Play';
    this.muteBtn.textContent = m.muted || m.volume === 0 ? '🔇' : m.volume < 0.4 ? '🔈' : '🔊';
    this.muteBtn.title = m.muted ? 'Unmute' : 'Mute';
    const v = Math.round(m.volume * 100);
    if (document.activeElement !== this.volume) this.volume.value = String(v);
    this.volLabel.textContent = m.muted ? 'muted' : `${v}%`;
    this.shuffleBtn.classList.toggle('on', m.shuffle);
    this.shuffleBtn.setAttribute('aria-pressed', String(m.shuffle));
    this.shuffleBtn.title = m.shuffle ? 'Shuffle on' : 'Shuffle off';
    this.shuffleBtn.setAttribute('aria-label', this.shuffleBtn.title);
    this.loopBtn.dataset.loop = m.loop;
    this.loopBtn.classList.toggle('on', m.loop !== 'none');
    this.loopBtn.title = LOOP_TIP[m.loop];
    this.loopBtn.setAttribute('aria-label', this.loopBtn.title);
    this.rows.forEach((b, i) => {
      b.classList.toggle('cur', i === m.index);
      b.classList.toggle('on', i === m.index && m.playing);
    });
  }
}
