/**
 * The weekly titles on the game's side (docs/social.html, phase 4): who holds each title this week (won last week,
 * worn on the card, the name tag and the Fleets rows) and who leads it as this week stands, asked of the server when
 * the game is up and every two minutes after, and the World tab's two boards for them: This week (the race and the
 * holders) and Lifetime titles (every fleet's titles over all time). The titles themselves are counted on the server
 * (server/titles.ts) from what the dealings ledger and the shared fleets already hear.
 */
import { esc, money } from '../game/cargoHud';
import { chip } from '../game/firmSpec';
import type { OnlineExtra } from './online';
import type { BoardBody } from './worldTab';
import type { BoardRow, CellDoc, ClientMsg, ServerMsg, Welcome } from '../../shared/protocol';
import { TITLES, TITLE_INFO, type TitleId, type TitleRow } from '../../shared/social';

/** Seconds between asks while the game is up. */
const ASK_S = 120;

export interface TitlesHost {
  online(): boolean;
  me(): string | null;
  post(m: ClientMsg): void;
  /** A fleet's livery by a player in it, for the boards' chips. */
  livery(pid: string): { primary: number; accent: number; logo: string } | null;
  /** The titles changed (name tags, cards, the deed). */
  changed(): void;
}

type Lifetime = Extract<ServerMsg, { t: 'titles' }>['lifetime'];

export class Titles implements OnlineExtra {
  live: TitleRow[] = [];
  last: TitleRow[] = [];
  lifetime: Lifetime = [];
  private heard = false;
  private t = 0;

  constructor(private host: TitlesHost) {}

  // ---- the online session ----
  welcome(_w: Welcome): void { this.reset(); }
  cell(_k: string, _doc: CellDoc): void { /* nothing per cell */ }
  got(m: ServerMsg): boolean {
    if (m.t !== 'titles') return false;
    this.live = m.live; this.last = m.last; this.lifetime = m.lifetime;
    this.heard = true;
    this.host.changed();
    return true;
  }
  ready(): void { this.ask(); }
  frame(dt: number): void {
    if (!this.host.online()) return;
    this.t += dt;
    if (this.t >= ASK_S) this.ask();
  }
  forget(): void { /* nothing per cell */ }
  reset(): void { this.live = []; this.last = []; this.lifetime = []; this.heard = false; this.t = 0; }

  ask(): void { this.t = 0; this.host.post({ t: 'titles' }); }

  /** The titles a player wears this week (won last week, by them or their shared fleet). */
  wornBy(pid: string): TitleId[] { return this.last.filter((r) => r.ids.includes(pid)).map((r) => r.id); }
  /** The titles a player leads as this week stands. */
  leading(pid: string): TitleId[] { return this.live.filter((r) => r.ids.includes(pid)).map((r) => r.id); }
  /** The icons of the titles a player wears, for a name tag or a row. */
  icons(pid: string): string { return this.wornBy(pid).map((id) => TITLE_INFO[id].icon).join(''); }

  private amount(id: TitleId, n: number): string { const t = TITLE_INFO[id]; return `${t.money ? money(n) : Math.round(n).toLocaleString('en-US')} ${t.unit}`; }

  private chipOf(pid: string): string {
    const l = this.host.livery(pid);
    return chip([l?.primary ?? 0x7d8a92, l?.accent ?? 0xffffff], l?.logo || undefined);
  }

  /** This week: last week's holders (worn now) and who leads each title so far. */
  readonly week: BoardBody = {
    opened: () => this.ask(),
    tick: () => { /* asked every two minutes */ },
    press: () => false,
    html: () => {
      if (!this.heard) return '<p class="none">Asking the server…</p>';
      const me = this.host.me();
      const rows = TITLES.map((id) => {
        const t = TITLE_INFO[id];
        const held = this.last.find((r) => r.id === id);
        const lead = this.live.find((r) => r.id === id);
        const who = (r: TitleRow | undefined, empty: string) => (r ? `${this.chipOf(r.who)}<b${me && r.ids.includes(me) ? ' class="you"' : ` data-pid="${esc(r.who)}"`}>${esc(me && r.ids.includes(me) ? 'You' : r.name)}</b> <small>${esc(this.amount(id, r.n))}</small>` : `<small class="mute">${empty}</small>`);
        return `<li class="title-row"><span class="ti">${t.icon}</span><span class="what"><b>${esc(t.name)}</b><small>${esc(t.what)}</small></span>`
          + `<span class="held"><small>Held this week</small>${who(held, 'nobody yet')}</span><span class="lead"><small>Leading so far</small>${who(lead, 'nobody yet this week')}</span></li>`;
      }).join('');
      return `<div class="lead">Nine titles, counted Monday to Monday (UTC). Last week’s winners wear theirs this week: on their card, their name tag and in Fleets.</div><ul class="titles">${rows}</ul>
        <p class="foot">No diamonds: a title is a title. Counted by the server from rent at doors, crossings of works, minutes beside other fleets, hearts given and on whole fleets, cameras following your vehicles, and a shared fleet’s takings.</p>`;
    },
  };

  /** Lifetime titles: every fleet's titles over all time, most first. */
  readonly lifetimeBoard: BoardBody = {
    opened: () => this.ask(),
    tick: () => { /* asked every two minutes */ },
    press: () => false,
    html: (_rows: () => BoardRow[], me: string | null) => {
      if (!this.heard) return '<p class="none">Asking the server…</p>';
      if (!this.lifetime.length) return '<p class="none">Nobody has held a title yet: the first are handed out when this week ends.</p>';
      const list = this.lifetime.map((r, k) => {
        const total = Object.values(r.n).reduce((s, v) => s + (v ?? 0), 0);
        const icons = TITLES.filter((id) => r.n[id]).map((id) => `<span title="${esc(TITLE_INFO[id].name)}">${TITLE_INFO[id].icon}${(r.n[id] ?? 0) > 1 ? `<sub>${r.n[id]}</sub>` : ''}</span>`).join(' ');
        const you = !!me && r.ids.includes(me);
        return `<li class="${you ? 'you' : ''}"><span class="nm"><i>${k + 1}</i>${this.chipOf(r.who)}<b${you ? '' : ` data-pid="${esc(r.who)}"`}>${esc(r.name)}</b>${you ? ' <small>you</small>' : ''}<span class="sub">${icons}</span></span><em>${total}</em></li>`;
      }).join('');
      return `<div class="lead">Every fleet’s weekly titles over all time.</div><ul class="ranking lifetime">${list}</ul>`;
    },
  };
}
