/**
 * The biomes' trees and ground clutter, as low-poly geometries in the style of the five ordinary
 * trees. Each is merged into one BufferGeometry with a colour and an `aLeaf` per vertex (see
 * propMaterial in props.ts) and drawn instanced; each stays under about two hundred triangles.
 */
import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';

/**
 * Colour a part, and say whether it is foliage: 4 a birch's leaves (gold in autumn), 3 blossoming
 * (cherry), 2 deciduous, 1 needles or fronds, 0 not a leaf. Crops keep their own year, which also
 * sets how tall they stand (see propMaterial): 5 grain, 6 a tall stalk, 7 a sunflower's head,
 * 8 a pumpkin's vine and 9 the pumpkins.
 */
export function paint(g: THREE.BufferGeometry, hexColor: number, leaf = 0): THREE.BufferGeometry {
  const col = new THREE.Color(hexColor);
  const n = g.getAttribute('position').count;
  const arr = new Float32Array(n * 3);
  const lf = new Float32Array(n);
  for (let i = 0; i < n; i++) { arr[i * 3] = col.r; arr[i * 3 + 1] = col.g; arr[i * 3 + 2] = col.b; lf[i] = leaf; }
  g.setAttribute('color', new THREE.BufferAttribute(arr, 3));
  g.setAttribute('aLeaf', new THREE.BufferAttribute(lf, 1));
  // the middle of the part, which a crown shrinks into when its tree drops its leaves
  g.computeBoundingBox();
  const hub = g.boundingBox!.getCenter(new THREE.Vector3());
  const hb = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) { hb[i * 3] = hub.x; hb[i * 3 + 1] = hub.y; hb[i * 3 + 2] = hub.z; }
  g.setAttribute('aHub', new THREE.BufferAttribute(hb, 3));
  return g;
}
/**
 * Geometries with bare boughs inside their crowns, and how many vertices come before the boughs. The
 * boughs show only once a tree has dropped its leaves (shedLeaves in props.ts: no tree goes bare before
 * winter reaches 2/32), so the rest of the year they are left off the end of the draw: about half a
 * broadleaf's triangles, in the shadow pass too (the lag audit, Oct 2026).
 */
const BOUGHED: { g: THREE.BufferGeometry; leaf: number }[] = [];
/** Winter past which some tree may be bare (the earliest drop code, 2/32, less a little). */
const BARE_FROM = 0.05;
let boughsShown: boolean | null = null;
/** Draw the boughs or not, from how far into winter the year is. Called as the year turns. */
export function syncBoughs(winter: number): void {
  const on = winter > BARE_FROM;
  if (on === boughsShown) return;
  boughsShown = on;
  for (const b of BOUGHED) b.g.setDrawRange(0, on ? Infinity : b.leaf);
}

export function merge(parts: THREE.BufferGeometry[]): THREE.BufferGeometry {
  // the boughs last, so leaving them off is a shorter draw range
  const bare = parts.filter((p) => p.userData.bough);
  if (bare.length) parts = [...parts.filter((p) => !p.userData.bough), ...bare];
  const nonIndexed = parts.map((p) => {
    const g = p.index ? p.toNonIndexed() : p;
    // uv-less parts (lathes keep theirs) must match for mergeGeometries
    g.deleteAttribute('uv');
    g.deleteAttribute('normal');
    return g;
  });
  const g = mergeGeometries(nonIndexed, false)!;
  g.computeVertexNormals();
  if (bare.length) {
    const leaf = nonIndexed.slice(0, parts.length - bare.length).reduce((n, q) => n + q.attributes.position.count, 0);
    BOUGHED.push({ g, leaf });
    if (boughsShown === false) g.setDrawRange(0, leaf);
  }
  return g;
}

const UP = new THREE.Vector3(0, 1, 0);
/** A tapered cylinder from a to b: a branch, a pole, a bent trunk segment. */
function limb(a: [number, number, number], b: [number, number, number], r0: number, r1: number, radial = 5, open = true): THREE.BufferGeometry {
  const va = new THREE.Vector3(...a), vb = new THREE.Vector3(...b);
  const d = vb.clone().sub(va);
  const len = d.length();
  const g = new THREE.CylinderGeometry(r1, r0, len, radial, 1, open);
  g.translate(0, len / 2, 0);
  g.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(UP, d.normalize()));
  g.translate(va.x, va.y, va.z);
  return g;
}
/**
 * The bare boughs of a broadleaf, hidden inside its crown until the tree drops its leaves in winter:
 * a few limbs fanning up and out from the top of the trunk, each forking once into a twig. `base` is
 * where they leave the trunk, `top` how high the tips reach, `spread` how far out.
 */
export function boughs(base: [number, number, number], top: number, spread: number, seed: number, hex: number, limbs = 4): THREE.BufferGeometry[] {
  const parts: THREE.BufferGeometry[] = [];
  const [bx, by, bz] = base;
  for (let k = 0; k < limbs; k++) {
    const a = (k / limbs) * Math.PI * 2 + seed;
    const reach = spread * (0.75 + 0.25 * Math.sin(seed * 3 + k * 1.7));
    const mx = bx + Math.cos(a) * reach * 0.55, mz = bz + Math.sin(a) * reach * 0.55;
    const my = by + (top - by) * (0.5 + 0.08 * (k % 2));
    const tx = bx + Math.cos(a) * reach, tz = bz + Math.sin(a) * reach;
    const ty = top - (k % 2) * (top - by) * 0.12;
    parts.push(paint(limb([bx, by, bz], [mx, my, mz], 0.03, 0.02, 3), hex));
    parts.push(paint(limb([mx, my, mz], [tx, ty, tz], 0.02, 0.008, 3), hex));
    // a twig forking off sideways
    const b = a + 0.9;
    parts.push(paint(limb([mx, my, mz], [mx + Math.cos(b) * reach * 0.45, my + (top - my) * 0.8, mz + Math.sin(b) * reach * 0.45], 0.014, 0.006, 3), hex));
  }
  for (const p of parts) p.userData.bough = true;
  return parts;
}

function lathe(profile: [number, number][], radial: number): THREE.BufferGeometry {
  return new THREE.LatheGeometry(profile.map(([r, y]) => new THREE.Vector2(r, y)), radial);
}

// ------------------------------------------------------------------------------------------ trees

/** A date palm: a tall straight ringed trunk, a tight crown of stiff fronds, hanging dates. */
function datePalmGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const H = 1.35;
  for (let k = 0; k < 3; k++) {
    const y0 = (k / 3) * H, y1 = ((k + 1) / 3) * H + 0.02;
    parts.push(paint(limb([0, y0, 0], [0, y1, 0], 0.07 - k * 0.008, 0.058 - k * 0.008, 6), k % 2 ? 0x9a7a52 : 0x8a6c48));
  }
  parts.push(paint(new THREE.OctahedronGeometry(0.075, 0).translate(0, H + 0.02, 0), 0x7a6040));
  for (let k = 0; k < 8; k++) {
    const a = (k / 8) * Math.PI * 2 + (k % 2) * 0.2;
    const frond = new THREE.BoxGeometry(0.44, 0.02, 0.1);
    frond.translate(0.22, 0, 0);
    frond.rotateZ(k % 2 ? 0.55 : -0.12);       // alternate up-thrust and level, stiff not drooping
    frond.rotateY(a);
    frond.translate(0, H + 0.03, 0);
    parts.push(paint(frond, k % 2 ? 0x6a9a4a : 0x5a8a44, 1));
  }
  for (const a of [0.4, 2.5]) {
    parts.push(paint(new THREE.OctahedronGeometry(0.06, 0).scale(1, 1.4, 1).translate(Math.cos(a) * 0.08, H - 0.1, Math.sin(a) * 0.08), 0xc0782a));
  }
  return merge(parts);
}

/** A rainforest emergent: a tall bare trunk on buttress roots under a wide flat crown. */
function canopyTreeGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  parts.push(paint(limb([0, 0, 0], [0, 1.45, 0], 0.085, 0.05, 6), 0x9a8a72));
  for (let k = 0; k < 3; k++) {
    const a = (k / 3) * Math.PI * 2 + 0.3;
    const fin = new THREE.BoxGeometry(0.22, 0.26, 0.03).translate(0.1, 0.13, 0);
    // a sloping fin: cut the top outer corner down by shearing
    const pos = fin.getAttribute('position') as THREE.BufferAttribute;
    for (let v = 0; v < pos.count; v++) if (pos.getX(v) > 0.1 && pos.getY(v) > 0.1) pos.setY(v, 0.02);
    fin.rotateY(a);
    parts.push(paint(fin, 0x8a7a64));
  }
  parts.push(paint(new THREE.DodecahedronGeometry(0.46, 0).scale(1.45, 0.42, 1.3).translate(0, 1.58, 0), 0x2f7a38, 1));
  parts.push(paint(new THREE.DodecahedronGeometry(0.3, 0).scale(1.3, 0.5, 1.2).translate(0.18, 1.74, -0.1), 0x3a8a40, 1));
  parts.push(paint(new THREE.DodecahedronGeometry(0.22, 0).scale(1.3, 0.55, 1.2).translate(-0.3, 1.5, 0.22), 0x2a6e34, 1));
  return merge(parts);
}

/** An acacia: a thin forked trunk under a flat umbrella crown. */
function acaciaGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  parts.push(paint(limb([0, 0, 0], [0.02, 0.42, 0], 0.045, 0.035, 5), 0x6a5040));
  parts.push(paint(limb([0.02, 0.4, 0], [0.26, 0.78, 0.06], 0.032, 0.02, 5), 0x6a5040));
  parts.push(paint(limb([0.02, 0.4, 0], [-0.22, 0.74, -0.08], 0.03, 0.02, 5), 0x6a5040));
  parts.push(paint(new THREE.DodecahedronGeometry(0.4, 0).scale(1.55, 0.22, 1.35).translate(0.03, 0.82, 0), 0x7a9a3e, 1));
  parts.push(paint(new THREE.DodecahedronGeometry(0.26, 0).scale(1.4, 0.26, 1.3).translate(0.12, 0.9, 0.08), 0x86a646, 1));
  return merge(parts);
}

/** A baobab: a fat bottle trunk, a few stubby branches and a small crown. */
function baobabGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  parts.push(paint(lathe([[0.3, 0], [0.34, 0.25], [0.3, 0.55], [0.2, 0.8], [0.14, 0.95], [0, 0.97]], 7), 0x9a8a7a));
  for (let k = 0; k < 5; k++) {
    const a = (k / 5) * Math.PI * 2 + 0.4;
    const r = 0.36 + (k % 2) * 0.08;
    parts.push(paint(limb([Math.cos(a) * 0.08, 0.9, Math.sin(a) * 0.08], [Math.cos(a) * r, 1.14 + (k % 2) * 0.06, Math.sin(a) * r], 0.05, 0.025, 4), 0x8a7a6a));
  }
  for (let k = 0; k < 3; k++) {
    const a = (k / 3) * Math.PI * 2 + 0.9;
    parts.push(paint(new THREE.IcosahedronGeometry(0.15, 0).scale(1.2, 0.7, 1.2).translate(Math.cos(a) * 0.3, 1.2, Math.sin(a) * 0.3), 0x6f9a44, 2));
  }
  return merge(parts);
}

/**
 * A bald cypress for the Fens: a trunk flaring into buttresses at the waterline, a thin grey-green
 * crown in tiers, knees poking up round its foot, and Spanish moss hanging from it.
 */
function cypressGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  parts.push(paint(lathe([[0.22, -0.05], [0.14, 0.08], [0.075, 0.3], [0.055, 0.8], [0.03, 1.3], [0, 1.32]], 6), 0x7a6a58));
  const tiers: [number, number, number, number][] = [[0.08, 0.82, 0.02, 0.28], [-0.08, 1.04, -0.04, 0.24], [0.04, 1.26, 0.03, 0.18]];
  for (const [x, y, z, r] of tiers) {
    parts.push(paint(new THREE.IcosahedronGeometry(r, 0).scale(1.3, 0.55, 1.2).translate(x, y, z), 0x7f9470, 2));
  }
  for (const [a, d, h] of [[0.5, 0.3, 0.12], [2.4, 0.26, 0.09], [4.3, 0.34, 0.1]]) {
    parts.push(paint(new THREE.ConeGeometry(0.035, h, 4).translate(Math.cos(a) * d, h / 2 - 0.02, Math.sin(a) * d), 0x6a5a4a));
  }
  for (const [x, y, z, h] of [[0.26, 0.72, 0.05, 0.22], [-0.22, 0.95, -0.06, 0.2], [0.05, 0.68, -0.24, 0.18]]) {
    parts.push(paint(new THREE.BoxGeometry(0.05, h, 0.012).translate(x, y - h / 2, z), 0x9aa08a));
  }
  return merge(parts);
}

/** An olive: a short gnarled trunk under a rounded silver-green crown. */
function oliveGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  parts.push(paint(limb([0, 0, 0], [0.08, 0.2, 0.02], 0.07, 0.055, 5), 0x6a5a48));
  parts.push(paint(limb([0.08, 0.19, 0.02], [-0.02, 0.4, -0.02], 0.055, 0.04, 5), 0x6a5a48));
  parts.push(paint(new THREE.DodecahedronGeometry(0.3, 0).scale(1.25, 0.8, 1.15).translate(0, 0.5, 0), 0x8a9e78, 1));
  parts.push(paint(new THREE.DodecahedronGeometry(0.18, 0).translate(0.22, 0.42, 0.12), 0x9aae88, 1));
  return merge(parts);
}

/** A cherry: the round tree spread wider, on a dark trunk; its crown is aLeaf 3 so it blossoms. */
function cherryGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  parts.push(paint(limb([0, 0, 0], [0.02, 0.3, 0], 0.06, 0.045, 6), 0x5a3a32));
  parts.push(...boughs([0.02, 0.28, 0], 0.66, 0.3, 0.4, 0x5a3a32, 5));
  parts.push(paint(new THREE.DodecahedronGeometry(0.3, 0).scale(1.3, 0.9, 1.2).translate(0, 0.55, 0), 0x5aa84e, 3));
  parts.push(paint(new THREE.DodecahedronGeometry(0.2, 0).translate(0.26, 0.46, 0.08), 0x64b058, 3));
  parts.push(paint(new THREE.DodecahedronGeometry(0.18, 0).translate(-0.22, 0.5, -0.12), 0x50a048, 3));
  return merge(parts);
}

/** A bamboo clump: thin tall poles with small leafy tops. */
function bambooGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const poles: [number, number, number, number][] = [
    [0, 0, 1.45, 0.02], [0.12, 0.05, 1.25, -0.05], [-0.1, 0.08, 1.35, 0.06], [0.04, -0.13, 1.15, 0.04],
    [-0.08, -0.08, 1.05, -0.08], [0.16, -0.08, 0.95, 0.1], [-0.16, 0.0, 0.9, -0.1],
  ];
  for (const [x, z, h, lean] of poles) {
    const tx = x + lean * 1.6, tz = z + lean;
    parts.push(paint(limb([x, 0, z], [tx, h, tz], 0.022, 0.016, 4), 0x9ab452));
    parts.push(paint(new THREE.OctahedronGeometry(0.07, 0).scale(1.4, 1.2, 0.5).rotateY(x * 20).translate(tx, h - 0.03, tz), 0x5a9a44, 1));
  }
  return merge(parts);
}

/** A wind-bent pine for the Moors: a trunk leaning hard downwind and a crown streaming after it. */
function windPineGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const pts: [number, number, number][] = [[0, 0, 0], [0.08, 0.28, 0], [0.24, 0.52, 0], [0.46, 0.68, 0]];
  for (let k = 0; k < 3; k++) parts.push(paint(limb(pts[k], pts[k + 1], 0.055 - k * 0.012, 0.045 - k * 0.012, 5), 0x5e4a38));
  parts.push(paint(new THREE.DodecahedronGeometry(0.26, 0).scale(1.7, 0.4, 0.9).translate(0.4, 0.7, 0), 0x3f6a4a, 1));
  parts.push(paint(new THREE.DodecahedronGeometry(0.18, 0).scale(1.8, 0.45, 0.9).translate(0.2, 0.56, 0.02), 0x48744f, 1));
  return merge(parts);
}

// ---------------------------------------------------------------------------------------- clutter

/** A dry scrub clump. */
function shrubGeometry(): THREE.BufferGeometry {
  return merge([
    paint(new THREE.IcosahedronGeometry(0.13, 0).scale(1.3, 0.75, 1.2).translate(0, 0.08, 0), 0x8a8e58, 1),
    paint(new THREE.IcosahedronGeometry(0.09, 0).scale(1.2, 0.8, 1.1).translate(0.12, 0.06, 0.06), 0x9a9460, 1),
  ]);
}
/** A low purple mound of heather. */
function heatherGeometry(): THREE.BufferGeometry {
  return merge([
    paint(new THREE.IcosahedronGeometry(0.16, 0).scale(1.4, 0.45, 1.2).translate(0, 0.04, 0), 0x86588a, 1),
    paint(new THREE.IcosahedronGeometry(0.1, 0).scale(1.3, 0.5, 1.2).translate(0.16, 0.03, -0.1), 0x9a6a9c, 1),
  ]);
}
/** A tall reddish termite mound, with a lesser spire leaning on it. */
function termiteMoundGeometry(): THREE.BufferGeometry {
  return merge([
    paint(new THREE.ConeGeometry(0.15, 0.6, 6).translate(0, 0.28, 0), 0xb0643a),
    paint(new THREE.ConeGeometry(0.09, 0.34, 5).translate(0.1, 0.15, 0.05), 0xa05834),
  ]);
}
/** A clump of reeds with a couple of bulrush heads. */
function reedsGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  for (let k = 0; k < 7; k++) {
    const a = (k / 7) * Math.PI * 2 + k * 0.7;
    const d = 0.04 + (k % 3) * 0.04;
    const h = 0.34 + ((k * 37) % 5) * 0.05;
    const bx = Math.cos(a) * d, bz = Math.sin(a) * d;
    const blade = new THREE.ConeGeometry(0.018, h, 3).translate(0, h / 2, 0);
    blade.rotateZ(-Math.cos(a) * 0.25);
    blade.rotateX(Math.sin(a) * 0.25);
    parts.push(paint(blade.translate(bx, 0, bz), k % 2 ? 0x8aa052 : 0x9aac5e, 2));
  }
  for (const [x, z, h] of [[0.03, 0.02, 0.44], [-0.05, -0.03, 0.38]]) {
    parts.push(paint(new THREE.CylinderGeometry(0.018, 0.018, 0.08, 4).translate(x, h, z), 0x6a4a30));
  }
  return merge(parts);
}
/** A low fan of fern fronds. */
function fernGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  for (let k = 0; k < 7; k++) {
    const a = (k / 7) * Math.PI * 2;
    const frond = new THREE.ConeGeometry(0.08, 0.4, 3).scale(1, 1, 0.3);
    frond.translate(0, 0.2, 0);
    frond.rotateZ(-1.0 - (k % 2) * 0.25);   // arch outward
    frond.rotateY(a);
    parts.push(paint(frond.translate(0, 0.02, 0), k % 2 ? 0x3f8e3e : 0x4a9a46, 1));
  }
  return merge(parts);
}
/** A round haystack under a conical top. */
function haystackGeometry(): THREE.BufferGeometry {
  return merge([
    paint(new THREE.CylinderGeometry(0.17, 0.19, 0.22, 8, 1, true).translate(0, 0.11, 0), 0xd8b85a),
    paint(new THREE.ConeGeometry(0.19, 0.2, 8).translate(0, 0.32, 0), 0xc8a84e),
  ]);
}
/** A small grey stone lantern: plinth, post, lamp box and a pointed cap. */
function stoneLanternGeometry(): THREE.BufferGeometry {
  return merge([
    paint(new THREE.BoxGeometry(0.16, 0.05, 0.16).translate(0, 0.025, 0), 0x8a8882),
    paint(new THREE.BoxGeometry(0.06, 0.2, 0.06).translate(0, 0.15, 0), 0x9a9892),
    paint(new THREE.BoxGeometry(0.12, 0.09, 0.12).translate(0, 0.29, 0), 0xe8d8a0),
    paint(new THREE.ConeGeometry(0.14, 0.09, 4).rotateY(Math.PI / 4).translate(0, 0.38, 0), 0x7a7872),
    paint(new THREE.OctahedronGeometry(0.025, 0).translate(0, 0.44, 0), 0x7a7872),
  ]);
}
/** A section of slatted timber snow fence, running along x. */
function snowFenceGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [
    paint(new THREE.BoxGeometry(0.04, 0.34, 0.04).translate(-0.4, 0.17, 0), 0x6a5038),
    paint(new THREE.BoxGeometry(0.04, 0.34, 0.04).translate(0.4, 0.17, 0), 0x6a5038),
  ];
  for (let k = 0; k < 4; k++) parts.push(paint(new THREE.BoxGeometry(0.84, 0.045, 0.015).translate(0, 0.08 + k * 0.075, 0.025), k % 2 ? 0x9a7a52 : 0x8a6c48));
  return merge(parts);
}
/** A beach hut: a white box the instance tint turns pastel, a pitched roof and a door facing +z. */
function beachHutGeometry(): THREE.BufferGeometry {
  return merge([
    paint(new THREE.BoxGeometry(0.4, 0.34, 0.36).translate(0, 0.17, 0), 0xf6f2ea),
    paint(new THREE.ConeGeometry(0.34, 0.16, 4).rotateY(Math.PI / 4).scale(1, 1, 0.95).translate(0, 0.42, 0), 0xe8e0d6),
    paint(new THREE.BoxGeometry(0.16, 0.24, 0.02).translate(0, 0.12, 0.185), 0x8a7a70),
    paint(new THREE.BoxGeometry(0.42, 0.03, 0.2).translate(0, 0.015, 0.28), 0xb09a78),
  ]);
}
/** A section of drystone wall along x, standing in for the timber fence on the Moors. */
function drystoneWallGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [
    paint(new THREE.BoxGeometry(1.0, 0.16, 0.14).translate(0, 0.08, 0), 0x8a8680),
  ];
  const stones: [number, number, number][] = [[-0.38, 0.19, 0x7a766f], [-0.13, 0.2, 0x96918a], [0.12, 0.185, 0x827e77], [0.37, 0.2, 0x9a958d]];
  for (const [x, y, c] of stones) parts.push(paint(new THREE.BoxGeometry(0.24, 0.07, 0.12).translate(x, y, 0), c));
  return merge(parts);
}
/** An iceberg: white chunks with a pale cyan underside, sitting a little into the water. */
function icebergGeometry(): THREE.BufferGeometry {
  return merge([
    paint(new THREE.DodecahedronGeometry(0.34, 0).scale(1.2, 0.8, 1).translate(0, 0.12, 0), 0xeef6fa),
    paint(new THREE.IcosahedronGeometry(0.24, 0).scale(1, 1.4, 0.9).translate(0.18, 0.28, -0.06), 0xf8fcff),
    paint(new THREE.DodecahedronGeometry(0.3, 0).scale(1.3, 0.3, 1.1).translate(-0.05, -0.04, 0.04), 0xbfe6ee),
  ]);
}
/** A small fishing boat along x, bow to +x: hull, painted strake, wheelhouse and a mast. */
function mooredBoatGeometry(): THREE.BufferGeometry {
  const hull = new THREE.BoxGeometry(0.46, 0.1, 0.2);
  // taper the bow to a point and pinch the keel
  const pos = hull.getAttribute('position') as THREE.BufferAttribute;
  for (let v = 0; v < pos.count; v++) {
    if (pos.getX(v) > 0) pos.setZ(v, pos.getZ(v) * 0.15);
    if (pos.getY(v) < 0) pos.setZ(v, pos.getZ(v) * 0.6);
  }
  hull.translate(0, 0.03, 0);
  return merge([
    paint(hull, 0xf2eee2),
    paint(new THREE.BoxGeometry(0.34, 0.025, 0.205).translate(-0.05, 0.075, 0), 0x2a6ab0),
    paint(new THREE.BoxGeometry(0.12, 0.1, 0.13).translate(-0.1, 0.13, 0), 0xe8e2d0),
    paint(new THREE.CylinderGeometry(0.008, 0.008, 0.36, 4).translate(0.06, 0.26, 0), 0x7a6a58),
  ]);
}

// ---------------------------------------------------------------------- the ordinary country's trees

/** An oak: a short thick trunk under a broad, low crown, wider than it is tall. */
function oakGeometry(): THREE.BufferGeometry {
  return merge([
    paint(limb([0, 0, 0], [0.02, 0.34, 0], 0.085, 0.06, 6), 0x6a5038),
    paint(limb([0.02, 0.3, 0], [0.22, 0.46, 0.04], 0.045, 0.03, 4), 0x6a5038),
    ...boughs([0.02, 0.32, 0], 0.74, 0.4, 1.1, 0x6a5038, 5),
    paint(new THREE.IcosahedronGeometry(0.36, 0).scale(1.35, 0.72, 1.25).translate(0, 0.62, 0), 0x4e9a44, 2),
    paint(new THREE.IcosahedronGeometry(0.24, 0).scale(1.3, 0.8, 1.2).translate(0.3, 0.52, 0.1), 0x5aa64c, 2),
    paint(new THREE.IcosahedronGeometry(0.22, 0).scale(1.3, 0.8, 1.2).translate(-0.26, 0.54, -0.14), 0x46903e, 2),
  ]);
}

/** A birch: a slim white trunk with dark bands under a small, open crown that turns gold. */
function birchGeometry(): THREE.BufferGeometry {
  return merge([
    paint(limb([0, 0, 0], [0.03, 0.8, 0], 0.036, 0.022, 5), 0xece8e0),
    paint(new THREE.CylinderGeometry(0.036, 0.037, 0.035, 5, 1, true).translate(0.006, 0.2, 0), 0x3a3632),
    paint(new THREE.CylinderGeometry(0.031, 0.032, 0.03, 5, 1, true).translate(0.015, 0.45, 0), 0x3a3632),
    ...boughs([0.02, 0.55, 0], 1.0, 0.16, 0.3, 0xd8d2c8, 3),
    paint(new THREE.IcosahedronGeometry(0.2, 0).scale(1, 1.45, 1).translate(0.03, 0.86, 0), 0x78b85a, 4),
    paint(new THREE.IcosahedronGeometry(0.14, 0).scale(1, 1.3, 1).translate(-0.1, 0.62, 0.06), 0x84c062, 4),
  ]);
}

/** A weeping willow for the riverbank: a dome of a crown with long strands hanging round it. */
function willowGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [
    paint(limb([0, 0, 0], [0.04, 0.5, 0], 0.07, 0.05, 5), 0x6a5a44),
    ...boughs([0.04, 0.48, 0], 0.84, 0.34, 0.7, 0x6a5a44, 5),
    paint(new THREE.DodecahedronGeometry(0.36, 0).scale(1.25, 0.72, 1.25).translate(0.03, 0.72, 0), 0x86b45a, 2),
  ];
  for (let k = 0; k < 8; k++) {
    const a = (k / 8) * Math.PI * 2 + 0.2;
    const h = 0.42 + (k % 3) * 0.06;
    // a hanging strand: a thin three-sided cone, point down, from under the crown's rim
    const strand = new THREE.ConeGeometry(0.1, h, 3, 1, true).rotateX(Math.PI).rotateY(a);
    strand.translate(0.03 + Math.cos(a) * 0.38, 0.68 - h / 2, Math.sin(a) * 0.38);
    parts.push(paint(strand, k % 2 ? 0x94bc62 : 0x7eaa52, 2));
  }
  return merge(parts);
}

/** A stone pine for warm coasts: a tall bare trunk leaning a little under a flat dark umbrella. */
function stonePineGeometry(): THREE.BufferGeometry {
  return merge([
    paint(limb([0, 0, 0], [0.06, 0.55, 0], 0.05, 0.038, 5), 0x8a6a50),
    paint(limb([0.06, 0.55, 0], [0.14, 0.95, 0.02], 0.038, 0.026, 5), 0x8a6a50),
    paint(new THREE.DodecahedronGeometry(0.36, 0).scale(1.5, 0.34, 1.45).translate(0.14, 1.02, 0.02), 0x3f6e3e, 1),
    paint(new THREE.IcosahedronGeometry(0.22, 0).scale(1.4, 0.4, 1.3).translate(0.08, 1.12, -0.06), 0x4a7a46, 1),
  ]);
}

/**
 * A redwood for the Big Timber: a straight red trunk three times the height of any other tree, bare for
 * its lower half, under short drooping tiers of dark needles that narrow to a point.
 */
function redwoodGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [
    paint(limb([0, 0, 0], [0, 1.5, 0], 0.13, 0.085, 7), 0x9a5638),
    paint(limb([0, 1.5, 0], [0, 2.9, 0], 0.085, 0.025, 6), 0x8a4c32),
    // the buttressed foot
    paint(new THREE.ConeGeometry(0.2, 0.3, 7, 1, true).translate(0, 0.15, 0), 0x8a4c32),
  ];
  const tiers: [number, number, number][] = [[1.25, 0.46, 0.5], [1.62, 0.42, 0.5], [1.98, 0.36, 0.48], [2.32, 0.29, 0.46], [2.64, 0.21, 0.44], [2.92, 0.13, 0.42]];
  tiers.forEach(([y, r, h], k) => parts.push(paint(new THREE.ConeGeometry(r, h, 7).rotateY(k * 0.5).translate(0, y + h / 2, 0), k % 2 ? 0x2f5f3a : 0x274f32, 1)));
  return merge(parts);
}

// -------------------------------------------------------------------- hedges and wild flowers

/** A stretch of hedgerow along x, in place of a timber fence: fewer triangles, and softer to hit. */
function hedgeGeometry(): THREE.BufferGeometry {
  return merge([
    paint(new THREE.BoxGeometry(1.04, 0.2, 0.17).translate(0, 0.1, 0), 0x4a8a3e, 2),
    paint(new THREE.OctahedronGeometry(0.13, 0).scale(1.6, 0.7, 0.8).translate(-0.28, 0.2, 0), 0x55963f, 2),
    paint(new THREE.OctahedronGeometry(0.12, 0).scale(1.6, 0.7, 0.8).translate(0.3, 0.2, 0.01), 0x427e38, 2),
  ]);
}

/** A tuft of gorse or wild flowers: a low green clump with three pale heads the instance tint colours. */
function tuftGeometry(): THREE.BufferGeometry {
  return merge([
    paint(new THREE.OctahedronGeometry(0.12, 0).scale(1.4, 0.5, 1.3).translate(0, 0.04, 0), 0x6a9e4a, 1),
    paint(new THREE.OctahedronGeometry(0.04, 0).translate(0.05, 0.1, 0.03), 0xffffff),
    paint(new THREE.OctahedronGeometry(0.035, 0).translate(-0.06, 0.085, 0.04), 0xffffff),
    paint(new THREE.OctahedronGeometry(0.038, 0).translate(0.01, 0.09, -0.07), 0xffffff),
  ]);
}

// -------------------------------------------------------------------------------------- crops
// One tile each, centred on the tile with its rows along x, so neighbouring tiles' rows join up.

/** Wheat or barley: three ridged rows filling the tile. Green in spring, gold in summer, stubble after. */
function wheatGeometry(): THREE.BufferGeometry {
  const pos: number[] = [];
  for (const z of [-0.333, 0, 0.333]) {
    // a ridge along x: two slopes meeting at the crest, open at the ends where the next tile's row carries on
    const lo = -0.02, hi = 0.2, half = 0.16;
    pos.push(-0.5, lo, z + half, 0.5, lo, z + half, 0.5, hi, z, -0.5, lo, z + half, 0.5, hi, z, -0.5, hi, z);
    pos.push(-0.5, lo, z - half, -0.5, hi, z, 0.5, hi, z, -0.5, lo, z - half, 0.5, hi, z, 0.5, lo, z - half);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  paint(g, 0xdcb24e, 5);
  // shade the furrows between the rows so the rows read from above, where both slopes catch the sun alike
  const col = g.getAttribute('color') as THREE.BufferAttribute;
  for (let v = 0; v < col.count; v++) if (pos[v * 3 + 1] < 0) col.setXYZ(v, col.getX(v) * 0.62, col.getY(v) * 0.62, col.getZ(v) * 0.62);
  return merge([g]);
}

/** Maize: three tall leafy rows about as high as a car, pale tassels along their tops. */
function maizeGeometry(): THREE.BufferGeometry {
  const pos: number[] = [];
  const lo = -0.02, hi = 0.5, half = 0.12;
  for (const z of [-0.333, 0, 0.333]) {
    pos.push(-0.5, lo, z + half, 0.5, lo, z + half, 0.5, hi, z, -0.5, lo, z + half, 0.5, hi, z, -0.5, hi, z);
    pos.push(-0.5, lo, z - half, -0.5, hi, z, 0.5, hi, z, -0.5, lo, z - half, 0.5, hi, z, 0.5, lo, z - half);
  }
  const rows = new THREE.BufferGeometry();
  rows.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  paint(rows, 0x5e9e3a, 6);
  const col = rows.getAttribute('color') as THREE.BufferAttribute;
  for (let v = 0; v < col.count; v++) if (pos[v * 3 + 1] < 0) col.setXYZ(v, col.getX(v) * 0.55, col.getY(v) * 0.55, col.getZ(v) * 0.55);
  const parts: THREE.BufferGeometry[] = [rows];
  for (const z of [-0.333, 0, 0.333]) {
    for (const x of [-0.25, 0.25]) {
      parts.push(paint(new THREE.OctahedronGeometry(0.05, 0).scale(0.8, 1.3, 0.8).translate(x + z * 0.3, hi + 0.02, z), 0xd8cc7a, 6));
    }
  }
  return merge(parts);
}

/** Sunflowers: three stalks, every head turned the same way to the sun. */
function sunflowerGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  const plants: [number, number, number][] = [[-0.25, -0.2, 0.44], [0.2, 0.05, 0.5], [-0.05, 0.3, 0.4]];
  for (const [x, z, h] of plants) {
    parts.push(paint(new THREE.CylinderGeometry(0.014, 0.02, h, 3, 1, true).translate(x, h / 2, z), 0x5a8a34, 6));
    parts.push(paint(new THREE.OctahedronGeometry(0.06, 0).scale(1.3, 0.4, 0.8).translate(x + 0.05, h * 0.55, z), 0x5a9a3a, 6));
    // the head faces +x: a flat six-sided disc and a dark middle
    parts.push(paint(new THREE.ConeGeometry(0.13, 0.03, 6).rotateZ(-Math.PI / 2).translate(x + 0.03, h, z), 0xf2c21e, 7));
    parts.push(paint(new THREE.OctahedronGeometry(0.055, 0).scale(0.5, 1, 1).translate(x + 0.055, h, z), 0x5a3a1a, 7));
  }
  return merge(parts);
}

/** A pumpkin patch: a low mat of vine with pumpkins that swell and ripen orange by autumn. */
function pumpkinGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [
    paint(new THREE.BoxGeometry(1.0, 0.05, 1.0).translate(0, 0.005, 0), 0x5a9440, 8),
    paint(new THREE.OctahedronGeometry(0.16, 0).scale(1.4, 0.3, 1.2).translate(-0.18, 0.04, -0.12), 0x4e8a38, 8),
  ];
  for (const [x, z, r] of [[0.22, 0.12, 0.11], [-0.2, 0.2, 0.09], [0.02, -0.26, 0.1]]) {
    parts.push(paint(new THREE.OctahedronGeometry(r, 0).scale(1.25, 0.8, 1.25).translate(x, 0.1, z), 0xe8841e, 9));
  }
  return merge(parts);
}

/** Lavender: three rounded purple rows to a tile, grey-green at the foot, in flower from spring to the cut. */
function lavenderGeometry(): THREE.BufferGeometry {
  const pos: number[] = [];
  const lo = -0.02, mid = 0.1, hi = 0.17, half = 0.15, crown = 0.06;
  for (const z of [-0.333, 0, 0.333]) {
    // a rounded ridge along x: a steep foot each side and a flat-ish crown, open at the ends to join the next tile
    for (const s of [1, -1]) {
      const a = z + s * half, b = z + s * crown;
      const quad = (y0: number, z0: number, y1: number, z1: number) => {
        if (s > 0) pos.push(-0.5, y0, z0, 0.5, y0, z0, 0.5, y1, z1, -0.5, y0, z0, 0.5, y1, z1, -0.5, y1, z1);
        else pos.push(-0.5, y0, z0, 0.5, y1, z1, 0.5, y0, z0, -0.5, y0, z0, -0.5, y1, z1, 0.5, y1, z1);
      };
      quad(lo, a, mid, b);
      quad(mid, b, hi, z);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  paint(g, 0x8a62c8, 8);
  // the foot of each row is leaf, not flower
  const col = g.getAttribute('color') as THREE.BufferAttribute;
  for (let v = 0; v < col.count; v++) if (pos[v * 3 + 1] < 0) col.setXYZ(v, 0.36, 0.42, 0.3);
  return merge([g]);
}

/** Tulips in one colour: three rows of cupped heads over a low mat of leaf, in flower all season (a bulb field's band). */
function tulipGeometry(colour: number): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  for (const z of [-0.333, 0, 0.333]) {
    parts.push(paint(new THREE.BoxGeometry(1.0, 0.07, 0.17).translate(0, 0.015, z), 0x5d9a45, 8));
    for (const x of [-0.375, -0.125, 0.125, 0.375]) {
      parts.push(paint(new THREE.OctahedronGeometry(0.06, 0).scale(1, 1.25, 1).translate(x + (z > 0 ? 0.06 : z < 0 ? -0.06 : 0), 0.13, z), colour, 8));
    }
  }
  return merge(parts);
}

/** Rice: four rows of slim green tufts standing in the flooded paddy, golden by autumn and cut by winter. */
function riceGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [];
  for (const z of [-0.375, -0.125, 0.125, 0.375]) {
    for (const x of [-0.4, -0.2, 0, 0.2, 0.4]) {
      parts.push(paint(new THREE.ConeGeometry(0.045, 0.2, 4).translate(x + z * 0.12, 0.09, z), 0x7fb84a, 5));
    }
  }
  return merge(parts);
}

/**
 * An oil palm, one a tile in a plantation's rows: a short stout trunk, a crown of long arching fronds and the
 * orange-red fruit bunches tucked under it. Evergreen: the fronds take no season (a crop of the hot country).
 */
function oilPalmGeometry(): THREE.BufferGeometry {
  const parts: THREE.BufferGeometry[] = [paint(new THREE.CylinderGeometry(0.045, 0.06, 0.34, 6).translate(0, 0.17, 0), 0x6b5236)];
  for (let f = 0; f < 9; f++) {
    const a = (f / 9) * Math.PI * 2;
    // a frond: a long flat blade rising from the crown and drooping out
    const blade = new THREE.BoxGeometry(0.34, 0.012, 0.075).translate(0.17, 0, 0).rotateZ(f % 2 ? 0.28 : -0.12).rotateY(a).translate(0, 0.36, 0);
    parts.push(paint(blade, f % 3 ? 0x3f7f34 : 0x4d9140, 1));
  }
  for (const a of [0.3, 2.4, 4.4]) parts.push(paint(new THREE.OctahedronGeometry(0.045, 0).translate(Math.cos(a) * 0.06, 0.3, Math.sin(a) * 0.06), 0xd2522a));
  return merge(parts);
}

export interface RegionPropGeometries {
  datePalm: THREE.BufferGeometry; canopy: THREE.BufferGeometry; acacia: THREE.BufferGeometry; baobab: THREE.BufferGeometry;
  cypress: THREE.BufferGeometry; olive: THREE.BufferGeometry; cherry: THREE.BufferGeometry; bamboo: THREE.BufferGeometry;
  windPine: THREE.BufferGeometry;
  shrub: THREE.BufferGeometry; heather: THREE.BufferGeometry; termiteMound: THREE.BufferGeometry; reeds: THREE.BufferGeometry;
  fern: THREE.BufferGeometry; haystack: THREE.BufferGeometry; stoneLantern: THREE.BufferGeometry; snowFence: THREE.BufferGeometry;
  beachHut: THREE.BufferGeometry; drystoneWall: THREE.BufferGeometry; iceberg: THREE.BufferGeometry; mooredBoat: THREE.BufferGeometry;
  oak: THREE.BufferGeometry; birch: THREE.BufferGeometry; willow: THREE.BufferGeometry; stonePine: THREE.BufferGeometry;
  redwood: THREE.BufferGeometry; lavender: THREE.BufferGeometry;
  hedge: THREE.BufferGeometry; tuft: THREE.BufferGeometry;
  wheat: THREE.BufferGeometry; maize: THREE.BufferGeometry; sunflower: THREE.BufferGeometry; pumpkin: THREE.BufferGeometry;
  tulipRed: THREE.BufferGeometry; tulipYellow: THREE.BufferGeometry; tulipPink: THREE.BufferGeometry; tulipWhite: THREE.BufferGeometry;
  tulipPurple: THREE.BufferGeometry; rice: THREE.BufferGeometry; oilPalm: THREE.BufferGeometry;
}
export function createRegionPropGeometries(): RegionPropGeometries {
  return {
    datePalm: datePalmGeometry(), canopy: canopyTreeGeometry(), acacia: acaciaGeometry(), baobab: baobabGeometry(),
    cypress: cypressGeometry(), olive: oliveGeometry(), cherry: cherryGeometry(), bamboo: bambooGeometry(), windPine: windPineGeometry(),
    shrub: shrubGeometry(), heather: heatherGeometry(), termiteMound: termiteMoundGeometry(), reeds: reedsGeometry(), fern: fernGeometry(),
    haystack: haystackGeometry(), stoneLantern: stoneLanternGeometry(), snowFence: snowFenceGeometry(), beachHut: beachHutGeometry(),
    drystoneWall: drystoneWallGeometry(), iceberg: icebergGeometry(), mooredBoat: mooredBoatGeometry(),
    oak: oakGeometry(), birch: birchGeometry(), willow: willowGeometry(), stonePine: stonePineGeometry(),
    redwood: redwoodGeometry(), lavender: lavenderGeometry(),
    hedge: hedgeGeometry(), tuft: tuftGeometry(),
    wheat: wheatGeometry(), maize: maizeGeometry(), sunflower: sunflowerGeometry(), pumpkin: pumpkinGeometry(),
    tulipRed: tulipGeometry(0xe0302a), tulipYellow: tulipGeometry(0xf5d22c), tulipPink: tulipGeometry(0xf27ab0),
    tulipWhite: tulipGeometry(0xf6f3ea), tulipPurple: tulipGeometry(0x7d3fb8), rice: riceGeometry(), oilPalm: oilPalmGeometry(),
  };
}
