import { hex, scale, type RGB } from '../../../world/biomes';
import type { Rng } from '../../../world/rng';
import type { RegionBuildingKind } from '../../../world/tiles';
import type { Sched } from '../../nightLights';
import { DARK, GLASS_LIGHT, METAL, WARM_GLOW, type Draw, type Kit } from '../kit';

/**
 * The Steppe: white felt gers with painted doors, an ovoo streaming blue scarves, a horse corral, a herders'
 * camp, and the colossal steel horseman on his colonnaded drum.
 */

const FELT = hex(0xf2efe6), FELT_SHADE = hex(0xe0dccf), ROPE = hex(0x9a7a52), CROWN = hex(0xd9682a);
const TIMBER = hex(0x7a5a3c), TIMBER_DARK = hex(0x5a4030), GRASS = hex(0x9aae62), WORN = hex(0xb8a878), HAY = hex(0xd9bc5a);
const SCARF = hex(0x2f6fd0), SCARF_LIGHT = hex(0x5f9ae8), CAIRN = hex(0x8e8e88), CAIRN_DARK = hex(0x73736e);
const STEEL = hex(0xb4bac0), STEEL_LIGHT = hex(0xd0d5da), STEEL_DARK = hex(0x8e969e), GOLD = hex(0xe0b040);
const PALE = hex(0xe8e2d2), PALE_SHADE = hex(0xcfc8b6), SHADOW = hex(0x6a6458);
const DOORS = [0xe0702a, 0x2f7fc8, 0xd9482f, 0xe8922a, 0x2a9a8a];
const HORSES = [0x7a4a2a, 0x2e2a28, 0xc2a070, 0x9a623a, 0x5a3a26, 0xd8d0c0];
const EVENING: Sched = [18, 23.5, 1.4];

/** Draw with the frame turned `yaw` about the local point (x, z): `draw` is handed that point in the turned frame. */
function about(k: Kit, x: number, z: number, yaw: number, draw: (lx: number, lz: number) => void): void {
  const c = Math.cos(yaw), s = Math.sin(yaw);
  k.turned(yaw, () => draw(x * c - z * s, x * s + z * c));
}

/** A ger of radius R: a white felt drum under a shallow cone, rope bands, a crown ring and stovepipe, a painted door to +z. */
function ger(k: Kit, x: number, z: number, R: number, door: RGB, y = 0.02): void {
  const wh = R * 0.62, rh = R * 0.42;
  k.cyl(x, y, z, R, wh, FELT, 12);
  k.band(x, z, y + wh, R * 1.05, y + wh + rh, R * 0.24, 12, FELT_SHADE);
  k.band(x, z, y + wh - 0.012, R * 1.05, y + wh, R * 1.05, 12, ROPE);
  k.cyl(x, y + wh + rh - 0.01, z, R * 0.26, 0.03, CROWN, 8, DARK);
  k.band(x, z, y + wh * 0.3, R * 1.012, y + wh * 0.3 + 0.022, R * 1.012, 12, ROPE);
  k.band(x, z, y + wh * 0.62, R * 1.012, y + wh * 0.62 + 0.022, R * 1.012, 12, ROPE);
  k.box(x + R * 0.12, y + wh + rh * 0.7, z - R * 0.1, 0.03, rh * 0.75 + 0.06, 0.03, DARK);
  // the door in its frame, a lit pane over it
  const dw = Math.max(0.1, R * 0.42), dh = wh * 0.86;
  k.box(x, y, z + R * 0.97, dw + 0.04, dh + 0.02, 0.05, scale(door, 0.7));
  k.box(x, y, z + R * 0.97 + 0.02, dw, dh, 0.03, door);
  k.pane(x, y + dh * 0.55, z + R * 0.97 + 0.035, dw * 0.5, dh * 0.25, 1, scale(door, 0.5), EVENING, WARM_GLOW);
}

/** A blocky horse facing `yaw` (0 faces +x), `s` times life size. */
function horse(k: Kit, x: number, z: number, yaw: number, s: number, col: RGB): void {
  about(k, x, z, yaw, (lx, lz) => {
    const dark = scale(col, 0.6);
    k.box(lx, 0.02 + 0.1 * s, lz, 0.22 * s, 0.09 * s, 0.085 * s, col);
    for (const a of [-1, 1]) for (const b of [-1, 1]) k.box(lx + a * 0.085 * s, 0.02, lz + b * 0.026 * s, 0.03 * s, 0.11 * s, 0.03 * s, dark);
    k.bar([lx + 0.085 * s, 0.02 + 0.16 * s, lz], [lx + 0.15 * s, 0.02 + 0.25 * s, lz], 0.03 * s, col);
    k.bar([lx + 0.14 * s, 0.02 + 0.265 * s, lz], [lx + 0.21 * s, 0.02 + 0.21 * s, lz], 0.024 * s, col);
    k.bar([lx + 0.07 * s, 0.02 + 0.2 * s, lz], [lx + 0.135 * s, 0.02 + 0.285 * s, lz], 0.012 * s, dark);
    k.bar([lx - 0.11 * s, 0.02 + 0.18 * s, lz], [lx - 0.15 * s, 0.02 + 0.06 * s, lz], 0.014 * s, dark);
  });
}

const horseCol = (r: Rng): RGB => hex(HORSES[Math.floor(r() * HORSES.length)]);
const doorCol = (r: Rng): RGB => hex(DOORS[Math.floor(r() * DOORS.length)]);

// ---- one ger (1 × 1) ----------------------------------------------------------------------------------

/** One ger: white felt, rope bands, a smoke ring and stovepipe, a bright door to the road. */
const yurt: Draw = (k, _W, _D, _b, r) => {
  const R = 0.3 + r() * 0.06;
  ger(k, (r() - 0.5) * 0.08, -0.06 + (r() - 0.5) * 0.06, R, r() < 0.6 ? hex(DOORS[r() < 0.5 ? 0 : 1]) : doorCol(r));
  // firewood or a milk churn by the door
  if (r() < 0.5) k.box(0.3, 0.02, 0.36, 0.14, 0.07, 0.08, TIMBER_DARK, TIMBER);
  else k.cyl(-0.3, 0.02, 0.36, 0.035, 0.09, METAL, 6);
};

// ---- the herders' camp (3 × 3) ------------------------------------------------------------------------

/** A herders' camp: gers of several sizes, a motorbike and a solar panel, horses at a rail, dung fuel, a small truck. */
const yurtCamp: Draw = (k, W, D, _b, r) => {
  const hw = W / 2, hd = D / 2;
  k.box(0, 0, 0.1, W - 0.9, 0.02, D - 1.0, WORN);
  ger(k, -0.75, -hd + 0.7, 0.44, doorCol(r));
  ger(k, 0.45, -hd + 0.6, 0.36, doorCol(r));
  ger(k, -hw + 0.55, 0.35, 0.33, doorCol(r));
  ger(k, hw - 0.55, -0.1, 0.3, doorCol(r));
  // a solar panel on a frame and a motorbike outside the big one
  const sx = -0.1, sz = -hd + 1.15;
  k.box(sx, 0.02, sz - 0.04, 0.03, 0.12, 0.03, METAL);
  k.quad([sx - 0.13, 0.08, sz + 0.07], [sx + 0.13, 0.08, sz + 0.07], [sx + 0.13, 0.2, sz - 0.07], [sx - 0.13, 0.2, sz - 0.07], hex(0x2a4a7a), [sx, 0, sz - 0.2]);
  k.quad([sx - 0.13, 0.075, sz + 0.07], [sx + 0.13, 0.075, sz + 0.07], [sx + 0.13, 0.195, sz - 0.07], [sx - 0.13, 0.195, sz - 0.07], METAL, [sx, 1, sz + 0.3]);
  const mx = -0.75, mz = -hd + 1.42;
  k.box(mx, 0.05, mz, 0.2, 0.06, 0.05, hex(0xc2412f));
  for (const s of [-1, 1]) k.cyl(mx + s * 0.09, 0.02, mz, 0.04, 0.035, DARK, 6);
  k.box(mx + 0.07, 0.11, mz, 0.02, 0.05, 0.1, DARK);
  // the hitching rail and two horses
  const rx = 0.25, rz = 0.75;
  for (const s of [-1, 1]) k.box(rx + s * 0.3, 0.02, rz, 0.035, 0.2, 0.035, TIMBER_DARK);
  k.box(rx, 0.19, rz, 0.68, 0.03, 0.03, TIMBER);
  horse(k, rx - 0.14, rz + 0.22, Math.PI / 2, 1.05, horseCol(r));
  horse(k, rx + 0.16, rz + 0.22, Math.PI / 2 + 0.2, 1.05, horseCol(r));
  // the stack of dung fuel, and a small truck
  for (let i = 0; i < 3; i++) k.box(-hw + 0.5, 0.02 + i * 0.05, -0.35, 0.3 - i * 0.07, 0.05, 0.22 - i * 0.05, i % 2 ? hex(0x5a4a38) : hex(0x6a5642));
  const tx = hw - 0.7, tz = hd - 0.45;
  k.box(tx, 0.02, tz, 0.4, 0.04, 0.2, DARK);
  k.box(tx + 0.13, 0.06, tz, 0.16, 0.15, 0.2, hex(0x3f7a9a));
  k.box(tx + 0.14, 0.14, tz, 0.145, 0.06, 0.205, GLASS_LIGHT);
  k.box(tx - 0.09, 0.06, tz, 0.28, 0.09, 0.2, TIMBER, TIMBER_DARK);
  // firewood by the second ger
  k.box(0.95, 0.02, -hd + 1.05, 0.16, 0.08, 0.1, TIMBER_DARK, TIMBER);
};

// ---- an ovoo (1 × 1) ----------------------------------------------------------------------------------

/** A sacred cairn: a cone of piled stones round a pole, blue prayer scarves streaming from it. */
const ovoo: Draw = (k, _W, _D, _b, r) => {
  k.band(0, 0, 0.02, 0.36, 0.2, 0.22, 9, CAIRN);
  k.band(0, 0, 0.2, 0.24, 0.36, 0.1, 8, CAIRN_DARK);
  k.cyl(0, 0.19, 0, 0.24, 0.012, CAIRN_DARK, 8);
  k.cyl(0, 0.35, 0, 0.1, 0.012, CAIRN, 8);
  for (let i = 0; i < 9; i++) {
    const a = r() * Math.PI * 2, d = 0.1 + r() * 0.24, s = 0.06 + r() * 0.05;
    k.box(Math.cos(a) * d, 0.02 + (0.36 - d) * 0.75 - 0.02, Math.sin(a) * d, s, s * 0.8, s, i % 2 ? hex(0xa3a39c) : CAIRN_DARK);
  }
  k.box(0, 0.3, 0, 0.03, 0.6, 0.03, TIMBER_DARK);
  // scarves tied round the pole and streaming off downwind, and a wrap of them round its foot
  k.cyl(0, 0.36, 0, 0.06, 0.12, SCARF, 6);
  const COLS = [SCARF, SCARF_LIGHT, SCARF, hex(0xf4f2ec), SCARF, hex(0xf2c14e), SCARF_LIGHT];
  for (let i = 0; i < 7; i++) {
    const y = 0.86 - i * 0.055, a = 0.3 + (r() - 0.5) * 0.9, len = 0.22 + r() * 0.16;
    const ex = Math.cos(a) * len, ez = Math.sin(a) * len, sag = 0.05 + r() * 0.1;
    k.quad([0, y, 0], [0, y - 0.045, 0], [ex, y - 0.045 - sag, ez], [ex, y - sag, ez], COLS[i], [ez, y - 1, -ex]);
    k.quad([0, y, 0], [0, y - 0.045, 0], [ex, y - 0.045 - sag, ez], [ex, y - sag, ez], scale(COLS[i], 0.85), [-ez, y + 1, ex]);
  }
};

// ---- the horse corral (3 × 2) -------------------------------------------------------------------------

/** A post-and-rail corral with horses in it, a hay pile and a trough, and a lean-to at the back. */
const horseCorral: Draw = (k, W, D, _b, r) => {
  const hw = W / 2 - 0.15, hd = D / 2 - 0.15;
  k.box(0, 0, 0, W - 0.3, 0.02, D - 0.3, WORN);
  // the rails, with a gate gap at the front
  const rail = (x0: number, z0: number, x1: number, z1: number) => {
    const n = Math.max(1, Math.round(Math.hypot(x1 - x0, z1 - z0) / 0.45));
    for (let i = 0; i <= n; i++) k.box(x0 + ((x1 - x0) * i) / n, 0.02, z0 + ((z1 - z0) * i) / n, 0.04, 0.2, 0.04, TIMBER_DARK);
    for (const y of [0.1, 0.18]) k.bar([x0, y, z0], [x1, y, z1], 0.012, TIMBER);
  };
  rail(-hw, -hd, hw, -hd);
  rail(-hw, -hd, -hw, hd);
  rail(hw, -hd, hw, hd);
  rail(-hw, hd, -0.1, hd);
  rail(0.45, hd, hw, hd);
  k.bar([-0.1, 0.18, hd], [0.3, 0.1, hd + 0.22], 0.012, TIMBER);
  // the lean-to: three plank walls and a tin skillion falling to the back
  const sx = -hw + 0.6, sz = -hd + 0.32;
  k.box(sx, 0.02, sz - 0.2, 0.9, 0.26, 0.04, TIMBER);
  for (const s of [-1, 1]) k.box(sx + s * 0.43, 0.02, sz, 0.04, 0.3, 0.44, TIMBER);
  k.quad([sx - 0.5, 0.27, sz - 0.27], [sx + 0.5, 0.27, sz - 0.27], [sx + 0.5, 0.36, sz + 0.27], [sx - 0.5, 0.36, sz + 0.27], hex(0x8e969e), [sx, 0, sz]);
  k.quad([sx - 0.5, 0.26, sz - 0.27], [sx + 0.5, 0.26, sz - 0.27], [sx + 0.5, 0.35, sz + 0.27], [sx - 0.5, 0.35, sz + 0.27], hex(0x6a7078), [sx, 1, sz]);
  for (const s of [-1, 1]) k.box(sx + s * 0.43, 0.02, sz + 0.22, 0.04, 0.33, 0.04, TIMBER_DARK);
  // hay, a trough, and the horses
  k.dome(hw - 0.4, 0.02, -hd + 0.35, 0.24, HAY, 8, 3);
  k.box(hw - 0.85, 0.02, -hd + 0.25, 0.22, 0.1, 0.16, scale(HAY, 0.92));
  k.box(0.3, 0.02, -hd + 0.2, 0.5, 0.09, 0.14, TIMBER_DARK, hex(0x6fa8c8));
  const spots: [number, number][] = [[-0.55, 0.15], [0.15, 0.4], [0.75, -0.05], [-0.1, -0.3], [0.95, 0.5]];
  spots.forEach(([x, z], i) => horse(k, x + (r() - 0.5) * 0.12, z + (r() - 0.5) * 0.12, r() * Math.PI * 2, 1.05, hex(HORSES[i % HORSES.length])));
};

// ---- the horseman (the wonder, 12 × 12) ---------------------------------------------------------------

/** The colossal steel horseman with his golden whip, on a two-storey colonnaded drum, steps and a gate before it, gers behind. */
const khanStatue: Draw = (k, W, D, _b, r) => {
  const hw = W / 2, hd = D / 2;
  k.box(0, 0, 0, W - 0.3, 0.02, D - 0.3, GRASS);
  k.cyl(0, 0.02, 0, 3.3, 0.02, WORN, 24);
  // the drum: a plinth, two storeys of dark wall behind pale columns, a floor between and a cornice over
  const R = 2.3;
  k.cyl(0, 0.02, 0, R + 0.35, 0.1, PALE_SHADE, 24);
  k.cyl(0, 0.12, 0, R - 0.22, 1.5, SHADOW, 24);
  k.cyl(0, 0.84, 0, R + 0.08, 0.08, PALE, 24);
  k.cyl(0, 1.58, 0, R + 0.14, 0.12, PALE, 24, PALE_SHADE);
  for (let i = 0; i < 36; i++) {
    const a = ((i + 0.5) / 36) * Math.PI * 2, x = Math.cos(a) * R, z = Math.sin(a) * R;
    k.box(x, 0.12, z, 0.09, 0.72, 0.09, PALE);
    k.box(x, 0.92, z, 0.09, 0.66, 0.09, PALE);
  }
  // lit windows round the upper storey, glimpsed between the columns
  for (let i = 0; i < 18; i++) {
    const a = (i / 18) * Math.PI * 2;
    k.glowBox(Math.cos(a) * (R - 0.22), 1.02, Math.sin(a) * (R - 0.22), 0.16, 0.34, 0.16, DARK, EVENING, WARM_GLOW);
  }
  // the wide steps up the front to the upper floor, and the door at their head
  for (let i = 0; i < 5; i++) k.box(0, 0.02, (R - 0.3 + 4.5 - i * 0.42) / 2, 2.6 - i * 0.04, (i + 1) * 0.168, 4.5 - i * 0.42 - (R - 0.3), PALE_SHADE, PALE);
  for (const s of [-1, 1]) k.box(s * 1.42, 0.02, 3.2, 0.2, 0.5, 2.6, PALE);
  k.box(0, 0.86, R - 0.16, 0.7, 0.62, 0.1, DARK);
  k.box(0, 1.48, R - 0.1, 1.0, 0.1, 0.2, GOLD);

  // the horseman, facing the road; everything in statue units off the roof of the drum
  const B = 1.7, S = 1.15;
  const sb = (x: number, y: number, z: number, w: number, h: number, d: number, col: RGB, top: RGB = col) => k.box(x * S, B + y * S, z * S, w * S, h * S, d * S, col, top);
  const sr = (a: [number, number, number], b: [number, number, number], rad: number, col: RGB) =>
    k.bar([a[0] * S, B + a[1] * S, a[2] * S], [b[0] * S, B + b[1] * S, b[2] * S], rad * S, col);
  k.box(0, B - 0.02, 0, 1.6 * S, 0.1, 3.0 * S, STEEL_DARK);
  // the horse: four legs, barrel, chest and quarters, neck, head, tail
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    sb(sx * 0.32, 0.05, sz * 0.88, 0.24, 1.4, 0.28, STEEL_DARK);
    sb(sx * 0.32, 0.05, sz * 0.88 + 0.03, 0.3, 0.16, 0.36, STEEL);
  }
  sb(0, 1.4, 0, 0.9, 0.9, 2.3, STEEL, STEEL_LIGHT);
  sb(0, 1.5, 1.05, 0.8, 0.95, 0.5, STEEL_LIGHT);
  sb(0, 1.5, -1.05, 0.96, 0.85, 0.45, STEEL, STEEL_LIGHT);
  sr([0, 2.15, 1.0], [0, 3.15, 1.5], 0.23, STEEL_LIGHT);
  sr([0, 2.3, 0.75], [0, 3.3, 1.22], 0.07, STEEL_DARK);
  sr([0, 3.25, 1.4], [0, 2.7, 2.1], 0.16, STEEL);
  for (const s of [-1, 1]) sb(s * 0.12, 3.4, 1.3, 0.08, 0.18, 0.08, STEEL_DARK);
  sr([0, 2.2, -1.2], [0, 0.9, -1.6], 0.13, STEEL_DARK);
  // the rider: legs down the flanks, a robed body, shoulders, head and pointed helmet
  for (const s of [-1, 1]) {
    sr([s * 0.5, 2.35, -0.15], [s * 0.6, 1.45, 0.3], 0.16, STEEL_DARK);
    sb(s * 0.6, 1.25, 0.38, 0.22, 0.2, 0.42, STEEL);
  }
  sb(0, 2.25, -0.2, 0.95, 0.35, 0.8, STEEL_DARK);
  sb(0, 2.6, -0.18, 0.78, 0.75, 0.5, STEEL_LIGHT);
  sb(0, 3.35, -0.18, 1.08, 0.26, 0.56, STEEL, STEEL_LIGHT);
  sb(0, 3.61, -0.16, 0.36, 0.36, 0.36, STEEL_LIGHT);
  k.cyl(0, B + 3.93 * S, -0.16 * S, 0.26 * S, 0.06 * S, STEEL_DARK, 8);
  k.cone(0, B + 3.99 * S, -0.16 * S, 0.2 * S, 0.34 * S, STEEL, 8);
  // arms: the left on the reins, the right holding the golden whip across the thigh
  sr([-0.52, 3.45, -0.18], [-0.42, 2.75, 0.45], 0.13, STEEL);
  sr([0.52, 3.45, -0.18], [0.72, 2.7, 0.3], 0.13, STEEL);
  sr([0.74, 2.95, 0.1], [0.86, 1.75, 0.95], 0.06, GOLD);
  sr([-0.42, 2.75, 0.45], [0, 2.95, 1.75], 0.025, STEEL_DARK);

  // the ceremonial gate at the front edge, and flags either side of it
  const gz = hd - 0.7;
  for (const s of [-1, 1]) {
    k.box(s * 1.25, 0.02, gz, 0.36, 1.25, 0.36, PALE);
    k.box(s * 1.25, 0.02, gz, 0.46, 0.14, 0.46, PALE_SHADE);
    k.box(s * 2.0, 0.02, gz, 0.9, 0.7, 0.26, PALE_SHADE, PALE);
  }
  k.box(0, 1.27, gz, 3.1, 0.22, 0.42, PALE, PALE_SHADE);
  k.box(0, 1.49, gz, 2.0, 0.16, 0.34, PALE_SHADE);
  k.box(0, 1.65, gz, 0.5, 0.2, 0.2, GOLD);
  const FLAGS = [0xc8322a, SCARF, 0xc8322a, SCARF] as const;
  [-4.2, -3.2, 3.2, 4.2].forEach((fx, i) => {
    const c = FLAGS[i];
    k.box(fx, 0.02, gz, 0.04, 1.7, 0.04, METAL);
    k.box(fx + 0.2, 1.42, gz, 0.36, 0.26, 0.015, typeof c === 'number' ? hex(c) : c);
  });
  // the ring of gers round the back
  for (let i = 0; i < 6; i++) {
    const a = Math.PI * (1.1 + (i / 5) * 0.8), d = hw - 1.05;
    ger(k, Math.cos(a) * d, Math.sin(a) * d * 0.98, 0.42 + r() * 0.08, doorCol(r));
  }
};

export const STEPPE_DRAW: Partial<Record<RegionBuildingKind, Draw>> = { yurtCamp, yurt, ovoo, horseCorral, khanStatue };
