import { cargoById, type CargoType } from '../cargoTypes';
import { valueOf } from '../cargo';
import { MADE_FIGURES } from './made';
import { recipeBook } from './recipes';

/**
 * The value ladder (docs/supplychains.html, "Money"): a load a plant makes is worth at least LADDER times what went
 * into it, measured at a 60-tile standard trip, compounding up the chain (books are paid for the paper, the paper
 * for the pulpwood). An island good keeps its own price as a floor. No made good is worth more than CAP at 60
 * tiles before pedigree, so with the most pedigree it still sits under a gold long-haul load ($5,000).
 */
export const LADDER = 1.6;
export const CAP = 3000;

const priced = (t: CargoType): CargoType => (MADE_FIGURES[t.id] ? { ...t, ...MADE_FIGURES[t.id] } : t);
/** What a kind is worth on the island's terms at 60 tiles, standard. */
export const islandValue = (t: CargoType): number => valueOf(priced(t), 60, 'standard', 200);

const memo = new Map<string, number>();
const busy = new Set<string>();

/** What a load of this id is worth made, at 60 tiles, standard, before pedigree. */
export function madeValue(id: string): number {
  const hit = memo.get(id);
  if (hit !== undefined) return hit;
  const t = cargoById(id);
  if (!t) return 0;
  const own = islandValue(t);
  if (busy.has(id)) return own;
  busy.add(id);
  let best = own;
  for (const rs of recipeBook().values()) for (const r of rs) {
    if (!r.takes.length || !r.makes.some((m) => m.id === id)) continue;
    // the cheapest of a slot's alternatives: what the plant could have been fed
    const ins = r.takes.reduce((s, slot) => s + slot.n * Math.min(...slot.ids.map((q) => madeValue(q))), 0);
    best = Math.max(best, LADDER * ins);
  }
  busy.delete(id);
  const v = Math.min(Math.max(own, CAP), best);
  memo.set(id, v);
  return v;
}

/** How much more a made load of this id is worth than the island's own: what `produce` multiplies by. */
export function madeScale(id: string): number {
  const t = cargoById(id);
  if (!t) return 1;
  return Math.max(1, madeValue(id) / Math.max(1, islandValue(t)));
}
