import { hex, scale } from '../../world/biomes';
import type { HomeKind, LandmarkKind } from '../../world/tiles';
import { FLOOR } from '../../world/towns';
import {
  BRICK, BRIGHT, CARS, COOL_GLOW, DARK, GLASS, GLASS_LIGHT, METAL, RED_LIGHT, ROOF_GREY, STONE, TAU, WARM_GLOW,
  WATER, WHITE, WOOD, car, cur, curArch, pick, row, styleGlass, styleRoof, styleTrim, styleWall, topOff, tower,
  tree, win, flatTop, roofOver, styledGable, type Draw, type Kit,
} from './kit';
import { clock } from './civic';
import { lorry } from './business';

/** Homes between a house and a tower, and the landmarks and works that punctuate a skyline. */

const DOORS = [0x5a3a28, 0x2f4d7a, 0x8a3a34, 0x3f5a3f, 0xe2b53a, 0x2bb3a3];
const HEDGE = hex(0x3f7d3a), THATCH = hex(0xc9a55a);

// ---- 77. bungalow ------------------------------------------------------------------------------

const bungalow: Draw = (k, _W, _D, b, r) => {
  const wall = styleWall(r), roof = styleRoof(r);
  k.box(-0.12, 0, -0.1, 0.62, 0.26, 0.5, wall);
  if (cur.form === 'flat' || cur.form === 'curved' || cur.form === 'low') roofOver(k, r, -0.12, 0.26, -0.1, 0.62, 0.5, wall, roof);
  else k.hip(-0.12, 0.26, -0.1, 0.72, 0.2, 0.6, roof);
  // the picture window and door
  win(k, b, r, -0.24, 0.07, 0.15, 0.24, 0.13, 1, GLASS_LIGHT);
  k.box(0.06, 0, 0.155, 0.08, 0.18, 0.02, pick(r, DOORS));
  // the carport with a car in it
  k.box(0.33, 0.24, -0.02, 0.26, 0.02, 0.6, roof);
  for (const sz of [-0.28, 0.24]) k.box(0.44, 0, sz, 0.025, 0.24, 0.025, WHITE);
  car(k, 0.33, 0.02, false, pick(r, CARS));
};

// ---- 78. cottage -------------------------------------------------------------------------------

const cottage: Draw = (k, _W, _D, b, r) => {
  const wall = pick(r, [0xf4efe4, 0xefe3c8, 0xe8dcc2]);
  const slate = curArch === 'victorian';
  const bw = 0.52, bd = 0.4, bz = -0.1, h = 0.26;
  k.box(0, 0, bz, bw, h, bd, wall);
  if (slate) k.gable(0, h, bz, bw + 0.06, 0.34, bd + 0.08, hex(0x4f4a52), wall);
  else if (cur.form) styledGable(k, r, 0, h, bz, bw + 0.06, 0.34, bd + 0.08, styleRoof(r), wall);
  else {
    // thatch: a steep roof with a rounded ridge
    k.gable(0, h - 0.02, bz, bw + 0.1, 0.34, bd + 0.14, THATCH, wall);
    k.bar([-bw / 2 - 0.02, h + 0.31, bz], [bw / 2 + 0.02, h + 0.31, bz], 0.035, scale(THATCH, 0.9));
  }
  for (const sx of [-1, 1]) k.box(sx * (bw / 2 - 0.04), h, bz, 0.07, 0.4, 0.08, pick(r, STONE));
  k.box(0, 0, bz + bd / 2 + 0.005, 0.08, 0.18, 0.02, pick(r, DOORS));
  for (const sx of [-0.16, 0.16]) win(k, b, r, sx, 0.08, bz + bd / 2, 0.1, 0.09, 1);
  // the dry-stone wall and roses
  k.box(0, 0, 0.42, 0.84, 0.07, 0.05, hex(0xa39a8c));
  for (let i = 0; i < 6; i++) k.dome(-0.35 + i * 0.14, 0.02, 0.33, 0.035, i % 2 ? hex(0xe86a92) : HEDGE, 5, 2);
};

// ---- 79. duplex --------------------------------------------------------------------------------

const duplex: Draw = (k, _W, _D, b, r) => {
  const wall = styleWall(r), roof = styleRoof(r), h = 0.46;
  k.box(0, 0, -0.1, 0.8, h, 0.48, wall);
  styledGable(k, r, 0, h, -0.1, 0.8 + cur.eaves, Math.max(0.12, cur.pitch * 0.7), 0.48 + cur.eaves, roof, wall);
  k.box(0, 0, 0.145, 0.015, h, 0.01, styleTrim());
  for (const sx of [-1, 1]) {
    k.box(sx * 0.08, 0, 0.145, 0.08, 0.18, 0.02, pick(r, DOORS));
    win(k, b, r, sx * 0.26, 0.08, 0.14, 0.14, 0.1, 1);
    win(k, b, r, sx * 0.2, 0.31, 0.14, 0.2, 0.1, 1);
    k.box(sx * 0.2, 0.002, 0.32, 0.16, 0.01, 0.3, hex(0xbdb6a8));
  }
};

// ---- 80. terrace row ---------------------------------------------------------------------------

const terraceRow: Draw = (k, W, _D, b, r) => {
  const wall = styleWall(r), roof = styleRoof(r), h = b.floors * FLOOR;
  const bw = W - 0.1, bd = 0.62, bz = -0.1;
  k.box(0, 0, bz, bw, h, bd, wall);
  styledGable(k, r, 0, h, bz, bw, Math.max(0.16, cur.pitch * 0.6), bd + 0.06, roof, wall);
  const n = 6, cell = bw / n;
  for (let i = 0; i < n; i++) {
    const x = -bw / 2 + cell * (i + 0.5);
    k.box(x - cell / 2, 0, bz + bd / 2 + 0.005, 0.01, h, 0.01, scale(wall, 0.9));
    k.box(x - cell * 0.22, 0, bz + bd / 2 + 0.01, 0.08, 0.18, 0.02, hex(DOORS[i % 2 ? 0 : 1 + (i % 4)]));
    // a bay window
    k.box(x + cell * 0.12, 0, bz + bd / 2 + 0.04, cell * 0.4, 0.22, 0.08, wall, roof);
    k.pane(x + cell * 0.12, 0.06, bz + bd / 2 + 0.08, cell * 0.34, 0.12, 1, GLASS, [17 + r() * 3, 20.5 + r() * 4, 1.3], WARM_GLOW);
    for (let f = 1; f < b.floors; f++) win(k, { ...b, kind: 'townhouse' }, r, x, 0.07 + f * FLOOR, bz + bd / 2, cell * 0.36, 0.12, 1);
    k.box(x, h + 0.08, bz, 0.06, 0.16, 0.1, pick(r, BRICK));
  }
};

// ---- 81. mansion -------------------------------------------------------------------------------

const mansion: Draw = (k, W, D, b, r) => {
  const wall = styleWall(r), roof = styleRoof(r), stone = pick(r, STONE), h = 2 * FLOOR + 0.06;
  const bz = -D / 2 + 0.55;
  k.box(0, 0, bz, 0.9, h, 0.6, wall);
  if (cur.form === 'flat') flatTop(k, r, 0, h, bz, 0.9, 0.6, wall);
  else k.hip(0, h, bz, 1.0, 0.28, 0.7, roof);
  for (const sx of [-1, 1]) {
    k.box(sx * 0.6, 0, bz - 0.05, 0.36, h - 0.1, 0.5, wall);
    if (cur.form === 'flat') flatTop(k, r, sx * 0.6, h - 0.1, bz - 0.05, 0.36, 0.5, wall);
    else k.hip(sx * 0.6, h - 0.1, bz - 0.05, 0.42, 0.2, 0.56, roof);
    for (let f = 0; f < 2; f++) win(k, b, r, sx * 0.6, 0.08 + f * FLOOR, bz + 0.2, 0.14, 0.12, 1);
  }
  for (let f = 0; f < 2; f++) row(k, b, r, 0, 0.08 + f * FLOOR, bz + 0.3, 0.7, 0.12, 3, 1);
  // the columned porch
  for (let i = 0; i < 4; i++) k.cyl(-0.2 + i * 0.133, 0, bz + 0.42, 0.02, h - 0.06, WHITE, 6);
  k.gable(0, h - 0.06, bz + 0.42, 0.5, 0.12, 0.2, roof, stone);
  // circular drive and fountain
  k.hoop(0, 0.004, 0.45, 0.4, 0.08, hex(0xd9c9a3), 14, 'xz');
  k.cyl(0, 0, 0.45, 0.12, 0.05, stone, 10);
  k.cyl(0, 0.02, 0.45, 0.1, 0.04, WATER, 10);
  // the pool, garage, gate and hedge
  k.box(W / 2 - 0.35, 0, D / 2 - 0.4, 0.4, 0.02, 0.5, WHITE);
  k.box(W / 2 - 0.35, 0.01, D / 2 - 0.4, 0.32, 0.02, 0.42, WATER);
  k.box(-W / 2 + 0.3, 0, D / 2 - 0.45, 0.38, 0.24, 0.4, wall, roof);
  k.box(-W / 2 + 0.3, 0, D / 2 - 0.245, 0.28, 0.18, 0.01, WHITE);
  for (const sx of [-1, 1]) {
    k.box(sx * 0.2, 0, D / 2 - 0.08, 0.06, 0.2, 0.06, stone);
    k.box(sx * (W / 4 + 0.15), 0, D / 2 - 0.08, W / 2 - 0.4, 0.14, 0.08, HEDGE);
  }
};

// ---- 82. retirement home -----------------------------------------------------------------------

const retirementHome: Draw = (k, W, D, b, r) => {
  const wall = styleWall(r), roof = styleRoof(r), h = 2 * FLOOR;
  const t = 0.55;
  // a U: back wing and two arms around a sheltered garden open to the front
  k.box(0, 0, -D / 2 + 0.1 + t / 2, W - 0.2, h, t, wall);
  styledGable(k, r, 0, h, -D / 2 + 0.1 + t / 2, W - 0.14, 0.18, t + 0.06, roof, wall);
  for (const sx of [-1, 1]) {
    const ax = sx * (W / 2 - 0.1 - t / 2), ad = D - 0.9 - t, az = -D / 2 + 0.1 + t + ad / 2;
    k.box(ax, 0, az, t, h, ad, wall);
    styledGable(k, r, ax, h, az, t + 0.06, 0.18, ad, roof, wall, true);
    for (let f = 0; f < 2; f++) row(k, b, r, ax - sx * t / 2, 0.08 + f * FLOOR, az, ad - 0.2, 0.12, 2, sx > 0 ? 2 : 0);
  }
  for (let f = 0; f < 2; f++) row(k, b, r, 0, 0.08 + f * FLOOR, -D / 2 + 0.1 + t, W - 1.4, 0.12, 4, 1);
  // the garden: benches and a pergola
  const gz = 0.1;
  for (let i = 0; i < 3; i++) k.box(-0.5 + i * 0.5, 0.2, gz, 0.02, 0.02, 0.6, WOOD);
  for (const sx of [-0.55, 0.55]) for (const sz of [-0.28, 0.28]) k.box(sx, 0, gz + sz, 0.025, 0.2, 0.025, WOOD);
  for (const sx of [-0.35, 0.35]) k.box(sx, 0.03, gz + 0.45, 0.22, 0.03, 0.06, WOOD);
  tree(k, 0, 0, gz - 0.1, 0.7, false);
  // the minibus at the door
  k.box(W / 2 - 0.35, 0.02, D / 2 - 0.25, 0.44, 0.2, 0.2, WHITE, WHITE);
  k.box(W / 2 - 0.35, 0.12, D / 2 - 0.25, 0.4, 0.06, 0.205, GLASS);
};

// ---- 83. trailer park --------------------------------------------------------------------------

const trailerPark: Draw = (k, W, D, _b, r) => {
  const bodies = [0xf4f2ec, 0xe8e2d4, 0xcfe0e8, 0xdbe8c9, 0xf6e7a8];
  for (const sz of [-D / 4, D / 4]) {
    for (let i = 0; i < 4; i++) {
      const x = -W / 2 + 0.4 + i * ((W - 0.8) / 3), col = pick(r, bodies);
      k.box(x, 0.03, sz, 0.26, 0.18, 0.56, col, hex(0xb9bdc2));
      k.box(x + 0.134, 0.08, sz + 0.1, 0.004, 0.06, 0.18, GLASS);
      k.box(x + 0.134, 0.03, sz - 0.12, 0.004, 0.14, 0.07, pick(r, DOORS));
      // striped awning
      k.box(x + 0.2, 0.18, sz - 0.05, 0.14, 0.01, 0.32, i % 2 ? pick(r, BRIGHT) : WHITE);
      if (r() < 0.4) {
        k.cyl(x - 0.05, 0.21, sz + 0.15, 0.004, 0.03, METAL, 4);
        k.dome(x - 0.05, 0.24, sz + 0.15, 0.03, WHITE, 6, 2);
      }
    }
  }
  // shower block and washing line
  k.box(W / 2 - 0.25, 0, 0, 0.3, 0.22, 0.4, hex(0xd8d2c6), ROOF_GREY);
  k.bar([-W / 2 + 0.2, 0.2, 0], [-W / 2 + 0.9, 0.2, 0], 0.004, WHITE);
  for (let i = 0; i < 4; i++) k.box(-W / 2 + 0.3 + i * 0.16, 0.14, 0, 0.08, 0.06, 0.004, pick(r, BRIGHT));
  for (const sx of [0.2, 0.9]) k.box(-W / 2 + sx, 0, 0, 0.015, 0.22, 0.015, METAL);
};

// ---- 84. courtyard block -----------------------------------------------------------------------

const courtyardBlock: Draw = (k, W, D, b, r) => {
  const wall = styleWall(r), glass = styleGlass(r), t = 0.8, f = b.floors;
  const hb: Parameters<typeof tower>[1] = { ...b, kind: 'apartment' };
  // the back and side ranges
  tower(k, hb, r, 0, 0, -D / 2 + 0.1 + t / 2, W - 0.2, t, f, wall, glass, 0.09);
  for (const sx of [-1, 1]) tower(k, hb, r, sx * (W / 2 - 0.1 - t / 2), 0, 0.1, t, D - 0.2 - t - 0.2, f, wall, glass, 0.09);
  // the road range, split by an arch through to the courtyard
  const fz = D / 2 - 0.1 - t / 2, gap = 0.4, side = (W - 0.2 - gap) / 2;
  for (const sx of [-1, 1]) tower(k, hb, r, sx * (gap / 2 + side / 2), 0, fz, side, t, f, wall, glass, 0.09);
  tower(k, hb, r, 0, FLOOR * 1.2, fz, gap + 0.02, t, f - 1, wall, glass, 0.09);
  k.hoop(0, FLOOR * 0.8, fz + t / 2 + 0.01, gap / 2, 0.02, styleTrim(), 8);
  const top = f * FLOOR;
  if (cur.pitch > 0.3) {
    styledGable(k, r, 0, top, -D / 2 + 0.1 + t / 2, W - 0.16, 0.2, t + 0.04, styleRoof(r), wall);
    styledGable(k, r, 0, top, fz, W - 0.16, 0.2, t + 0.04, styleRoof(r), wall);
  } else {
    k.box(0, top, -D / 2 + 0.1 + t / 2, W - 0.16, 0.05, t + 0.04, cur.form ? wall : styleTrim());
    k.box(0, top, fz, W - 0.16, 0.05, t + 0.04, cur.form ? wall : styleTrim());
  }
  // the inner garden
  tree(k, -0.25, 0, 0, 0.8, false);
  tree(k, 0.3, 0, 0.2, 0.7, false);
  for (let i = 0; i < 3; i++) k.box(-0.1 + i * 0.1, 0, -0.25, 0.01, 0.16, 0.01, hex(0xe2412f));
  k.box(0, 0.16, -0.25, 0.22, 0.01, 0.01, hex(0xe2412f));
};

// ---- 85. tower block ---------------------------------------------------------------------------

const towerBlock: Draw = (k, W, D, b, r) => {
  const concrete = pick(r, [0xb8b4ad, 0xa8a49c, 0xc4c0b8]);
  const bw = W - 0.7, bd = D - 1.0, bz = -0.2;
  const top = tower(k, { ...b, kind: 'apartment' }, r, 0, 0, bz, bw, bd, b.floors, concrete, hex(0x4a6878), 0.09);
  // balconies as a grid of little shelves on the front and back
  for (let f = 1; f < b.floors; f++) {
    for (let i = 0; i < 4; i++) {
      const x = -bw / 2 + 0.16 + (i * (bw - 0.32)) / 3;
      k.box(x, f * FLOOR, bz + bd / 2 + 0.05, 0.22, 0.05, 0.1, scale(concrete, 0.9));
      k.box(x, f * FLOOR, bz - bd / 2 - 0.05, 0.22, 0.05, 0.1, scale(concrete, 0.9));
    }
  }
  // the service core rising past the roof
  k.box(0, top, bz, 0.34, 0.4, 0.3, scale(concrete, 0.85));
  k.glowBox(0, top + 0.4, bz, 0.05, 0.05, 0.05, hex(0x882222), [17, 30, 2.4], RED_LIGHT);
  // the estate lawn with a path and a small play frame
  k.box(0, 0.004, D / 2 - 0.25, 0.14, 0.01, 0.5, hex(0xd9c9a3));
  for (let i = 0; i < 3; i++) k.box(W / 2 - 0.3 + (i % 2) * 0.1, 0, D / 2 - 0.35 + i * 0.1, 0.012, 0.18, 0.012, hex(0x2f7fb5));
  k.box(W / 2 - 0.25, 0.18, D / 2 - 0.25, 0.14, 0.012, 0.22, hex(0x2f7fb5));
};

// ---- 86. condo tower ---------------------------------------------------------------------------

const condoTower: Draw = (k, W, D, b, r, t) => {
  const accent = t?.accent !== undefined ? hex(t.accent) : pick(r, BRIGHT);
  const glass = pick(r, [0x8fb8c2, 0x9fc3cf, 0x7fb1cc]), frame = hex(0xf1f0ea);
  // a podium of shops in the city colour
  k.box(0, 0, 0, W - 0.2, FLOOR * 1.3, D - 0.2, frame);
  k.box(0, FLOOR * 1.3 - 0.05, D / 2 - 0.09, W - 0.2, 0.05, 0.02, accent);
  k.glowBox(0, 0.03, D / 2 - 0.095, W - 0.4, FLOOR * 0.9, 0.01, GLASS_LIGHT, [16.5, 22.5, 1.6], WARM_GLOW);
  const R = Math.min(W, D) / 2 - 0.35, h = b.floors * FLOOR, y0 = FLOOR * 1.3;
  k.cyl(0, y0, 0, R, h, glass, 16);
  // curved balconies ring each storey
  for (let f = 1; f < b.floors; f += 1) k.cyl(0, y0 + f * FLOOR - 0.02, 0, R + 0.06, 0.03, WHITE, 16);
  // window light, floor by floor
  for (let f = 0; f < b.floors; f += 2) {
    const s: [number, number, number] = r() < 0.2 ? [99, 0, 0] : [17 + r() * 4, 21 + r() * 5, 1.2];
    k.glowBox(0, y0 + f * FLOOR + 0.05, 0, R * 1.35, FLOOR * 1.6, R * 1.35, glass, s, WARM_GLOW);
  }
  // the rooftop pool
  k.cyl(0, y0 + h, 0, R + 0.04, 0.06, frame, 16);
  k.box(0, y0 + h + 0.05, 0, R * 0.9, 0.02, R * 0.6, WATER);
};

// ---- 87. comms tower ---------------------------------------------------------------------------

const commsTower: Draw = (k, _W, _D, _b, r) => {
  const red = hex(0xd23a2e), H = 2.8;
  // a tapering lattice mast
  for (let s = 0; s < 3; s++) {
    const a = (s / 3) * TAU;
    k.bar([Math.cos(a) * 0.28, 0, Math.sin(a) * 0.28], [Math.cos(a) * 0.04, H, Math.sin(a) * 0.04], 0.018, s === 0 ? red : WHITE);
  }
  for (let i = 1; i < 10; i++) {
    const f = i / 10, rr = 0.28 * (1 - f) + 0.04 * f, y = H * f;
    for (let s = 0; s < 3; s++) {
      const a0 = (s / 3) * TAU, a1 = ((s + 1) / 3) * TAU;
      k.bar([Math.cos(a0) * rr, y, Math.sin(a0) * rr], [Math.cos(a1) * rr, y, Math.sin(a1) * rr], 0.006, i % 2 ? red : WHITE);
    }
  }
  // three dishes
  for (let d = 0; d < 3; d++) {
    const a = (d / 3) * TAU + 0.5, y = H * (0.45 + d * 0.12);
    k.dome(Math.cos(a) * 0.16, y, Math.sin(a) * 0.16, 0.08, WHITE, 8, 2);
  }
  k.box(0.2, 0, 0.3, 0.3, 0.22, 0.24, hex(0xcfc9bc), ROOF_GREY);
  k.glowBox(0, H, 0, 0.06, 0.06, 0.06, hex(0x882222), [16.5, 30, 3], RED_LIGHT);
  k.glowBox(0, H * 0.5, 0, 0.12, 0.05, 0.12, hex(0x882222), [16.5, 30, 2.4], RED_LIGHT);
  void r;
};

// ---- 88. observation tower ---------------------------------------------------------------------

const observationTower: Draw = (k, _W, _D, _b, r, t) => {
  const accent = t?.accent !== undefined ? hex(t.accent) : pick(r, BRIGHT), concrete = hex(0xd8d4cc);
  const H = 5.4;
  k.cyl(0, 0, 0, 0.36, 0.2, concrete, 10);
  k.cyl(0, 0.2, 0, 0.12, H, concrete, 10);
  // the lift shaft, striped in the city colour
  for (let i = 0; i < 6; i++) k.box(0.13, 0.2 + i * (H / 6), 0, 0.05, H / 12, 0.08, accent);
  // the viewing gallery: a disc of glass under a shallow cone
  k.cyl(0, H - 0.2, 0, 0.5, 0.06, concrete, 16);
  k.cyl(0, H - 0.14, 0, 0.46, 0.22, GLASS_LIGHT, 16);
  k.glowBox(0, H - 0.12, 0, 0.8, 0.18, 0.8, GLASS_LIGHT, [16.5, 24, 1.8], COOL_GLOW);
  k.cone(0, H + 0.08, 0, 0.52, 0.2, concrete, 16);
  k.cyl(0, H + 0.28, 0, 0.03, 0.8, METAL, 5);
  k.glowBox(0, H + 1.08, 0, 0.08, 0.08, 0.08, hex(0x882222), [16, 30, 3.6], RED_LIGHT);
};

// ---- 89. clock tower ---------------------------------------------------------------------------

const clockTower: Draw = (k, _W, _D, _b, r) => {
  const stone = pick(r, STONE), roof = styleRoof(r), H = 1.6;
  k.box(0, 0, 0, 0.44, H, 0.44, stone);
  k.box(0, H * 0.35, 0, 0.47, 0.04, 0.47, scale(stone, 0.9));
  k.box(0, H, 0, 0.5, 0.06, 0.5, scale(stone, 0.9));
  k.hip(0, H + 0.06, 0, 0.5, 0.5, 0.5, roof);
  k.box(0, 0, 0.225, 0.12, 0.22, 0.02, hex(0x5a3a28));
  // a face on each side, each with hands that turn with the day clock
  for (let f = 0; f < 4; f++) {
    const saved = f;
    // clock() draws facing +z; turn the frame by drawing each face in its own rotated copy
    faceOn(k, saved, H - 0.26, 0.225, 0.14);
  }
};

/** A clock on side `side` (0 front, 1 right, 2 back, 3 left) of a square tower centred on the origin. */
function faceOn(k: Kit, side: number, y: number, half: number, r: number): void {
  k.turned(side * Math.PI / 2, () => clock(k, 0, y, half, r));
}

// ---- 90. parking garage ------------------------------------------------------------------------

const parkingGarage: Draw = (k, W, D, b, r) => {
  const concrete = hex(0xc4c0b8), floors = Math.max(3, b.floors), bw = W - 0.2, bd = D - 0.2;
  for (let f = 0; f <= floors; f++) {
    const y = f * FLOOR * 1.1;
    k.box(0, y, 0, bw, 0.05, bd, concrete);
    k.box(0, y + 0.05, bd / 2 - 0.02, bw, 0.06, 0.04, scale(concrete, 0.92));
    k.box(0, y + 0.05, -bd / 2 + 0.02, bw, 0.06, 0.04, scale(concrete, 0.92));
    if (f === floors) break;
    for (let i = 0; i < 4; i++) for (const sz of [-0.4, 0.4]) if (r() < 0.65) car(k, -bw / 2 + 0.35 + i * 0.36, sz, false, pick(r, CARS));
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * (bw / 2 - 0.05), y + 0.05, sz * (bd / 2 - 0.05), 0.08, FLOOR * 1.1 - 0.05, 0.08, concrete);
  }
  // the spiral ramp at one corner: a stack of turned wedges
  const rx = bw / 2 - 0.25, rz = -bd / 2 + 0.25;
  for (let f = 0; f < floors; f++) {
    k.cyl(rx, f * FLOOR * 1.1, rz, 0.28, 0.04, scale(concrete, 0.95), 10);
  }
  // the lit stair core
  k.box(-bw / 2 + 0.12, 0, bd / 2 - 0.12, 0.2, floors * FLOOR * 1.1 + 0.2, 0.2, hex(0xf2c14e));
  k.glowBox(-bw / 2 + 0.12, 0.05, bd / 2 - 0.015, 0.1, floors * FLOOR * 1.1, 0.01, GLASS_LIGHT, [16.5, 30, 1.6], COOL_GLOW);
};

// ---- 91. triumphal arch ------------------------------------------------------------------------

const triumphalArch: Draw = (k, W, D, _b, r) => {
  const stone = pick(r, STONE), bronze = hex(0x7a6a3a);
  const span = W - 0.3, pier = 0.3, H = 1.2, dd = Math.min(D - 0.2, 0.6);
  for (const sx of [-1, 1]) k.box(sx * (span / 2 - pier / 2), 0, 0, pier, H, dd, stone);
  // the vault between the piers
  const seg = 8, R = span / 2 - pier;
  for (let s = 0; s < seg; s++) {
    const a0 = (s / seg) * Math.PI, a1 = ((s + 1) / seg) * Math.PI;
    k.quad([Math.cos(a0) * R, H * 0.7 + Math.sin(a0) * 0.3, -dd / 2], [Math.cos(a1) * R, H * 0.7 + Math.sin(a1) * 0.3, -dd / 2],
      [Math.cos(a1) * R, H * 0.7 + Math.sin(a1) * 0.3, dd / 2], [Math.cos(a0) * R, H * 0.7 + Math.sin(a0) * 0.3, dd / 2], scale(stone, 0.9), [0, 5, 0]);
  }
  for (const sz of [-1, 1]) k.box(0, H * 0.7, sz * (dd / 2 - 0.02), span - 2 * pier, H * 0.3, 0.04, stone);
  // the attic with a relief band, and the statue group on top
  k.box(0, H, 0, span + 0.06, 0.34, dd + 0.04, stone);
  k.box(0, H + 0.12, dd / 2 + 0.025, span - 0.1, 0.1, 0.01, scale(stone, 0.8));
  k.box(0, H + 0.34, 0, span * 0.5, 0.06, dd * 0.6, stone);
  for (const sx of [-0.18, 0, 0.18]) {
    k.cyl(sx, H + 0.4, 0, 0.05, 0.22, bronze, 6);
    k.dome(sx, H + 0.62, 0, 0.05, bronze, 6, 2);
  }
};

// ---- 92. wind turbine --------------------------------------------------------------------------

/** A wind turbine on the origin; also drawn outside towns. */
export function turbine(k: Kit, seed: number): void {
  const H = 2.6;
  k.cyl(0, 0, 0, 0.09, H, WHITE, 8);
  k.cyl(0, 0, 0, 0.12, 0.06, hex(0xd8dcd6), 8);
  k.box(0, H - 0.02, -0.04, 0.12, 0.12, 0.3, WHITE);
  // the rotor turns at its own pace
  k.spin(0, H + 0.04, 0.14, 'z', 1.4 + (seed % 7) * 0.08, (s) => {
    s.dome(0, 0, 0, 0.05, WHITE, 6, 2);
    for (let i = 0; i < 3; i++) {
      const a = (i / 3) * TAU + seed;
      s.bar([0, 0, 0], [Math.cos(a) * 1.05, Math.sin(a) * 1.05, 0], 0.03, WHITE);
    }
  });
  // a slow red blink on the nacelle
  k.glowBox(0, H + 0.1, -0.12, 0.04, 0.04, 0.04, hex(0x882222), [17, 30, 2.4], RED_LIGHT);
  k.box(0.22, 0, 0.2, 0.14, 0.16, 0.1, hex(0xb9bdc2));
}

const windTurbine: Draw = (k, _W, _D, b) => turbine(k, b.seed);

// ---- 93. fuel depot ----------------------------------------------------------------------------

const fuelDepot: Draw = (k, W, D, _b, r) => {
  const stripe = hex(0xf2c14e);
  // the bund wall
  for (const [x, z, w, d] of [[0, -D / 2 + 0.12, W - 0.2, 0.06], [-W / 2 + 0.12, -0.1, 0.06, D - 0.6], [W / 2 - 0.12, -0.1, 0.06, D - 0.6]] as number[][]) {
    k.box(x, 0, z, w, 0.1, d, hex(0xb9b4aa));
  }
  // three big white tanks, one with a spiral stair
  const tanks: [number, number, number][] = [[-0.45, -0.45, 0.36], [0.45, -0.45, 0.36], [0, 0.25, 0.3]];
  tanks.forEach(([x, z, rr], i) => {
    k.cyl(x, 0, z, rr, 0.55, WHITE, 14);
    k.cyl(x, 0.55, z, rr + 0.005, 0.03, stripe, 14);
    k.cone(x, 0.58, z, rr, 0.06, hex(0xd8dcd6), 14);
    if (i === 0) {
      let prev: [number, number, number] = [x + rr + 0.03, 0, z];
      for (let s = 1; s <= 10; s++) {
        const a = (s / 10) * TAU * 0.8, p: [number, number, number] = [x + Math.cos(a) * (rr + 0.03), 0.055 * s, z + Math.sin(a) * (rr + 0.03)];
        k.bar(prev, p, 0.012, METAL);
        prev = p;
      }
    }
  });
  // the loading gantry with a tanker under it
  const gz = D / 2 - 0.35;
  for (const sx of [-0.3, 0.3]) k.box(sx, 0, gz, 0.04, 0.42, 0.04, stripe);
  k.box(0, 0.42, gz, 0.66, 0.05, 0.1, stripe);
  lorry(k, 0, gz, true, hex(0xe8e8e4));
  k.glowBox(0, 0.4, gz, 0.4, 0.02, 0.06, WHITE, [16.5, 30, 1.8], COOL_GLOW);
};

