/**
 * The Inbox (docs/social.html, "Messages and the inbox"): everything addressed to you, kept on the server until
 * read and for thirty days after, as threads by player. Notes left while you were away, whispers both ways, fleet
 * invites with a button to accept, asks to join your fleet with Let in and Not now, the answers to your own asks,
 * friend adds, and the server's own lines. A reply goes as a whisper when they are signed in and as a note when
 * they are not; your own lines are kept on this device (localStorage, per player), the server keeps theirs.
 *
 * Mute is here too (and on the card): a muted player's chat, notes, invites, asks and hearts never reach you, the
 * server sees to that. Report files the thread to the developer.
 */
import { esc } from '../game/cargoHud';
import type { SocialTabBody } from '../game/socialWindow';
import type { OnlineExtra } from './online';
import type { CellDoc, ClientMsg, ServerMsg, Welcome } from '../../shared/protocol';
import { NOTE_MAX, cleanNote, type InboxItem } from '../../shared/social';

/** One of my own lines, kept on this device. */
interface Sent { to: string; t: number; text: string; k: 'note' | 'w' }
/** A whisper to me while signed in (the server keeps notes; whispers pass through). */
interface Heard { from: string; name: string; t: number; text: string }
/** A line of a thread. */
interface Line { t: number; mine: boolean; text: string; item?: InboxItem; k: string }

const SENT_KEEP = 300, HEARD_KEEP = 200;
const SERVER = 'server';

export interface InboxHost {
  online(): boolean;
  me(): string | null;
  post(m: ClientMsg): void;
  /** Whisper through the chat (they are signed in). */
  whisper(name: string, text: string): void;
  /** Is this player signed in? */
  isOn(pid: string): boolean;
  /** A player's name, fleet's name and colour, as the game knows them. */
  nameOf(pid: string): { name: string; fleet: string; colour: number } | null;
  /** A player by name (case aside), as the game has heard of them. */
  findPlayer(name: string): { id: string; name: string } | null;
  /** Join with an invite code (signs out and in, then asks to confirm: net/crewMenu.ts joinWith). */
  join(code: string): string | null;
  /** A word in the social window's note line, and a card over the game when it is closed. */
  say(text: string): void;
  toast(title: string, body: string): void;
  openCard(pid: string): void;
}

export class Inbox implements OnlineExtra, SocialTabBody {
  onlineOnly = true;
  items: InboxItem[] = [];
  muted: { id: string; name: string }[] = [];
  private heard: Heard[] = [];
  private heardOnce = false;
  private pick: string | null = null;
  private sureReport = '';
  private draft = '';
  private seen = new Set<string>();
  /** The window redraws when the inbox changes. */
  onData: () => void = () => {};

  constructor(private host: InboxHost) {}

  // ---- the online session ----
  welcome(_w: Welcome): void { this.reset(); }
  cell(_k: string, _doc: CellDoc): void { /* nothing per cell */ }
  got(m: ServerMsg): boolean {
    if (m.t === 'inbox') {
      const fresh = this.heardOnce ? m.items.filter((i) => !this.seen.has(i.id) && !i.read) : [];
      this.items = m.items;
      this.muted = m.muted;
      for (const i of m.items) this.seen.add(i.id);
      this.heardOnce = true;
      for (const i of fresh) this.host.toast(TOAST[i.k] ?? 'In your inbox', `${i.name ?? 'The server'}${i.text ? `: ${i.text}` : ''} · I → Inbox`);
      this.onData();
      return true;
    }
    if (m.t === 'inboxSay') {
      this.host.say(m.text);
      // an open fleet: straight to the join (sign out, sign in, confirm)
      if (m.code) { const why = this.host.join(m.code); if (why) this.host.say(why); }
      return true;
    }
    // whispers pass through to the chat as ever, and are kept in their threads here
    if (m.t === 'chat' && (m.kind === 'w' || m.kind === 'wto') && m.from) {
      if (m.kind === 'w') { this.heard.push({ from: m.from, name: m.name ?? '', t: Date.now(), text: m.text }); if (this.heard.length > HEARD_KEEP) this.heard.shift(); }
      else this.keep({ to: this.toPid(m.to ?? '') ?? '', t: Date.now(), text: m.text, k: 'w' });
      this.onData();
    }
    return false;
  }
  ready(): void { this.host.post({ t: 'inbox' }); }
  frame(): void { /* nothing per frame */ }
  forget(): void { /* nothing per cell */ }
  reset(): void { this.items = []; this.muted = []; this.heard = []; this.heardOnce = false; this.seen.clear(); this.pick = null; }

  /** A whisper's "to" is a name; the thread is by player. */
  private toPid(name: string): string | null {
    const lower = name.toLowerCase();
    for (const i of this.items) if (i.from && i.name?.toLowerCase() === lower) return i.from;
    for (const h of this.heard) if (h.name.toLowerCase() === lower) return h.from;
    return this.host.findPlayer(name)?.id ?? null;
  }

  // ---- my own lines, on this device ----
  private key(): string { return `tinyfleet-sent:${this.host.me() ?? ''}`; }
  private sent(): Sent[] {
    try { return JSON.parse(localStorage.getItem(this.key()) ?? '[]') as Sent[]; } catch { return []; }
  }
  private keep(s: Sent): void {
    if (!s.to) return;
    const all = [...this.sent(), s].slice(-SENT_KEEP);
    try { localStorage.setItem(this.key(), JSON.stringify(all)); } catch { /* not kept on this device */ }
  }

  /** Unread items: the tab's badge. */
  badge(): number { return this.items.filter((i) => !i.read && !(i.k === 'ask' && i.done)).length; }

  /** Asks to join my fleet still waiting (the Shared Fleet tab's Requests). */
  asks(): InboxItem[] { return this.items.filter((i) => i.k === 'ask' && !i.done); }

  isMuted(pid: string): boolean { return this.muted.some((m) => m.id === pid); }

  /** Open on one player's thread (Message on a card). */
  show(pid: string): void { this.pick = pid; }

  /** Every thread: by player, newest first, with its last line and how many are unread. */
  private threads(): { id: string; t: number; last: string; unread: number; name: string }[] {
    const by = new Map<string, { t: number; last: string; unread: number; name: string }>();
    const touch = (id: string, t: number, last: string, unread: boolean, name?: string) => {
      const had = by.get(id) ?? { t: 0, last: '', unread: 0, name: '' };
      if (t >= had.t) { had.t = t; had.last = last; }
      if (unread) had.unread++;
      if (name && !had.name) had.name = name;
      by.set(id, had);
    };
    for (const i of this.items) touch(i.from ?? SERVER, i.t, summary(i), !i.read && !(i.k === 'ask' && i.done), i.from ? i.name : 'TinyFleet');
    for (const h of this.heard) touch(h.from, h.t, h.text, false, h.name);
    for (const s of this.sent()) touch(s.to, s.t, `You: ${s.text}`, false);
    if (this.pick && !by.has(this.pick)) touch(this.pick, 0, '', false);
    return [...by.entries()].map(([id, v]) => ({ id, ...v, name: v.name || this.host.nameOf(id)?.name || 'a player' })).sort((a, b) => b.t - a.t);
  }

  private lines(id: string): Line[] {
    const out: Line[] = [];
    for (const i of this.items) if ((i.from ?? SERVER) === id) out.push({ t: i.t, mine: false, text: i.text ?? '', item: i, k: i.k });
    for (const h of this.heard) if (h.from === id) out.push({ t: h.t, mine: false, text: h.text, k: 'w' });
    for (const s of this.sent()) if (s.to === id) out.push({ t: s.t, mine: true, text: s.text, k: s.k });
    return out.sort((a, b) => a.t - b.t);
  }

  // ---- the tab ----
  opened(): void { this.host.post({ t: 'inbox' }); }
  tick(): void { /* pushed by the server */ }
  typed(name: string, value: string): void { if (name === 'reply') this.draft = value; }

  press(target: HTMLElement): boolean {
    const p = target.closest('[data-ipick]') as HTMLElement | null;
    if (p) { this.pick = p.dataset.ipick!; this.sureReport = ''; this.markRead(); return true; }
    const b = target.closest('[data-iact]') as HTMLElement | null;
    if (!b) return false;
    const act = b.dataset.iact!, id = b.dataset.id ?? this.pick ?? '';
    if (act === 'join' && b.dataset.code) { const why = this.host.join(b.dataset.code); if (why) this.host.say(why); }
    else if (act === 'letin' || act === 'notnow') this.host.post({ t: 'crewAnswer', id, ok: act === 'letin' });
    else if (act === 'mute') this.host.post({ t: 'mute', id, on: true });
    else if (act === 'unmute') this.host.post({ t: 'mute', id, on: false });
    else if (act === 'card') this.host.openCard(id);
    else if (act === 'report') {
      if (this.sureReport !== id) { this.sureReport = id; return true; }
      this.sureReport = '';
      this.host.post({ t: 'reportPlayer', id, text: 'Reported from the inbox.' });
    } else if (act === 'send') this.send(b);
    else if (act === 'readall') this.host.post({ t: 'read', id: '*' });
    return true;
  }

  /** A reply: a whisper while they are signed in, else a note kept for them. */
  private send(b: HTMLElement): void {
    const input = b.closest('.ib-reply')?.querySelector<HTMLInputElement>('input[name="reply"]');
    const text = cleanNote(input?.value ?? this.draft);
    const id = this.pick;
    if (!text || !id || id === SERVER) return;
    const who = this.host.nameOf(id);
    if (this.host.isOn(id) && who) this.host.whisper(who.name, text);
    else { this.host.post({ t: 'note', to: id, text }); this.keep({ to: id, t: Date.now(), text, k: 'note' }); }
    this.draft = '';
    if (input) input.value = '';
  }

  /** The thread shown is read. */
  private markRead(): void {
    const id = this.pick;
    if (id && this.items.some((i) => (i.from ?? SERVER) === id && !i.read)) this.host.post({ t: 'read', id });
  }

  html(): { left: string; right: string } {
    const threads = this.threads();
    if (this.pick === null && threads.length) this.pick = threads[0].id;
    if (this.pick) this.markRead();
    const rows = threads.map((th) => {
      const c = th.id === SERVER ? 0x1f2b33 : this.host.nameOf(th.id)?.colour ?? 0x9aa6ad;
      return `<li class="${this.pick === th.id ? 'on' : ''}${th.unread ? ' unread' : ''}"><button type="button" class="pick" data-ipick="${esc(th.id)}"><i class="dot" style="background:#${c.toString(16).padStart(6, '0')}"></i>`
        + `<span class="what"><b>${esc(th.name)}</b><small>${esc(th.last.slice(0, 90))}</small></span>${th.unread ? `<em class="ib-n">${th.unread}</em>` : ''}</button></li>`;
    }).join('');
    const muted = this.muted.length ? `<div class="ib-muted"><h4>Muted <small>${this.muted.length}</small></h4>${this.muted.map((m) => `<p><b>${esc(m.name)}</b> <button type="button" class="link" data-iact="unmute" data-id="${esc(m.id)}">Unmute</button></p>`).join('')}</div>` : '';
    const unread = this.badge();
    const left = `<div class="lead">${unread ? `<b>${unread}</b> new · <button type="button" class="link" data-iact="readall">mark all read</button>` : 'Notes, invites, asks and whispers, by player.'}</div>
      <ul class="fleets inbox">${rows || '<li class="none">Nothing yet. Notes left for you while you were away, fleet invites and asks to join your fleet all arrive here.</li>'}</ul>${muted}
      <p class="foot">Kept for thirty days. Message a player from their card (I → Fleets); a whisper to somebody signed out comes here as a note.</p>`;
    return { left, right: this.pick ? this.threadHtml(this.pick) : '' };
  }

  private threadHtml(id: string): string {
    const who = id === SERVER ? null : this.host.nameOf(id);
    const name = id === SERVER ? 'TinyFleet' : who?.name ?? this.threads().find((t) => t.id === id)?.name ?? 'a player';
    const on = id !== SERVER && this.host.isOn(id);
    const muted = this.isMuted(id);
    const lines = this.lines(id).map((l) => this.lineHtml(l, id)).join('');
    const sure = this.sureReport === id;
    const acts = id === SERVER ? '' : `<div class="fc-acts"><button type="button" class="fc-btn" data-iact="card" data-id="${esc(id)}">Their card</button>`
      + `<button type="button" class="fc-btn" data-iact="${muted ? 'unmute' : 'mute'}" data-id="${esc(id)}">${muted ? 'Unmute' : '🔇 Mute'}</button>`
      + `<button type="button" class="fc-btn${sure ? ' warn' : ''}" data-iact="report" data-id="${esc(id)}">${sure ? 'Sure? Report them' : '⚑ Report'}</button></div>`;
    const reply = id === SERVER || muted ? '' : `<div class="ib-reply"><input type="text" name="reply" maxlength="${NOTE_MAX}" value="${esc(this.draft)}" placeholder="${on ? `Whisper to ${esc(name)}` : `Leave ${esc(name)} a note`}" spellcheck="true" autocomplete="off">`
      + `<button type="button" class="fc-btn on" data-iact="send">${on ? 'Whisper' : 'Leave note'}</button></div>`;
    return `<div class="fcard thread"><header class="fc-head"><div><h3>${esc(name)}</h3><div class="fc-who">${id === SERVER ? 'the server’s own lines' : on ? '<i class="on"></i> signed in: replies go as whispers' : 'not signed in: replies wait for them as notes'}</div></div></header>`
      + `${acts}<div class="ib-lines">${lines || '<p class="none">Nothing yet.</p>'}</div>${reply}</div>`;
  }

  private lineHtml(l: Line, id: string): string {
    const when = new Date(l.t).toLocaleString(undefined, { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' });
    const i = l.item;
    let body = esc(l.text);
    let extra = '';
    if (i?.k === 'invite') {
      body = `<b>Invite to ${esc(i.fleet ?? 'their fleet')}</b>${i.text ? ` · ${esc(i.text)}` : ''}`;
      extra = i.done ? `<small class="ib-done">${i.done === 'yes' ? 'used' : 'let go'}</small>` : i.code ? `<button type="button" class="fc-btn on" data-iact="join" data-code="${esc(i.code)}">Accept: join ${esc(i.fleet ?? 'them')}</button><small> signs you out and back in to confirm; good for a week</small>` : '';
    } else if (i?.k === 'ask') {
      body = `<b>Asks to join your fleet</b>${i.text ? ` · “${esc(i.text)}”` : ''}`;
      extra = i.done ? `<small class="ib-done">${i.done === 'yes' ? 'let in' : 'not now'}</small>`
        : `<button type="button" class="fc-btn on" data-iact="letin" data-id="${esc(id)}">Let in</button><button type="button" class="fc-btn" data-iact="notnow" data-id="${esc(id)}">Not now</button>`;
    } else if (i?.k === 'answer') body = `<b>${esc(i.fleet ?? 'They')}</b> answered your ask: ${esc(i.text ?? '')}`;
    else if (i?.k === 'friend') body = `<i>${esc(i.text ?? 'added you as a friend')}</i>`;
    const tag = l.k === 'w' ? 'whisper' : l.k === 'note' ? 'note' : '';
    return `<div class="ib-line${l.mine ? ' mine' : ''}"><div class="ib-b">${body}${extra ? `<div class="ib-x">${extra}</div>` : ''}</div><small>${esc(when)}${tag ? ` · ${tag}` : ''}</small></div>`;
  }
}

const TOAST: Record<InboxItem['k'], string> = { note: 'A note for you', invite: 'An invite', ask: 'An ask to join your fleet', answer: 'An answer', friend: 'A new friend', sys: 'In your inbox' };

function summary(i: InboxItem): string {
  if (i.k === 'invite') return `Invite to ${i.fleet ?? 'their fleet'}${i.done ? ' (done)' : ''}`;
  if (i.k === 'ask') return `Asks to join${i.done ? (i.done === 'yes' ? ': let in' : ': not now') : ''}`;
  if (i.k === 'answer') return `Answered: ${i.text ?? ''}`;
  if (i.k === 'friend') return i.text ?? 'added you as a friend';
  return i.text ?? '';
}
