import type { Pid } from './protocol';

/**
 * Postcards (docs/postcards.html, phase 2): a spot in the world and how the camera stood on it, kept by
 * the server under a short id, so a clip's corner can carry a link that takes whoever opens it there.
 * Imported by the game, the server and the gate; nothing here touches the DOM or Node.
 */

export const POSTCARD = {
  /** New postcards a player may make in a day (real time). Updating one is free. */
  perDay: 20,
  /** Postcards a player keeps: making one past this lets the oldest go. */
  keep: 200,
  titleMax: 80,
  idLen: 5,
  /** A take this far (tiles) from the camera session's postcard makes a new one rather than moving it. */
  apart: 48,
  /** The postcard's picture (its link preview): the longest side in pixels, the most base64 accepted, and the reports that hide it. */
  picSide: 960, picMax: 220_000, picReports: 3,
} as const;

/** 31 letters and digits with nothing to misread off a video: no i, l, o, 0 or 1. */
export const ID_ALPHABET = 'abcdefghjkmnpqrstuvwxyz23456789';
const ID = new RegExp(`^[${ID_ALPHABET}]{${POSTCARD.idLen}}$`);
export const isCardId = (s: unknown): s is string => typeof s === 'string' && ID.test(s);

/** Where the camera stood: the point it looked at (world tiles), its turn, tilt and distance, the look, and the hour it was lit at. */
export interface CardPose {
  x: number; z: number; y: number;
  yaw: number; pitch: number; dist: number;
  /** The camera mode's look: 0 as played, 1 miniature, 2 clear. */
  look: number;
  hour: number;
  /** The camera was on the maker's own vehicle: opened while they are signed in, it rides with them. */
  follow?: boolean;
}

/** A postcard as the server keeps it. */
export interface Postcard extends CardPose {
  id: string; by: Pid; title: string;
  /** Made, in ms; and the world it was made in. */
  at: number; epoch: number;
  /** Times opened (once an address a day), and fleets made from it (phase 3). */
  opens: number; rides: number;
  /** Taken down by its maker: the link says so. */
  gone?: boolean;
  /** When its picture (the link preview) was last sent, in ms; absent with none. */
  pic?: number;
  /** Reports of its picture (once an address), and whether that hid it until the developer looks (docs/postcards.html). */
  reports?: number;
  /** Who reported the picture: a short hash of each address, so one address reports it once, ever (server only). */
  reportedBy?: string[];
  picHidden?: boolean;
}

/** A picture as sent: base64 of a JPEG, nothing else. */
export const isJpeg = (b64: unknown): b64 is string => typeof b64 === 'string' && b64.length > 100 && b64.length <= POSTCARD.picMax && b64.startsWith('/9j/') && /^[A-Za-z0-9+/=]+$/.test(b64);

/** A postcard as anyone who opens its link is told: the maker by fleet name and colour only. */
export interface PostcardView extends CardPose {
  id: string; title: string; epoch: number; at: number;
  fleet: string; colour: number;
  /** The maker's id, for following them when they are signed in. */
  by: Pid;
  /** The world's epoch now: a postcard from an earlier one can't be gone to. */
  now: number;
  /** It has a picture showing (the guest bar offers to report it). */
  pic?: boolean;
}

const num = (v: unknown, lo: number, hi: number): number | null =>
  typeof v === 'number' && Number.isFinite(v) ? Math.min(hi, Math.max(lo, v)) : null;

/** A pose off the wire, every number made finite and kept in bounds; null when it isn't one. */
export function cleanPose(raw: unknown): CardPose | null {
  if (!raw || typeof raw !== 'object') return null;
  const r = raw as Record<string, unknown>;
  const W = 1 << 22;
  const x = num(r.x, -W, W), z = num(r.z, -W, W), y = num(r.y, -500, 5000);
  const yaw = num(r.yaw, -1e4, 1e4), pitch = num(r.pitch, 0, Math.PI / 2), dist = num(r.dist, 2, 2000);
  const look = num(r.look, 0, 2), hour = num(r.hour, 0, 24);
  if (x === null || z === null || yaw === null || pitch === null || dist === null) return null;
  const tau = Math.PI * 2;
  return {
    x: Math.round(x * 100) / 100, z: Math.round(z * 100) / 100, y: Math.round((y ?? 0) * 100) / 100,
    yaw: Math.round((((yaw % tau) + tau) % tau) * 1000) / 1000, pitch: Math.min(Math.round(pitch * 1000), Math.floor((Math.PI / 2) * 1000)) / 1000, dist: Math.round(dist * 10) / 10,
    look: Math.round(look ?? 1), hour: Math.round((hour ?? 12) * 100) / 100,
    ...(r.follow === true ? { follow: true } : {}),
  };
}

/** A title off the wire: one line, no control characters, at most titleMax. */
export function cleanTitle(raw: unknown): string {
  return String(raw ?? '').replace(/[\u0000-\u001f\u007f<>]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, POSTCARD.titleMax);
}

/** A new id. `rnd` gives 0..1. */
export function newCardId(rnd: () => number): string {
  let s = '';
  for (let i = 0; i < POSTCARD.idLen; i++) s += ID_ALPHABET[Math.floor(rnd() * ID_ALPHABET.length) % ID_ALPHABET.length];
  return s;
}
