import { hex, scale, type RGB } from '../../world/biomes';
import { ranchBrand, type RanchKind } from '../../world/ranchKinds';
import type { Sched } from '../nightLights';
import { DARK, TAU, WARM_GLOW, WHITE, type Draw, type Kit } from './kit';

/**
 * A ranch's own (world/ranchKinds.ts, world/ranches.ts): the log arch over the gate with the ranch's name burned
 * into a board hung under it and a longhorn skull on top, the hands' bunkhouse with its porch and stovepipe, the
 * open-sided hay barn stacked with bales, and the round corral with its snubbing post and trough. Weathered pine,
 * tin roofs, dust.
 */

const LOG = hex(0x8a6440), LOG_DARK = hex(0x6a4a2e), BOARD = hex(0x5a3e26), PLANK = hex(0x9a7650), PLANK_DARK = hex(0x7e5e3c);
const TIN = hex(0x9a9e9c), TIN_DARK = hex(0x7e8280), RUST = hex(0x9a5a3a), BONE = hex(0xeee6d2), HORN = hex(0xd8c8a0);
const HAY = hex(0xd9b85a), HAY_DARK = hex(0xb8963e), DUST = hex(0xc8a878), IRON = hex(0x3a3a3c), WATER = hex(0x5f9fbf);
const LETTER = hex(0xf2e2c0);
const EVENING: Sched = [18, 23.5, 1.4];
/** What the atlas can spell (render/buildings/signGlyphs.ts): capitals, digits, a few marks; a space is a gap. */
const SPELLS = /[A-Z0-9&'\-.! ]/;

/** The ranch's name across the board, read the right way round from both sides. */
function brand(k: Kit, text: string, y: number, z: number, cell: number, width: number): void {
  if (k.mode === 'derelict') return;
  const chars = [...text.toUpperCase()].filter((c) => SPELLS.test(c));
  const c = Math.min(cell, width / Math.max(1, chars.length));
  const x0 = -(chars.length * c) / 2;
  chars.forEach((ch, i) => {
    if (ch === ' ') return;
    const xa = x0 + i * c + c * 0.06, xb = xa + c * 0.88, yt = y + c * 1.05;
    // the front, seen from +z; and the back, seen from the yard, mirrored so it reads too
    k.glyph(ch, [xa, y, z + 0.018], [xb, y, z + 0.018], [xb, yt, z + 0.018], [xa, yt, z + 0.018], LETTER);
    k.glyph(ch, [-xa, y, z - 0.018], [-xb, y, z - 0.018], [-xb, yt, z - 0.018], [-xa, yt, z - 0.018], LETTER);
  });
}

/** A small horse standing at (x, z), its nose along yaw. */
function horse(k: Kit, x: number, z: number, yaw: number, col: RGB): void {
  const c = Math.cos(yaw), s = Math.sin(yaw);
  const at = (u: number, v: number): [number, number] => [x + u * c + v * s, z - u * s + v * c];
  const body = at(0, 0), rump = at(0, -0.06), head = at(0, 0.14);
  k.box(body[0], 0.1, body[1], 0.07, 0.07, 0.07, col);
  k.box(rump[0], 0.1, rump[1], 0.07, 0.07, 0.07, col);
  for (const [u, v] of [[-0.025, -0.06], [0.025, -0.06], [-0.025, 0.04], [0.025, 0.04]]) {
    const p = at(u, v);
    k.box(p[0], 0, p[1], 0.018, 0.1, 0.018, scale(col, 0.8));
  }
  k.bar([body[0], 0.16, body[1]], [head[0], 0.22, head[1]], 0.02, col);
}

// ---- the arch over the gate (3 × 1) ------------------------------------------------------------------------

const ranchGate: Draw = (k, W, _D, b) => {
  const px = W / 2 - 0.3, H = 1.0;
  // two peeled logs, a third across their tops
  for (const sx of [-1, 1]) {
    k.cyl(sx * px, 0, 0, 0.065, H, LOG, 8, LOG_DARK);
    // a brace from each post out along the fence line
    k.bar([sx * px, 0.5, 0], [sx * (px + 0.24), 0.02, 0], 0.025, LOG_DARK);
    // and a stub of rail either side of it, where the fence comes in
    for (const y of [0.09, 0.17]) k.box(sx * (px + 0.17), y, 0.0, 0.34, 0.045, 0.045, PLANK);
  }
  k.box(0, H - 0.02, 0, 2 * px + 0.3, 0.09, 0.1, LOG_DARK);
  // the board, hung on two chains under the beam, with the name burned in
  const by = H - 0.36;
  for (const sx of [-1, 1]) k.bar([sx * (px - 0.2), H - 0.02, 0], [sx * (px - 0.2), by + 0.2, 0], 0.008, IRON);
  k.box(0, by, 0, 2 * px - 0.25, 0.2, 0.03, BOARD);
  brand(k, ranchBrand(b.seed), by + 0.035, 0, 0.13, 2 * px - 0.4);
  // a longhorn's skull on top
  k.box(0, H + 0.07, 0.02, 0.07, 0.07, 0.05, BONE);
  k.box(0, H + 0.04, 0.05, 0.04, 0.05, 0.05, BONE);
  for (const sx of [-1, 1]) {
    k.bar([sx * 0.03, H + 0.12, 0.02], [sx * 0.2, H + 0.16, 0.02], 0.014, HORN);
    k.bar([sx * 0.2, H + 0.16, 0.02], [sx * 0.26, H + 0.24, 0.02], 0.01, HORN);
  }
  // the cattle grid under it, laid over the lane's surface: a pit, and steel bars across the way in
  k.box(0, 0.03, 0, 0.78, 0.006, 0.8, IRON);
  for (let i = 0; i < 7; i++) k.box(0, 0.036, -0.33 + i * 0.11, 0.78, 0.012, 0.035, TIN);
};

// ---- the bunkhouse (2 × 1) ---------------------------------------------------------------------------------

const bunkhouse: Draw = (k, W, D, _b, r) => {
  const bw = W - 0.2, bd = D - 0.42, bz = -0.12;
  // board and batten on a low stone footing, a tin roof
  k.box(0, 0, bz, bw, 0.05, bd, hex(0x8a847a));
  k.box(0, 0.05, bz, bw - 0.02, 0.3, bd - 0.02, PLANK);
  for (let i = 0; i < 9; i++) k.box(-bw / 2 + 0.1 + i * ((bw - 0.2) / 8), 0.05, bz + bd / 2, 0.015, 0.3, 0.005, PLANK_DARK);
  k.gable(0, 0.35, bz, bw + 0.12, 0.2, bd + 0.12, TIN, PLANK_DARK);
  // the porch along the front: a deck, posts and a shed roof
  const pz = bz + bd / 2 + 0.13;
  k.box(0, 0.02, pz, bw, 0.03, 0.26, PLANK_DARK);
  for (const x of [-bw / 2 + 0.05, 0, bw / 2 - 0.05]) k.box(x, 0.05, pz + 0.11, 0.035, 0.27, 0.035, LOG);
  k.wedge(0, 0.3, pz, bw + 0.04, 0.05, 0.3, TIN_DARK);
  // a door, windows lit after dark, a bench and a stovepipe
  k.box(0.12, 0.05, bz + bd / 2 + 0.003, 0.12, 0.22, 0.006, BOARD);
  for (const x of [-0.58, -0.28, 0.45]) k.pane(x, 0.15, bz + bd / 2 + 0.006, 0.13, 0.11, 1, DARK, EVENING, WARM_GLOW);
  k.box(-0.42, 0.05, pz + 0.02, 0.32, 0.05, 0.07, LOG_DARK);
  k.cyl(bw / 2 - 0.22, 0.42, bz - 0.08, 0.025, 0.22, IRON, 6);
  // and a hitching rail out front, a saddle over it now and then
  for (const sx of [-1, 1]) k.box(sx * 0.35, 0, D / 2 - 0.04, 0.03, 0.14, 0.03, LOG);
  k.box(0, 0.13, D / 2 - 0.04, 0.76, 0.025, 0.025, LOG);
  if (r() < 0.6) k.box(-0.15, 0.12, D / 2 - 0.04, 0.09, 0.05, 0.07, hex(0x6a3a20));
};

// ---- the hay barn (2 × 2) ----------------------------------------------------------------------------------

const hayBarn: Draw = (k, W, D, _b, r) => {
  const hw = W / 2 - 0.2, hd = D / 2 - 0.25, H = 0.62;
  // six poles under a high tin roof, open on every side
  for (const x of [-hw, 0, hw]) for (const z of [-hd, hd]) k.box(x, 0, z, 0.06, H, 0.06, LOG);
  k.box(0, H, -hd, 2 * hw + 0.06, 0.05, 0.06, LOG_DARK);
  k.box(0, H, hd, 2 * hw + 0.06, 0.05, 0.06, LOG_DARK);
  k.gable(0, H + 0.05, 0, 2 * hw + 0.3, 0.2, 2 * hd + 0.3, r() < 0.4 ? RUST : TIN, TIN_DARK);
  // the hay: square bales stacked to the rafters at the back, fewer at the front
  const rows = 3;
  for (let row = 0; row < rows; row++) {
    const z = -hd + 0.18 + row * 0.26, high = rows - row + 1;
    for (let lvl = 0; lvl < high; lvl++) {
      for (let i = 0; i < 5; i++) {
        const x = -hw + 0.2 + i * ((2 * hw - 0.4) / 4);
        k.box(x, lvl * 0.12, z, 0.24, 0.12, 0.22, (i + lvl + row) % 3 ? HAY : HAY_DARK);
      }
    }
  }
  // round bales out front, standing and lying
  k.cyl(-0.45, 0, D / 2 - 0.14, 0.11, 0.14, HAY, 10, HAY_DARK);
  k.cyl(-0.18, 0, D / 2 - 0.12, 0.11, 0.14, HAY_DARK, 10, HAY);
  k.cyl(0.45, 0, D / 2 - 0.16, 0.11, 0.14, HAY, 10, HAY_DARK);
  // a pitchfork against a pole
  k.bar([hw - 0.06, 0, hd + 0.06], [hw - 0.02, 0.4, hd + 0.04], 0.008, LOG_DARK);
};

// ---- the round corral (3 × 3) -----------------------------------------------------------------------------

const ranchCorral: Draw = (k, W, _D, b, r) => {
  const R = W / 2 - 0.22, n = 20;
  // the trodden dirt inside it
  k.disc(0, 0.004, 0, R - 0.02, DUST, 20);
  // posts round the ring, three rails between them, a gap at the back where the gate stands open
  const post = (a: number) => [Math.sin(a) * R, Math.cos(a) * R] as const;
  for (let i = 0; i < n; i++) {
    const a0 = (i / n) * TAU, a1 = ((i + 1) / n) * TAU;
    const [x0, z0] = post(a0), [x1, z1] = post(a1);
    k.box(x0, 0, z0, 0.05, 0.3, 0.05, LOG_DARK);
    // the gate: the panel nearest the back (-z) swung out
    if (i === n / 2 - 1 || i === n / 2) continue;
    for (const y of [0.1, 0.18, 0.26]) k.bar([x0, y, z0], [x1, y, z1], 0.014, PLANK);
  }
  const [gx, gz] = post(Math.PI);
  k.bar([gx, 0.18, gz], [gx + 0.4, 0.18, gz - 0.2], 0.014, PLANK);
  k.bar([gx, 0.1, gz], [gx + 0.4, 0.1, gz - 0.2], 0.014, PLANK);
  // the snubbing post in the middle, a trough by the rail, a horse or two being worked
  k.cyl(0, 0, 0, 0.05, 0.28, LOG, 8, LOG_DARK);
  k.box(R - 0.35, 0.02, 0.35, 0.36, 0.08, 0.12, TIN_DARK, WATER);
  const coats = [0x7a4a2a, 0x5a3420, 0xb08a58, 0xd8cfc0, 0x2e2622];
  const pickCoat = () => hex(coats[Math.floor(r() * coats.length)]);
  horse(k, 0.45, -0.1, 1.4 + r(), pickCoat());
  if (r() < 0.6) horse(k, -0.5, 0.35, -2.2 + r(), pickCoat());
  // a saddle on the top rail
  k.box(-R * 0.7, 0.27, R * 0.7, 0.12, 0.05, 0.1, hex(0x6a3a20));
  void [b, WHITE];
};

export const RANCH_DRAW: Record<RanchKind, Draw> = { ranchGate, bunkhouse, hayBarn, ranchCorral };
