import { DIRS, N, type World } from '../world/tiles';
import { hashString } from '../world/rng';
import { cellKind, coastalContinent, crossingAt, landBorder, straitAt } from '../world/macro';
import { SECONDS_PER_HOUR } from '../render/daynight';
import { money } from './cargoHud';
import { deeds } from './deeds';
import { reachOf } from './orders';
import { rankOf, type Driver } from './drivers';
import { clock, kerbNear, roadLeft, type Fleet, type FleetHost, type Road, type Unit } from './fleet';
import type { Wallet } from './economy';
import type { VehicleDef } from './vehicles';
import type { Agent, Traffic } from './traffic';

/**
 * The convoy: the vehicles told to follow you come with you (docs/convoy.html).
 *
 * The fleet keeps one cell it is trying to be in, the muster: the player's. Since 14 Oct 2026 only a
 * vehicle in Follow mode (game/formation.ts) travels to it. One in Work mode stays and works in the cell
 * it is based in, the HQ's or wherever its base is, however far the player goes, and main.ts keeps that
 * cell in memory with traffic so it goes on earning. Settle somewhere else and every follower gives up
 * what it was doing, at no cost to anybody, and drives here across the cell lattice, by the causeways,
 * county roads and ferries that really exist in this seed. Vehicles with nobody in them stay put unless
 * the player has asked for them to be brought along (Settings), when a delivery driver brings them over
 * and is billed once.
 *
 * Nothing is a clock. A vehicle on its way is a real one on the road the whole time: it drives to the
 * border on its route, is handed to the next cell's traffic as it crosses, and so on until it pulls
 * up at a base near the player. A ferry is the one cut, as it is for the player: it waits on the slip,
 * then comes off at the far one. The cells it is in and bound for are held in memory while it drives
 * (main.ts pins them), so a fleet that sets off soon after the player never leaves the 3x3 round them.
 *
 * Which way to go is still decided on the lattice: cellKind, landBorder, straitAt and crossingAt are
 * hashes of the seed and answer for cells not yet generated, so the route is a short list of cells.
 */

/** Game hours the player must stay in a new cell before the fleet is told: long enough not to chase a line being weaved over. */
const SETTLE = 0.1;
/** Share of its top speed a vehicle averages on a journey, for the ETA the fleet window shows. */
const CONVOY_SHARE = { land: 0.6, water: 0.6, air: 0.8 } as const;
/** A route is never the straight line: the road bends. */
const WANDER_LATTICE = 1.15;

/**
 * Tiles a unit on a journey (fleet.ts Road) still has to go, the whole way: from where it is through every
 * county ahead to the one it is bound for, at the lattice's bends; in the last county, the drive to its base.
 * The ETA reads it (reckon), and so does a vehicle's card while it is on the way (game/inspect.ts).
 */
export function journeyLeft(u: Unit, r: Road): number {
  const a = u.agent;
  let x = a ? a.w.ox + a.state.x : u.cx * N + u.x, z = a ? a.w.oz + a.state.z : u.cz * N + u.z;
  let t = 0;
  for (let k = r.leg + 1; k < r.cells.length; k++) {
    const [cx, cz] = r.cells[k];
    const tx = cx * N + N / 2, tz = cz * N + N / 2;
    t += Math.hypot(tx - x, tz - z);
    x = tx; z = tz;
  }
  // in the last cell: what is left of the drive to its base
  if (r.leg >= r.cells.length - 1 && a) t = Math.hypot(a.to.x - a.state.x, a.to.z - a.state.z);
  return t * WANDER_LATTICE;
}
/** How far from a unit the router will look for a way through, in cells. */
const MAX_CELLS = 12;
/** Seconds a vehicle stands on the slip before the boat takes it over. */
const FERRY_SLIP = 12;
/** The fare, off the same table the player's own car ferry uses. */
const FERRY_BASE = 30, FERRY_PER_TILE = 0.8;
/** A delivery: one callout for the move, then a rate a unit, with everyone after the first at half. */
const TRANSPORT_CALL = 50, TRANSPORT_PER_TILE = 0.4, TRANSPORT_GAP = 120, TRANSPORT_TAIL = 0.5;
/** What a water crossing takes out of a driver: an ace shrugs it off, a careful one half feels it. */
const RECALL_MOOD = 0.02;
/** What the router pays for a hop, and for one it has to wait for a boat on. */
const HOP_COST = 1, FERRY_COST = 3.5;
/** No hop is reckoned shorter than this share of a cell: even a border dash is a drive. */
const MIN_LEG = 0.35;
/** Times a vehicle is sent for the same border before it is taken over some other way. */
const MAX_TRIES = 3;

const key = (cx: number, cz: number): string => `${cx},${cz}`;
const cheb = (ax: number, az: number, bx: number, bz: number): number => Math.max(Math.abs(ax - bx), Math.abs(az - bz));
const inCell = (v: number): number => Math.min(N - 0.5, Math.max(0.5, v));

/** How fast this vehicle covers ground on a journey, tiles a second. */
function convoyPace(def: VehicleDef): number {
  const share = def.kind === 'water' ? CONVOY_SHARE.water : def.kind === 'air' ? CONVOY_SHARE.air : CONVOY_SHARE.land;
  return Math.max(0.2, def.topSpeed * share);
}

/** What the router treats a vehicle as; a train never travels, so it has none. */
type Mode = 'land' | 'water' | 'air';
const modeOfDef = (def: VehicleDef): Mode | null =>
  def.kind === 'water' ? 'water' : def.kind === 'air' ? 'air' : def.kind === 'land' ? 'land' : null;

interface ConvoyHost extends FleetHost {
  player(): { cx: number; cz: number; x: number; z: number } | null;
}

/** One step of a route: the cell entered, and whether getting into it meant a boat. */
interface Step { cx: number; cz: number; ferry: boolean }

export class Convoy {
  /** The cell the fleet is trying to be in. */
  cx = 0;
  cz = 0;
  /** Bring vehicles with no driver along too. Settings menu; off by default (14 Oct 2026), since the working fleet stays at its base. */
  carry = false;
  /** Game hours the player has spent in a cell that is not the muster. */
  private settle = 0;
  private sweepT = 0;
  /** The move under way: how many were sent, how many are here, and the bill run up so far. */
  private move: { sent: number; home: number; bill: number; to: string } | null = null;
  /** Kerbs this move has already put a vehicle on, so no two pull up on one tile. */
  private taken: { x: number; z: number }[] = [];

  private sh = 0;
  private seedFor = '';

  constructor(private fleet: Fleet, private wallet: Wallet, private host: ConvoyHost) {
    // a vehicle on its way that can find no road on is taken over the next border some other way
    fleet.onConvoyStuck = (u) => { if (u.road) u.road.tries = MAX_TRIES; };
  }

  /**
   * Where the unit being seen to is going, when it isn't the player (this.cx/cz): a vehicle at work goes to
   * the HQ's county (the user, 15 Oct 2026: a fleet kept working at the old HQ's county after a new HQ was
   * bought far away). Set round each unit's own handling by `as`.
   */
  private aim: { cx: number; cz: number; x: number; z: number } | null = null;

  /** The point a unit pulls up nearest: the HQ for one at work, the player for a follower. */
  private focus(): { cx: number; cz: number; x: number; z: number } | null { return this.aim ?? this.host.player(); }

  /**
   * Where a unit goes: a follower to the player (the muster); one at work to the HQ's county, or nowhere
   * ('stay') with no HQ, working where it is.
   */
  private targetOf(u: Unit): { cx: number; cz: number; x: number; z: number } | 'player' | 'stay' {
    if (u.mode === 'follow') return 'player';
    // a base the player chose is where it works, HQ or none (Order.chosen)
    const b = u.order.chosen ? u.order.base : null;
    if (b) return { cx: b.cx, cz: b.cz, x: b.x, z: b.z };
    const h = this.fleet.hq;
    return h ? { cx: h.cx, cz: h.cz, x: h.x, z: h.z } : 'stay';
  }

  /** Run `fn` with the muster set to where unit u is going (see targetOf), and put it back after. */
  private as<T>(u: Unit, fn: () => T): T {
    const t = this.targetOf(u);
    if (typeof t !== 'object') return fn();
    const cx = this.cx, cz = this.cz, aim = this.aim;
    this.cx = t.cx; this.cz = t.cz; this.aim = t;
    try { return fn(); } finally { this.cx = cx; this.cz = cz; this.aim = aim; }
  }

  /** The hash every lattice question is asked of; recomputed when the world changes. */
  private hash(): number {
    const s = this.host.seed();
    if (s !== this.seedFor) { this.seedFor = s; this.sh = hashString(s); }
    return this.sh;
  }

  /** Start here, with nothing settling: a new game, a load, or stepping into a world. */
  reset(cx: number, cz: number): void {
    this.cx = cx;
    this.cz = cz;
    this.settle = 0;
    this.move = null;
    this.sweepT = 0;
  }

  /** The player took the ferry, or some other cut: taking it was no accident, so the fleet is told at once. */
  settleNow(): void {
    const p = this.host.player();
    if (!p) return;
    if (p.cx !== this.cx || p.cz !== this.cz) {
      this.cx = p.cx;
      this.cz = p.cz;
      this.settle = 0;
      this.sweepT = 0;
    }
  }

  /** True while anything of the player's is on the road. */
  get moving(): boolean { return this.fleet.units.some((u) => u.where === 'enroute'); }

  /** Every unit on the road, soonest home first. */
  get enroute(): Unit[] {
    return this.fleet.units.filter((u) => u.where === 'enroute' && u.road)
      .sort((a, b) => roadLeft(a.road!) - roadLeft(b.road!));
  }

  /** The line over the fleet window while a move is on, or null. */
  header(): string | null {
    const list = this.enroute;
    if (!list.length) return null;
    const first = roadLeft(list[0].road!), last = roadLeft(list[list.length - 1].road!);
    const to = list[0].road!.to;
    return `${list.length} on the road to ${to} · first in ≈ ${clock(first)}${list.length > 1 ? ` · all in by ≈ ${clock(last)}` : ''}`;
  }

  /**
   * The cells that must stay in memory for the fleet on the road: the one each vehicle is in, and the
   * one it is driving into. main.ts pins them and gives each its traffic, whatever the player does.
   */
  needed(): [number, number][] {
    const out: [number, number][] = [];
    for (const u of this.fleet.units) {
      const r = u.road;
      if (u.where !== 'enroute' || !r) continue;
      out.push(r.cells[r.leg]);
      if (r.leg + 1 < r.cells.length) out.push(r.cells[r.leg + 1]);
    }
    return out;
  }

  // ---- the frame ----

  update(dt: number): void {
    if (dt <= 0) return;
    const p = this.host.player();
    if (p) {
      if (p.cx !== this.cx || p.cz !== this.cz) {
        this.settle += dt / SECONDS_PER_HOUR;
        if (this.settle >= SETTLE) {
          this.cx = p.cx;
          this.cz = p.cz;
          this.settle = 0;
          this.sweepT = 0;
        }
      } else this.settle = 0;
    }
    this.drive(dt);
    this.sweepT -= dt;
    if (this.sweepT <= 0) { this.sweepT = 1; this.sweep(); }
    if (this.move && !this.moving) this.closeMove();
  }

  /** Every vehicle on its way: on the road where it is, over the border it has crossed, on for the next one. */
  private drive(dt: number): void {
    for (const u of [...this.fleet.units]) {
      if (u.where !== 'enroute' || !u.road) continue;
      this.as(u, () => this.driveOne(u, dt));
    }
  }

  /** One vehicle on its way, with the muster set to where it is going. */
  private driveOne(u: Unit, dt: number): void {
    {
      const r = u.road!;
      // its traffic went quiet under it (and wrote it back): it goes on again from where it was
      if (u.agent && (!u.traffic || !u.traffic.agents.includes(u.agent))) { u.agent = null; u.traffic = null; }
      if ((r.tries ?? 0) >= MAX_TRIES) { this.jump(u); return; }
      if (!u.agent && !this.launchOn(u)) return;
      const a = u.agent!, tr = u.traffic!;
      if (a.w !== tr.world) { this.handOver(u, a); return; }
      if (r.slip !== undefined) {
        r.slip -= dt;
        if (r.slip <= 0) this.cross(u, true);
        return;
      }
      if (a.phase === 'parked') this.next(u, a, tr);
    }
  }

  /** Put a vehicle on its way on the road in the cell it is in, once that cell's traffic is running. */
  private launchOn(u: Unit): boolean {
    const w = this.host.worldAt(u.cx, u.cz);
    const tr = w ? this.host.trafficOf(w) : null;
    if (!w || !tr) return false;
    tr.fleet = this.fleet;
    const a = tr.launchOwned(u.uid, this.fleet.defFor(u), u.x, u.z, u.heading, null);
    if (!a) return false;
    u.agent = a;
    u.traffic = tr;
    return true;
  }

  /** Take a vehicle off the road, writing where it was back to its unit. */
  private pull(u: Unit): void {
    const a = u.agent;
    if (a && u.traffic) {
      const s = a.state;
      u.cx = a.w.cx; u.cz = a.w.cz; u.x = inCell(s.x); u.z = inCell(s.z); u.y = s.y; u.heading = s.heading;
      u.traffic.dropOwned(a);
    }
    u.agent = null;
    u.traffic = null;
  }

  /** It has stopped where it was sent: on to the next border, the slip, or its new base; or it is there. */
  private next(u: Unit, a: Agent, tr: Traffic): void {
    const r = u.road!;
    const w = a.w;
    const def = this.fleet.defFor(u);
    // in the muster cell: a driver of yours has arrived the moment it is over the line, and works from
    // where it is (driving on to a base first only kept it "on the road" beside you); one brought over
    // by a delivery driver is set down at the kerb nearest you
    if (r.leg >= r.cells.length - 1) {
      if (r.aim === 'base' || (u.driver && !r.carried)) { this.land(u); return; }
      r.aim = 'base';
      const spot = this.arrival(u, w, def, !!r.carried);
      if (!tr.driveOwned(a, spot.x, spot.z)) this.land(u);
      return;
    }
    const [nx, nz] = r.cells[r.leg + 1];
    const nb = this.host.worldAt(nx, nz);
    // the next cell is still being built (it is pinned, so it will come): wait where it is
    if (!nb) return;
    if (r.ferry[r.leg] || def.kind === 'water') {
      // by boat: to the slip (a boat to its harbour mouth), to wait for the crossing
      if (r.aim === 'slip') { r.slip = FERRY_SLIP; return; }
      r.aim = 'slip';
      const slip = this.slipIn(u, w, def);
      if (!slip || !tr.driveOwned(a, slip.x, slip.z)) r.slip = FERRY_SLIP;
      return;
    }
    // stopped short of the border it was sent over: send it again, a few times
    if (r.aim === 'door') r.tries = (r.tries ?? 0) + 1;
    r.aim = 'door';
    const door = this.door(u, nb, def, dirInto(w.cx, w.cz, nx, nz), false, false, false);
    if (!tr.driveOwned(a, door.x + nb.ox - w.ox, door.z + nb.oz - w.oz)) r.tries = MAX_TRIES;
  }

  /** Over a border: the vehicle is handed to that cell's traffic, going as fast as it was, and sent on. */
  private handOver(u: Unit, a: Agent): void {
    const r = u.road!;
    const v = a.state.v;
    const nw = a.w;
    this.pull(u);
    const k = r.cells.findIndex((c) => c[0] === nw.cx && c[1] === nw.cz);
    if (k > r.leg) { for (let i = r.leg; i < k; i++) r.owed += r.fares[i]; }
    if (k >= 0) r.leg = k;
    else if (!this.again(u, nw.cx, nw.cz)) return;
    r.aim = undefined;
    r.slip = undefined;
    r.tries = 0;
    if (!this.launchOn(u)) return;
    (u.agent!.state as { v: number }).v = v;
    this.next(u, u.agent!, u.traffic!);
  }

  /** Strayed into a cell off its way (a road that bends over the line and back): route again from there. */
  private again(u: Unit, cx: number, cz: number): boolean {
    const r = u.road!;
    const def = this.fleet.defFor(u);
    const mode = r.carried ? 'land' : modeOfDef(def);
    if (!mode) return false;
    if (cx === this.cx && cz === this.cz) {
      u.road = { ...r, cells: [[cx, cz]], ferry: [], fares: [], leg: 0 };
      return true;
    }
    const road = this.route(u, def, mode, cx, cz);
    if (!road) { this.fleet.hold(u, 'no way on from here'); return false; }
    road.owed = r.owed;
    road.carried = r.carried;
    road.billTiles = r.billTiles;
    if (r.carried) road.fares = road.fares.map(() => 0);
    u.road = road;
    return true;
  }

  /** Over the next border without driving it: off the ferry at the far slip, or some other way round when the road would not do. */
  private cross(u: Unit, ferry: boolean): void {
    const r = u.road!;
    if (r.leg + 1 >= r.cells.length) { this.land(u); return; }
    const [nx, nz] = r.cells[r.leg + 1];
    const nb = this.host.worldAt(nx, nz);
    // the far cell is still being built: stay on the slip a moment longer
    if (!nb) { r.slip = 0.5; return; }
    const def = this.fleet.defFor(u);
    const spot = this.door(u, nb, def, dirInto(u.cx, u.cz, nx, nz), ferry, false, true);
    this.pull(u);
    r.owed += r.fares[r.leg];
    r.leg++;
    r.slip = undefined;
    r.aim = undefined;
    r.tries = 0;
    u.cx = nx; u.cz = nz; u.x = spot.x; u.z = spot.z; u.y = 0; u.heading = spot.heading;
    this.launchOn(u);
    this.fleet.onChange();
  }

  /** Could find no road on: over the next border some other way, or, already here, it has arrived. */
  private jump(u: Unit): void {
    const r = u.road!;
    if (r.leg >= r.cells.length - 1) { this.land(u); return; }
    this.cross(u, !!r.ferry[r.leg]);
  }

  // ---- the order ----

  /** Who has to move, who may stay, and who cannot come at all. Once a second. */
  private sweep(): void {
    const muster = this.host.worldAt(this.cx, this.cz);
    let sent = 0, carried = 0;
    for (const u of this.fleet.units) {
      // a fleet-mate's vehicle is driven by their game, not called over by this one (docs/sharedfleets.html)
      if (u.where === 'ridden' || u.where === 'towing' || u.away) continue;
      // each with the muster set to where it is going: a follower to you, one at work to the HQ's county
      const r = u.driver ? this.as(u, () => this.sweepOne(u, muster, carried)) : this.sweepOne(u, muster, carried);
      if (r === 'sent') sent++;
      else if (r === 'carried') { carried++; sent++; }
    }
    if (sent > 0) {
      this.openMove(sent);
      this.fleet.onChange();
    }
  }

  /** One unit's part in the sweep: 'sent' when it set off, 'carried' when a delivery driver took it. */
  private sweepOne(u: Unit, muster: World | null, carried: number): 'sent' | 'carried' | null {
    const def = this.fleet.defFor(u);
    const mode = modeOfDef(def);
    // a train stays on its own railway, whatever the player does
    if (!mode) return null;
    // it got here but could not be paid for: set it down now if the money has turned up since
    if (u.where === 'waiting' && u.road && u.road.leg >= u.road.cells.length - 1) {
      if (this.wallet.canAfford(u.road.owed)) { u.where = 'enroute'; this.land(u); }
      return null;
    }
    // a driver that has reached where it was going is there there and then: a follower falls in behind you
    // (game/formation.ts), a worker starts work where it is; neither drives on to a base first,
    // which a boat may not even be able to reach
    if (u.where === 'enroute' && u.driver && u.road && !u.road.carried
      && u.road.leg >= u.road.cells.length - 1 && u.cx === this.cx && u.cz === this.cz) {
      this.land(u);
      return null;
    }
    // already on the road: where it is going may have moved behind it
    if (u.where === 'enroute') {
      if (u.road) { this.reroute(u); this.reckon(u); }
      return null;
    }
    // a crewed jet flies the air service between airports (game/jetPilots.ts): it never drives over
    if (u.driver && def.kind === 'air' && def.jet) return null;
    if (u.driver) {
      // at work with no HQ: it stays and works where it is (14 Oct 2026). At work with an HQ, its county is
      // where the fleet works (15 Oct 2026): within the reach of its orders of it, it stays and works; further
      // off (a new HQ bought far away) it drives over. A follower goes wherever you are.
      if (this.targetOf(u) === 'stay') return null;
      const reach = u.mode === 'follow' ? 0 : reachOf(u.order.range);
      if (cheb(u.cx, u.cz, this.cx, this.cz) <= reach && this.joined(mode, u.cx, u.cz, reach)) { this.rebase(u); return null; }
      if (u.where !== 'working' && u.where !== 'shadowed' && u.where !== 'waiting') return null;
      const road = this.route(u, def, mode, u.cx, u.cz);
      if (!road) {
        const to = u.mode === 'follow' ? 'you' : u.order.chosen && u.order.base ? u.order.base.name : 'the HQ';
        this.fleet.hold(u, mode === 'land' ? `no road to ${to}` : mode === 'water' ? `no water to ${to}` : 'nowhere to land');
        return null;
      }
      const cells = new Set(road.cells.map(([cx, cz]) => key(cx, cz)));
      return this.fleet.recall(u, road, (cx, cz) => cells.has(key(cx, cz))) ? 'sent' : null;
    }
    // nobody in it: a delivery driver brings it over, if the player wants that and it is not laid up
    if (u.where !== 'parked' || u.laidUp || !this.carry || mode !== 'land') return null;
    if (cheb(u.cx, u.cz, this.cx, this.cz) === 0 || !muster) return null;
    const road = this.route(u, def, 'land', u.cx, u.cz);
    if (!road) return null;
    road.carried = true;
    road.fares = road.fares.map(() => 0);
    road.owed = this.transportFee(road, carried);
    u.where = 'enroute';
    u.road = road;
    u.held = undefined;
    return 'carried';
  }

  /** The muster moved while a unit was on its way: it carries on from the cell it is in, and turns only if its next border changed. */
  private reroute(u: Unit): void {
    const r = u.road!;
    const end = r.cells[r.cells.length - 1];
    if (end[0] === this.cx && end[1] === this.cz) return;
    const [hx, hz] = r.cells[r.leg];
    const next = r.leg + 1 < r.cells.length ? r.cells[r.leg + 1] : null;
    if (!this.again(u, hx, hz)) { this.pull(u); return; }
    const road = u.road!;
    const now = road.cells.length > 1 ? road.cells[1] : null;
    const same = !!next && !!now && next[0] === now[0] && next[1] === now[1];
    if (same) { road.aim = r.aim; road.slip = r.slip; road.tries = r.tries; }
    else if (u.agent && u.traffic) this.next(u, u.agent, u.traffic);
  }

  /** How far it still has to go, for the ETA: from where it is through the cells ahead, at the lattice's bends. */
  private reckon(u: Unit): void {
    const r = u.road!;
    r.tiles = journeyLeft(u, r);
  }

  /** A unit near enough to stay takes the base nearest the player that its range can still hold. */
  private rebase(u: Unit): void {
    const p = this.focus();
    const b = u.order.base;
    if (!p) return;
    // the player's own pick stays put (Order.chosen)
    if (b && u.order.chosen) return;
    if (b && b.cx === this.cx && b.cz === this.cz) return;
    const reach = reachOf(u.order.range);
    const list = this.fleet.basesFor(u).filter((q) => cheb(q.cx, q.cz, this.cx, this.cz) <= reach);
    if (!list.length) return;
    const px = p.cx * N + p.x, pz = p.cz * N + p.z;
    const far = (q: { cx: number; cz: number; x: number; z: number }) => Math.hypot(q.cx * N + q.x - px, q.cz * N + q.z - pz);
    list.sort((a, c) => far(a) - far(c));
    if (list[0] !== b) { u.order.base = list[0]; this.fleet.onChange(); }
  }

  /**
   * Can a unit in (cx, cz) keep working where it is and still count as with you? Its range is
   * counted in cells, but a car can only drift your way over land: from another island (over a
   * causeway, on a ferry, or not at all) it could never home to a base near you, so it comes over.
   * Boats and flyers cross water anyway, and keep the plain count.
   */
  private joined(mode: Mode, cx: number, cz: number, reach: number): boolean {
    if (mode !== 'land' || (cx === this.cx && cz === this.cz)) return true;
    const sh = this.hash();
    const seen = new Set([key(cx, cz)]);
    const open: [number, number][] = [[cx, cz]];
    while (open.length) {
      const [ax, az] = open.pop()!;
      if (ax === this.cx && az === this.cz) return true;
      for (let d = 0; d < 4; d++) {
        const nx = ax + DIRS[d][0], nz = az + DIRS[d][1];
        if (seen.has(key(nx, nz)) || cheb(nx, nz, this.cx, this.cz) > reach || !landBorder(sh, ax, az, d)) continue;
        seen.add(key(nx, nz));
        open.push([nx, nz]);
      }
    }
    return false;
  }

  // ---- the lattice ----

  /** Is there anywhere in this cell a car ferry could put in, or a boat tie up? */
  private coastal(cx: number, cz: number): boolean {
    // a cell in memory answers for itself; one that will never be generated answers from its kind
    const w = this.host.worldAt(cx, cz);
    if (w) return w.ports.length > 0;
    const k = cellKind(this.hash(), cx, cz);
    if (k === 'sea') return false;
    if (k === 'continent') return coastalContinent(this.hash(), cx, cz);
    return true;
  }

  /** How this vehicle may cross side d of cell (cx, cz), or null when it may not. */
  private crossing(mode: Mode, cx: number, cz: number, d: number): 'road' | 'ferry' | null {
    const sh = this.hash();
    const nx = cx + DIRS[d][0], nz = cz + DIRS[d][1];
    if (mode === 'air') return 'road';
    if (mode === 'water') return this.coastal(nx, nz) ? 'road' : null;
    if (cellKind(sh, nx, nz) === 'sea') return null;
    if (landBorder(sh, cx, cz, d)) return 'road';
    if (straitAt(sh, cx, cz, d) >= 0) return 'road';
    return this.coastal(cx, cz) && this.coastal(nx, nz) ? 'ferry' : null;
  }

  /**
   * The way from (fx, fz) to the muster, cell by cell: a Dijkstra over the lattice, bounded to
   * MAX_CELLS around where it sets out, that pays more for a hop it has to wait for a boat on.
   */
  private walk(mode: Mode, fx: number, fz: number): Step[] | null {
    if (fx === this.cx && fz === this.cz) return [];
    if (cheb(fx, fz, this.cx, this.cz) > MAX_CELLS) return null;
    const cost = new Map<string, number>([[key(fx, fz), 0]]);
    const back = new Map<string, Step>();
    const open: [number, number][] = [[fx, fz]];
    const done = new Set<string>();
    while (open.length) {
      // the cheapest open cell; the frontier is small enough that a scan beats a heap
      let best = 0;
      for (let k = 1; k < open.length; k++) {
        const a = cost.get(key(open[k][0], open[k][1])) ?? Infinity;
        const b = cost.get(key(open[best][0], open[best][1])) ?? Infinity;
        if (a < b) best = k;
      }
      const [cx, cz] = open.splice(best, 1)[0];
      if (done.has(key(cx, cz))) continue;
      done.add(key(cx, cz));
      if (cx === this.cx && cz === this.cz) break;
      const here = cost.get(key(cx, cz)) ?? Infinity;
      for (let d = 0; d < 4; d++) {
        const nx = cx + DIRS[d][0], nz = cz + DIRS[d][1];
        if (cheb(nx, nz, fx, fz) > MAX_CELLS) continue;
        const how = this.crossing(mode, cx, cz, d);
        if (!how) continue;
        const next = here + (how === 'ferry' ? FERRY_COST : HOP_COST);
        const k = key(nx, nz);
        if (next >= (cost.get(k) ?? Infinity)) continue;
        cost.set(k, next);
        back.set(k, { cx, cz, ferry: how === 'ferry' });
        open.push([nx, nz]);
      }
    }
    if (!cost.has(key(this.cx, this.cz))) return null;
    const out: Step[] = [];
    let cx = this.cx, cz = this.cz;
    while (cx !== fx || cz !== fz) {
      const from = back.get(key(cx, cz));
      if (!from) return null;
      out.unshift({ cx, cz, ferry: from.ferry });
      cx = from.cx;
      cz = from.cz;
    }
    return out;
  }

  /** Turn a walk into a journey: the cells, the ferries and their fares, and the distance it is reckoned at. */
  private route(u: Unit, def: VehicleDef, mode: Mode, fx: number, fz: number): Road | null {
    const steps = this.walk(mode, fx, fz);
    if (!steps || !steps.length) return null;
    const muster = this.host.worldAt(this.cx, this.cz);
    // its real place at the start, cell middles on the way: the ETA and the delivery bill
    const start = { x: fx * N + u.x, z: fz * N + u.z };
    const end = { x: this.cx * N + N / 2, z: this.cz * N + N / 2 };
    const cells: [number, number][] = [[fx, fz], ...steps.map((s): [number, number] => [s.cx, s.cz])];
    const ferry: boolean[] = [], fares: number[] = [];
    const mid = (c: [number, number]) => ({ x: c[0] * N + N / 2, z: c[1] * N + N / 2 });
    let tiles = 0;
    for (let k = 0; k < steps.length; k++) {
      const a = k === 0 ? start : mid(cells[k]);
      const c = k === steps.length - 1 ? end : mid(cells[k + 1]);
      const run = Math.max(N * MIN_LEG, Math.hypot(c.x - a.x, c.z - a.z));
      tiles += run * WANDER_LATTICE;
      ferry.push(steps[k].ferry);
      fares.push(steps[k].ferry ? Math.round(FERRY_BASE + FERRY_PER_TILE * Math.round(run)) : 0);
    }
    return {
      cells, ferry, fares, leg: 0, pace: convoyPace(def), tiles, billTiles: tiles, owed: 0,
      to: muster?.name ?? 'the next cell',
    };
  }

  /** What a delivery charges for one vehicle on this move: everyone after the first comes at half. */
  private transportFee(road: Road, already: number): number {
    const gaps = road.ferry.filter(Boolean).length;
    const one = TRANSPORT_PER_TILE * road.billTiles + TRANSPORT_GAP * gaps;
    return Math.round((already === 0 ? TRANSPORT_CALL + one : one * TRANSPORT_TAIL) / 5) * 5;
  }

  // ---- places ----

  /** Where it pulls up in the muster cell: the base nearest the player, or for a delivery a kerb near the player. */
  private arrival(u: Unit, w: World, def: VehicleDef, carried: boolean): { x: number; z: number } {
    const p = this.focus();
    if (carried && def.kind === 'land' && p && p.cx === w.cx && p.cz === w.cz) {
      const k = kerbNear(w, p.x, p.z, 16, this.taken);
      if (k) { this.taken.push(k); return k; }
    }
    const bases = this.fleet.basesFor(u).filter((q) => q.cx === w.cx && q.cz === w.cz);
    if (p) bases.sort((a, b) => Math.hypot(a.x - p.x, a.z - p.z) - Math.hypot(b.x - p.x, b.z - p.z));
    return bases[0] ?? { x: u.agent?.state.x ?? u.x, z: u.agent?.state.z ?? u.z };
  }

  /** The ferry slip nearest where it is (a boat: the mouth of its nearest harbour), or null when the cell has none. */
  private slipIn(u: Unit, w: World, def: VehicleDef): { x: number; z: number } | null {
    const x = u.agent?.state.x ?? u.x, z = u.agent?.state.z ?? u.z;
    if (def.kind === 'water') {
      const ports = this.fleet.basesFor(u).filter((q) => q.kind === 'port' && q.cx === w.cx && q.cz === w.cz);
      ports.sort((a, b) => Math.hypot(a.x - x, a.z - z) - Math.hypot(b.x - x, b.z - z));
      return ports[0] ?? null;
    }
    const p = nearestPort(w, x, z);
    return p ? kerbNear(w, p.x + 0.5, p.z + 0.5, 12) : null;
  }

  // ---- arriving ----

  /** It has pulled up in the muster cell: settle what it owes, and it goes to work (or is parked, if nobody is in it). */
  private land(u: Unit): void {
    const r = u.road!;
    const w = this.host.worldAt(u.cx, u.cz);
    if (!w) return;
    const def = this.fleet.defFor(u);
    this.pull(u);
    if (r.owed > 0) {
      if (r.carried && !this.wallet.spend(r.owed, 'fines')) {
        // a delivery is not handed over until it is paid for: it waits here, finished, and the moment
        // the money is there the next sweep sets it down without sending it round again
        r.leg = r.cells.length - 1;
        u.where = 'waiting';
        u.held = `bring over ${money(Math.round(r.owed))}`;
        this.fleet.onChange();
        return;
      }
      if (!r.carried) this.wallet.fine(r.owed, 'fines');
      if (this.move) this.move.bill += r.owed;
    }
    const crossings = r.ferry.filter(Boolean).length;
    const driver = this.fleet.driverOf(u);
    if (driver && crossings) dockMood(driver, crossings);
    deeds.best('convoyCells', r.cells.length - 1);
    if (r.carried && !u.driver) {
      const k = def.kind === 'land' ? kerbNear(w, u.x, u.z, 6) ?? { x: u.x, z: u.z } : { x: u.x, z: u.z };
      u.x = k.x; u.z = k.z; u.y = 0;
      u.where = 'parked';
      u.road = null;
      u.place = this.fleet.placeName(u);
      this.fleet.onChange();
      this.host.announce(u.name, `brought over to ${u.place}`);
    } else {
      this.fleet.arriveAt(u, w, u.x, u.z, u.heading);
      this.host.announce(u.name, `${r.carried ? 'brought over' : 'here'} · ${u.order.base?.name ?? w.name}`);
    }
    if (this.move) this.move.home++;
  }

  /**
   * Where a vehicle comes into a cell over side d: the causeway landing or county crossing, on the
   * nearest drivable ground to it, or the harbour slip off a ferry. `mark` keeps two arrivals off
   * the same kerb; a place only driven for is not marked.
   */
  private door(u: Unit, w: World, def: VehicleDef, d: number, ferry: boolean, carried: boolean, mark = true): { x: number; z: number; heading: number } {
    const p = this.focus();
    const bases = this.fleet.basesFor(u).filter((q) => q.cx === w.cx && q.cz === w.cz);
    if (p) bases.sort((a, b) => Math.hypot(a.x - p.x, a.z - p.z) - Math.hypot(b.x - p.x, b.z - p.z));
    const base = bases[0];
    const fallback = base ? { x: base.x, z: base.z } : { x: w.spawn.x, z: w.spawn.z };
    const taken = mark ? this.taken : [];
    if (carried) {
      const spot = def.kind === 'water' ? fallback : kerbNear(w, fallback.x, fallback.z, 16, taken) ?? fallback;
      if (mark) this.taken.push({ x: spot.x, z: spot.z });
      return { ...spot, heading: base ? 0 : w.spawn.heading };
    }
    // a boat comes in at its harbour: there is no road for it to come in on
    if (def.kind === 'water' || d < 0) return { ...fallback, heading: 0 };

    // the way it is pointing once it is through: into the cell, away from the border it crossed
    const heading = Math.atan2(-DIRS[d][0], -DIRS[d][1]);
    let at: { x: number; z: number } | null = null;
    if (ferry) {
      const port = nearestPort(w, fallback.x, fallback.z);
      if (port) at = kerbNear(w, port.x + 0.5, port.z + 0.5, 12) ?? { x: port.x + 0.5, z: port.z + 0.5 };
    } else {
      const st = w.straits.find((s) => s.dir === d);
      const cross = st ? st.at : (crossingAt(this.hash(), w.cx, w.cz, d)[0]?.at ?? N / 2);
      const bx = d === 0 ? N - 1.5 : d === 2 ? 1.5 : cross + 0.5;
      const bz = d === 1 ? N - 1.5 : d === 3 ? 1.5 : cross + 0.5;
      at = def.kind === 'air' ? { x: bx, z: bz } : kerbNear(w, bx, bz, 24, taken);
    }
    if (!at) at = fallback;
    if (mark) this.taken.push({ x: at.x, z: at.z });
    return { x: Math.min(N - 1, Math.max(1, at.x)), z: Math.min(N - 1, Math.max(1, at.z)), heading };
  }

  // ---- the move ----

  private openMove(sent: number): void {
    const to = this.host.worldAt(this.cx, this.cz)?.name ?? 'the new cell';
    if (this.move) { this.move.sent += sent; return; }
    this.move = { sent, home: 0, bill: 0, to };
    this.taken = [];
    this.host.announce('Fleet', `${sent} setting off for ${to}`);
  }

  private closeMove(): void {
    const m = this.move;
    this.move = null;
    if (!m || !m.home) return;
    deeds.add('convoys');
    deeds.best('allPresent', this.fleet.units.filter((u) => u.where === 'working').length);
    const bill = Math.round(m.bill);
    this.host.announce('Fleet', `all ${m.home} here${bill > 0 ? ` · ${money(bill)} in fares and deliveries` : ''}`);
  }

  /** What bringing a stranded vehicle over would cost, or null when there is no way to do it. */
  towOver(u: Unit): number | null {
    if (u.where !== 'waiting' && u.where !== 'parked') return null;
    if (u.road && u.road.leg >= u.road.cells.length - 1) return Math.round(u.road.owed);
    if (cheb(u.cx, u.cz, this.cx, this.cz) === 0) return null;
    const def = this.fleet.defFor(u);
    if (def.kind !== 'land') return null;
    const road = this.route(u, def, 'land', u.cx, u.cz);
    return road ? this.transportFee(road, 0) : null;
  }

  /** Pay to have one brought over: a delivery driver drives it here, whoever normally drives it. */
  bringOver(u: Unit): string | null {
    const def = this.fleet.defFor(u);
    if (def.kind === 'rail') return `${u.name} never leaves its railway`;
    if (def.kind !== 'land') return `${u.name} can't be driven over`;
    // one that is already here, waiting to be paid for, is simply set down
    if (u.where === 'waiting' && u.road && u.road.leg >= u.road.cells.length - 1) {
      if (!this.wallet.canAfford(u.road.owed)) return `Bringing ${u.name} over costs ${money(Math.round(u.road.owed))}`;
      u.where = 'enroute';
      this.land(u);
      return null;
    }
    const road = this.route(u, def, 'land', u.cx, u.cz);
    if (!road) return `There is no way to bring ${u.name} over from there`;
    const fee = this.transportFee(road, 0);
    if (!this.wallet.canAfford(fee)) return `Bringing ${u.name} over costs ${money(fee)}`;
    road.carried = true;
    road.fares = road.fares.map(() => 0);
    road.owed = fee;
    u.where = 'enroute';
    u.road = road;
    u.held = undefined;
    this.openMove(1);
    this.fleet.onChange();
    return null;
  }

  /** Where everything on the road is right now, in world tiles: a dot a unit for the map. */
  pips(): { x: number; z: number; eta: string; name: string }[] {
    return this.enroute.map((u) => {
      const a = u.agent;
      return {
        x: a ? a.w.ox + a.state.x : u.cx * N + u.x,
        z: a ? a.w.oz + a.state.z : u.cz * N + u.z,
        eta: clock(roadLeft(u.road!)),
        name: u.name,
      };
    });
  }

  /** Console: take every vehicle on the road over its next border now, to see an arrival without the drive. */
  skip(): string[] {
    for (const u of this.enroute) this.jump(u);
    return this.list();
  }

  /** Console: one line a journey. */
  list(): string[] {
    return this.enroute.map((u) => {
      const r = u.road!;
      const path = r.cells.map(([x, z], k) => (k === r.leg ? `[${x},${z}]` : `${x},${z}`)).join(' → ');
      const how = u.agent ? `${u.agent.phase}${r.aim ? ` for the ${r.aim}` : ''}` : 'waiting for its cell';
      return `${u.name}${r.carried ? ' (delivery)' : ''} ${path} · ${how}${r.slip !== undefined ? ` · slip ${Math.ceil(r.slip)} s` : ''} · ≈ ${clock(roadLeft(r))} left · owes ${money(Math.round(r.owed))}`;
    });
  }
}

/** DIRS index of the side of (bx, bz) that (ax, az) lies on. */
function dirInto(ax: number, az: number, bx: number, bz: number): number {
  const dx = ax - bx, dz = az - bz;
  for (let d = 0; d < 4; d++) if (DIRS[d][0] === dx && DIRS[d][1] === dz) return d;
  return -1;
}

/** The harbour nearest (x, z) on this island, or null when it has none. */
function nearestPort(w: World, x: number, z: number): { x: number; z: number } | null {
  let best: { x: number; z: number } | null = null, bestD = Infinity;
  for (const p of w.ports) {
    const d = Math.hypot(p.x - x, p.z - z);
    if (d < bestD) { bestD = d; best = { x: p.x, z: p.z }; }
  }
  return best;
}

/** Being dragged over the water is wearing; an ace does not mind, and a careful driver half minds. */
function dockMood(d: Driver, crossings: number): void {
  if (rankOf(d) === 'ace') return;
  const share = d.temper === 'careful' ? 0.5 : 1;
  d.mood = Math.max(0, d.mood - RECALL_MOOD * share * crossings);
}
