/**
 * Performance and first-minute telemetry for the play reports (src/net/report.ts, docs/dev page): what
 * device a game runs on, the graphics settings (and which level Auto has chosen, and for how long), the
 * frame rate actually achieved, how the first moments went (the welcome card, the first key, the first
 * tile driven) and any script errors. It exists to answer one question: why do some players never drive
 * a single tile? Nothing personal is sent: no names beyond the game's own, nothing typed.
 */

/** Settings kept on this device that matter to how the game runs, by their storage keys. */
const SETTING_KEYS: Record<string, string> = {
  quality: 'pocket-roads-quality',
  fpsCap: 'tinyfleet-fps-cap',
  effects: 'pocket-roads-effects',
  theme: 'tinyfleet-theme',
  units: 'tinyfleet-units',
  autoPath: 'tinyfleet-autopath',
  audio: 'pocket-roads-settings',
  pitch: 'pocket-roads-camera-pitch',
  controlsHidden: 'pocket-roads-controls-collapsed',
};

/** Frame-time buckets, ms (upper bounds); the last catches everything slower. */
const BUCKETS = [12, 17, 20, 25, 33, 50, 67, 100, 250, 1000, Infinity];

interface PerfDevice {
  ua: string; platform: string; mobile: boolean; touchPoints: number; coarse: boolean; fine: boolean;
  screen: [number, number]; viewport: [number, number]; dpr: number; cores: number | null; memoryGb: number | null;
  gpu: string; gpuVendor: string; webgl2: boolean; maxTexture: number; lang: string;
  /** A phone or tablet that pressed "continue anyway" past the mobile card (index.html). */
  mobileAnyway: boolean;
  /** WebGL drawn on the processor, not a graphics card (title/gpuCard.ts). */
  softwareGl: boolean;
}

export interface PerfReport {
  device: PerfDevice;
  settings: Record<string, unknown>;
  quality: { setting: string; level: string; seconds: Record<string, number>; changes: number; label: string };
  frames: {
    /** Wall-clock seconds in play with the tab visible, and frames drawn in them. */
    seconds: number; count: number; avgFps: number;
    /** The frame rate the slowest 1% and 5% of frames ran at. */
    low1: number; low5: number;
    worstMs: number; over50: number; over250: number;
    hist: number[];
    /** Every 15 visible seconds: [seconds into play, average fps then, quality level then]. */
    timeline: [number, number, string][];
  };
  /** Where the frame time goes, every freeze and what caused it, the machine (net/perfField.ts). */
  field: FieldReport;
  /** Seconds in play with the tab hidden. */
  hiddenSeconds: number;
  /** ms from the page loading to the game first being played, and to this report. */
  loadMs: number | null; pageMs: number;
  funnel: {
    welcomeSeen: boolean; welcomeSeconds: number; welcomeClosedAt: number | null;
    firstKeyAt: number | null; firstDriveKeyAt: number | null; firstMoveAt: number | null;
    keys: Record<string, number>; clicks: number; touches: number; gamepad: boolean;
    paused: number; menuSeconds: number;
  };
  errors: { msg: string; at: number; n: number; stack?: string }[];
  /** Why this report went: the first one soon after starting, the regular timer, the tab hidden, or leaving. */
  why: string;
}

import { gpuInfo } from '../title/gpuCard';
import { FieldPerf, type FieldReport } from './perfField';

const round = (v: number, d = 1): number => Math.round(v * 10 ** d) / 10 ** d;
const mm = (q: string): boolean => { try { return !!window.matchMedia?.(q).matches; } catch { return false; } };

export class Perf {
  private t0 = performance.now();
  private playAt: number | null = null;
  private lastFrame = 0;
  private visible = 0;
  private hidden = 0;
  private count = 0;
  private hist = new Array(BUCKETS.length).fill(0);
  private worst = 0;
  private window = { t: 0, frames: 0 };
  private timeline: [number, number, string][] = [];
  /** The tab was hidden since the last frame: the frame after it spans the hidden time, not a slow frame. */
  private wentHidden = false;
  private levelSecs: Record<string, number> = {};
  private lastLevel = '';
  private changes = 0;
  private welcomeSeen = false;
  private welcomeSecs = 0;
  private welcomeClosedAt: number | null = null;
  private firstKeyAt: number | null = null;
  private firstDriveKeyAt: number | null = null;
  private firstMoveAt: number | null = null;
  private keys: Record<string, number> = {};
  private clicks = 0;
  private touches = 0;
  private gamepad = false;
  private paused = 0;
  private wasPaused = false;
  private menuSecs = 0;
  private errors: { msg: string; at: number; n: number; stack?: string }[] = [];
  private device: PerfDevice | null = null;

  /** Field profiling: the frame's parts, freezes and their causes, the machine (net/perfField.ts). */
  readonly field: FieldPerf;

  constructor(private gl: () => WebGLRenderingContext | WebGL2RenderingContext | null) {
    this.field = new FieldPerf(gl);
    window.addEventListener('error', (e) => this.error(e.message || String(e.error), (e.error as Error | undefined)?.stack, e.filename ? `${e.filename}:${e.lineno}` : ''));
    window.addEventListener('unhandledrejection', (e) => {
      const r = e.reason as Error | string | undefined;
      this.error(`unhandled rejection: ${typeof r === 'string' ? r : r?.message ?? String(r)}`, typeof r === 'object' ? r?.stack : undefined);
    });
    window.addEventListener('keydown', (e) => {
      if (e.repeat) return;
      const s = this.sinceStart();
      if (this.firstKeyAt === null && this.playAt !== null) this.firstKeyAt = s;
      const drive = ['KeyW', 'ArrowUp', 'KeyS', 'ArrowDown', 'KeyA', 'KeyD', 'ArrowLeft', 'ArrowRight'].includes(e.code);
      if (drive && this.firstDriveKeyAt === null && this.playAt !== null) this.firstDriveKeyAt = s;
      const k = drive || ['Space', 'Enter', 'Escape', 'ShiftLeft', 'KeyM', 'KeyI', 'KeyJ', 'KeyF', 'KeyG', 'Tab'].includes(e.code) ? e.code : 'other';
      if (this.playAt !== null) this.keys[k] = (this.keys[k] ?? 0) + 1;
    }, true);
    window.addEventListener('pointerdown', (e) => { if (this.playAt === null) return; if (e.pointerType === 'touch') this.touches++; else this.clicks++; }, true);
    window.addEventListener('gamepadconnected', () => { this.gamepad = true; });
    document.addEventListener('visibilitychange', () => { if (document.hidden) this.wentHidden = true; });
  }

  /** Seconds of wall clock since the game was first played (0 before). */
  private sinceStart(): number { return this.playAt === null ? 0 : round((performance.now() - this.playAt) / 1000); }

  error(msg: string, stack?: string, where = ''): void {
    const text = `${msg}${where ? ` (${where})` : ''}`.slice(0, 300);
    const had = this.errors.find((x) => x.msg === text);
    if (had) { had.n++; return; }
    this.errors.push({ msg: text, at: this.sinceStart(), n: 1, ...(stack ? { stack: stack.slice(0, 800) } : {}) });
    if (this.errors.length > 12) this.errors.shift();
  }

  /** The game has started being played (a new game, a load, or an online sign-in). */
  started(): void { if (this.playAt === null) { this.playAt = performance.now(); this.field.started(this.playAt); } }

  /**
   * Every frame while a game is up. `level`: the quality level in effect; `paused`: a menu is over it;
   * `driven`: tiles the player has driven; `welcome`: the welcome card is up.
   */
  frame(level: string, paused: boolean, driven: number, welcome: boolean): void {
    const now = performance.now();
    const dt = this.lastFrame ? now - this.lastFrame : 0;
    this.lastFrame = now;
    if (this.playAt === null || dt <= 0) return;
    // a hidden tab draws nothing, so the first frame back spans the hidden time (even a short one): not a slow frame
    if (dt > 5000 || document.hidden || this.wentHidden) { this.wentHidden = document.hidden; this.hidden += dt / 1000; return; }
    const s = dt / 1000;
    this.visible += s;
    this.count++;
    let b = 0;
    while (dt > BUCKETS[b]) b++;
    this.hist[b]++;
    this.worst = Math.max(this.worst, dt);
    this.field.interval(dt, this.visible, paused);
    if (level !== this.lastLevel) { if (this.lastLevel) this.changes++; this.lastLevel = level; }
    this.levelSecs[level] = (this.levelSecs[level] ?? 0) + s;
    if (paused) this.menuSecs += s;
    if (paused && !this.wasPaused) this.paused++;
    this.wasPaused = paused;
    if (welcome) { this.welcomeSeen = true; this.welcomeSecs += s; }
    else if (this.welcomeSeen && this.welcomeClosedAt === null) this.welcomeClosedAt = this.sinceStart();
    if (driven > 0 && this.firstMoveAt === null) this.firstMoveAt = this.sinceStart();
    if (navigator.getGamepads && !this.gamepad) { try { this.gamepad = [...navigator.getGamepads()].some((g) => !!g); } catch { /* not allowed */ } }
    this.window.t += s;
    this.window.frames++;
    if (this.window.t >= 15) {
      this.timeline.push([round(this.visible, 0), round(this.window.frames / this.window.t), level]);
      this.field.window(this.window.frames / this.window.t, level);
      if (this.timeline.length > 120) this.timeline.splice(0, this.timeline.length - 120);
      this.window = { t: 0, frames: 0 };
    }
  }

  private dev(): PerfDevice {
    if (this.device) return this.device;
    let gpu = 'unknown', gpuVendor = '', webgl2 = false, maxTexture = 0;
    try {
      const gl = this.gl();
      if (gl) {
        webgl2 = typeof WebGL2RenderingContext !== 'undefined' && gl instanceof WebGL2RenderingContext;
        maxTexture = gl.getParameter(gl.MAX_TEXTURE_SIZE) as number;
        const ext = gl.getExtension('WEBGL_debug_renderer_info');
        gpu = String(ext ? gl.getParameter(ext.UNMASKED_RENDERER_WEBGL) : gl.getParameter(gl.RENDERER));
        gpuVendor = String(ext ? gl.getParameter(ext.UNMASKED_VENDOR_WEBGL) : gl.getParameter(gl.VENDOR));
      }
    } catch { /* hidden by the browser */ }
    const ua = navigator.userAgent;
    const nav = navigator as Navigator & { deviceMemory?: number; userAgentData?: { platform?: string; mobile?: boolean } };
    let anyway = false;
    try { anyway = sessionStorage.getItem('tinyfleet-mobile-anyway') === '1'; } catch { /* private mode */ }
    this.device = {
      ua: ua.slice(0, 300), platform: nav.userAgentData?.platform ?? navigator.platform ?? '',
      mobile: nav.userAgentData?.mobile ?? (/Android|iPhone|iPad|iPod|Mobile/i.test(ua) || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1)),
      touchPoints: navigator.maxTouchPoints ?? 0, coarse: mm('(pointer: coarse)'), fine: mm('(any-pointer: fine)'),
      screen: [screen.width, screen.height], viewport: [innerWidth, innerHeight], dpr: round(devicePixelRatio, 2),
      cores: navigator.hardwareConcurrency ?? null, memoryGb: nav.deviceMemory ?? null,
      gpu: gpu.slice(0, 160), gpuVendor: gpuVendor.slice(0, 80), webgl2, maxTexture, lang: navigator.language ?? '', mobileAnyway: anyway, softwareGl: gpuInfo()?.software ?? false,
    };
    return this.device;
  }

  /** Everything, for a report. */
  report(quality: { setting: string; level: string; label: string }, why: string): PerfReport {
    const settings: Record<string, unknown> = {};
    for (const [name, key] of Object.entries(SETTING_KEYS)) {
      let v: string | null = null;
      try { v = localStorage.getItem(key); } catch { /* blocked */ }
      if (v === null) continue;
      try { settings[name] = JSON.parse(v); } catch { settings[name] = v.slice(0, 200); }
    }
    // the frame rate the slowest n% of frames ran at, from the histogram
    const low = (pct: number): number => {
      let left = Math.max(1, Math.round(this.count * pct));
      for (let b = BUCKETS.length - 1; b >= 0; b--) {
        left -= this.hist[b];
        if (left <= 0) return round(1000 / (BUCKETS[b] === Infinity ? Math.max(1000, this.worst) : BUCKETS[b]));
      }
      return 0;
    };
    const seconds: Record<string, number> = {};
    for (const [k, v] of Object.entries(this.levelSecs)) seconds[k] = round(v, 0);
    return {
      device: this.dev(),
      settings,
      quality: { ...quality, seconds, changes: this.changes },
      frames: {
        seconds: round(this.visible, 0), count: this.count, avgFps: this.visible ? round(this.count / this.visible) : 0,
        low1: low(0.01), low5: low(0.05), worstMs: Math.round(this.worst),
        over50: this.hist.slice(BUCKETS.indexOf(67)).reduce((a, b) => a + b, 0),
        over250: this.hist.slice(BUCKETS.indexOf(1000)).reduce((a, b) => a + b, 0),
        hist: this.hist.slice(), timeline: this.timeline.slice(),
      },
      field: this.field.report(),
      hiddenSeconds: round(this.hidden, 0),
      loadMs: this.playAt === null ? null : Math.round(this.playAt - this.t0), pageMs: Math.round(performance.now() - this.t0),
      funnel: {
        welcomeSeen: this.welcomeSeen, welcomeSeconds: round(this.welcomeSecs), welcomeClosedAt: this.welcomeClosedAt,
        firstKeyAt: this.firstKeyAt, firstDriveKeyAt: this.firstDriveKeyAt, firstMoveAt: this.firstMoveAt,
        keys: { ...this.keys }, clicks: this.clicks, touches: this.touches, gamepad: this.gamepad, paused: this.paused, menuSeconds: round(this.menuSecs),
      },
      errors: this.errors.slice(),
      why,
    };
  }
}
