import { hex, scale, type RGB } from '../../world/biomes';
import type { ThemeKind } from '../../world/tiles';
import type { Sched } from '../nightLights';
import { DARK, TAU, WARM_GLOW, type Draw, type Kit, type P3 } from './kit';

/**
 * The signature buildings of three towns out of well-loved kinds of story: a village of round-doored
 * burrows under a green hill with its party tree and inn; a white city of seven walls stepped up a crag,
 * and the beacon that calls for its aid; and a spirit town's towering bath house and clock gate. Each
 * carries its own fixed palette, so it looks the same whatever style the gallery is set to.
 */

const EVENING: Sched = [18, 23.5, 1.4], LATE: Sched = [17.5, 25.5, 1.4], FIRE: Sched = [17.5, 31, 2.2];

// the burrow village
const TURF = hex(0x6fae4e), TURF2 = hex(0x7fb85a), FIELD = hex(0x8cc063), CREAM = hex(0xeadfc2), FIELDSTONE = hex(0xa9a394);
const BRICK = hex(0xa85a42), BRASS = hex(0xe0b548), THATCH = hex(0xb8923f), THATCH_DARK = hex(0x8f6f30);
const OAK_BARK = hex(0x6e5236), OAK_A = hex(0x4f9a44), OAK_B = hex(0x5eaa4c), OAK_C = hex(0x458a40);
const PLANK = hex(0x9a7648), BARREL = hex(0x8a6238), PATH = hex(0xd8c8a0), SMOKE = hex(0xe6e6e2);
const DOORS: readonly number[] = [0x3f8a3f, 0xe8b830, 0x2f6fb5, 0xc23a2a];
const PARTY: readonly number[] = [0xe2412f, 0xf2c14e, 0x2f7fb5, 0x3f9b4a, 0xf28a3b, 0xb05cc7];
// the white city
const MARBLE = hex(0xf2f1ec), MARBLE_SHADE = hex(0xdcdbd4), PAVE = hex(0xcfcdc6), CRAG = hex(0xb4b8be), SLATE = hex(0x6c7f98);
const BANNER = hex(0x27366e), PALE_LEAF = hex(0xeef2e6);
// the spirit town
const LACQUER = hex(0xb8322a), PLASTER = hex(0xf0e8d8), JADE = hex(0x2a7a5c), JADE_DARK = hex(0x1f5a44), GOLD = hex(0xe2b53c);
const TIMBER = hex(0x5e4030), PAPER = hex(0xf2e6c8), PAPER_GLOW = hex(0xffd898), BASE_STONE = hex(0xb9b3a6), MOAT = hex(0x5fa6c4);
const LANTERN = hex(0xd9502f), LANTERN_GLOW = hex(0xff9a48), CURTAIN = hex(0x3a2f7a), STUCCO = hex(0x7a2a26), COPPER = hex(0x6fae98);
const SHADOW = hex(0x2a2426), FROG = hex(0x7f9478);

// ---- shared pieces ---------------------------------------------------------------------------------

/** Draw at (x, z) with the frame turned `yaw` there: `draw` is handed where that point lies in the turned frame. */
function place(k: Kit, x: number, z: number, yaw: number, draw: (ox: number, oz: number) => void): void {
  const c = Math.cos(yaw), s = Math.sin(yaw);
  k.turned(yaw, () => draw(x * c - z * s, x * s + z * c));
}

/**
 * A rounded lump: the top half of an ellipsoid standing on y, and under it a shallow belly (`belly` of
 * the height, 0 for a mound that sits on the ground) so a tree's crown is closed from below.
 */
function blob(k: Kit, x: number, y: number, z: number, rx: number, ry: number, rz: number, col: RGB, seg = 8, rings = 3, belly = 0.35): void {
  const I: P3 = [x, y, z];
  const at = (a: number, p: number): P3 => [x + Math.cos(a) * Math.cos(p) * rx, y + Math.sin(p) * ry, z + Math.sin(a) * Math.cos(p) * rz];
  for (let s = 0; s < seg; s++) {
    const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU;
    for (let j = 0; j < rings; j++) {
      const p0 = ((j / rings) * Math.PI) / 2, p1 = (((j + 1) / rings) * Math.PI) / 2;
      const c = j % 2 ? scale(col, 1.06) : col;
      if (j === rings - 1) k.tri(at(a0, p0), at(a1, p0), [x, y + ry, z], c, I);
      else k.quad(at(a0, p0), at(a1, p0), at(a1, p1), at(a0, p1), c, I);
    }
    if (belly > 0) k.tri(at(a0, 0), at(a1, 0), [x, y - ry * belly, z], scale(col, 0.8), I);
  }
}

/** A round window on a wall facing +z: a frame and three panes that make an octagon of light. */
function roundWin(k: Kit, x: number, y: number, z: number, rad: number, frame: RGB, s: Sched = EVENING): void {
  k.face(x, y, z + 0.004, rad * 1.3, frame, 8);
  const zz = z + 0.004;
  k.pane(x, y - rad * 0.42, zz, rad * 1.9, rad * 0.84, 1, DARK, s, WARM_GLOW);
  k.pane(x, y + rad * 0.42, zz, rad * 1.25, rad * 0.5, 1, DARK, s, WARM_GLOW);
  k.pane(x, y - rad * 0.92, zz, rad * 1.25, rad * 0.5, 1, DARK, s, WARM_GLOW);
}

/** A round door facing +z in its stone ring, a brass knob in the very middle. */
function roundDoor(k: Kit, x: number, y: number, z: number, rad: number, col: RGB): void {
  k.face(x, y, z + 0.004, rad * 1.22, FIELDSTONE, 10);
  k.face(x, y, z + 0.01, rad, col, 10);
  k.box(x, y - rad * 0.12, z + 0.016, rad * 0.24, rad * 0.24, 0.012, BRASS);
}

/** A triangle seen from both sides: bunting, a banner's tail. */
function cloth(k: Kit, a: P3, b: P3, c: P3, col: RGB): void {
  const ux = b[0] - a[0], uy = b[1] - a[1], uz = b[2] - a[2], vx = c[0] - a[0], vy = c[1] - a[1], vz = c[2] - a[2];
  const nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
  const m: P3 = [(a[0] + b[0] + c[0]) / 3, (a[1] + b[1] + c[1]) / 3, (a[2] + b[2] + c[2]) / 3];
  k.tri(a, b, c, col, [m[0] + nx, m[1] + ny, m[2] + nz]);
  k.tri(a, b, c, col, [m[0] - nx, m[1] - ny, m[2] - nz]);
}

/** A truncated pyramid: a battered plinth, a chimney, a roof cut off for a belfry. */
function frustum(k: Kit, x: number, y: number, z: number, w0: number, d0: number, w1: number, d1: number, h: number, col: RGB, top: RGB = col): void {
  const I: P3 = [x, y + h / 2, z];
  const b = [[-w0 / 2, -d0 / 2], [w0 / 2, -d0 / 2], [w0 / 2, d0 / 2], [-w0 / 2, d0 / 2]];
  const t = [[-w1 / 2, -d1 / 2], [w1 / 2, -d1 / 2], [w1 / 2, d1 / 2], [-w1 / 2, d1 / 2]];
  for (let i = 0; i < 4; i++) {
    const j = (i + 1) % 4;
    k.quad([x + b[i][0], y, z + b[i][1]], [x + b[j][0], y, z + b[j][1]], [x + t[j][0], y + h, z + t[j][1]], [x + t[i][0], y + h, z + t[i][1]], col, I);
  }
  k.quad([x + t[0][0], y + h, z + t[0][1]], [x + t[1][0], y + h, z + t[1][1]], [x + t[2][0], y + h, z + t[2][1]], [x + t[3][0], y + h, z + t[3][1]], top, I);
}

/**
 * A swept tiled roof over a w×d rectangle (the east's, as regions/terraces.ts draws it): the eaves
 * curl up `lift` at the corners and the slope steepens to a short ridge. Returns the ridge height.
 */
function sweptRoof(k: Kit, x: number, y: number, z: number, w: number, d: number, h: number, col: RGB, lift = 0.06, ridge: RGB = scale(col, 0.7)): number {
  const n = 4, hx = w / 2, hz = d / 2;
  const tx = w >= d ? (w - d) / 2 : 0, tz = d > w ? (d - w) / 2 : 0;
  const ring = (ax: number, az: number, yy: number, up: number): P3[] => {
    const pts: P3[] = [];
    for (let s = 0; s < 4; s++) for (let i = 0; i < n; i++) {
      const u = -1 + (2 * i) / n;
      const [px, pz] = s === 0 ? [u, 1] : s === 1 ? [1, -u] : s === 2 ? [-u, -1] : [-1, u];
      pts.push([x + px * ax, yy + up * (px * pz) ** 2, z + pz * az]);
    }
    return pts;
  };
  const lerp = (a: number, b: number, f: number) => a + (b - a) * f;
  const outer = ring(hx, hz, y, lift);
  const mid = ring(lerp(hx, tx, 0.4), lerp(hz, tz, 0.4), y + h * 0.3, lift * 0.35);
  const top = ring(tx, tz, y + h, 0);
  const under = ring(hx * 0.8, hz * 0.8, y + lift * 0.2, lift * 0.3);
  const below: P3 = [x, y - h, z], above: P3 = [x, y + h * 2, z];
  const m = outer.length, soffit = scale(TIMBER, 0.9);
  for (let i = 0; i < m; i++) {
    const j = (i + 1) % m;
    k.quad(outer[i], outer[j], mid[j], mid[i], col, below);
    k.quad(mid[i], mid[j], top[j], top[i], scale(col, 0.93), below);
    k.quad(outer[i], outer[j], under[j], under[i], soffit, above);
  }
  k.box(x, y + h - 0.012, z, 2 * tx + 0.05, 0.03, 2 * tz + 0.05, ridge);
  return y + h;
}

// ---- a burrow home (1 × 1) -------------------------------------------------------------------------

/**
 * A burrow home: a grassy mound with a plastered front cut into it, a round bright door with a brass
 * knob, a round window either side, a brick chimney smoking out of the turf and a little fenced garden.
 * Drawn for every house of its village, so it is kept to a couple of hundred triangles.
 */
const hobbitHole: Draw = (k, _W, _D, _b, r) => {
  const H = 0.4 + r() * 0.1, rx = 0.37 + r() * 0.04, mz = -0.08;
  const door = hex(DOORS[Math.floor(r() * DOORS.length)]), grass = r() < 0.5 ? TURF : TURF2;
  const side = r() < 0.5 ? -1 : 1, cx = side * (0.08 + r() * 0.12);
  blob(k, 0, 0, mz, rx, H, 0.33, grass, 8, 3, 0);
  // the front: a plastered wall standing out of the hill, turf over its top
  const fz = 0.27;
  k.box(0, 0, fz - 0.12, 0.44, 0.26, 0.24, CREAM, grass);
  roundDoor(k, 0, 0.115, fz, 0.082, door);
  for (const sx of [-1, 1]) roundWin(k, sx * 0.165, 0.16, fz, 0.036, FIELDSTONE);
  // the chimney and its smoke
  const top = H + 0.1;
  k.box(cx, H * 0.55, mz - 0.03, 0.08, top - H * 0.55, 0.08, BRICK, DARK);
  k.box(cx + 0.02, top + 0.04, mz - 0.03, 0.05, 0.045, 0.05, SMOKE);
  k.box(cx + 0.06, top + 0.12, mz - 0.02, 0.07, 0.06, 0.07, SMOKE);
  // the garden: a path to the gate, flowers, a fence and a mailbox
  k.box(0, 0, 0.345, 0.1, 0.015, 0.15, PATH);
  k.box(-0.24, 0, 0.345, 0.2, 0.04, 0.09, hex(0x4f8f3f), hex(0xe86a8a));
  k.box(0.26, 0, 0.345, 0.16, 0.04, 0.09, hex(0x4f8f3f), hex(0xf2c94e));
  for (const sx of [-1, 1]) {
    k.box(sx * 0.255, 0.03, 0.42, 0.35, 0.06, 0.015, PLANK);
    k.box(sx * 0.07, 0, 0.42, 0.025, 0.12, 0.025, PLANK);
  }
  k.box(0, 0.02, 0.42, 0.115, 0.085, 0.015, scale(door, 0.85));
  k.box(-side * 0.13, 0, 0.375, 0.015, 0.1, 0.015, PLANK);
  k.box(-side * 0.13, 0.1, 0.375, 0.04, 0.035, 0.06, hex(0xc23a2a));
};

// ---- the party tree (3 × 3) ------------------------------------------------------------------------

/** A trestle table along x with a bench either side and the supper laid on it. */
function trestle(k: Kit, x: number, z: number, len: number): void {
  k.box(x, 0.13, z, len, 0.025, 0.2, PLANK);
  for (const sx of [-1, 1]) k.box(x + sx * (len / 2 - 0.1), 0.02, z, 0.03, 0.11, 0.16, OAK_BARK);
  for (const sz of [-1, 1]) {
    k.box(x, 0.065, z + sz * 0.18, len * 0.94, 0.02, 0.07, PLANK);
    for (const sx of [-1, 1]) k.box(x + sx * (len / 2 - 0.12), 0.02, z + sz * 0.18, 0.025, 0.045, 0.06, OAK_BARK);
  }
  k.box(x - len * 0.25, 0.155, z, 0.07, 0.03, 0.07, hex(0xf4f2ec));
  k.box(x + len * 0.05, 0.155, z + 0.02, 0.09, 0.045, 0.09, hex(0xd8a44a));
  k.box(x + len * 0.3, 0.155, z - 0.02, 0.05, 0.06, 0.05, BARREL);
}

/**
 * The party field: one very big spreading oak hung with paper lanterns, long trestle tables and benches
 * under it, a striped pavilion, bunting between poles and a barrel or two. Only the trunk is solid.
 */
const partyTree: Draw = (k, W, D, _b, r) => {
  const hw = W / 2, hd = D / 2;
  k.box(0, 0, 0, W - 0.2, 0.02, D - 0.2, FIELD);
  // the oak: flared roots, a thick trunk, boughs up into a crown of overlapping domes
  k.band(0, 0, 0.02, 0.3, 0.28, 0.19, 8, OAK_BARK);
  k.band(0, 0, 0.28, 0.19, 1.2, 0.15, 8, OAK_BARK);
  const spin0 = r() * TAU;
  for (let i = 0; i < 5; i++) {
    const a = spin0 + (i / 5) * TAU, c = Math.cos(a), s = Math.sin(a);
    k.bar([c * 0.08, 0.85, s * 0.08], [c * 0.75, 1.4, s * 0.75], 0.05, OAK_BARK);
    blob(k, c * 0.72, 1.18 + r() * 0.22, s * 0.72, 0.6, 0.62, 0.6, i % 2 ? OAK_B : OAK_C, 8, 3, 0.35);
  }
  blob(k, 0, 1.4, 0, 0.95, 1.2, 0.95, OAK_A, 10, 3, 0.3);
  // lanterns on strings from the boughs
  for (let i = 0; i < 12; i++) {
    const a = spin0 + 0.3 + (i / 12) * TAU, d = 0.45 + ((i * 7) % 5) * 0.17, ly = 0.72 + ((i * 3) % 4) * 0.06;
    const x = Math.cos(a) * d, z = Math.sin(a) * d, col = hex(PARTY[i % PARTY.length]);
    k.box(x, ly + 0.08, z, 0.01, 1.12 - ly, 0.01, DARK);
    k.glowBox(x, ly, z, 0.07, 0.085, 0.07, col, LATE, scale(col, 1.25));
  }
  // the supper tables
  trestle(k, -0.62, hd - 0.55, 1.0);
  trestle(k, 0.62, hd - 0.55, 1.0);
  place(k, -hw + 0.5, -0.15, Math.PI / 2, (ox, oz) => trestle(k, ox, oz, 0.9));
  // the pavilion in the back corner: poles, a valance and a striped roof
  const tx = hw - 0.62, tz = -hd + 0.62, tr = 0.46;
  for (let i = 0; i < 4; i++) {
    const a = Math.PI / 4 + (i / 4) * TAU;
    k.box(tx + Math.cos(a) * tr * 0.92, 0.02, tz + Math.sin(a) * tr * 0.92, 0.025, 0.36, 0.025, PLANK);
  }
  for (let i = 0; i < 8; i++) {
    const a0 = Math.PI / 8 + (i / 8) * TAU, a1 = a0 + TAU / 8, col = i % 2 ? hex(0xf4efe0) : hex(0xd8453a);
    const p0: P3 = [tx + Math.cos(a0) * tr, 0.38, tz + Math.sin(a0) * tr], p1: P3 = [tx + Math.cos(a1) * tr, 0.38, tz + Math.sin(a1) * tr];
    k.tri(p0, p1, [tx, 0.72, tz], col, [tx, 0.3, tz]);
    k.quad([p0[0], 0.3, p0[2]], [p1[0], 0.3, p1[2]], p1, p0, i % 2 ? hex(0xd8453a) : hex(0xf4efe0), [tx, 0.34, tz]);
    k.tri(p0, p1, [tx, 0.4, tz], scale(col, 0.75), [tx, 1, tz]);
  }
  k.box(tx, 0.7, tz, 0.015, 0.14, 0.015, PLANK);
  k.box(tx, 0.84, tz, 0.04, 0.04, 0.04, BRASS);
  trestle(k, tx, tz, 0.5);
  // bunting round the field
  const e = 0.28, poles: [number, number][] = [[-hw + e, hd - e], [hw - e, hd - e], [hw - e, -hd + e], [-hw + e, -hd + e]];
  for (let i = 0; i < 4; i++) {
    const [ax, az] = poles[i], [bx, bz] = poles[(i + 1) % 4];
    k.box(ax, 0.02, az, 0.03, 0.56, 0.03, PLANK);
    const at = (t: number): P3 => [ax + (bx - ax) * t, 0.56 - Math.sin(t * Math.PI) * 0.1, az + (bz - az) * t];
    k.bar(at(0), at(0.5), 0.006, DARK);
    k.bar(at(0.5), at(1), 0.006, DARK);
    for (let j = 0; j < 7; j++) {
      const p = at((j + 0.6) / 8), q = at((j + 1.2) / 8);
      cloth(k, p, q, [(p[0] + q[0]) / 2, (p[1] + q[1]) / 2 - 0.1, (p[2] + q[2]) / 2], hex(PARTY[(i + j) % PARTY.length]));
    }
  }
  // barrels by the trunk
  k.cyl(0.42, 0.02, 0.3, 0.085, 0.17, BARREL, 8, scale(BARREL, 0.75));
  k.cyl(0.58, 0.02, 0.18, 0.085, 0.17, BARREL, 8, scale(BARREL, 0.75));
  k.cyl(-0.45, 0.02, 0.32, 0.085, 0.17, BARREL, 8, scale(BARREL, 0.75));
};

// ---- the village inn (2 × 1) -----------------------------------------------------------------------

/**
 * The village inn: a long low house half dug into a grassy bank, its thatch sagging along the ridge,
 * round windows and a big round green door under a porch, a painted board on a post, barrels, a bench
 * and tall crooked chimneys.
 */
const hobbitInn: Draw = (k, W) => {
  const bw = W - 0.5, bz = 0.0, bd = 0.44, wh = 0.28, fz = bz + bd / 2;
  // the bank behind and over it
  blob(k, 0, 0, -0.1, W / 2 - 0.06, 0.66, 0.33, TURF, 10, 3, 0);
  k.box(0, 0, bz, bw + 0.04, 0.05, bd + 0.04, FIELDSTONE);
  k.box(0, 0.05, bz, bw, wh - 0.05, bd, CREAM);
  // the thatch, low in the middle like an old horse's back
  const n = 6, rw = bw + 0.14, rd = bd + 0.16, I: P3 = [0, wh - 0.1, bz];
  const ridge = (u: number): P3 => [-rw / 2 + rw * u, wh + 0.25 - 0.08 * Math.sin(Math.PI * u), bz + 0.04];
  const eave = (u: number, sz: number): P3 => [-rw / 2 + rw * u, wh - 0.04 - 0.025 * Math.sin(Math.PI * u), bz + (sz * rd) / 2];
  for (let i = 0; i < n; i++) {
    const u0 = i / n, u1 = (i + 1) / n, col = i % 2 ? THATCH : scale(THATCH, 0.94);
    k.quad(eave(u0, 1), eave(u1, 1), ridge(u1), ridge(u0), col, I);
    k.quad(eave(u0, -1), eave(u1, -1), ridge(u1), ridge(u0), col, I);
    k.bar(ridge(u0), ridge(u1), 0.022, THATCH_DARK);
  }
  for (const u of [0, 1]) k.tri(eave(u, -1), eave(u, 1), ridge(u), CREAM, I);
  // round windows, the round door and its porch
  for (const x of [-0.62, -0.34, 0.34, 0.62]) roundWin(k, x, 0.165, fz, 0.048, FIELDSTONE, LATE);
  roundDoor(k, 0, 0.125, fz, 0.1, hex(0x3f8a3f));
  for (const sx of [-1, 1]) k.box(sx * 0.17, 0, fz + 0.17, 0.035, 0.27, 0.035, OAK_BARK);
  k.gable(0, 0.27, fz + 0.09, 0.44, 0.11, 0.24, THATCH_DARK, CREAM, true);
  k.glowBox(0, 0.2, fz + 0.19, 0.04, 0.05, 0.04, hex(0xe8c070), LATE, WARM_GLOW);
  k.box(0, 0, fz + 0.12, 0.26, 0.015, 0.22, PATH);
  // the sign: a plain board with a green shape, hung from a post
  const sx = W / 2 - 0.2, sz = fz + 0.17;
  k.box(sx, 0, sz, 0.03, 0.46, 0.03, OAK_BARK);
  k.box(sx - 0.1, 0.42, sz, 0.2, 0.02, 0.02, OAK_BARK);
  k.box(sx - 0.12, 0.27, sz, 0.15, 0.13, 0.014, hex(0xf2e6c4));
  k.face(sx - 0.12, 0.335, sz + 0.011, 0.045, hex(0x3f8a3f), 6);
  k.box(sx - 0.12, 0.3, sz - 0.009, 0.07, 0.07, 0.004, hex(0x3f8a3f));
  // barrels, a bench and flowers along the front
  const bx = -W / 2 + 0.22;
  k.cyl(bx, 0, fz + 0.14, 0.075, 0.15, BARREL, 8, scale(BARREL, 0.75));
  k.cyl(bx + 0.16, 0, fz + 0.14, 0.075, 0.15, BARREL, 8, scale(BARREL, 0.75));
  k.cyl(bx + 0.08, 0.15, fz + 0.14, 0.075, 0.15, BARREL, 8, scale(BARREL, 0.75));
  k.box(0.46, 0.06, fz + 0.06, 0.28, 0.02, 0.07, PLANK);
  for (const s of [-1, 1]) k.box(0.46 + s * 0.11, 0, fz + 0.06, 0.025, 0.06, 0.06, OAK_BARK);
  k.box(-0.47, 0, fz + 0.05, 0.36, 0.04, 0.07, hex(0x4f8f3f), hex(0xe86a8a));
  // two tall crooked chimneys, one of them smoking
  k.bar([-0.42, 0.3, -0.05], [-0.47, 0.84, -0.07], 0.045, BRICK);
  k.box(-0.47, 0.83, -0.07, 0.12, 0.03, 0.12, DARK);
  k.bar([0.5, 0.3, -0.06], [0.54, 0.76, -0.03], 0.04, BRICK);
  k.box(0.54, 0.75, -0.03, 0.11, 0.03, 0.11, DARK);
  k.box(-0.45, 0.9, -0.07, 0.06, 0.05, 0.06, SMOKE);
  k.box(-0.4, 0.99, -0.06, 0.08, 0.07, 0.08, SMOKE);
};

// ---- the white citadel (7 × 6) ---------------------------------------------------------------------

/**
 * A white city built against a crag: seven walls, each a level of the city, stepping up and back in
 * half-rings round the rock; a keel of stone thrusting out through every level above the great gate;
 * slate-roofed houses packed along each terrace; and on the top court a slender tower, a banner and one
 * pale tree.
 */
const whiteCitadel: Draw = (k, W, D, _b, r) => {
  const RX = W / 2 - 0.2, zc = -D / 2 + 1.45, RZ = D / 2 - 0.25 - zc, RB = 1.1;
  const N = 7, SEG = 23, STEP = 0.55, A0 = -0.25 * Math.PI, A1 = 1.25 * Math.PI;
  const f = (i: number) => 1 - i * 0.125;
  const pt = (fr: number, a: number, y: number): P3 => [Math.cos(a) * RX * fr, y, zc + Math.sin(a) * (Math.sin(a) >= 0 ? RZ : RB) * fr];
  const ang = (j: number) => A0 + ((A1 - A0) * j) / SEG;
  const floorY = (i: number) => (i === 0 ? 0.02 : i * STEP);

  // the crag: a jagged grey mass behind and above the city
  const ys = [0, 1.3, 2.5, 3.4, 4.0, 4.35], rxs = [3.05, 2.65, 1.95, 1.3, 0.75, 0.28], rbs = [1.18, 1.08, 0.95, 0.75, 0.5, 0.2], rfs = [0.4, 0.4, 0.4, 0.35, 0.3, 0.15];
  const M = 12, rings: P3[][] = [];
  for (let j = 0; j < ys.length; j++) {
    const ring: P3[] = [], cz = zc - 0.05 - j * 0.06;
    for (let i = 0; i < M; i++) {
      const a = (i / M) * TAU, jit = 0.95 + r() * 0.1;
      ring.push([Math.cos(a) * rxs[j] * jit, ys[j] + (j > 0 ? (r() - 0.5) * 0.25 : 0), cz + Math.sin(a) * (Math.sin(a) >= 0 ? rfs[j] : rbs[j]) * jit]);
    }
    rings.push(ring);
  }
  const core: P3 = [0, 2, zc - 0.2], peak: P3 = [0.1, 4.75, zc - 0.5];
  for (let j = 0; j + 1 < rings.length; j++) for (let i = 0; i < M; i++) {
    const i1 = (i + 1) % M;
    k.quad(rings[j][i], rings[j][i1], rings[j + 1][i1], rings[j + 1][i], scale(CRAG, 0.88 + r() * 0.2), core);
  }
  for (let i = 0; i < M; i++) k.tri(rings[5][i], rings[5][(i + 1) % M], peak, scale(CRAG, 0.95 + r() * 0.15), core);

  // the seven walls and the terraces between them
  for (let i = 0; i < N; i++) {
    const fo = f(i), fi = fo - 0.018, fy = floorY(i);
    const yb = i === 0 ? 0 : floorY(i - 1), yt = fy + (i === 0 ? 0.42 : 0.08);
    const inside: P3 = [0, (yb + yt) / 2, zc + 0.3];
    for (let j = 0; j < SEG; j++) {
      const a0 = ang(j), a1 = ang(j + 1), am = (a0 + a1) / 2;
      k.quad(pt(fo, a0, yb), pt(fo, a1, yb), pt(fo, a1, yt), pt(fo, a0, yt), j % 2 ? MARBLE : scale(MARBLE, 0.97), inside);
      k.quad(pt(fo, a0, yt), pt(fo, a1, yt), pt(fi, a1, yt), pt(fi, a0, yt), MARBLE, [0, yt - 1, zc]);
      k.quad(pt(fi, a0, fy), pt(fi, a1, fy), pt(fi, a1, yt), pt(fi, a0, yt), MARBLE_SHADE, pt(fo * 3, am, fy));
      if (i < N - 1) k.quad(pt(fi, a0, fy), pt(fi, a1, fy), pt(f(i + 1), a1, fy), pt(f(i + 1), a0, fy), PAVE, [0, fy - 1, zc]);
      else k.tri(pt(fi, a0, fy), pt(fi, a1, fy), [0, fy, zc + 0.2], PAVE, [0, fy - 1, zc]);
    }
  }

  // houses along every terrace, their backs to the wall above
  for (let i = 0; i < N - 1; i++) {
    const fm = f(i + 1) + 0.048, fy = floorY(i), n = Math.floor((fm * 11.9) / 0.56);
    for (let h = 0; h < n; h++) {
      const a = Math.PI * (0.05 + (0.9 * (h + 0.5)) / n), p = pt(fm, a, fy);
      const w = 0.3 + r() * 0.14, hh = 0.2 + r() * 0.17, shade = r() < 0.3;
      if (Math.abs(p[0]) < (i === 0 ? 0.42 : 0.5)) continue;
      const yaw = Math.atan2(Math.cos(a) / RX, Math.sin(a) / RZ);
      place(k, p[0], p[2], yaw, (ox, oz) => {
        k.box(ox, fy, oz, w, hh, 0.24, shade ? MARBLE_SHADE : MARBLE);
        k.gable(ox, fy + hh, oz, w + 0.03, 0.1, 0.28, h % 3 ? SLATE : scale(SLATE, 0.88), MARBLE);
        k.pane(ox - w * 0.2, fy + hh * 0.45, oz + 0.12, 0.06, 0.08, 1, DARK, EVENING, WARM_GLOW);
        if (w > 0.37) k.pane(ox + w * 0.22, fy + hh * 0.45, oz + 0.12, 0.06, 0.08, 1, DARK, LATE, WARM_GLOW);
      });
    }
  }

  // the keel of rock: out from the top court over every level, its edge raked down to the first wall
  const top = floorY(N - 1) + 0.1, zr = zc + RZ * f(N - 1) - 0.3, zt = zc + RZ * 0.78, kw = 0.27, rake = 0.11;
  const edge = (y: number): P3 => [0, y, zt + (top - y) * rake];
  for (const sx of [-1, 1]) {
    const in0: P3 = [0, top / 2, zr + 0.5];
    k.quad([sx * kw, 0, zr], edge(0), edge(top - 0.16), [sx * kw, top - 0.16, zr], sx < 0 ? CRAG : scale(CRAG, 1.08), in0);
    k.quad([sx * (kw + 0.03), top - 0.16, zr], [0, top - 0.16, zt + 0.06], [0, top, zt + 0.06], [sx * (kw + 0.03), top, zr], MARBLE, in0);
  }
  k.tri([-kw - 0.03, top, zr], [kw + 0.03, top, zr], [0, top, zt + 0.06], PAVE, [0, 0, zr + 0.5]);

  // the great gate in the first wall
  const gz = zc + RZ - 0.03;
  k.box(0, 0, gz, 0.62, 0.64, 0.24, MARBLE);
  for (const gx of [-0.2, 0, 0.2]) k.box(gx, 0.64, gz + 0.08, 0.1, 0.06, 0.06, MARBLE);
  k.box(0, 0, gz + 0.121, 0.24, 0.3, 0.012, DARK);
  k.face(0, 0.3, gz + 0.128, 0.12, DARK, 10);
  for (const sx of [-1, 1]) {
    k.cyl(sx * 0.4, 0, gz, 0.12, 0.8, MARBLE, 8);
    k.cone(sx * 0.4, 0.8, gz, 0.15, 0.22, SLATE, 8);
    k.glowBox(sx * 0.2, 0.34, gz + 0.13, 0.04, 0.06, 0.04, hex(0xe8c070), FIRE, WARM_GLOW);
  }

  // the top court: the white tower and its banner, two halls and one pale tree
  const cy = floorY(N - 1), tz = zc + 0.48;
  k.box(0, cy, tz, 0.36, 0.1, 0.36, MARBLE);
  k.band(0, tz, cy + 0.1, 0.14, cy + 1.08, 0.1, 8, MARBLE);
  k.band(0, tz, cy + 1.08, 0.1, cy + 1.16, 0.16, 8, MARBLE_SHADE);
  k.cyl(0, cy + 1.16, tz, 0.16, 0.05, MARBLE, 8);
  k.cyl(0, cy + 1.21, tz, 0.09, 0.14, MARBLE, 8);
  k.cone(0, cy + 1.35, tz, 0.115, 0.3, MARBLE_SHADE, 8);
  for (const y of [0.35, 0.65, 0.92]) k.pane(0, cy + y, tz + 0.133 - y * 0.035, 0.045, 0.1, 1, DARK, LATE, WARM_GLOW);
  const py = cy + 1.65;
  k.box(0, py, tz, 0.014, 0.42, 0.014, DARK);
  const b0: P3 = [0.01, py + 0.4, tz], b1: P3 = [0.01, py + 0.27, tz], b2: P3 = [0.3, py + 0.35, tz + 0.04], b3: P3 = [0.3, py + 0.25, tz + 0.04];
  cloth(k, b0, b1, b2, BANNER);
  cloth(k, b1, b3, b2, BANNER);
  cloth(k, b2, b3, [0.62, py + 0.24, tz - 0.02], BANNER);
  for (const sx of [-1, 1]) {
    k.box(sx * 0.44, cy, tz - 0.06, 0.36, 0.26, 0.28, MARBLE);
    k.gable(sx * 0.44, cy + 0.26, tz - 0.06, 0.4, 0.12, 0.32, SLATE, MARBLE);
    k.pane(sx * 0.44, cy + 0.08, tz + 0.08, 0.16, 0.1, 1, DARK, EVENING, WARM_GLOW);
  }
  k.disc(0, cy + 0.004, tz + 0.36, 0.17, hex(0x9fc08a), 10);
  k.cyl(0, cy, tz + 0.36, 0.018, 0.16, hex(0xd8d4c8), 5);
  blob(k, 0, cy + 0.16, tz + 0.36, 0.11, 0.11, 0.11, PALE_LEAF, 6, 2, 0.5);
};

// ---- a beacon tower (1 × 1) ------------------------------------------------------------------------

/**
 * A signal beacon: a slim round white tower with a stair winding up the outside, a corbelled top
 * carrying an iron basket of logs that burns all night, and a small guard room at its foot.
 */
const beaconTower: Draw = (k) => {
  const H = 1.72;
  k.cyl(0, 0, 0, 0.23, 0.05, PAVE, 10);
  k.band(0, 0, 0.05, 0.18, H, 0.135, 10, MARBLE);
  k.band(0, 0, H, 0.135, H + 0.12, 0.25, 10, MARBLE_SHADE);
  k.cyl(0, H + 0.12, 0, 0.25, 0.05, MARBLE, 10, PAVE);
  for (let i = 0; i < 8; i++) k.turned((i / 8) * TAU, () => k.box(0, H + 0.17, 0.215, 0.08, 0.06, 0.05, MARBLE));
  // the stair: stone treads let into the wall, a turn and a half to the top
  for (let i = 0; i < 21; i++) {
    const y = 0.07 + i * 0.078, rad = 0.18 - (0.045 * y) / H;
    k.turned(1.5 + i * 0.44, () => k.box(0, y, rad + 0.04, 0.1, 0.035, 0.12, i % 2 ? MARBLE_SHADE : PAVE));
  }
  for (const y of [0.7, 1.25]) k.pane(0, y, 0.18 - (0.045 * y) / H, 0.04, 0.1, 1, DARK, EVENING, WARM_GLOW);
  // the guard room
  const gx = 0.2, gz = 0.2;
  k.box(gx, 0, gz, 0.32, 0.24, 0.3, MARBLE);
  k.gable(gx, 0.24, gz, 0.36, 0.12, 0.34, SLATE, MARBLE);
  k.box(gx - 0.05, 0, gz + 0.151, 0.08, 0.15, 0.01, hex(0x6a4a30));
  k.pane(gx + 0.08, 0.1, gz + 0.15, 0.06, 0.07, 1, DARK, FIRE, WARM_GLOW);
  k.pane(gx + 0.16, 0.1, gz, 0.07, 0.07, 0, DARK, FIRE, WARM_GLOW);
  // the fire basket: iron legs and hoop, a stack of logs, and the fire itself
  const fy = H + 0.17, iron = hex(0x2e2e33), log = hex(0x6a4a30);
  for (let i = 0; i < 4; i++) {
    const a = Math.PI / 4 + (i / 4) * TAU, c = Math.cos(a), s = Math.sin(a);
    k.bar([c * 0.06, fy, s * 0.06], [c * 0.12, fy + 0.2, s * 0.12], 0.012, iron);
  }
  k.hoop(0, fy + 0.11, 0, 0.1, 0.012, iron, 6, 'xz');
  k.hoop(0, fy + 0.2, 0, 0.125, 0.012, iron, 6, 'xz');
  k.bar([-0.1, fy + 0.13, -0.03], [0.1, fy + 0.13, -0.03], 0.022, log);
  k.bar([-0.1, fy + 0.13, 0.04], [0.1, fy + 0.13, 0.04], 0.022, log);
  k.bar([0.0, fy + 0.17, -0.1], [0.0, fy + 0.17, 0.1], 0.022, log);
  k.glowBox(0, fy + 0.19, 0, 0.13, 0.08, 0.13, scale(log, 0.8), FIRE, hex(0xff8a28));
  k.glowBox(0.01, fy + 0.27, 0, 0.09, 0.09, 0.09, scale(log, 0.7), FIRE, hex(0xffb83a));
  k.glowBox(-0.01, fy + 0.36, 0.01, 0.05, 0.09, 0.05, scale(log, 0.6), FIRE, hex(0xffe27a));
};

// ---- the grand bath house (5 × 4) ------------------------------------------------------------------

/**
 * A spirit town's bath house: a stepped timber palace of red lacquer and white plaster, every storey
 * under its own sweeping green roof with a balcony round it, a tall pavilion on top, a boiler chimney
 * trailing steam at one side, a curtained entrance, and a red arched bridge to it over the water.
 */
const grandBathhouse: Draw = (k, W, D) => {
  const hw = W / 2, hd = D / 2, px = -0.15, cz = -0.4;
  // the water along the front, its kerbs, and the forecourt
  const wz = hd - 0.4;
  k.box(0, 0, wz, W - 0.2, 0.03, 0.5, MOAT);
  for (const s of [-1, 1]) k.box(0, 0, wz + s * 0.28, W - 0.2, 0.06, 0.06, BASE_STONE);
  k.box(px, 0, cz, 4.3, 0.12, 2.7, BASE_STONE, scale(BASE_STONE, 1.08));
  k.box(px, 0, cz + 1.52, 1.3, 0.06, 0.36, scale(BASE_STONE, 1.08));

  // the storeys
  const sizes: [number, number][] = [[3.7, 2.2], [3.0, 1.8], [2.35, 1.4], [1.7, 1.0]];
  const wall = 0.5;
  let y = 0.12;
  const storey = (w: number, d: number, h: number, first: boolean) => {
    const fz = cz + d / 2, bz = cz - d / 2;
    k.box(px, y - 0.06, cz, w, h + 0.06, d, PLASTER);
    k.box(px, y, cz, w + 0.04, 0.1, d + 0.04, LACQUER);
    k.box(px, y + h - 0.07, cz, w + 0.04, 0.07, d + 0.04, LACQUER);
    const nx = Math.max(2, Math.round(w / 0.62)), nz = Math.max(2, Math.round(d / 0.62));
    for (let i = 0; i <= nx; i++) {
      const x = px - w / 2 + (w * i) / nx;
      k.box(x, y + 0.1, fz, 0.06, h - 0.17, 0.06, LACQUER);
      k.box(x, y + 0.1, bz, 0.06, h - 0.17, 0.06, LACQUER);
      if (i < nx) {
        const xm = x + w / nx / 2, pw = (w / nx) * 0.56;
        k.pane(xm, y + 0.16, fz, pw, h - 0.3, 1, PAPER, (i + nx) % 3 ? LATE : EVENING, PAPER_GLOW);
        k.pane(xm, y + 0.16, bz, pw, h - 0.3, 3, PAPER, i % 2 ? LATE : EVENING, PAPER_GLOW);
      }
    }
    for (let i = 0; i <= nz; i++) {
      const z = bz + (d * i) / nz;
      if (i > 0 && i < nz) for (const s of [-1, 1]) k.box(px + (s * w) / 2, y + 0.1, z, 0.06, h - 0.17, 0.06, LACQUER);
      if (i < nz) {
        const zm = z + d / nz / 2, pw = (d / nz) * 0.56;
        k.pane(px + w / 2, y + 0.16, zm, pw, h - 0.3, 0, PAPER, i % 2 ? LATE : EVENING, PAPER_GLOW);
        k.pane(px - w / 2, y + 0.16, zm, pw, h - 0.3, 2, PAPER, i % 2 ? EVENING : LATE, PAPER_GLOW);
      }
    }
    // the balcony round it
    if (!first) {
      const o = 0.17;
      k.box(px, y - 0.03, cz, w + o * 2, 0.03, d + o * 2, TIMBER);
      for (const s of [-1, 1]) {
        k.box(px, y + 0.09, cz + s * (d / 2 + o - 0.02), w + o * 2, 0.022, 0.022, LACQUER);
        k.box(px + s * (w / 2 + o - 0.02), y + 0.09, cz, 0.022, 0.022, d + o * 2, LACQUER);
      }
    }
    // the roof, gold at its four corner tips, lanterns hung under the eaves
    const ov = 0.36, lift = 0.13, ry = y + h;
    sweptRoof(k, px, ry, cz, w + ov * 2, d + ov * 2, 0.3, JADE, lift, JADE_DARK);
    for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(px + sx * (w / 2 + ov - 0.01), ry + lift - 0.025, cz + sz * (d / 2 + ov - 0.01), 0.055, 0.06, 0.055, GOLD);
    const nl = Math.max(2, Math.round(w / 0.8));
    for (let i = 0; i < nl; i++) for (const s of [-1, 1]) {
      const lx = px - w / 2 + (w * (i + 0.5)) / nl;
      if (first && s > 0 && Math.abs(lx - px) < 0.7) continue;
      k.glowBox(lx, ry - 0.1, cz + s * (d / 2 + ov + 0.035), 0.06, 0.085, 0.06, LANTERN, FIRE, LANTERN_GLOW);
    }
    for (const s of [-1, 1]) for (const t of [-0.25, 0.25]) k.glowBox(px + s * (w / 2 + ov + 0.035), ry - 0.1, cz + t * d, 0.06, 0.085, 0.06, LANTERN, FIRE, LANTERN_GLOW);
    y = ry + 0.13;
  };
  sizes.forEach(([w, d], i) => storey(w, d, wall, i === 0));

  // the top pavilion, its ridge ending in gold
  const tw = 1.0, td = 0.66, th = 0.55;
  k.box(px, y - 0.06, cz, tw, th + 0.06, td, PLASTER);
  k.box(px, y, cz, tw + 0.04, 0.1, td + 0.04, LACQUER);
  k.box(px, y + th - 0.07, cz, tw + 0.04, 0.07, td + 0.04, LACQUER);
  for (const sx of [-1, 0, 1]) for (const sz of [-1, 1]) k.box(px + (sx * tw) / 2, y + 0.1, cz + (sz * td) / 2, 0.06, th - 0.17, 0.06, LACQUER);
  for (const sx of [-1, 1]) {
    k.pane(px + sx * 0.25, y + 0.16, cz + td / 2, 0.3, th - 0.3, 1, PAPER, FIRE, PAPER_GLOW);
    k.pane(px + sx * 0.25, y + 0.16, cz - td / 2, 0.3, th - 0.3, 3, PAPER, LATE, PAPER_GLOW);
    k.pane(px + (sx * tw) / 2, y + 0.16, cz, 0.4, th - 0.3, sx > 0 ? 0 : 2, PAPER, FIRE, PAPER_GLOW);
  }
  k.box(px, y - 0.03, cz, tw + 0.3, 0.03, td + 0.3, TIMBER);
  for (const s of [-1, 1]) {
    k.box(px, y + 0.09, cz + s * (td / 2 + 0.13), tw + 0.3, 0.022, 0.022, LACQUER);
    k.box(px + s * (tw / 2 + 0.13), y + 0.09, cz, 0.022, 0.022, td + 0.3, LACQUER);
    for (const t of [-1, 1]) k.box(px + s * (tw / 2 + 0.13), y, cz + t * (td / 2 + 0.13), 0.035, 0.13, 0.035, LACQUER);
  }
  const ty = sweptRoof(k, px, y + th, cz, tw + 0.76, td + 0.76, 0.5, JADE, 0.16, JADE_DARK);
  for (const sx of [-1, 1]) {
    k.box(px + sx * ((tw - td) / 2 + 0.03), ty, cz, 0.06, 0.13, 0.06, GOLD);
    for (const sz of [-1, 1]) k.box(px + sx * (tw / 2 + 0.37), y + th + 0.135, cz + sz * (td / 2 + 0.37), 0.055, 0.06, 0.055, GOLD);
  }
  k.box(px, ty, cz, 0.03, 0.3, 0.03, GOLD);
  k.box(px, ty + 0.3, cz, 0.07, 0.07, 0.07, GOLD);

  // the entrance: a gabled porch out of the first roof, the curtain across it with its plain circle
  const ez = cz + sizes[0][1] / 2, pz = ez + 0.5;
  k.box(px, 0.12, ez + 0.012, 0.8, 0.4, 0.02, SHADOW);
  for (const sx of [-1, 1]) k.box(px + sx * 0.52, 0, pz, 0.08, 0.62, 0.08, LACQUER);
  k.box(px, 0.56, pz, 1.12, 0.06, 0.07, LACQUER);
  k.gable(px, 0.62, ez + 0.2, 1.36, 0.34, 0.76, JADE, PLASTER, true);
  k.box(px, 0.93, ez + 0.2, 0.05, 0.05, 0.8, JADE_DARK);
  k.box(px, 0.93, ez + 0.6, 0.07, 0.1, 0.05, GOLD);
  for (const i of [-1, 0, 1]) k.box(px + i * 0.32, 0.3, pz, 0.3, 0.26, 0.014, CURTAIN);
  k.face(px, 0.43, pz + 0.011, 0.075, PLASTER, 10);
  for (const sx of [-1, 1]) k.glowBox(px + sx * 0.64, 0.36, pz, 0.08, 0.12, 0.08, LANTERN, FIRE, LANTERN_GLOW);

  // the bridge: a red arch with railings and gold-capped end posts
  const z0 = wz - 0.34, z1 = wz + 0.34, bw = 0.2, n = 6;
  const arc = (t: number): number => 0.06 + Math.sin(t * Math.PI) * 0.13;
  for (let i = 0; i < n; i++) {
    const t0 = i / n, t1 = (i + 1) / n, za = z0 + (z1 - z0) * t0, zb = z0 + (z1 - z0) * t1, ya = arc(t0), yb = arc(t1);
    k.quad([px - bw, ya, za], [px + bw, ya, za], [px + bw, yb, zb], [px - bw, yb, zb], hex(0x9a4f3a), [px, -1, wz]);
    for (const sx of [-1, 1]) {
      const x = px + sx * bw;
      k.quad([x, ya - 0.05, za], [x, ya, za], [x, yb, zb], [x, yb - 0.05, zb], LACQUER, [px, 0, wz]);
      k.quad([x, ya - 0.05, za], [x, ya, za], [x, yb, zb], [x, yb - 0.05, zb], scale(LACQUER, 0.7), [px + sx * 3, 0, wz]);
      k.bar([x, ya + 0.12, za], [x, yb + 0.12, zb], 0.013, LACQUER);
      if (i > 0) k.box(x, ya, za, 0.025, 0.12, 0.025, LACQUER);
    }
  }
  for (const sx of [-1, 1]) for (const z of [z0, z1]) {
    k.box(px + sx * bw, 0, z, 0.05, 0.24, 0.05, LACQUER);
    k.box(px + sx * bw, 0.24, z, 0.065, 0.035, 0.065, GOLD);
  }
  for (const sx of [-1, 1]) {
    const lx = px + sx * 0.5;
    k.box(lx, 0, z1 + 0.06, 0.03, 0.3, 0.03, TIMBER);
    k.glowBox(lx, 0.3, z1 + 0.06, 0.08, 0.1, 0.08, LANTERN, FIRE, LANTERN_GLOW);
  }

  // the boiler house and its chimney, steam turning off the top
  const hx = hw - 0.3, hz = cz - 0.75;
  k.box(hx - 0.02, 0, hz + 0.55, 0.4, 0.5, 0.6, hex(0x8a5a48));
  k.gable(hx - 0.02, 0.5, hz + 0.55, 0.46, 0.16, 0.66, JADE_DARK, hex(0x8a5a48), true);
  k.glowBox(hx - 0.02, 0.1, hz + 0.855, 0.14, 0.16, 0.01, SHADOW, FIRE, hex(0xff8a28));
  frustum(k, hx, 0, hz, 0.36, 0.36, 0.2, 0.2, 3.3, hex(0x9a5a48), DARK);
  k.box(hx, 1.6, hz, 0.3, 0.05, 0.3, hex(0x6a3a30));
  k.box(hx, 3.3, hz, 0.25, 0.07, 0.25, hex(0x4a3a36));
  k.spin(hx, 3.4, hz, 'y', 0.3, (s) => {
    const steam = hex(0xf2f4f6);
    for (let i = 0; i < 5; i++) blob(s, 0.04 + i * 0.09, i * 0.12, Math.sin(i * 1.7) * 0.06, 0.1 + i * 0.025, 0.09 + i * 0.02, 0.1 + i * 0.025, steam, 6, 2, 0.6);
  });
  // a pine either side of the court
  for (const sx of [-1, 1]) {
    const tx = px + sx * 1.75, tzz = cz + 1.62;
    k.cyl(tx, 0, tzz, 0.03, 0.22, TIMBER, 5);
    blob(k, tx, 0.2, tzz, 0.17, 0.12, 0.15, hex(0x3f7a4a), 6, 2, 0.4);
    blob(k, tx + 0.05, 0.33, tzz, 0.11, 0.09, 0.1, hex(0x4a8a54), 6, 2, 0.4);
  }
};

// ---- the clock gate (2 × 2) ------------------------------------------------------------------------

/**
 * A spirit town's gate: a squat deep-red stucco tower with a round tunnel straight through it, a big
 * pale clock over the arch, a belfry under a green copper roof, a lantern either side, and a stone frog
 * sitting out in front.
 */
const clockGate: Draw = (k, _W, D) => {
  const bw = 1.5, bd = 1.0, bz = -0.15, H = 1.05, aw = 0.27, spring = 0.32, crown = spring + aw;
  const z0 = bz - bd / 2, z1 = bz + bd / 2, stone = hex(0xcfc6b0);
  k.box(0, 0, 0, 2 * aw + 0.1, 0.02, D - 0.3, hex(0x85807a));
  // two piers and the wall over the passage
  const pw = bw / 2 - aw;
  for (const sx of [-1, 1]) {
    const x = sx * (aw + pw / 2);
    k.box(x, 0, bz, pw, H, bd, STUCCO);
    k.box(x + sx * 0.02, 0, bz, pw, 0.14, bd + 0.05, stone);
    k.box(sx * (aw - 0.003), 0.02, bz, 0.01, spring - 0.02, bd - 0.02, SHADOW);
  }
  k.box(0, crown, bz, 2 * aw, H - crown, bd, STUCCO);
  // the round arch: its dark soffit, the wall either side of the curve, and a stone ring on both faces
  const n = 8;
  for (let i = 0; i < n; i++) {
    const t0 = (i / n) * Math.PI, t1 = ((i + 1) / n) * Math.PI;
    const x0 = Math.cos(t0) * aw, y0 = spring + Math.sin(t0) * aw, x1 = Math.cos(t1) * aw, y1 = spring + Math.sin(t1) * aw;
    k.quad([x0, y0, z0], [x1, y1, z0], [x1, y1, z1], [x0, y0, z1], SHADOW, [(x0 + x1) * 2, (y0 + y1) / 2 + 1, bz]);
    for (const [z, s] of [[z0, -1], [z1, 1]] as const) {
      k.quad([x0, y0, z], [x1, y1, z], [x1, crown, z], [x0, crown, z], STUCCO, [0, crown - 0.1, bz]);
      k.bar([x0 * 1.06, spring + (y0 - spring) * 1.06, z + s * 0.012], [x1 * 1.06, spring + (y1 - spring) * 1.06, z + s * 0.012], 0.028, stone);
    }
  }
  // cornice, the clock, windows and lanterns
  k.box(0, H, bz, bw + 0.1, 0.06, bd + 0.1, stone);
  const cy = 0.83, cr = 0.165;
  k.face(0, cy, z1 + 0.004, cr * 1.18, hex(0x3f6f60), 14);
  k.face(0, cy, z1 + 0.01, cr, hex(0xf2ecd8), 14);
  k.glowBox(0, cy - cr * 0.7, z1 + 0.014, cr * 1.4, cr * 1.4, 0.004, hex(0xf2ecd8), [17.2, 30, 1.2], WARM_GLOW);
  k.spin(0, cy, z1 + 0.022, 'z', 0, (h) => h.box(0, 0, 0, 0.018, cr * 0.55, 0.004, DARK), 'hour');
  k.spin(0, cy, z1 + 0.03, 'z', 0, (h) => h.box(0, 0, 0, 0.012, cr * 0.85, 0.004, DARK), 'minute');
  for (const sx of [-1, 1]) {
    k.pane(sx * 0.52, 0.66, z1, 0.13, 0.2, 1, DARK, EVENING, WARM_GLOW);
    k.pane(sx * 0.52, 0.66, z0, 0.13, 0.2, 3, DARK, LATE, WARM_GLOW);
    k.pane(sx * 0.52, 0.22, z1, 0.1, 0.14, 1, DARK, LATE, WARM_GLOW);
    k.pane((sx * bw) / 2, 0.66, bz, 0.16, 0.2, sx > 0 ? 0 : 2, DARK, EVENING, WARM_GLOW);
    k.box(sx * 0.4, 0.5, z1 + 0.05, 0.02, 0.02, 0.1, DARK);
    k.glowBox(sx * 0.4, 0.4, z1 + 0.09, 0.06, 0.09, 0.06, LANTERN, FIRE, LANTERN_GLOW);
    k.glowBox(sx * 0.4, 0.4, z0 - 0.09, 0.06, 0.09, 0.06, LANTERN, FIRE, LANTERN_GLOW);
  }
  // the copper roof, cut off for a belfry with a bell in it
  const ry = H + 0.06;
  frustum(k, 0, ry, bz, bw + 0.18, bd + 0.18, 0.62, 0.5, 0.36, COPPER, scale(COPPER, 0.8));
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * 0.22, ry + 0.36, bz + sz * 0.17, 0.07, 0.28, 0.07, STUCCO);
  k.cone(0, ry + 0.44, bz, 0.09, 0.14, GOLD, 8);
  k.box(0, ry + 0.57, bz, 0.02, 0.08, 0.02, DARK);
  k.box(0, ry + 0.64, bz, 0.6, 0.04, 0.5, stone);
  k.hip(0, ry + 0.68, bz, 0.7, 0.34, 0.6, COPPER);
  k.box(0, ry + 1.0, bz, 0.02, 0.16, 0.02, DARK);
  k.box(0, ry + 1.14, bz, 0.05, 0.05, 0.05, GOLD);
  // the frog on its plinth
  const fx = 0.62, fz = 0.68;
  k.box(fx, 0, fz, 0.3, 0.1, 0.3, stone);
  blob(k, fx, 0.13, fz - 0.03, 0.11, 0.1, 0.12, FROG, 6, 2, 0.3);
  blob(k, fx, 0.2, fz + 0.06, 0.08, 0.06, 0.08, FROG, 6, 2, 0.4);
  for (const sx of [-1, 1]) {
    k.box(fx + sx * 0.045, 0.245, fz + 0.07, 0.03, 0.03, 0.03, scale(FROG, 1.1), DARK);
    k.box(fx + sx * 0.1, 0.1, fz - 0.06, 0.05, 0.06, 0.1, scale(FROG, 0.9));
    k.box(fx + sx * 0.06, 0.1, fz + 0.09, 0.03, 0.07, 0.03, scale(FROG, 0.9));
  }
};

