/** The stamp for a town of this style and size. */
export function townStamp(style: Arch, kind: TownKind): StampLook {
  const s = STYLE[style];
  if (s) return { icon: s[0], colour: s[1], label: ARCH_LABEL[style] ?? style };
  const k = KIND[kind];
  return { icon: k[0], colour: k[1], label: k[2] };
}

/** The stamp out in the country: the biome's, or the plain countryside's. */
export function landStamp(region: RegionKind | null | undefined): StampLook {
  const b = region ? BIOME[region] : undefined;
  if (region && b) return { icon: b[0], colour: b[1], label: REGIONS[region].title.replace(/^the /i, '') };
  return { icon: '🚗', colour: '#2f7a5a', label: 'Countryside' };
}
