import * as THREE from 'three';
import { N, CHUNK, World, RoadType, REGION_KINDS, inB, idx, heightAt, type Road, type RegionKind, type Town } from '../world/tiles';
import { REGIONS } from '../world/regions';
import { isJunction, isWide, nodeCenter } from '../world/roads';
import { inSweep } from '../world/curves';
import { hex, scale, type RGB } from '../world/biomes';
import { hash2 } from '../world/rng';
import { GlowBuf, PoolBuf, type Sched } from './nightLights';
import { propXray } from './xray';

const postMaterial = new THREE.MeshStandardMaterial({ vertexColors: true, flatShading: true, roughness: 0.6, metalness: 0.2 });
// a post between the eye and the car is stippled away with the trees around it
postMaterial.onBeforeCompile = (shader) => propXray(shader);

type P3 = [number, number, number];

/** Flat-coloured solids in world space: lamp posts and arms, bridge decks and piers. */
export class SolidBuf {
  pos: number[] = [];
  col: number[] = [];

  /** A convex solid from 8 corners: a bottom ring (0..3) and the top ring above it (4..7), in the same order. */
  hull(p: P3[], c: RGB): void {
    const I: P3 = [0, 0, 0];
    for (const q of p) { I[0] += q[0] / 8; I[1] += q[1] / 8; I[2] += q[2] / 8; }
    const tri = (a: P3, b: P3, e: P3) => {
      const ux = b[0] - a[0], uy = b[1] - a[1], uz = b[2] - a[2], vx = e[0] - a[0], vy = e[1] - a[1], vz = e[2] - a[2];
      const nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
      const m = ((a[0] + b[0] + e[0]) / 3 - I[0]) * nx + ((a[1] + b[1] + e[1]) / 3 - I[1]) * ny + ((a[2] + b[2] + e[2]) / 3 - I[2]) * nz;
      const [s, t] = m < 0 ? [e, b] : [b, e];
      this.pos.push(...a, ...s, ...t);
      for (let k = 0; k < 3; k++) this.col.push(c[0], c[1], c[2]);
    };
    const quad = (a: number, b: number, e: number, f: number) => { tri(p[a], p[b], p[e]); tri(p[a], p[e], p[f]); };
    quad(4, 5, 6, 7); quad(0, 1, 2, 3);
    quad(0, 1, 5, 4); quad(1, 2, 6, 5); quad(2, 3, 7, 6); quad(3, 0, 4, 7);
  }

  box(x: number, y: number, z: number, w: number, h: number, d: number, c: RGB): void {
    const x0 = x - w / 2, x1 = x + w / 2, z0 = z - d / 2, z1 = z + d / 2, y1 = y + h;
    const I: P3 = [x, y + h / 2, z];
    const tri = (a: P3, b: P3, e: P3) => {
      const ux = b[0] - a[0], uy = b[1] - a[1], uz = b[2] - a[2], vx = e[0] - a[0], vy = e[1] - a[1], vz = e[2] - a[2];
      const nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
      const m = ((a[0] + b[0] + e[0]) / 3 - I[0]) * nx + ((a[1] + b[1] + e[1]) / 3 - I[1]) * ny + ((a[2] + b[2] + e[2]) / 3 - I[2]) * nz;
      const [p, q] = m < 0 ? [e, b] : [b, e];
      this.pos.push(...a, ...p, ...q);
      for (let k = 0; k < 3; k++) this.col.push(c[0], c[1], c[2]);
    };
    const quad = (a: P3, b: P3, e: P3, f: P3) => { tri(a, b, e); tri(a, e, f); };
    quad([x0, y1, z0], [x1, y1, z0], [x1, y1, z1], [x0, y1, z1]);
    quad([x0, y, z1], [x1, y, z1], [x1, y1, z1], [x0, y1, z1]);
    quad([x0, y, z0], [x1, y, z0], [x1, y1, z0], [x0, y1, z0]);
    quad([x1, y, z0], [x1, y, z1], [x1, y1, z1], [x1, y1, z0]);
    quad([x0, y, z0], [x0, y, z1], [x0, y1, z1], [x0, y1, z0]);
  }
  mesh(): THREE.Mesh | null {
    if (!this.pos.length) return null;
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.pos, 3));
    g.setAttribute('color', new THREE.Float32BufferAttribute(this.col, 3));
    g.computeVertexNormals();
    g.computeBoundingSphere();
    const m = new THREE.Mesh(g, postMaterial);
    m.castShadow = true;
    return m;
  }
}

/** highway: tall double-arm lamps in a four-lane median; street: single arm over a two-lane road;
 *  lane: short globe beside a paved lane; lantern: wooden post with a lantern on dirt lanes in towns;
 *  paper: a stone post carrying a glowing paper box (the Terraces); torch: a short post with a fire bowl (the Sands).
 *  And six more that follow a town's style or the place (see `styleLamp`): gaslight, a cast-iron gas lamp
 *  (Victorian, classical, gothic, Budapest and colonial towns); bracket, a wrought-iron post with a lantern hung off a scroll
 *  (Tudor, medieval and Dutch towns); deco, a fluted post with two frosted globes (art deco towns); modern, a slim
 *  pole with an LED blade (modernist, brutalist and postmodern towns, and every megalopolis); bollard, a
 *  squat glowing post along a seafront; utility, a wooden pole with a crossarm and a cobra-head light on
 *  a paved country road. */
type LampKind = 'highway' | 'street' | 'lane' | 'lantern' | 'paper' | 'torch' | 'gaslight' | 'bracket' | 'deco' | 'modern' | 'bollard' | 'utility';
interface Lamp { x: number; z: number; ax: number; az: number; kind: LampKind }

const SPACING = [0, 6, 5, 4, 4];
const KIND: LampKind[] = ['lane', 'lantern', 'lane', 'street', 'highway'];

/**
 * What a biome does to the lamps on a road tile: the town's own biome if it has one, else the tile's.
 * Highways keep their lamps everywhere; 'none' (the Veldt) leaves villages and open roads dark but
 * lights a city as usual.
 */
function biomeLamp(w: World, tile: number, kind: LampKind): LampKind | null {
  if (kind === 'highway') return kind;
  const tid = w.townId[tile];
  const town: (Town & { region?: RegionKind }) | undefined = tid >= 0 ? (w.towns[tid]?.id === tid ? w.towns[tid] : w.towns.find((t) => t.id === tid)) : undefined;
  const region = town?.region ?? (w.regionK[tile] > 0 ? REGION_KINDS[w.regionK[tile] - 1] : undefined);
  const lamp = region ? REGIONS[region]?.lamp : undefined;
  if (lamp === 'lantern') return 'paper';
  if (lamp === 'torch') return 'torch';
  if (lamp === 'none' && (!town || town.kind === 'rural' || town.kind === 'suburb')) return null;
  return kind;
}

/** How near the sea, in tiles, a town street counts as the seafront. */
const SEAFRONT = 4;

/**
 * The lamp a town's style or the place asks for, over what the road type alone would put there. A biome's
 * own lamps (paper, torch, none) have already won by now, and a highway keeps its double-arm lamps.
 */
function styleLamp(w: World, tile: number, kind: LampKind, road: RoadType): LampKind {
  if (kind === 'highway' || kind === 'paper' || kind === 'torch') return kind;
  const tid = w.townId[tile];
  const town = tid >= 0 ? (w.towns[tid]?.id === tid ? w.towns[tid] : w.towns.find((t) => t.id === tid)) : undefined;
  if (town?.region) return kind;
  // the seafront, in a town or out of one: bollards along the promenade rather than posts
  if (road !== RoadType.Dirt && w.coastDist[tile] <= SEAFRONT) return 'bollard';
  if (!town) return road === RoadType.Dirt ? kind : 'utility';
  if (town.kind === 'mega') return 'modern';
  switch (town.style) {
    case 'victorian': case 'classic': case 'gothic': return 'gaslight';
    case 'tudor': case 'medieval': case 'dutch': return 'bracket';
    case 'budapest': case 'colonial': return 'gaslight';
    case 'japanese': return 'paper';
    case 'western': return 'lantern';
    case 'deco': return 'deco';
    // Russia keeps gaslights on its squares, the bazaar towns hang lanterns, and Mesoamerica burns torches
    case 'russian': return 'gaslight';
    case 'ottoman': return 'lantern';
    case 'maya': return 'torch';
    // the classical world burns oil in bronze, China hangs paper lanterns, and the tropics hang them too
    case 'roman': return 'lantern';
    // the bay city keeps its cast-iron gaslights, as the hill streets still do
    case 'sanfran': return 'gaslight';
    // Tokyo's streets are lit by plain modern standards: the signs do the rest
    case 'tokyo': return 'modern';
    // and Osaka's: the signs light the streets there too
    case 'osaka': return 'modern';
    // the Adriatic's lanes are lit by iron lanterns on brackets off the house walls
    case 'adriatic': return 'bracket';
    // an onsen town's lanes are lit by gas lamps, as Ginzan's are
    case 'onsen': return 'gaslight';
    // the lake towns: Léman's and Como's lungolago keep their cast-iron lanterns
    case 'leman': return 'gaslight';
    case 'como': return 'bracket';
    // Paris and Washington keep their cast-iron lanterns; New York its gaslight-era posts
    case 'paris': return 'gaslight';
    case 'capital': return 'gaslight';
    case 'newyork': return 'gaslight';
    // Chicago's streets keep their tall cast-iron and deco standards
    case 'chicago': return 'deco';
    case 'chinese': return 'paper';
    case 'seasia': return 'paper';
    // lanterns in the old quarters of the south and the east, gaslight in the iron-balcony cities, plain
    // standards under the glass towers, and torches in mud country
    case 'mughal': case 'moorish': case 'himalayan': case 'norse': case 'shire': return 'lantern';
    case 'sahel': return 'torch';
    case 'andean': case 'havana': case 'venice': case 'neworleans': case 'london': case 'steampunk': return 'gaslight';
    case 'whitecity': return 'bracket';
    case 'spirit': return 'paper';
    case 'motherroad': return 'deco';
    case 'hongkong': case 'vegas': case 'dubai': case 'solarpunk': case 'cyberpunk': return 'modern';
    case 'modernist': case 'brutalist': case 'postmodern': return 'modern';
    default: return kind;
  }
}

/** Lamp spots along a road: straight stretches only, off junctions, not where another road or a building sits beside. */
function lampsFor(w: World, r: Road): Lamp[] {
  const out: Lamp[] = [];
  const wide = isWide(r.type), every = SPACING[r.type], kind = KIND[r.type];
  const nodes = r.nodes;
  for (let k = 1; k < nodes.length - 1; k++) {
    if (k % every !== 2 % every) continue;
    const [px, pz] = nodeCenter(nodes[k - 1], wide), [cx, cz] = nodeCenter(nodes[k], wide), [nx, nz] = nodeCenter(nodes[k + 1], wide);
    const dx = Math.sign(nx - px), dz = Math.sign(nz - pz);
    if (dx !== 0 && dz !== 0) continue; // on a bend
    const tile = idx(Math.floor(cx - (wide ? 0.5 : 0)), Math.floor(cz - (wide ? 0.5 : 0)));
    if (isJunction(w, tile) || w.deckAxis[tile] || inSweep(w, tile)) continue; // a sweep's curve runs through the kerb there
    const biome = biomeLamp(w, tile, kind);
    if (!biome) continue;
    const here = styleLamp(w, tile, biome, r.type);
    if (wide) {
      out.push({ x: cx, z: cz, ax: -dz, az: dx, kind: here });
      continue;
    }
    if (r.type === RoadType.Dirt && w.townId[nodes[k]] < 0) continue;
    const side = r.type === RoadType.TwoLane && (k / every) % 2 >= 1 ? -1 : 1;
    const ox = -dz * side, oz = dx * side;
    const bx = Math.floor(cx) + ox, bz = Math.floor(cz) + oz;
    if (!inB(bx, bz)) continue;
    const beside = idx(bx, bz);
    if (w.road[beside] || w.blocked[beside] || w.water[beside] >= 0) continue;
    out.push({ x: cx + ox * 0.5, z: cz + oz * 0.5, ax: -ox, az: -oz, kind: here });
  }
  return out;
}

const WARM = hex(0xffdca8), COOL = hex(0xe2ecff), GLOBE = hex(0xffd08a), FLAME = hex(0xffae55);
const PAPER = hex(0xf4ecd8), PAPER_GLOW = hex(0xfff0d0), GRANITE = hex(0xa8a49c), EMBER = hex(0xff8a3a), BOWL = hex(0x5a4a3e), MUD = hex(0xc9a27a);
const STEEL = hex(0x9aa0a6), IRON = hex(0x3a3f45), WOOD = hex(0x6e4f33), BULB = hex(0xdfe3e6);
const GAS = hex(0xffcf78), WROUGHT = hex(0x2a2a2e), BRONZE = hex(0x6e5a3a), LED = hex(0xf0f6ff), SEA_GLOW = hex(0xd8f0ff), SODIUM = hex(0xffb25a);
const SLATE_GREY = hex(0x6e757c), BOLLARD = hex(0x3e4a52), POLE = hex(0x4e3a2a), INSULATOR = hex(0x7fa8a0);

/** A light pool draped over the ground as a small grid, lifted just clear of it. */
function pool(p: PoolBuf, w: World, cx: number, cz: number, r: number, s: Sched, g: RGB): void {
  const n = 4, step = (2 * r) / n;
  const y = (x: number, z: number) => heightAt(w, Math.min(N - 0.001, Math.max(0, x)), Math.min(N - 0.001, Math.max(0, z))) + 0.06;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      const x0 = cx - r + i * step, x1 = x0 + step, z0 = cz - r + j * step, z1 = z0 + step;
      const v = (x: number, z: number) => p.vert(x, y(x, z), z, (x - cx) / r, (z - cz) / r, s, g);
      v(x0, z0); v(x0, z1); v(x1, z1);
      v(x0, z0); v(x1, z1); v(x1, z0);
    }
  }
}

function drawLamp(w: World, L: Lamp, posts: SolidBuf, heads: GlowBuf, pools: PoolBuf): void {
  const y = heightAt(w, L.x, L.z);
  const on = 17.6 + hash2(Math.floor(L.x * 3), Math.floor(L.z * 3), 7) * 0.8;
  switch (L.kind) {
    case 'highway': {
      const H = 1.3, s: Sched = [on, 30, 2.2];
      posts.box(L.x, y, L.z, 0.06, H, 0.06, STEEL);
      for (const side of [1, -1]) {
        const hx = L.x + L.ax * 0.42 * side, hz = L.z + L.az * 0.42 * side;
        posts.box((L.x + hx) / 2, y + H - 0.03, (L.z + hz) / 2, Math.abs(hx - L.x) + 0.04, 0.03, Math.abs(hz - L.z) + 0.04, STEEL);
        heads.box(hx, y + H - 0.08, hz, 0.16, 0.05, 0.16, BULB, s, COOL);
        pool(pools, w, hx, hz, 1.0, [on, 30, 0.55], COOL);
      }
      break;
    }
    case 'street': {
      const H = 0.95, s: Sched = [on, 30, 2.0];
      const hx = L.x + L.ax * 0.34, hz = L.z + L.az * 0.34;
      posts.box(L.x, y, L.z, 0.045, H, 0.045, IRON);
      posts.box((L.x + hx) / 2, y + H - 0.03, (L.z + hz) / 2, Math.abs(hx - L.x) + 0.035, 0.03, Math.abs(hz - L.z) + 0.035, IRON);
      heads.box(hx, y + H - 0.07, hz, 0.12, 0.045, 0.12, BULB, s, WARM);
      pool(pools, w, hx, hz, 0.8, [on, 30, 0.5], WARM);
      break;
    }
    case 'lane': {
      const H = 0.55, s: Sched = [on, 30, 1.8];
      posts.box(L.x, y, L.z, 0.035, H, 0.035, IRON);
      heads.box(L.x, y + H, L.z, 0.09, 0.09, 0.09, scale(BULB, 0.95), s, GLOBE);
      pool(pools, w, L.x + L.ax * 0.2, L.z + L.az * 0.2, 0.6, [on, 30, 0.45], GLOBE);
      break;
    }
    case 'lantern': {
      const H = 0.48, off = 24.5 + hash2(Math.floor(L.x * 3), Math.floor(L.z * 3), 8);
      const hx = L.x + L.ax * 0.12, hz = L.z + L.az * 0.12;
      posts.box(L.x, y, L.z, 0.05, H, 0.05, WOOD);
      posts.box((L.x + hx) / 2, y + H - 0.02, (L.z + hz) / 2, Math.abs(hx - L.x) + 0.04, 0.03, Math.abs(hz - L.z) + 0.04, WOOD);
      heads.box(hx, y + H - 0.13, hz, 0.06, 0.08, 0.06, hex(0xc9b27a), [on, off, 1.6], FLAME);
      pool(pools, w, hx, hz, 0.45, [on, off, 0.4], FLAME);
      break;
    }
    case 'paper': {
      // a stone lantern post: a plinth, a shaft, a paper box under a little flared cap
      const H = 0.34, off = 24 + hash2(Math.floor(L.x * 3), Math.floor(L.z * 3), 8) * 2;
      posts.box(L.x, y, L.z, 0.1, 0.05, 0.1, GRANITE);
      posts.box(L.x, y + 0.05, L.z, 0.045, H - 0.05, 0.045, GRANITE);
      posts.box(L.x, y + H, L.z, 0.1, 0.02, 0.1, GRANITE);
      heads.box(L.x, y + H + 0.02, L.z, 0.08, 0.1, 0.08, PAPER, [on, off, 2.0], PAPER_GLOW);
      posts.box(L.x, y + H + 0.12, L.z, 0.15, 0.02, 0.15, scale(GRANITE, 0.8));
      posts.box(L.x, y + H + 0.14, L.z, 0.07, 0.03, 0.07, scale(GRANITE, 0.8));
      pool(pools, w, L.x, L.z, 0.5, [on, off, 0.45], PAPER_GLOW);
      break;
    }
    case 'gaslight': {
      // a cast-iron column on a stepped foot, a ladder bar under a four-sided glass lantern and its cap
      const H = 0.62, s: Sched = [on, 30, 1.9];
      posts.box(L.x, y, L.z, 0.09, 0.07, 0.09, IRON);
      posts.box(L.x, y + 0.07, L.z, 0.04, H - 0.07, 0.04, IRON);
      posts.box(L.x, y + H - 0.12, L.z, 0.16, 0.018, 0.018, IRON);
      heads.box(L.x, y + H, L.z, 0.1, 0.12, 0.1, hex(0xf0e2b8), s, GAS);
      posts.box(L.x, y + H + 0.12, L.z, 0.13, 0.025, 0.13, IRON);
      posts.box(L.x, y + H + 0.145, L.z, 0.04, 0.05, 0.04, IRON);
      pool(pools, w, L.x, L.z, 0.6, [on, 30, 0.45], GAS);
      break;
    }
    case 'bracket': {
      // a wrought-iron post leaning a scrolled arm out over the cobbles, a lantern hung from its end
      const H = 0.72, off = 24.5 + hash2(Math.floor(L.x * 3), Math.floor(L.z * 3), 8);
      const hx = L.x + L.ax * 0.2, hz = L.z + L.az * 0.2;
      posts.box(L.x, y, L.z, 0.035, H, 0.035, WROUGHT);
      posts.box((L.x + hx) / 2, y + H - 0.03, (L.z + hz) / 2, Math.abs(hx - L.x) + 0.03, 0.022, Math.abs(hz - L.z) + 0.03, WROUGHT);
      posts.box(L.x + L.ax * 0.08, y + H - 0.1, L.z + L.az * 0.08, 0.025, 0.07, 0.025, WROUGHT);
      posts.box(hx, y + H - 0.08, hz, 0.012, 0.05, 0.012, WROUGHT);
      heads.box(hx, y + H - 0.2, hz, 0.075, 0.11, 0.075, hex(0xd8b870), [on, off, 1.8], FLAME);
      posts.box(hx, y + H - 0.09, hz, 0.1, 0.02, 0.1, WROUGHT);
      pool(pools, w, hx, hz, 0.5, [on, off, 0.42], FLAME);
      break;
    }
    case 'deco': {
      // a fluted column with a crossbar carrying two frosted globes, and a spike between them
      const H = 0.78, s: Sched = [on, 30, 2.0];
      posts.box(L.x, y, L.z, 0.1, 0.06, 0.1, BRONZE);
      posts.box(L.x, y + 0.06, L.z, 0.05, H - 0.06, 0.05, BRONZE);
      for (const f of [-1, 1]) posts.box(L.x + f * 0.028, y + 0.12, L.z, 0.01, H - 0.2, 0.052, scale(BRONZE, 0.8));
      const px = -L.az, pz = L.ax;
      posts.box(L.x, y + H, L.z, Math.abs(px) * 0.3 + 0.03, 0.025, Math.abs(pz) * 0.3 + 0.03, BRONZE);
      for (const side of [-1, 1]) {
        const gx = L.x + px * 0.14 * side, gz = L.z + pz * 0.14 * side;
        heads.box(gx, y + H + 0.025, gz, 0.085, 0.085, 0.085, hex(0xf4efe4), s, WARM);
        pool(pools, w, gx, gz, 0.55, [on, 30, 0.4], WARM);
      }
      posts.box(L.x, y + H + 0.025, L.z, 0.015, 0.14, 0.015, BRONZE);
      break;
    }
    case 'modern': {
      // a slim grey pole and a flat LED blade out over the road, cool and bright
      const H = 1.1, s: Sched = [on, 30, 2.4];
      const hx = L.x + L.ax * 0.4, hz = L.z + L.az * 0.4;
      posts.box(L.x, y, L.z, 0.035, H, 0.035, SLATE_GREY);
      posts.box((L.x + hx) / 2, y + H - 0.015, (L.z + hz) / 2, Math.abs(hx - L.x) + 0.025, 0.018, Math.abs(hz - L.z) + 0.025, SLATE_GREY);
      heads.box(hx, y + H - 0.03, hz, 0.19, 0.02, 0.19, hex(0xe9eef2), s, LED);
      pool(pools, w, hx, hz, 0.95, [on, 30, 0.55], LED);
      break;
    }
    case 'bollard': {
      // a squat post with a band of light round its head, a pair of them either side of the road: one at
      // the kerb the lamp stands on and one on the far kerb, a tile across (`ax` points across the road).
      // At 0.45 the far one stood in the carriageway instead, which on a causeway read as one strip of
      // lights down the middle of the road and one off to the side.
      const H = 0.22, s: Sched = [on, 30, 1.6];
      for (const side of [0, 1]) {
        const bx = L.x + L.ax * side, bz = L.z + L.az * side;
        // the far kerb may be the edge of a causeway with nothing beyond it: no bollard out over the water
        if (side) {
          const fx = Math.floor(bx + L.ax * 0.3), fz = Math.floor(bz + L.az * 0.3);
          if (!inB(fx, fz)) continue;
          const f = idx(fx, fz);
          if (w.water[f] >= 0 && !w.deckAxis[f]) continue;
        }
        posts.box(bx, y, bz, 0.07, H, 0.07, BOLLARD);
        heads.box(bx, y + H, bz, 0.07, 0.05, 0.07, hex(0xdce8ee), s, SEA_GLOW);
        posts.box(bx, y + H + 0.05, bz, 0.08, 0.018, 0.08, BOLLARD);
        pool(pools, w, bx, bz, 0.35, [on, 30, 0.35], SEA_GLOW);
      }
      break;
    }
    case 'utility': {
      // a creosoted pole, a crossarm with its insulators, and a cobra-head sodium lamp out over the lane
      const H = 1.25, s: Sched = [on, 30, 2.1];
      const hx = L.x + L.ax * 0.3, hz = L.z + L.az * 0.3, px = -L.az, pz = L.ax;
      posts.box(L.x, y, L.z, 0.05, H, 0.05, POLE);
      posts.box(L.x, y + H - 0.08, L.z, Math.abs(px) * 0.4 + 0.03, 0.03, Math.abs(pz) * 0.4 + 0.03, POLE);
      for (const side of [-1, 1]) posts.box(L.x + px * 0.17 * side, y + H - 0.05, L.z + pz * 0.17 * side, 0.02, 0.04, 0.02, INSULATOR);
      posts.box((L.x + hx) / 2, y + H - 0.3, (L.z + hz) / 2, Math.abs(hx - L.x) + 0.02, 0.018, Math.abs(hz - L.z) + 0.02, STEEL);
      heads.box(hx, y + H - 0.33, hz, 0.1, 0.035, 0.1, hex(0xd8d4c8), s, SODIUM);
      pool(pools, w, hx, hz, 0.8, [on, 30, 0.5], SODIUM);
      break;
    }
    case 'torch': {
      // a squat mud post with a bowl of fire on top
      const H = 0.3, off = 23.5 + hash2(Math.floor(L.x * 3), Math.floor(L.z * 3), 8) * 2;
      posts.box(L.x, y, L.z, 0.08, H, 0.08, MUD);
      posts.box(L.x, y + H, L.z, 0.13, 0.04, 0.13, BOWL);
      heads.box(L.x, y + H + 0.04, L.z, 0.08, 0.05, 0.08, hex(0xe0a050), [on - 0.3, off, 2.4], EMBER);
      pool(pools, w, L.x, L.z, 0.55, [on - 0.3, off, 0.5], EMBER);
      break;
    }
  }
}

/** Every street lamp standing in this chunk, as posts, glowing heads and light pools. */
export function buildLampChunk(w: World, cx: number, cz: number): THREE.Group | null {
  const x0 = cx * CHUNK, z0 = cz * CHUNK;
  const posts = new SolidBuf(), heads = new GlowBuf(), pools = new PoolBuf();
  for (const r of w.roads) {
    for (const L of lampsFor(w, r)) {
      if (L.x < x0 || L.x >= x0 + CHUNK || L.z < z0 || L.z >= z0 + CHUNK) continue;
      drawLamp(w, L, posts, heads, pools);
    }
  }
  const parts = [posts.mesh(), heads.mesh(), pools.mesh()].filter((m): m is THREE.Mesh => m !== null);
  if (!parts.length) return null;
  const g = new THREE.Group();
  g.add(...parts);
  return g;
}
