import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
import type { CargoClass } from '../game/vehicles';
import { cargoModel } from './cargoModels';
import { SEEN_THROUGH, drapeFlat, laidFloor, laidGround, layFlat, type Ground } from './drape';

/**
 * Ground markers for cargo: a soft glow disc, a ring at the loading radius and a ripple that
 * keeps expanding out to it, with the goods themselves bobbing above and a gem floating over them.
 * Geometry is shared; every marker has its own materials so it can fade and blink on its own.
 *
 * A night run's marker (game/smuggling.ts) is the same thing with its outline cut into dashes and a
 * caution triangle lying in the middle of the ring, so an illegal job never reads as an honest one
 * however far away it is.
 *
 * What colour is game/cargoLook.ts's call (docs/cargolook.html): a look is a colour, and for the dark ones
 * (the Family, the Army) and the Press a rim in another, and for a mission's load a badge in its thread's.
 */

const flat = (g: THREE.BufferGeometry) => g.rotateX(-Math.PI / 2);
// the disc and the hoops are laid over the ground marker by marker (render/drape.ts drapeFlat), so they are cut
// finely enough to follow it: the disc in a grid, the thick hoop in three bands across
const DISC = flat(new THREE.PlaneGeometry(2, 2, 16, 16));
/** Goods wear a thick hoop; a destination wears a thin rim around its filled disc. */
const RING_THICK = flat(new THREE.RingGeometry(0.72, 1, 56, 3));
const RING_THIN = flat(new THREE.RingGeometry(0.88, 1, 56));
const WAVE = flat(new THREE.RingGeometry(0.95, 1, 56));
/** A look's rim: a thin band round each edge of the thick hoop (0.72–1), in the rim's colour. */
const EDGE_BANDS = (() => {
  const a = new THREE.RingGeometry(0.72, 0.785, 56), b = new THREE.RingGeometry(0.93, 1, 56);
  const m = mergeGeometries([a, b])!;
  a.dispose(); b.dispose();
  return flat(m);
})();

/** The dashed outline: this many dashes round the ring, each covering this much of its slot. */
const DASHES = 18, DUTY = 0.56;
/**
 * Goods the vehicle being driven can't carry: one flat, very dull grey, faint and still (no pulse, no ripple),
 * ring, arrow and load alike (docs/cargolook.html rule 1).
 */
const DULL_GREY = 0x6b6f73;
/** How much of a dull grey marker shows. */
const DULL_ALPHA = 0.45;

/** A marker's look: its colour, a rim in another (a dark look's glow, the Press's black band), a badge's. */
/** `beacon`: a pillar of light over the goods, seen from far off and from the air (long-haul work). */
/** `halo`: a dashed hazard band turning round outside the hoop, and the load drawn outsized (Ultra-Bulk work). */
export interface CargoLook { color: number; edge?: number; badge?: number; beacon?: boolean; halo?: boolean }
const lum = (c: number) => 0.299 * ((c >> 16) & 255) + 0.587 * ((c >> 8) & 255) + 0.114 * (c & 255);
/** The caution triangle's width, as a share of the ring's radius. */
const SIGN = 0.62;

/** One ring cut into dashes, so an illegal job's outline reads as a warning at a glance. */
function dashed(inner: number, outer: number): THREE.BufferGeometry {
  const step = (Math.PI * 2) / DASHES;
  const parts: THREE.BufferGeometry[] = [];
  for (let i = 0; i < DASHES; i++) parts.push(new THREE.RingGeometry(inner, outer, 4, outer - inner > 0.2 ? 3 : 1, i * step, step * DUTY));
  const merged = mergeGeometries(parts)!;
  for (const g of parts) g.dispose();
  return flat(merged);
}
const DASH_THICK = dashed(0.72, 1);
const DASH_THIN = dashed(0.88, 1);
const SIGN_PLANE = flat(new THREE.PlaneGeometry(1, 1));
/** Ultra-Bulk's hazard halo, outside the hoop, and how much bigger its load is drawn than any other. */
const HALO = dashed(1.12, 1.32);
const ULTRA_LIFT = 2.1;
const GEM = new THREE.OctahedronGeometry(0.09, 0).scale(1, 1.5, 1);
/** A long-haul load's beacon: a tall open shaft, its foot at the goods, fading towards the top (the vertex colours). */
const BEACON_HIGH = 34;
const BEACON = (() => {
  const g = new THREE.CylinderGeometry(0.16, 0.3, BEACON_HIGH, 10, 6, true).translate(0, BEACON_HIGH / 2, 0);
  const pos = g.getAttribute('position'), col = new Float32Array(pos.count * 3);
  for (let i = 0; i < pos.count; i++) { const f = 1 - pos.getY(i) / BEACON_HIGH; col[i * 3] = col[i * 3 + 1] = col[i * 3 + 2] = f * f; }
  g.setAttribute('color', new THREE.BufferAttribute(col, 3));
  return g;
})();
const BODY = new THREE.CylinderGeometry(0.03, 0.04, 0.11, 8).translate(0, 0.055, 0);
const HEAD = new THREE.SphereGeometry(0.032, 10, 8).translate(0, 0.14, 0);
const BOX = new THREE.BoxGeometry(1, 1, 1);
const BALE = new THREE.CylinderGeometry(0.07, 0.07, 0.15, 14).rotateZ(Math.PI / 2);

let glowTex: THREE.Texture | null = null;
function glowTexture(): THREE.Texture {
  if (glowTex) return glowTex;
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const g = c.getContext('2d')!;
  const grad = g.createRadialGradient(64, 64, 0, 64, 64, 64);
  grad.addColorStop(0, 'rgba(255,255,255,0.95)');
  grad.addColorStop(0.5, 'rgba(255,255,255,0.5)');
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = grad;
  g.fillRect(0, 0, 128, 128);
  glowTex = new THREE.CanvasTexture(c);
  glowTex.colorSpace = THREE.SRGBColorSpace;
  return glowTex;
}

let signTex: THREE.Texture | null = null;
/** The caution sign: a white triangle with a black outline and a bang inside it, drawn once (yellow is missions'). */
function cautionTexture(): THREE.Texture {
  if (signTex) return signTex;
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const g = c.getContext('2d')!;
  const cx = 64, top = 14, bot = 106, half = 53;
  g.beginPath();
  g.moveTo(cx, top);
  g.lineTo(cx + half, bot);
  g.lineTo(cx - half, bot);
  g.closePath();
  g.lineJoin = 'round';
  g.lineWidth = 13;
  g.strokeStyle = '#15161a';
  g.stroke();
  g.fillStyle = '#ffffff';
  g.fill();
  // the bang: a tapered bar over a dot
  g.fillStyle = '#15161a';
  g.beginPath();
  g.moveTo(cx - 8, 44);
  g.lineTo(cx + 8, 44);
  g.lineTo(cx + 5, 80);
  g.lineTo(cx - 5, 80);
  g.closePath();
  g.fill();
  g.beginPath();
  g.arc(cx, 92, 7, 0, Math.PI * 2);
  g.fill();
  signTex = new THREE.CanvasTexture(c);
  signTex.colorSpace = THREE.SRGBColorSpace;
  return signTex;
}

let badgeTex: THREE.Texture | null = null;
/** A mission load's badge: a round token, white (its material tints it) inside a dark outline, drawn once. */
function badgeTexture(): THREE.Texture {
  if (badgeTex) return badgeTex;
  const c = document.createElement('canvas');
  c.width = c.height = 64;
  const g = c.getContext('2d')!;
  g.beginPath();
  g.arc(32, 32, 27, 0, Math.PI * 2);
  g.fillStyle = '#ffffff';
  g.fill();
  g.lineWidth = 7;
  g.strokeStyle = 'rgba(21,22,26,0.85)';
  g.stroke();
  badgeTex = new THREE.CanvasTexture(c);
  badgeTex.colorSpace = THREE.SRGBColorSpace;
  return badgeTex;
}

export interface CargoMarker {
  group: THREE.Group;
  /**
   * The ripple, the caution sign and the arrow, which move or turn as they are posed: tilted together to the slope
   * under the ring and lifted clear of it (render/drape.ts layFlat). The disc, the hoop and the rim are laid over
   * the ground point by point instead (drapeFlat), each marker its own copy of them.
   */
  floor: THREE.Group;
  /** Where and how wide it was last laid, so it is laid again only when either changes. */
  laid?: string;
  /** The shared shapes its disc, hoop and rim were made from, flat: what each is laid from. */
  flat: { disc: THREE.BufferGeometry | null; ring: THREE.BufferGeometry; edge: THREE.BufferGeometry | null };
  lift: THREE.Group | null;   // the goods and gem, bobbing
  disc: THREE.Mesh | null;    // only a destination is filled in
  ring: THREE.Mesh; wave: THREE.Mesh;
  /** The caution triangle lying in the middle of an illegal job's ring; null on an honest one. */
  sign: THREE.Mesh | null;
  discMat: THREE.MeshBasicMaterial | null; ringMat: THREE.MeshBasicMaterial; waveMat: THREE.MeshBasicMaterial;
  signMat: THREE.MeshBasicMaterial | null;
  /** Goods waiting: an arrow lying in the ring pointing where they go (aimCargoMarker), and its outline. */
  arrow?: THREE.Group; arrowMat?: THREE.MeshBasicMaterial; arrowEdge?: THREE.MeshBasicMaterial; arrowGeo?: THREE.BufferGeometry[];
  /** The look's rim, drawn over the hoop, scaled and pulsed with it. */
  edge?: THREE.Mesh; edgeMat?: THREE.MeshBasicMaterial;
  /** The look as built: its colour, its rim, and the brighter of the two (what shows on dark ground). */
  look: { color: number; edge?: number; bright: number };
  mats: THREE.Material[];
  seed: number;
  /** Shown in greys: the vehicle being driven can't carry these goods at all (setCargoMarkerGrey). */
  grey?: boolean;
  /** The pillar of light over long-haul goods (CargoLook.beacon), pulsed with the ring. */
  beacon?: THREE.Mesh; beaconMat?: THREE.MeshBasicMaterial;
  /** Ultra-Bulk's hazard halo (CargoLook.halo), turning slowly round the ring. */
  halo?: THREE.Mesh; haloMat?: THREE.MeshBasicMaterial;
}

/**
 * Goods the vehicle being driven could never carry (freight or bulk in a Tomato) shown in one very dull grey,
 * faint and still: the ring, its arrow, its badge and the model of the load (docs/cargolook.html, 22 Oct
 * 2026; it had been each colour turned to its own lightness). Back in colour the moment a vehicle that can
 * carry them is driven.
 */
export function setCargoMarkerGrey(m: CargoMarker, grey: boolean): void {
  if (!!m.grey === grey) return;
  m.grey = grey;
  for (const mat of m.mats) greyMat(mat, grey);
}

function greyMat(mat: THREE.Material, grey: boolean): void {
  const c = (mat as THREE.MeshBasicMaterial).color;
  if (!c) return;
  const ud = mat.userData as { hue?: number };
  if (grey) {
    if (ud.hue === undefined) ud.hue = c.getHex();
    c.setHex(DULL_GREY);
  } else if (ud.hue !== undefined) {
    c.setHex(ud.hue);
    delete ud.hue;
  }
}

/** Tiles to the destination at which an arrow is at its daintiest, and at its boldest. */
const ARROW_NEAR = 12, ARROW_FAR = 160;

/**
 * A flat arrow, pointing along local +z once laid on the ground: a shaft `sw` wide and a head `hw` wide and
 * `hl` long, `len` long in all, centred on the ring. In units of the ring's radius.
 */
function arrowGeometry(len: number, sw: number, hw: number, hl: number): THREE.BufferGeometry {
  const sh = new THREE.Shape();
  const tail = -len / 2, neck = len / 2 - hl, tip = len / 2;
  // drawn pointing down the shape's −y, which flat() lays along +z
  sh.moveTo(-sw / 2, -tail);
  sh.lineTo(sw / 2, -tail);
  sh.lineTo(sw / 2, -neck);
  sh.lineTo(hw / 2, -neck);
  sh.lineTo(0, -tip);
  sh.lineTo(-hw / 2, -neck);
  sh.lineTo(-sw / 2, -neck);
  sh.closePath();
  return flat(new THREE.ShapeGeometry(sh));
}

/**
 * Goods waiting to be collected point the way they're going (the user, 15 Oct 2026): an arrow lying in the
 * ring, turned toward the destination at (dx, dz) from it, in world tiles. Bold, fat and long for a far
 * drop; short and dainty for one just down the road. In the ring's own colour, edged in a deeper shade of it,
 * so each arrow belongs to its circle (the user, 16 Oct 2026: it was white).
 */
export function aimCargoMarker(m: CargoMarker, dx: number, dz: number): void {
  if (!m.lift || m.arrow) return;
  const d = Math.hypot(dx, dz);
  if (d < 0.5) return;
  const f = Math.min(1, Math.max(0, (d - ARROW_NEAR) / (ARROW_FAR - ARROW_NEAR)));
  // inside the hoop (its inner edge is at 0.72 of the radius), longer and much fatter the further it goes
  const len = 0.62 + 0.64 * f, sw = 0.07 + 0.17 * f, hw = 0.26 + 0.32 * f, hl = 0.22 + 0.18 * f;
  const body = arrowGeometry(len, sw, hw, hl);
  const edge = arrowGeometry(len + 0.08, sw + 0.07, hw + 0.11, hl + 0.06);
  // the look's bright colour, edged in its other (white on black for the Press, gold on black for the Family)
  const hue = m.look.bright;
  const rim = m.look.edge === undefined ? new THREE.Color(hue).multiplyScalar(0.45).getHex() : (hue === m.look.edge ? m.look.color : m.look.edge);
  const arrowMat = overlay(hue), arrowEdge = overlay(rim);
  const a = new THREE.Group();
  const e = new THREE.Mesh(edge, arrowEdge), b = new THREE.Mesh(body, arrowMat);
  e.renderOrder = SEEN_THROUGH + 4; b.renderOrder = SEEN_THROUGH + 5;
  e.position.y = 0.014; b.position.y = 0.016;
  a.add(e, b);
  a.rotation.y = Math.atan2(dx, dz);
  m.floor.add(a);
  m.arrow = a; m.arrowMat = arrowMat; m.arrowEdge = arrowEdge; m.arrowGeo = [body, edge];
  m.mats.push(arrowMat, arrowEdge);
  if (m.grey) { greyMat(arrowMat, true); greyMat(arrowEdge, true); }
}

function overlay(color: number, map?: THREE.Texture): THREE.MeshBasicMaterial {
  return new THREE.MeshBasicMaterial({
    color, ...(map ? { map } : {}), transparent: true, depthWrite: false, toneMapped: false,
    polygonOffset: true, polygonOffsetFactor: -2, polygonOffsetUnits: -2,
  });
}

/**
 * A marker in a look (a colour, or a CargoLook). Goods (given a cargo class) get a thick pulsing hoop with a
 * model of the load bobbing inside it; a destination (no class) gets a solid glowing disc, so the two never
 * read as the same thing. A look's rim is drawn round both edges of the hoop; its badge floats over the gem.
 * `illegal` (a night run) cuts the hoop into dashes in the look's brighter colour and lays a caution
 * triangle in the middle of it. Given the cargo type's `id`, the load is that type's own model
 * (render/cargoModels.ts); without one, its class's plain model.
 */
export function buildCargoMarker(look: number | CargoLook, cls: CargoClass | null, illegal = false, id?: string): CargoMarker {
  const L: CargoLook = typeof look === 'number' ? { color: look } : look;
  const color = L.color, edgeCol = L.edge;
  const bright = edgeCol !== undefined && lum(edgeCol) > lum(color) ? edgeCol : color;
  const group = new THREE.Group();
  const floor = new THREE.Group();
  group.add(floor);
  const filled = cls === null;
  const discMat = filled ? overlay(bright, glowTexture()) : null;
  const ringMat = overlay(illegal || filled ? bright : color), waveMat = overlay(bright);
  const disc = discMat ? new THREE.Mesh(DISC, discMat) : null;
  const hoop = illegal ? (filled ? DASH_THIN : DASH_THICK) : (filled ? RING_THIN : RING_THICK);
  const ring = new THREE.Mesh(hoop, ringMat), wave = new THREE.Mesh(WAVE, waveMat);
  // drawn before the buildings, so a faded one between the camera and the ring lets it show (render/drape.ts SEEN_THROUGH)
  if (disc) { disc.renderOrder = SEEN_THROUGH + 2; group.add(disc); }
  ring.renderOrder = SEEN_THROUGH + 3; wave.renderOrder = SEEN_THROUGH + 3;
  ring.position.y = wave.position.y = 0.01;
  group.add(ring);
  floor.add(wave);
  const mats: THREE.Material[] = discMat ? [discMat, ringMat, waveMat] : [ringMat, waveMat];
  let edge: THREE.Mesh | undefined, edgeMat: THREE.MeshBasicMaterial | undefined;
  if (edgeCol !== undefined && !illegal && !filled) {
    edgeMat = overlay(edgeCol);
    edge = new THREE.Mesh(EDGE_BANDS, edgeMat);
    edge.renderOrder = SEEN_THROUGH + 3;
    edge.position.y = 0.012;
    group.add(edge);
    mats.push(edgeMat);
  }
  let sign: THREE.Mesh | null = null, signMat: THREE.MeshBasicMaterial | null = null;
  if (illegal) {
    signMat = overlay(0xffffff, cautionTexture());
    sign = new THREE.Mesh(SIGN_PLANE, signMat);
    sign.renderOrder = SEEN_THROUGH + 4;
    sign.position.y = 0.02;
    mats.push(signMat);
    floor.add(sign);
  }
  let lift: THREE.Group | null = null;
  if (cls) {
    lift = new THREE.Group();
    const paint = new THREE.MeshStandardMaterial({ color, roughness: 0.7 });
    const dark = new THREE.MeshStandardMaterial({ color: new THREE.Color(color).multiplyScalar(0.55), roughness: 0.8 });
    const pale = new THREE.MeshStandardMaterial({ color: edgeCol ?? 0xf4efe2, roughness: 0.8 });
    const gemMat = new THREE.MeshBasicMaterial({ color: bright, toneMapped: false });
    mats.push(paint, dark, pale, gemMat);
    const box = (mat: THREE.Material, w: number, h: number, d: number, x = 0, y = h / 2, z = 0) => {
      const m = new THREE.Mesh(BOX, mat);
      m.scale.set(w, h, d);
      m.position.set(x, y, z);
      m.castShadow = true;
      lift!.add(m);
    };
    const model = id ? cargoModel(id) : null;
    if (model) {
      // the type's own shape, shared by every marker of it, painted in this marker's materials by slot
      const skin = new THREE.MeshStandardMaterial({ color: 0xf1c7a1, roughness: 0.7 });
      mats.push(skin);
      const m = new THREE.Mesh(model, [paint, dark, pale, skin]);
      m.castShadow = true;
      lift.add(m);
    } else if (cls === 'people') {
      const skin = new THREE.MeshStandardMaterial({ color: 0xf1c7a1, roughness: 0.7 });
      mats.push(skin);
      for (const [x, z] of [[-0.06, 0.03], [0.06, 0.03], [0, -0.06]]) {
        const b = new THREE.Mesh(BODY, paint), h = new THREE.Mesh(HEAD, skin);
        b.position.set(x, 0, z); h.position.set(x, 0, z);
        b.castShadow = true;
        lift.add(b, h);
      }
    } else if (cls === 'parcel') {
      box(paint, 0.16, 0.12, 0.16);
      box(pale, 0.165, 0.125, 0.035);
    } else if (cls === 'freight') {
      box(dark, 0.26, 0.04, 0.26);
      box(paint, 0.22, 0.18, 0.22, 0, 0.13);
    } else if (cls === 'bulk') {
      for (const z of [-0.08, 0.08]) {
        const m = new THREE.Mesh(BALE, paint);
        m.position.set(0, 0.07, z);
        m.castShadow = true;
        lift.add(m);
      }
    } else {
      box(paint, 0.46, 0.18, 0.18);
      box(dark, 0.02, 0.185, 0.185, -0.23);
      box(dark, 0.02, 0.185, 0.185, 0.23);
    }
    const gem = new THREE.Mesh(GEM, gemMat);
    gem.position.y = 0.48;
    lift.add(gem);
    if (L.badge !== undefined) {
      // a mission's load: its thread's or chain's own colour, as a token over the gem, so a set reads as a set
      const badgeMat = new THREE.SpriteMaterial({ color: L.badge, map: badgeTexture(), depthWrite: false, toneMapped: false });
      const badge = new THREE.Sprite(badgeMat);
      badge.scale.set(0.17, 0.17, 1);
      badge.position.y = 0.7;
      badge.renderOrder = 6;
      lift.add(badge);
      mats.push(badgeMat);
    }
    lift.scale.setScalar(L.halo ? ULTRA_LIFT : 1.5);
    group.add(lift);
  }
  let halo: THREE.Mesh | undefined, haloMat: THREE.MeshBasicMaterial | undefined;
  if (L.halo && cls) {
    // in the rim's black, so it reads as a hazard band against the lime hoop inside it
    haloMat = overlay(edgeCol ?? color);
    halo = new THREE.Mesh(HALO, haloMat);
    halo.renderOrder = SEEN_THROUGH + 3;
    halo.position.y = 0.012;
    floor.add(halo);
    mats.push(haloMat);
  }
  let beacon: THREE.Mesh | undefined, beaconMat: THREE.MeshBasicMaterial | undefined;
  if (L.beacon && cls) {
    beaconMat = new THREE.MeshBasicMaterial({ color, vertexColors: true, transparent: true, depthWrite: false, toneMapped: false, blending: THREE.AdditiveBlending, side: THREE.DoubleSide });
    beacon = new THREE.Mesh(BEACON, beaconMat);
    beacon.renderOrder = SEEN_THROUGH + 4;
    group.add(beacon);
    mats.push(beaconMat);
  }
  return { group, floor, flat: { disc: disc ? DISC : null, ring: hoop, edge: edge ? EDGE_BANDS : null }, lift, disc, ring, wave, sign, discMat, ringMat, waveMat, signMat, edge, edgeMat, look: { color, edge: edgeCol, bright }, mats, seed: Math.random() * 10, beacon, beaconMat, halo, haloMat };
}

/**
 * Pulse the glow and ring, ripple outward to `radius`, bob the goods. `alpha` fades the whole marker;
 * `yaw` is the camera's, so a caution triangle lying on the ground stays the right way up on screen.
 */
export function poseCargoMarker(m: CargoMarker, time: number, radius: number, alpha = 1, yaw = 0): void {
  const t = time + m.seed;
  // laid to the ground under it, again whenever it moves or its ring changes size (its parent stands at the origin);
  // only while it shows, and a few a frame, so a new vehicle's reach doesn't lay every marker at once
  const ground = laidGround(), p = m.group.position;
  const key = ground ? `${p.x.toFixed(2)},${p.y.toFixed(2)},${p.z.toFixed(2)},${radius.toFixed(2)}${ground(p.x, p.z) === null ? '?' : ''}` : '';
  if (key !== m.laid && m.group.visible) {
    if (time !== layFrame) { layFrame = time; layLeft = LAYS_A_FRAME; }
    if (layLeft > 0) {
      layLeft--;
      m.laid = key;
      layMarker(m, radius);
    }
  }
  // goods that can't be carried: faint and still
  const dull = !!m.grey;
  if (dull) alpha *= DULL_ALPHA;
  const beat = dull ? 0.5 : 0.5 + 0.5 * Math.sin(t * 3.4);
  if (m.sign && m.signMat) {
    m.sign.scale.setScalar(radius * SIGN);
    m.sign.rotation.y = yaw;
    m.signMat.opacity = (0.8 + 0.2 * beat) * alpha;
  }
  if (m.disc && m.discMat) {
    m.disc.scale.setScalar(radius * (0.96 + 0.06 * beat));
    m.discMat.opacity = (0.5 + 0.25 * beat) * alpha;
  }
  m.ring.scale.setScalar(radius);
  m.ringMat.opacity = (0.6 + 0.35 * beat) * alpha;
  if (m.beacon && m.beaconMat) m.beaconMat.opacity = (0.45 + 0.3 * beat) * alpha;
  if (m.halo && m.haloMat) {
    m.halo.scale.setScalar(radius);
    m.halo.rotation.y = dull ? 0 : t * 0.5;
    m.haloMat.opacity = Math.min(1, (0.75 + 0.25 * beat) * alpha);
  }
  if (m.edge && m.edgeMat) {
    m.edge.scale.setScalar(radius);
    m.edgeMat.opacity = Math.min(1, (0.75 + 0.25 * beat) * alpha);
  }
  if (m.arrow && m.arrowMat && m.arrowEdge) {
    // laid in the ring at its size, breathing with it
    m.arrow.scale.setScalar(radius);
    m.arrowMat.opacity = (0.7 + 0.3 * beat) * alpha;
    m.arrowEdge.opacity = (0.5 + 0.25 * beat) * alpha;
  }
  const w = (t * 0.6) % 1;
  m.wave.scale.setScalar(radius * (0.2 + 0.8 * w));
  m.waveMat.opacity = dull ? 0 : (1 - w) * 0.85 * alpha;
  if (m.lift) {
    m.lift.position.y = 0.05 + (0.5 + 0.5 * Math.sin(t * 2.2)) * 0.08;
    m.lift.rotation.y = t * 0.8;
    m.lift.visible = alpha > 0.15 || dull;
  }
}

/** Markers laid over the ground in one frame, at most. */
const LAYS_A_FRAME = 6;
let layFrame = -1, layLeft = 0;

/**
 * Lay a marker over the ground under it at this radius: its own copies of the disc, hoop and rim, raised point by
 * point; the ripple, sign and arrow tilted to the slope. Where it stands on something other than the ground (a
 * deck, a roof, a ground not yet in memory), it goes back to the flat shapes.
 */
function layMarker(m: CargoMarker, radius: number): void {
  const p = m.group.position;
  // what it stands on: the ground (a road's top, the water's surface), or for goods on the seabed the bottom
  const near = (g: Ground | null) => { const y = g?.(p.x, p.z); return y !== null && y !== undefined && Math.abs(y - p.y) <= 0.3; };
  const ground = near(laidGround()) ? laidGround() : near(laidFloor()) ? laidFloor() : null;
  const own = (mesh: THREE.Mesh | null | undefined, src: THREE.BufferGeometry | null, s: number, on: boolean) => {
    if (!mesh || !src) return;
    if (mesh.geometry !== src) mesh.geometry.dispose();
    mesh.geometry = on && ground ? drapeFlat(src, s, p.x, p.y + mesh.position.y, p.z, ground) : src;
  };
  const on = !!ground && layFlat(m.floor, p.x, p.y, p.z, radius * 0.75, ground);
  own(m.ring, m.flat.ring, radius, on);
  own(m.edge, m.flat.edge, radius, on);
  own(m.disc, m.flat.disc, radius * 0.99, on);
}

export function disposeCargoMarker(m: CargoMarker): void {
  for (const mesh of [m.ring, m.edge, m.disc]) if (mesh && mesh.geometry !== m.flat.ring && mesh.geometry !== m.flat.edge && mesh.geometry !== m.flat.disc) mesh.geometry.dispose();
  m.group.removeFromParent();
  for (const mat of m.mats) mat.dispose();
  for (const g of m.arrowGeo ?? []) g.dispose();
}
