/**
 * The board (T): what the towns are asking, and the one being run.
 *
 * The left column lists every chain standing, with the step reached; the right shows the chosen one
 * with its next step measured in the units of the vehicle being driven. A chain the vehicle cannot do
 * is listed greyed with the reason it failed, never hidden — the board doubles as the reason to go and
 * buy the next vehicle.
 */
import { esc, money } from './cargoHud';
import type { Request, Requests } from './requests';
import type { VehicleDef } from './vehicles';

export interface BoardHost {
  /** The vehicle in the player's hands. */
  def(): VehicleDef;
  /** Point the camera at the next step's goods and drop a pin on the overview. */
  showMe(r: Request): void;
  /** Game hours now, for the clock on each card. */
  hours(): number;
  /** Told when the panel opens or closes, so the game can pause with it. */
  onToggle(open: boolean): void;
  /** A line the player should read. */
  say(title: string, body: string): void;
}

export class RequestBoard {
  private el = document.getElementById('requests')!;
  isOpen = false;
  /** Which card is chosen, by request id. */
  private chosen = -1;

  constructor(private requests: Requests, private host: BoardHost) {
    this.el.addEventListener('mousedown', (e) => { if (e.target === this.el) this.close(); });
    this.el.addEventListener('click', (e) => {
      const t = (e.target as HTMLElement).closest('[data-act], [data-pick]') as HTMLElement | null;
      if (!t) return;
      const pick = t.getAttribute('data-pick');
      if (pick) { this.chosen = Number(pick); this.render(); return; }
      this.act(t.getAttribute('data-act') ?? '');
    });
    window.addEventListener('keydown', (e) => {
      if (!this.isOpen) return;
      if (e.code === 'Escape') { this.close(); e.preventDefault(); return; }
      if (e.code === 'ArrowDown' || e.code === 'ArrowUp') {
        const list = this.requests.open;
        if (!list.length) return;
        const at = Math.max(0, list.findIndex((r) => r.id === this.chosen));
        const next = (at + (e.code === 'ArrowDown' ? 1 : list.length - 1)) % list.length;
        this.chosen = list[next].id;
        this.render();
        e.preventDefault();
        return;
      }
      if (e.code === 'Enter') {
        const r = this.current();
        if (r) this.act(r.state === 'taken' ? 'show' : 'take');
        e.preventDefault();
      }
    });
  }

  private current(): Request | null {
    const list = this.requests.open;
    return list.find((r) => r.id === this.chosen) ?? list[0] ?? null;
  }

  toggle(): void { if (this.isOpen) this.close(); else this.open(); }

  open(): void {
    this.isOpen = true;
    this.el.hidden = false;
    const running = this.requests.taken;
    if (running) this.chosen = running.id;
    this.render();
    this.host.onToggle(true);
  }

  /** Open at a town's first ask, by its key `cx,cz#id`; at the top when it has none. */
  openFor(key: string): void {
    const [cell, id] = key.split('#');
    const [cx, cz] = cell.split(',').map(Number);
    const r = this.requests.open.find((q) => q.cell[0] === cx && q.cell[1] === cz && q.townId === Number(id));
    this.open();
    if (r) { this.chosen = r.id; this.render(); }
  }

  close(): void {
    if (!this.isOpen) return;
    this.isOpen = false;
    this.el.hidden = true;
    (document.activeElement as HTMLElement | null)?.blur?.();
    this.host.onToggle(false);
  }

  /** Redraw if it is up: the steps and the clock move while it is open. */
  refresh(): void { if (this.isOpen) this.render(); }

  private act(what: string): void {
    const r = this.current();
    if (!r) return;
    if (what === 'close') { this.close(); return; }
    if (what === 'show') { this.host.showMe(r); this.close(); return; }
    if (what === 'give') { this.requests.giveUp(r); this.render(); return; }
    if (what === 'take') {
      const why = this.requests.accept(r);
      if (why) this.host.say(r.title, why);
      else { this.host.showMe(r); this.close(); }
    }
  }

  private render(): void {
    const list = this.requests.open;
    const def = this.host.def();
    const hours = this.host.hours();
    if (!list.some((r) => r.id === this.chosen)) this.chosen = list[0]?.id ?? -1;
    const cards = list.map((r) => {
      const why = this.requests.whyNot(r);
      const left = Math.max(0, Math.round(r.due - hours));
      const steps = r.steps.map((s, k) => {
        const mark = s.done ? '✓' : r.state === 'taken' && k === r.step ? '●' : `${k + 1}`;
        return `<span class="st ${s.done ? 'did' : r.state === 'taken' && k === r.step ? 'now' : ''}">${mark} ${esc(s.note)}</span>`;
      }).join('');
      return `<button type="button" class="card ${r.id === this.chosen ? 'on' : ''} ${why ? 'no' : ''} ${r.state === 'taken' ? 'running' : ''}" data-pick="${r.id}">
        <b>${esc(r.town)} · ${esc(r.title)}</b>
        ${why ? `<em class="whynot">${esc(why)}</em>` : `<em>“${esc(r.line)}”</em>`}
        <div class="steps">${steps}</div>
        <small>${money(r.reward)} purse · ${left} h left · ${esc(r.effectLine)}</small>
      </button>`;
    }).join('');

    const r = this.current();
    let side = `<p class="none">Nobody is asking just now. Towns post what they want as the days turn — keep trading and they will.</p>`;
    if (r) {
      const s = r.steps[r.step];
      const fit = this.requests.fitNow(r);
      const why = this.requests.whyNot(r);
      const paid = r.steps.reduce((a, q) => a + q.value, 0);
      const mins = fit ? Math.max(1, Math.round(fit.seconds / 60)) : 0;
      side = `<h3>${esc(r.title)}</h3>
        <p class="who">${esc(r.town)} · ${r.state === 'taken' ? `step ${Math.min(r.step + 1, r.steps.length)} of ${r.steps.length}` : `${r.steps.length} jobs`}</p>
        <p class="said">“${esc(r.line)}”</p>
        ${s ? `<p class="next"><b>${esc(s.note)}</b><br><span>${esc(s.type.name)} · ${s.type.units} unit${s.type.units === 1 ? '' : 's'} · ${esc(s.from.name)} → ${esc(s.to.name)}</span></p>` : ''}
        ${fit && s ? `<p class="est">${Math.round(fit.dist)} tiles · about ${mins} min in the ${esc(def.name)}${fit.urgency ? ` · ${fit.urgency} fits` : ''}</p>` : ''}
        ${s ? `<p class="pay">pays ${money(s.value)} · the chain pays ${money(r.reward)} on the last drop, on top of ${money(paid)} of steps</p>` : ''}
        <p class="eff">When it is done: ${esc(r.effectLine)}</p>
        ${why ? `<p class="warn">${esc(why)}</p>` : ''}
        <div class="acts">
          ${r.state === 'taken'
            ? `<button type="button" class="go" data-act="show">Show me</button><button type="button" class="off" data-act="give">Give it up</button>`
            : `<button type="button" class="go" ${why ? 'disabled' : ''} data-act="take">Take it on</button><button type="button" class="off" data-act="close">Not now</button>`}
        </div>`;
    }
    const hist = this.requests.log.length ? `<div class="hist">${this.requests.log.slice(0, 3).map((l) => `<span>${esc(l)}</span>`).join('')}</div>` : '';
    this.el.innerHTML = `<div class="panel">
      <header><b>Requests<span>.</span></b>
        <small>${list.length} asking · driving the ${esc(def.name)} · holds ${def.capacity}</small>
        <button type="button" class="x" data-act="close" aria-label="Close"><kbd>Esc</kbd></button></header>
      <div class="cols"><div class="list">${cards || '<p class="none">No town is asking today.</p>'}${hist}</div>
      <div class="side">${side}</div></div></div>`;
  }
}
