/**
 * The acts' rides (the user, 28 Oct 2026): a touring act or a league side has its next date at another stadium,
 * and the fleet is asked to get them there before it starts. Each job is the real thing: the act's next stop on
 * its tour (game/tours.ts, booked early with Tours.bookNext so the convoy goes there too) or the side's next away
 * fixture in its league (game/leagues.ts), at its real kick-off. The stadium card's Season and Tours tabs show
 * the job beside the fixture or the tour (missions/actBoard.ts).
 *
 * Three ways, each offered only about what is driven (Missions.nearActs), like the knack jobs:
 * - by bus: the Omnibus or a Star Tours double-decker, from one stadium's gates to the other's;
 * - by train: the player's own passenger train, from the station nearest the one stadium to the station nearest
 *   the other, both on one connected railway (and the one the train is on);
 * - by Jumbo: from the international airport nearest the one stadium to the one nearest the other.
 *
 * A band is wanted once its show is over and the convoy is packing up or on the road (the band missed the tour
 * bus); a side from a little before its away game. The deadline is the show or the kick-off itself, fixed on the
 * game clock (Mission.notes.by), and the pay grows with the distance and how big the act is.
 */
import { DIRS, N, type Building, type World } from '../../world/tiles';
import { hashString } from '../../world/rng';
import { cellKind, landBorder, straitAt } from '../../world/macro';
import { SPORT_NAME, stadiumPlanOf } from '../../world/stadiums';
import { builtShare } from '../../render/townMesh';
import { fixtureKey, fixtures, leagueFor, results, seasonAt, slotOf, table } from '../leagues';
import { homeTeam, stadiumsNow, venueName } from '../stadiums';
import { dayHour } from '../tours';
import { cargoById } from '../cargoTypes';
import { buildSites, type Site } from '../cargo';
import { canReach } from '../fit';
import { RAIL_VEHICLES, type VehicleDef } from '../vehicles';
import type { MissionCtx, Missions } from './missions';
import type { HeroSpec, Reward } from './model';
import { plainTown } from './text';
import { siteRef, townRef, type Draft, type Template } from './templates';

/** The ways an act can be carried. */
export type Form = 'bus' | 'train' | 'jet';

/** Hold space a band and its crew, or a squad and its staff, take up: a bus, a passenger train or the Jumbo. */
export const ACT_UNITS = 10;
/** A side is wanted from this many game hours before kick-off, at most (a game hour is 25 s: a bus ride is half a day or more). */
const TEAM_LEAD = 60;
/** A job is offered only with this many game hours in hand over the trip's own time, as a multiple of it. */
const SLACK = 1.25;
/** Stations and airports this far (tiles) from a stadium serve it. */
const STATION_NEAR = 160, AIR_NEAR = 300;
/** The shortest ride worth asking for, tiles: by road or rail, and in the air. */
const MIN_RIDE = 60, MIN_FLIGHT = 150;
/** The pickup no further than this from the player (tiles). */
const PICKUP_NEAR = 320;
/** Real seconds a game hour lasts (render/daynight.ts SECONDS_PER_HOUR). */
const HOUR_S = 25;
/** The cash reward: a base and so much a tile of the ride, times 0.6 + 0.8 × the act's size. */
const PAY_BASE = 300;
const PAY_TILE: Record<Form, number> = { bus: 5, train: 4, jet: 3 };
/** The share of top speed a ride is reckoned at, for the time it takes. */
const PACE: Record<Form, number> = { bus: 0.6, train: 0.8, jet: 0.5 };

const RIDE_BUS = { ids: ['bus', 'starTours'], label: 'a bus' };
const RIDE_JET = { ids: ['jumbo'], label: 'the Jumbo' };
/** Passenger trains with room for a band or a squad. */
const trainIds = (): string[] => RAIL_VEHICLES.filter((d) => d.holds.includes('people') && d.capacity >= ACT_UNITS).map((d) => d.id);
const RIDE_TRAIN = { ids: trainIds(), label: 'a passenger train' };
const RIDE: Record<Form, { ids: string[]; label: string }> = { bus: RIDE_BUS, train: RIDE_TRAIN, jet: RIDE_JET };
/** The model each is bound in by the missions gate (scripts/missions.ts). */
export const ACT_RIDE: Record<string, string> = { 'act:bus': 'bus', 'act:train': RIDE_TRAIN.ids[0] ?? 'kettle', 'act:jet': 'jumbo' };

const r10 = (v: number) => Math.round(v / 10) * 10;
const pick = <T>(h: number, xs: T[]): T => xs[h % xs.length];
const span = (a: { x: number; z: number }, b: { x: number; z: number }) => Math.hypot(a.x - b.x, a.z - b.z);
const worldAt = (c: MissionCtx, cx: number, cz: number): World | null => c.worlds.find((w) => w.cx === cx && w.cz === cz) ?? null;

/** A stadium as one end of a ride: its gates' site, its name and its town. */
interface Venue { w: World; b: Building; site: Site; name: string; town: string }

/** Somebody who needs to be at another stadium by a game hour. */
export interface Move {
  who: 'band' | 'team';
  /** The tour's id or the hash of the fixture's key, for the notes and the stadium card. */
  tour?: number; fix?: number;
  /** "Neon Hearts", "Fernley Foxes"; and the short name the objective uses. */
  name: string; nick: string;
  /** The tour's name, or the sport. */
  what: string;
  /** How big they are, 0.45 to 1: a band's draw, a side's place in its table. */
  size: number;
  from: Venue;
  /** The stadium they are wanted at, when it is in memory; the Jumbo flies to an away ground's county without it. */
  to: Venue | null;
  /** Where that is: the stadium's gates, or the middle of its county; its town and its name for the card. */
  dest: { x: number; z: number; cell: [number, number]; town: string; venue: string };
  /** The game hour the show or the game starts. */
  by: number;
}

/**
 * The places goods come and go in every county in memory, not only the ones the cargo system trades in now (those
 * round the player): a ride's far end is often a county or two off. Built as the cargo system builds them, kept
 * until the county changes. The mission's load stands in for a site not yet traded in (missions/wire.ts spawn).
 */
const SITES = new WeakMap<World, { rev: number; list: Site[] }>();
function sitesOf(c: MissionCtx, kinds: string[]): Site[] {
  const out: Site[] = [];
  for (const w of c.worlds) {
    let e = SITES.get(w);
    if (!e || e.rev !== w.revision) {
      const list: Site[] = [];
      buildSites(w, list, '');
      SITES.set(w, (e = { rev: w.revision, list }));
    }
    for (const s of e.list) if (kinds.includes(String(s.kind))) out.push(s);
  }
  return out;
}

/** A stadium in memory as where a ride is going. */
const destOf = (v: Venue): Move['dest'] => ({ x: v.site.x, z: v.site.z, cell: [v.w.cx, v.w.cz], town: v.town, venue: v.name });

/** A stadium as one end of a ride: its gates. */
function venueOf(c: MissionCtx, sites: Site[], w: World, b: Building, name: string): Venue | null {
  const site = sites.find((s) => s.b === b && s.w === w);
  if (!site) return null;
  const t = w.towns.find((q) => q.buildings.includes(b));
  return { w, b, site, name, town: t ? plainTown(t.name) : w.name };
}

/** Every ride wanted now: bands whose show here is over, sides with an away game coming up (exported for the gate). */
export function moves(c: MissionCtx): Move[] {
  const out: Move[] = [];
  const now = c.hours, sh = hashString(c.seed);
  const sites = sitesOf(c, ['stadium']);
  const S = stadiumsNow();
  // the tours: packing up after a show, or the convoy on the road; the next stop booked so the convoy goes there too
  if (S) {
    for (const t of S.tours.tours) {
      if (t.phase !== 'packing' && t.phase !== 'road') continue;
      const next = S.tours.bookNext(t);
      if (!next || next.show <= now) continue;
      const wa = worldAt(c, t.at.cx, t.at.cz), wb = worldAt(c, next.cx, next.cz);
      const ba = wa?.allBuildings[t.at.uid], bb = wb?.allBuildings[next.uid];
      if (!wa || !wb || !ba || !bb) continue;
      const from = venueOf(c, sites, wa, ba, t.at.venue), to = venueOf(c, sites, wb, bb, next.venue);
      if (!from || !to) continue;
      const act = S.tours.act(t.act);
      out.push({ who: 'band', tour: t.id, name: act.name, nick: 'the band', what: t.name, size: act.draw, from, to, dest: destOf(to), by: next.show });
    }
  }
  // the leagues: a club whose next game is away, not too far off, at a ground in memory
  const seen = new Set<number>();
  for (const w of c.worlds) {
    for (const b of w.allBuildings) {
      if (b.kind !== 'stadium' || b.gone || builtShare(b) < 1) continue;
      const sport = stadiumPlanOf(b).sport;
      const L = leagueFor(sh, sport, w.cx, w.cz), slot = slotOf(L, w.cx, w.cz);
      const s = seasonAt(sport, now);
      if (slot < 0 || !s.inSeason || (L.clubs[slot].since ?? -Infinity) > now) continue;
      // their next away game (home games before it are played where they are)
      const f = fixtures(L, s.k).find((q) => q.away === slot && q.at > now);
      if (!f || f.at > now + TEAM_LEAD) continue;
      const key = hashString(fixtureKey(L, s.k, f));
      if (seen.has(key)) continue;
      seen.add(key);
      const home = L.clubs[f.home], hw = worldAt(c, home.cx, home.cz);
      if ((home.since ?? -Infinity) > now || home.cx > 1e5) continue;
      const hb = hw?.allBuildings.find((q) => q.kind === 'stadium' && !q.gone && builtShare(q) >= 1 && stadiumPlanOf(q).sport === sport);
      const us = homeTeam(w, b);
      const from = venueOf(c, sites, w, b, venueName(stadiumPlanOf(b).design, us));
      if (!from) continue;
      // their ground in memory, or (for the Jumbo) the county it is in, known by its club
      const to = hw && hb ? venueOf(c, sites, hw, hb, venueName(stadiumPlanOf(hb).design, homeTeam(hw, hb))) : null;
      const club = S ? S.clubTeam(L, f.home) : home.team;
      const dest = to ? destOf(to) : { x: (home.cx + 0.5) * N, z: (home.cz + 0.5) * N, cell: [home.cx, home.cz] as [number, number], town: plainTown(club.town), venue: `${club.name}' ground` };
      // their place in the table: the top side is the big draw
      const rows = table(L, results(L, s.k, now, S?.overrides ?? new Map(), S?.liveKeys), s.k);
      const pos = rows.findIndex((r) => r.club === slot);
      const size = rows.length > 1 && pos >= 0 ? 1 - (pos / (rows.length - 1)) * 0.5 : 0.7;
      out.push({ who: 'team', fix: key, name: us.name, nick: `the ${us.nick}`, what: SPORT_NAME[sport].toLowerCase(), size, from, to, dest, by: f.at });
    }
  }
  return out;
}

/**
 * The county borders crossed on the way over land (county roads, causeways) from one county to another, through
 * counties in memory only, or -1 when there is no such way. 0 within one county.
 */
function landHops(sh: number, inMem: Set<string>, ax: number, az: number, bx: number, bz: number): number {
  if (ax === bx && az === bz) return 0;
  const key = (x: number, z: number) => `${x},${z}`;
  const hops = new Map([[key(ax, az), 0]]);
  const open: [number, number][] = [[ax, az]];
  for (let h = 0; h < open.length; h++) {
    const [cx, cz] = open[h];
    const n = hops.get(key(cx, cz))! + 1;
    for (let d = 0; d < 4; d++) {
      const nx = cx + DIRS[d][0], nz = cz + DIRS[d][1];
      if (hops.has(key(nx, nz)) || !inMem.has(key(nx, nz))) continue;
      if (cellKind(sh, nx, nz) === 'sea' || !(landBorder(sh, cx, cz, d) || straitAt(sh, cx, cz, d) >= 0)) continue;
      if (nx === bx && nz === bz) return n;
      hops.set(key(nx, nz), n);
      open.push([nx, nz]);
    }
  }
  return -1;
}

/**
 * Tiles by road from one place to another, roughly, or -1 when a road vehicle can't get there: the same county's roads,
 * or a land way through counties in memory (a way round by another county is the longer for it).
 */
function byRoad(c: MissionCtx, def: VehicleDef, a: Site | MissionCtx['at'], b: Site): number {
  if (a.w === b.w) return canReach(def, a, b) ? span(a, b) * 1.3 : -1;
  const n = landHops(hashString(c.seed), new Set(c.worlds.map((w) => `${w.cx},${w.cz}`)), a.w.cx, a.w.cz, b.w.cx, b.w.cz);
  // the straight line, or the borders crossed if the way goes round
  return n < 0 ? -1 : Math.max(span(a, b) * 1.3, (n - 1) * N + span(a, b));
}

/**
 * The railways in memory, as connected networks: each piece of track by its county and index, joined to the
 * pieces it runs on to (a turnout, a loop) and to the rest of its line over county borders (the same line key).
 */
function railNets(worlds: World[]): (w: World, path: number) => string {
  const up = new Map<string, string>();
  const find = (k: string): string => {
    let r = k;
    while (up.has(r) && up.get(r) !== r) r = up.get(r)!;
    up.set(k, r);
    return r;
  };
  const join = (a: string, b: string) => { const ra = find(a), rb = find(b); if (ra !== rb) up.set(ra, rb); };
  for (const w of worlds) {
    w.rails.forEach((p, k) => {
      const me = `${w.cx},${w.cz}#${k}`;
      join(me, `line:${p.key}`);
      for (const e of [p.start, p.end]) if (e.kind === 'join' && e.path !== undefined) join(me, `${w.cx},${w.cz}#${e.path}`);
    });
  }
  return (w, path) => find(`${w.cx},${w.cz}#${path}`);
}

/** The piece of track nearest a point in its county (the train being driven sits on it), or -1. */
function trackUnder(w: World, x: number, z: number): number {
  let best = -1, bestD = 4;
  const lx = x - w.ox, lz = z - w.oz;
  w.rails.forEach((p, k) => {
    for (let i = 0; i < p.xz.length; i += 2) {
      const d = Math.hypot(p.xz[i] - lx, p.xz[i + 1] - lz);
      if (d < bestD) { bestD = d; best = k; }
    }
  });
  return best;
}

/**
 * The internationals a Jumbo can land at: those in memory, as the cargo system has them, and the surveyed ones further
 * off (MissionCtx.airports) standing in at the middle of their runway, in the frame of the county the ride starts in,
 * the way a jet's long-haul work points at them (game/cargo.ts). The load is put right once that county is in.
 */
function internationals(c: MissionCtx, from: World): Site[] {
  const here = sitesOf(c, ['intl']);
  const out = [...here];
  for (const a of c.airports ?? []) {
    if (!a.major || c.worlds.some((w) => w.cx === a.cx && w.cz === a.cz)) continue;
    out.push({ id: -1, kind: 'intl' as never, name: a.name, w: from, lx: a.gx - from.ox, lz: a.gz - from.oz, x: a.gx, z: a.gz, y: a.y, port: -1, major: true, cell: [a.cx, a.cz] } as Site & { cell: [number, number] });
  }
  return out;
}

/** A site's county: its own world's, or a far airport's (internationals). */
export const cellOfSite = (s: Site): [number, number] => (s as Site & { cell?: [number, number] }).cell ?? [s.w.cx, s.w.cz];

/** The two ends of the ride in this form, or null: the gates, the stations or the airports. */
export function endsFor(c: MissionCtx, form: Form, mv: Move): [Site, Site] | null {
  const near = (v: { x: number; z: number }, max: number) => (s: Site) => span(s, v) <= max;
  const byNear = (v: { x: number; z: number }) => (a: Site, b: Site) => span(a, v) - span(b, v);
  if (form === 'jet') {
    // in from the international nearest the one stadium, out to the one nearest the other (or its county's middle)
    const all = internationals(c, mv.from.w);
    const a = all.filter((s) => s.id >= 0 && near(mv.from.site, AIR_NEAR)(s)).sort(byNear(mv.from.site))[0];
    if (!a) return null;
    const reach = mv.to ? AIR_NEAR : AIR_NEAR + N / 2;
    const b = all.filter((s) => s !== a && near(mv.dest, reach)(s) && span(s, a) >= MIN_FLIGHT && s.name !== a.name).sort(byNear(mv.dest))[0];
    return b ? [a, b] : null;
  }
  const to = mv.to;
  if (!to) return null;
  if (form === 'bus') {
    const a = mv.from.site, b = to.site;
    if (span(a, b) < MIN_RIDE || byRoad(c, c.def, c.at, a) < 0) return null;
    const road = byRoad(c, c.def, a, b);
    if (road < 0) return null;
    ROAD.set(b, road);
    return [a, b];
  }
  // a train: stations on one railway, the one the train being driven is on
  const all = sitesOf(c, ['terminus', 'cityStation', 'townStation', 'halt']).filter((s) => s.station);
  const net = railNets(c.worlds);
  const mine = c.def.kind === 'rail' ? trackUnder(c.at.w, c.at.x, c.at.z) : -1;
  const line = mine >= 0 ? net(c.at.w, mine) : null;
  const on = (s: Site) => net(s.w, s.station!.path);
  const froms = all.filter((s) => near(mv.from.site, STATION_NEAR)(s) && (!line || on(s) === line)).sort(byNear(mv.from.site)).slice(0, 3);
  for (const a of froms) {
    const b = all.filter((s) => s !== a && s.station!.name !== a.station!.name && near(to.site, STATION_NEAR)(s) && span(s, a) >= MIN_RIDE && on(s) === on(a)).sort(byNear(to.site))[0];
    if (b) return [a, b];
  }
  return null;
}

/** A bus ride's road tiles, as endsFor reckoned them (round by another county when the way goes round). */
const ROAD = new WeakMap<Site, number>();

/** Game hours the ride is reckoned to take in what is driven: to the pickup, then on to the drop. */
function hoursFor(c: MissionCtx, form: Form, a: Site, b: Site): number {
  const pace = Math.max(0.3, c.top * PACE[form]);
  const ride = form === 'bus' ? ROAD.get(b) ?? span(a, b) * 1.3 : span(a, b) * 1.1;
  // a jet's take-offs and landings, a train's stops: half a minute each end
  return ((span(c.at, a) + ride) / pace + 60) / HOUR_S;
}

/** The card for one ride. */
function draft(c: MissionCtx, form: Form, mv: Move, a: Site, b: Site, h: number): Draft {
  const band = mv.who === 'band';
  const cargo = band ? 'touringBand' : 'awayTeam';
  const type = cargoById(cargo)!;
  const ride = span(a, b);
  const when = dayHour(mv.by);
  // by bus, gates to gates; by train or air, the station's or the airport's own name
  const fromName = form === 'bus' ? `the ${mv.from.name}` : a.name.split(' · ')[0];
  const toName = form === 'bus' ? `the ${mv.dest.venue}` : b.name.split(' · ')[0];
  const to = { ...siteRef(b), cell: cellOfSite(b), name: toName }, from = { ...siteRef(a), name: fromName };
  const verb = form === 'bus' ? 'Drive' : form === 'train' ? 'Take' : 'Fly';
  // a station is often named like a town ("Driftwold City"): by rail, so it reads as the station
  const by = form === 'train' ? 'by rail' : 'in';
  const title = pick(h >>> 3, band
    ? { bus: ['Missed the Bus', 'On the Road', 'Next Stop'], train: ['The Band Train', 'Tour by Rail'], jet: ['Tour Flight', 'Flying Visit'] }[form]
    : { bus: ['Away Day', 'The Team Coach', 'Matchday Run'], train: ['The Matchday Special', 'Away by Train'], jet: ['Away by Air', 'Team Charter'] }[form]);
  const why = band
    ? `${mv.name} missed the tour bus. ${verb} them ${form === 'bus' ? `to ${mv.dest.town}` : `${by} to ${toName}`} for the show, ${when}.`
    : `The ${mv.name} play away at ${mv.dest.town}, ${when}. ${verb} the squad ${form === 'bus' ? 'there' : `${by} to ${toName}`} before kick-off.`;
  const details = band
    ? `The real tour: the ${mv.what} plays the ${mv.dest.venue} next, as the stadium card's Tours tab shows. The trucks went on ahead with the stage. Pick the band up at ${fromName} and set them down at ${toName} before the show starts.`
    : `Their real ${mv.what} fixture, on both stadium cards' Season tabs. Pick the squad up at ${fromName} and set them down at ${toName} before kick-off.`;
  const value = r10(60 + ride * 0.8);
  const reward: Reward[] = [{ r: 'cash', n: r10((PAY_BASE + ride * PAY_TILE[form]) * (0.6 + 0.8 * mv.size)) }];
  const town = mv.to?.w.towns.find((t) => t.buildings.includes(mv.to!.b));
  if (mv.to && town) reward.push({ r: 'standing', town: townRef(mv.to.w, town), n: 1 });
  const fromTown = mv.from.w.towns.find((t) => t.buildings.includes(mv.from.b));
  const hero: HeroSpec = { kind: 'vehicle', model: form === 'bus' ? 'bus' : form === 'jet' ? 'jumbo' : RIDE_TRAIN.ids.includes(c.def.id) ? c.def.id : ACT_RIDE['act:train'] };
  return {
    title, why, details,
    giver: { who: band ? 'manager' : 'club', name: band ? `${mv.name}${/s$/.test(mv.name) ? "'" : "'s"} manager` : `The ${mv.nick.replace(/^the /, '')}' manager`, at: from, town: fromTown ? townRef(mv.from.w, fromTown) : null },
    hero, caption: band ? (form === 'jet' ? 'The tour flight' : form === 'train' ? 'The band train' : 'The band bus') : (form === 'jet' ? 'The team charter' : form === 'train' ? 'The team train' : 'The team coach'),
    objs: [{ t: 'deliver', label: band ? 'Take the band to the show' : 'Take the team to the game', icon: type.icon, cargo, from, to, n: 1, value, ride: RIDE[form] }],
    reward,
    hours: Math.max(0.5, mv.by - c.hours),
    notes: { by: mv.by, ...(mv.tour !== undefined ? { tour: mv.tour } : {}), ...(mv.fix !== undefined ? { fix: mv.fix } : {}) },
  };
}

/** Is a ride's key already on the list (offered, under way, done or turned down)? */
const keyOf = (mv: Move): string => (mv.tour !== undefined ? `t${mv.tour}` : `f${mv.fix}`);

function actTemplate(form: Form, gate: (c: MissionCtx) => string | null): Template {
  return {
    id: `act:${form}`, thread: 'fleet', kind: 'job', cooldown: 2,
    gate,
    bind(c, h, ms: Missions) {
      if (gate(c)) return null;
      const type = cargoById('touringBand');
      if (!type || c.def.capacity < ACT_UNITS || !c.def.holds.includes('people')) return null;
      const cands = moves(c)
        .filter((mv) => !ms.actTaken?.(keyOf(mv)) && span(c.at, mv.from.site) <= PICKUP_NEAR * (form === 'jet' ? 1.5 : 1))
        .sort((p, q) => span(c.at, p.from.site) - span(c.at, q.from.site));
      for (let k = 0; k < cands.length; k++) {
        const mv = cands[(h + k) % cands.length];
        const ends = endsFor(c, form, mv);
        if (!ends) continue;
        // time in hand for the trip, and a little more
        if (mv.by - c.hours < hoursFor(c, form, ends[0], ends[1]) * SLACK + 0.5) continue;
        return draft(c, form, mv, ends[0], ends[1], h);
      }
      return null;
    },
  };
}

export const ACT_TEMPLATES: Template[] = [
  actTemplate('bus', (c) => (RIDE_BUS.ids.includes(c.def.id) ? null : 'in a bus')),
  actTemplate('train', (c) => (RIDE_TRAIN.ids.includes(c.def.id) ? null : 'in a passenger train')),
  actTemplate('jet', (c) => (RIDE_JET.ids.includes(c.def.id) ? null : 'in the Jumbo')),
];

/** A ride's key from its mission's notes, as Missions.actTaken looks for it. */
export const actKeyOf = (n: Record<string, number> | undefined): string | null =>
  n?.tour !== undefined ? `t${n.tour}` : n?.fix !== undefined ? `f${n.fix}` : null;

/** Console (pr.missions.acts()): every ride wanted now, and what each form makes of it from where the player is. */
export function actsReport(c: MissionCtx): string[] {
  return moves(c).map((mv) => {
    const forms = (['bus', 'train', 'jet'] as Form[]).map((f) => {
      const e = endsFor(c, f, mv);
      if (!e) return `${f}: no ends`;
      const need = hoursFor(c, f, e[0], e[1]) * SLACK + 0.5;
      return `${f}: ${e[0].name.split(' · ')[0]} → ${e[1].name.split(' · ')[0]}, ${Math.round(span(e[0], e[1]))} t, ${need.toFixed(1)} h needed`;
    });
    return `${mv.who} ${mv.name} · ${mv.from.name} → ${mv.dest.venue}${mv.to ? '' : ' (out of memory)'} · by ${dayHour(mv.by)} (in ${(mv.by - c.hours).toFixed(1)} h) · pickup ${Math.round(span(c.at, mv.from.site))} t · ${forms.join(' · ')}`;
  });
}
