import * as THREE from 'three';
import { N, heightAt, type Building, type World } from '../world/tiles';
import { buildOutline, disposeObject } from '../render/roadMesh';
import { pickGround } from '../render/pick';
import { demolish, targetAt, type Target } from './demolish';
import { money, type CargoHud } from './cargoHud';
import type { Wallet } from './economy';
import type { Input } from './input';
import type { FollowCamera } from './camera';
import { deeds } from './deeds';
import { clamp } from '../util/math';

const NOTHING: Target = { kind: 'none', label: 'Nothing to clear', detail: 'Bare ground', cost: 0, tiles: [] };

/**
 * The X tool. WASD pans, the tile under the cursor is outlined in red with a card saying what
 * stands there and what clearing it costs, and a click pays for it and clears it: trees for a
 * pound, a road tile for a few, a building for hundreds, a stadium for thousands.
 */
export class Bulldozer {
  active = false;
  /** Where the camera looks while bulldozing. */
  readonly focus = new THREE.Vector3();
  cleared = 0;
  spent = 0;
  private w: World | null = null;
  private ox = 0;
  private oz = 0;
  private target: Target = NOTHING;
  /** Told the tile cleared (and the building that stood on it, if one did), so it can go into the save delta. */
  onRazed: ((x: number, z: number, gone: Building | null) => void) | null = null;
  /** Online: why a building is not this player's to clear (it is another player's), or null. */
  barred: ((w: World, b: Building) => string | null) | null = null;
  /** Online: a tile that isn't this player's to clear though no building stands on it (a listed road or bridge). */
  barredTile: ((w: World, tile: number) => string | null) | null = null;
  /** What the player paid for a building, if they own it (docs/property.html): demolishing it voids the deed. */
  ownedCost: ((w: World, b: Building) => number | null) | null = null;
  /** What clearing a site of the player's own still going up pays back (docs/blueprints.html), or null for anything else. */
  refundOf: ((w: World, b: Building) => number | null) | null = null;
  /** The share off every clearing (a bulldozer in the fleet: vehicles.ts `dozer`), and its name for the card. */
  discount: (() => { share: number; name: string } | null) | null = null;
  /** A building has come down, for the deed book. */
  onBuildingGone: ((w: World, b: Building) => void) | null = null;
  /** The tile of a building of the player's whose demolition has been asked for once: the second click goes ahead. */
  private armed = -1;
  private at = -1;
  private layer = new THREE.Group();
  private mark: THREE.Object3D | null = null;
  private panel = document.getElementById('bulldoze')!;
  private tip = document.getElementById('dozer-tip')!;
  private help = document.getElementById('br')!;
  private tipTitle = document.createElement('b');
  private tipBody = document.createElement('span');
  private countEl = document.createElement('div');
  private fwd = new THREE.Vector2();

  constructor(scene: THREE.Scene, private cam: FollowCamera, private wallet: Wallet, private hud: CargoHud, private onChange: (tiles: number[]) => void) {
    scene.add(this.layer);
    this.tip.append(this.tipTitle, this.tipBody);
    this.countEl.className = 'count';
    const head = document.createElement('header');
    head.innerHTML = '<b>Bulldozer<span>.</span></b><span><kbd>X</kbd> done</span>';
    const help = document.createElement('div');
    help.className = 'help';
    help.innerHTML = '<kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd> pan · wheel zoom · click to clear<br>Trees cost $1 · buildings cost hundreds';
    this.panel.append(head, help, this.countEl);
    this.tally();
  }

  setWorld(w: World): void {
    this.close();
    this.w = w;
    this.ox = w.ox;
    this.oz = w.oz;
    this.layer.position.set(w.ox, 0, w.oz);
    this.cleared = 0;
    this.spent = 0;
    this.tally();
  }

  toggle(from: THREE.Vector3): void {
    if (this.active) this.close();
    else this.open(from);
  }

  open(from: THREE.Vector3): void {
    if (!this.w) return;
    this.active = true;
    this.focus.copy(from);
    this.cam.minDist = 26;
    this.cam.maxDist = 420;
    this.panel.hidden = false;
    this.help.hidden = true;
    this.at = -1;
  }

  close(): void {
    this.active = false;
    this.cam.minDist = 20;
    this.cam.maxDist = 140;
    this.panel.hidden = true;
    this.help.hidden = false;
    this.tip.hidden = true;
    this.clearMark();
    this.target = NOTHING;
    this.at = -1;
  }

  update(dt: number, input: Input, camera: THREE.Camera): void {
    const w = this.w;
    if (!this.active || !w) return;
    if (input.justPressed('Escape')) { this.close(); return; }

    // pan relative to the camera, like the road builder
    const f = this.cam.forwardXZ(this.fwd);
    const pan = this.cam.dist * 0.45 * dt;
    const th = input.throttle, st = input.steer;
    this.focus.x = clamp(this.focus.x + (f.x * th + f.y * st) * pan, this.ox, this.ox + N);
    this.focus.z = clamp(this.focus.z + (f.y * th - f.x * st) * pan, this.oz, this.oz + N);
    const gy = heightAt(w, clamp(this.focus.x - this.ox, 0, N - 0.001), clamp(this.focus.z - this.oz, 0, N - 0.001));
    this.focus.y += (gy - this.focus.y) * Math.min(1, dt * 6);

    const click = input.takeClick();
    if (click) {
      const hit = pickGround(w, camera, click.x, click.y, this.ox, this.oz);
      if (hit) {
        this.look(Math.floor(hit.x), Math.floor(hit.z));
        this.fire();
      }
    }
    if (input.hasMouse) {
      const hit = pickGround(w, camera, input.mouseX, input.mouseY, this.ox, this.oz);
      if (hit) this.look(Math.floor(hit.x), Math.floor(hit.z));
      else { this.at = -1; this.target = NOTHING; this.clearMark(); this.tip.hidden = true; }
      if (!this.tip.hidden) this.placeTip(input.mouseX, input.mouseY);
    }
  }

  /** Work out what is on a tile and outline it (only when the tile under the cursor changes). */
  private look(x: number, z: number): void {
    const w = this.w!;
    const i = z * N + x;
    if (i === this.at) return;
    this.at = i;
    this.target = targetAt(w, x, z);
    const off = this.discount?.();
    if (off && this.target.cost > 0) {
      const was = this.target.cost;
      this.target = { ...this.target, cost: Math.max(1, Math.round(was * (1 - off.share))), detail: `${this.target.detail}\nYour ${off.name} knocks ${Math.round(off.share * 100)}% off (was ${money(was)})` };
    }
    this.clearMark();
    const t = this.target;
    const afford = this.wallet.canAfford(t.cost);
    if (t.tiles.length) {
      let x0 = N, z0 = N, x1 = 0, z1 = 0;
      for (const tile of t.tiles) {
        const tx = tile % N, tz = (tile - tx) / N;
        x0 = Math.min(x0, tx); z0 = Math.min(z0, tz);
        x1 = Math.max(x1, tx + 1); z1 = Math.max(z1, tz + 1);
      }
      this.mark = buildOutline(w, x0, z0, x1, z1, t.kind === 'none' ? 0xffffff : afford ? 0xd2564f : 0x8a93a6);
      if (this.mark) this.layer.add(this.mark);
    }
    const paid = t.building ? this.ownedCost?.(w, t.building) ?? null : null;
    const barred = t.building ? this.barred?.(w, t.building) ?? null : t.kind !== 'none' && this.at >= 0 ? this.barredTile?.(w, this.at) ?? null : null;
    if (t.kind === 'none') this.setTip('none', t.label, t.detail);
    else if (barred) this.setTip('bad', t.label, `${t.detail}\n${barred}`);
    else if (paid !== null && afford) {
      const back = t.building ? this.refundOf?.(w, t.building) ?? null : null;
      this.setTip('bad', `${t.label} · ${money(t.cost)}`, back !== null
        ? `${t.detail}\nYour own site, still going up: clearing it pays ${money(back)} of the ${money(paid)} back.\nClick twice to clear it`
        : `${t.detail}\nYou own this. The deed is void and the ${money(paid)} is gone.\nClick twice to clear it`);
    }
    else if (!afford) this.setTip('bad', `${t.label} · ${money(t.cost)}`, `${t.detail}\nNot enough cash — you have ${money(this.wallet.cash)}`);
    else this.setTip('ok', `${t.label} · ${money(t.cost)}`, `${t.detail}\nClick to clear it`);
  }

  private fire(): void {
    const w = this.w!, t = this.target;
    if (t.kind === 'none') return;
    if ((t.building && this.barred?.(w, t.building)) || (!t.building && this.at >= 0 && this.barredTile?.(w, this.at))) {
      this.hud.float('Not yours to clear', this.focus, 'bad');
      return;
    }
    // a building of the player's asks twice
    if (t.building && this.ownedCost?.(w, t.building) != null && this.armed !== this.at) {
      this.armed = this.at;
      this.hud.float('Yours · click again to clear it', this.focus, 'bad');
      return;
    }
    this.armed = -1;
    const gone = t.building ?? null;
    if (!this.wallet.spend(t.cost, 'earthworks')) {
      this.hud.float('Not enough cash', this.focus, 'bad');
      return;
    }
    const tiles = demolish(w, t);
    if (t.kind === 'building') deeds.add('razed');
    this.cleared++;
    this.spent += t.cost;
    this.tally();
    const mid = tiles.length ? tiles[Math.floor(tiles.length / 2)] : 0;
    const mx = mid % N, mz = (mid - mx) / N;
    this.hud.float(`-${money(t.cost)}`, new THREE.Vector3(mx + 0.5 + this.ox, heightAt(w, mx + 0.5, mz + 0.5) + 0.6, mz + 0.5 + this.oz), 'bad');
    this.onRazed?.(this.at % N, Math.floor(this.at / N), gone);
    this.onChange(tiles);
    if (gone) this.onBuildingGone?.(w, gone);
    this.at = -1;         // the tile has changed: look again
    this.clearMark();
  }

  private tally(): void {
    this.countEl.textContent = this.cleared
      ? `${this.cleared} cleared · ${money(this.spent)} spent`
      : 'Nothing cleared yet';
  }

  private clearMark(): void {
    if (!this.mark) return;
    this.layer.remove(this.mark);
    disposeObject(this.mark);
    this.mark = null;
  }

  private setTip(kind: 'ok' | 'bad' | 'none', title: string, body: string): void {
    this.tip.className = `hud chip ${kind}`;
    this.tipTitle.textContent = title;
    this.tipBody.textContent = body;
    this.tip.hidden = false;
  }

  private placeTip(mx: number, my: number): void {
    const r = this.tip.getBoundingClientRect();
    let x = mx + 18, y = my + 18;
    if (x + r.width > window.innerWidth - 8) x = mx - 18 - r.width;
    if (y + r.height > window.innerHeight - 8) y = my - 18 - r.height;
    this.tip.style.transform = `translate(${Math.round(x)}px, ${Math.round(y)}px)`;
  }
}
