import { hex, scale, type RGB } from '../../world/biomes';
import { FLOOR } from '../../world/towns';
import type { ThemeKind } from '../../world/tiles';
import type { Rng } from '../../world/rng';
import type { Sched } from '../nightLights';
import { DARK, GLASS_LIGHT, METAL, TAU, WARM_GLOW, WHITE, type Draw, type Kit, type P3 } from './kit';

/**
 * The signature landmarks of five more town styles. Each carries its own fixed palette (a campanile is
 * red brick in any town) and stands on its lot centred on the origin, its front to +z.
 *
 * The Norse north: the **longhouse**, a bowed mead hall with a longship drawn up beside it, and a
 * **runestone** on its mound.
 *
 * Venice: the **campanile** of St Mark, the **Doge's Palace** on its arcades over the water, and
 * **St Mark's Basilica** under five lead domes.
 *
 * London: **Big Ben** at the corner of the Palace of Westminster, and the **Gherkin**.
 *
 * New Orleans: a French Quarter **jazz club** behind its iron gallery, and a walled **tomb yard**.
 *
 * Havana: a grand old **cigar factory** with two fifties cars at the kerb, and the **Morro** castle with
 * its lighthouse over the harbour mouth.
 */

const GOLD = hex(0xe0b040), SHADOW = hex(0x3a302c), IRON = hex(0x2a2e30), BLACK = hex(0x1e1e22);
const FLOOD: Sched = [18, 25.5, 1.3], EVENING: Sched = [18, 23.5, 1.4], LAMP: Sched = [17.5, 30, 1.8], OFF: Sched = [99, 0, 0];

/** A window's evening: most are lit for a while after dusk, some never. */
const lit = (r: Rng): Sched => (r() < 0.72 ? [17.4 + r() * 1.4, 22 + r() * 3, 1.35] : OFF);

// ---- shared pieces ----

/**
 * Draw the same thing on the faces of a w×d block centred (cx, cz): `draw` works in a frame turned so
 * the face looks down +z, the face's middle at local x0, its plane at local z = zf, `span` wide.
 * Faces: 0 the front (+z), 1 the +x side, 2 the back, 3 the -x side.
 */
export function around(k: Kit, cx: number, cz: number, w: number, d: number, draw: (x0: number, zf: number, span: number, f: number) => void, faces: readonly number[] = [0, 1, 2, 3]): void {
  for (const f of faces) {
    const a = (f * Math.PI) / 2, c = Math.round(Math.cos(a)), s = Math.round(Math.sin(a));
    const lx = cx * c - cz * s, lz = cx * s + cz * c;
    k.turned(a, () => draw(lx, lz + (f % 2 ? w : d) / 2, f % 2 ? d : w, f));
  }
}

/** A flat arched panel on a plane facing +z: a rectangle under a round or a pointed head, h tall in all. */
export function archPanel(k: Kit, x: number, y: number, z: number, w: number, h: number, col: RGB, pointed = false): void {
  const I: P3 = [x, y + h / 2, z - 0.2];
  const rise = Math.min(h * 0.6, pointed ? w * 0.8 : w / 2), ys = y + h - rise;
  k.quad([x - w / 2, y, z], [x + w / 2, y, z], [x + w / 2, ys, z], [x - w / 2, ys, z], col, I);
  if (pointed) { k.tri([x - w / 2, ys, z], [x + w / 2, ys, z], [x, y + h, z], col, I); return; }
  const n = 5;
  for (let i = 0; i < n; i++) {
    const a0 = (i / n) * Math.PI, a1 = ((i + 1) / n) * Math.PI;
    k.tri([x, ys, z], [x + (Math.cos(a0) * w) / 2, ys + Math.sin(a0) * rise, z], [x + (Math.cos(a1) * w) / 2, ys + Math.sin(a1) * rise, z], col, I);
  }
}

/** An arched window on a wall facing +z at z: a pale surround, dark glass, and a pane that lights after dark. */
export function archWin(k: Kit, x: number, y: number, z: number, w: number, h: number, frame: RGB, pointed: boolean, s: Sched, glass: RGB = hex(0x34424c)): void {
  archPanel(k, x, y - 0.012, z + 0.008, w + 0.04, h + 0.035, frame, pointed);
  archPanel(k, x, y, z + 0.012, w, h, glass, pointed);
  const rise = Math.min(h * 0.6, pointed ? w * 0.8 : w / 2);
  k.pane(x, y + 0.01, z + 0.012, w * 0.78, h - rise, 1, glass, s, WARM_GLOW);
}

/**
 * The stone between an arch and the beam over it, on a plane facing +z: fills a bay x0..x1 from the
 * springing at ys up to yt and leaves a round or pointed opening under it.
 */
export function spandrel(k: Kit, x0: number, x1: number, ys: number, yt: number, z: number, col: RGB, pointed: boolean): void {
  const xm = (x0 + x1) / 2, I: P3 = [xm, ys, z - 0.2];
  if (pointed) {
    k.tri([x0, ys, z], [x0, yt, z], [xm, yt, z], col, I);
    k.tri([x1, ys, z], [x1, yt, z], [xm, yt, z], col, I);
    return;
  }
  const n = 4, rx = (x1 - x0) / 2, ry = (yt - ys) * 0.88;
  for (let i = 0; i < n; i++) {
    const a0 = (i / n) * Math.PI, a1 = ((i + 1) / n) * Math.PI;
    const p0x = xm - Math.cos(a0) * rx, p0y = ys + Math.sin(a0) * ry, p1x = xm - Math.cos(a1) * rx, p1y = ys + Math.sin(a1) * ry;
    k.quad([p0x, p0y, z], [p1x, p1y, z], [p1x, yt, z], [p0x, yt, z], col, I);
  }
}

/** A barrel vault along z: half a cylinder r wide and ry high lying on y from z0 to z1, its two ends in `cap`. */
function barrel(k: Kit, x: number, y: number, z0: number, z1: number, r: number, ry: number, col: RGB, cap: RGB = col, n = 6): void {
  const I: P3 = [x, y, (z0 + z1) / 2];
  for (let i = 0; i < n; i++) {
    const a0 = (i / n) * Math.PI, a1 = ((i + 1) / n) * Math.PI;
    const p0x = x + Math.cos(a0) * r, p0y = y + Math.sin(a0) * ry, p1x = x + Math.cos(a1) * r, p1y = y + Math.sin(a1) * ry;
    k.quad([p0x, p0y, z0], [p1x, p1y, z0], [p1x, p1y, z1], [p0x, p0y, z1], col, I);
    k.tri([x, y, z1], [p0x, p0y, z1], [p1x, p1y, z1], cap, I);
    k.tri([x, y, z0], [p0x, p0y, z0], [p1x, p1y, z0], cap, I);
  }
}

/** A tapering block: a rectangle of half-size (ax, az) about (x0, z0) at y0 up to one of (bx, bz) about (x1, z1) at y1, capped. */
function taper(k: Kit, x0: number, z0: number, y0: number, ax: number, az: number, x1: number, z1: number, y1: number, bx: number, bz: number, col: RGB, top: RGB = col): void {
  const I: P3 = [(x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2];
  const lo = (sx: number, sz: number): P3 => [x0 + sx * ax, y0, z0 + sz * az];
  const hi = (sx: number, sz: number): P3 => [x1 + sx * bx, y1, z1 + sz * bz];
  k.quad(lo(-1, 1), lo(1, 1), hi(1, 1), hi(-1, 1), col, I);
  k.quad(lo(-1, -1), lo(1, -1), hi(1, -1), hi(-1, -1), col, I);
  k.quad(lo(1, -1), lo(1, 1), hi(1, 1), hi(1, -1), col, I);
  k.quad(lo(-1, -1), lo(-1, 1), hi(-1, 1), hi(-1, -1), col, I);
  k.quad(hi(-1, -1), hi(1, -1), hi(1, 1), hi(-1, 1), top, I);
}

/**
 * A slim double-ended hull lying along x with its keel on y: `beam` wide amidships and pinched to
 * nothing at both ends, which sweep up by `sheer`. Decked a little under the gunwale.
 */
export function hull(k: Kit, x: number, y: number, z: number, len: number, beam: number, depth: number, sheer: number, col: RGB, deck: RGB, n = 8): void {
  const at = (t: number) => {
    const u = 2 * t - 1;
    return { x: x - len / 2 + len * t, hw: (beam / 2) * Math.pow(Math.max(0, 1 - u * u), 0.6), ky: y + sheer * 0.7 * u * u * u * u, gy: y + depth + sheer * u * u };
  };
  for (let i = 0; i < n; i++) {
    const a = at(i / n), b = at((i + 1) / n);
    const I: P3 = [(a.x + b.x) / 2, (a.ky + b.ky + a.gy + b.gy) / 4, z];
    for (const s of [-1, 1]) k.quad([a.x, a.ky, z], [b.x, b.ky, z], [b.x, b.gy, z + s * b.hw], [a.x, a.gy, z + s * a.hw], col, I);
    const da = a.gy - depth * 0.3, db = b.gy - depth * 0.3;
    k.quad([a.x, da, z - a.hw * 0.85], [b.x, db, z - b.hw * 0.85], [b.x, db, z + b.hw * 0.85], [a.x, da, z + a.hw * 0.85], deck, I);
  }
}

// ================================ the Norse north ================================

const TIMBER = hex(0x7a5232), TIMBER_DARK = hex(0x4a3020), SHINGLE = hex(0x4a4038), TURF = hex(0x5f8040), CARVED = hex(0x9a3a2a);
const SHIELDS: readonly number[] = [0xc8352a, 0xe8c040, 0x2f5a9a, 0xf0ece0, 0x2f7a4a, 0x1e1e22];

/**
 * The longhouse: a long timber mead hall, boat-shaped under a steep bowed roof that comes down low,
 * crossed dragon heads at both gables, shields along the wall, and a longship on rollers in front.
 */
const longhouse: Draw = (k, W, D, _b, r) => {
  const L = W - 0.5, cz = -D / 2 + 0.64, hd0 = Math.min(0.48, D * 0.24), wallH = 0.3, ridge = 1.0, n = 8, e = 0.06, ey = wallH - 0.05;
  const roof = r() < 0.35 ? TURF : SHINGLE;
  const at = (t: number) => {
    const s = Math.sin(Math.PI * t);
    return { x: -L / 2 + L * t, hd: hd0 * (0.78 + 0.22 * s), ry: ridge * (0.86 + 0.14 * s) };
  };
  const hdAt = (x: number) => at((x + L / 2) / L).hd;
  // the bowed walls and the roof over them, a course of shingles to every bay
  for (let i = 0; i < n; i++) {
    const a = at(i / n), b = at((i + 1) / n), xm = (a.x + b.x) / 2;
    for (const s of [-1, 1]) {
      k.quad([a.x, 0, cz + s * a.hd], [b.x, 0, cz + s * b.hd], [b.x, wallH, cz + s * b.hd], [a.x, wallH, cz + s * a.hd], TIMBER, [xm, 0.15, cz]);
      k.quad([a.x, ey, cz + s * (a.hd + e)], [b.x, ey, cz + s * (b.hd + e)], [b.x, b.ry, cz], [a.x, a.ry, cz], scale(roof, i % 2 ? 0.92 : 1.04), [xm, 0.3, cz]);
      // a rafter showing at every joint
      if (i > 0) k.bar([a.x, ey + 0.012, cz + s * (a.hd + e)], [a.x, a.ry + 0.012, cz], 0.014, TIMBER_DARK);
    }
  }
  // the plank gables, and over each the barge boards crossing into two dragon heads
  for (const sx of [-1, 1]) {
    const g = at(sx < 0 ? 0 : 1), x = sx * (L / 2), I: P3 = [0, 0.3, cz];
    k.quad([x, 0, cz - g.hd], [x, 0, cz + g.hd], [x, wallH, cz + g.hd], [x, wallH, cz - g.hd], TIMBER, I);
    k.tri([x, ey, cz - g.hd - e], [x, ey, cz + g.hd + e], [x, g.ry, cz], scale(TIMBER, 1.12), I);
    k.box(x + sx * 0.004, 0, cz, 0.008, 0.24, 0.12, TIMBER_DARK);
    for (const s of [-1, 1]) {
      const bx = x + sx * 0.02, f = 1.3;
      const tip: P3 = [bx, ey + (g.ry - ey) * f, cz + s * (g.hd + e) * (1 - f)];
      k.bar([bx, ey, cz + s * (g.hd + e)], tip, 0.024, TIMBER_DARK);
      k.bar(tip, [bx + sx * 0.07, tip[1] + 0.05, tip[2] - s * 0.02], 0.028, CARVED);
    }
  }
  // the smoke hole on the ridge
  k.box(0, ridge - 0.04, cz, 0.24, 0.06, 0.1, TIMBER_DARK, hex(0x1c1816));
  // the carved doorway in the long side: a little porch between two posts
  const dx = -L * 0.22, dz = cz + hdAt(dx);
  k.box(dx, 0, dz + 0.08, 0.3, 0.38, 0.24, TIMBER);
  k.gable(dx, 0.38, dz + 0.08, 0.36, 0.18, 0.3, roof, scale(TIMBER, 1.12), true);
  k.box(dx, 0, dz + 0.203, 0.14, 0.3, 0.008, hex(0x2a1e16));
  for (const s of [-1, 1]) {
    k.cyl(dx + s * 0.13, 0, dz + 0.23, 0.028, 0.4, CARVED, 6);
    k.box(dx + s * 0.13, 0.4, dz + 0.23, 0.07, 0.03, 0.07, GOLD);
  }
  // shields hung in a row under the eaves
  let si = 0;
  for (let x = -L / 2 + 0.2; x < L / 2 - 0.1; x += 0.21) {
    if (Math.abs(x - dx) < 0.27) continue;
    const z = cz + hdAt(x) + 0.014;
    k.face(x, 0.15, z, 0.072, hex(SHIELDS[si++ % SHIELDS.length]), 8);
    k.box(x, 0.135, z + 0.008, 0.03, 0.03, 0.012, METAL);
  }
  // the longship drawn up on rollers: a dragon at the prow, a curl at the stern, the striped sail furled on its yard
  const sx = L * 0.2, sz = Math.min(D / 2 - 0.3, dz + 0.62), sl = Math.min(1.25, L * 0.5), ky = 0.07;
  for (const o of [-0.3, 0, 0.3]) k.box(sx + o * sl, 0, sz, 0.06, ky + 0.004, 0.4, hex(0x8a6a48));
  hull(k, sx, ky, sz, sl, 0.27, 0.11, 0.2, hex(0x6a4428), hex(0x9a7a50));
  const bow: P3 = [sx + sl / 2 - 0.02, ky + 0.28, sz], neck: P3 = [sx + sl / 2 + 0.05, ky + 0.47, sz];
  k.bar(bow, neck, 0.022, TIMBER_DARK);
  k.bar(neck, [neck[0] + 0.08, neck[1] + 0.01, sz], 0.03, CARVED);
  k.box(neck[0] + 0.1, neck[1] + 0.035, sz, 0.03, 0.025, 0.03, GOLD);
  const stern: P3 = [sx - sl / 2 + 0.02, ky + 0.28, sz], curl: P3 = [sx - sl / 2 - 0.04, ky + 0.45, sz];
  k.bar(stern, curl, 0.02, TIMBER_DARK);
  k.bar(curl, [curl[0] + 0.06, curl[1] + 0.04, sz], 0.02, TIMBER_DARK);
  for (let i = 0; i < 5; i++) {
    const x = sx + (i - 2) * sl * 0.13;
    for (const s of [-1, 1]) k.box(x, ky + 0.085, sz + s * 0.128, 0.055, 0.055, 0.012, hex(SHIELDS[(i + (s > 0 ? 0 : 2)) % SHIELDS.length]));
  }
  k.cyl(sx, ky + 0.06, sz, 0.016, 0.46, TIMBER_DARK, 5);
  for (const o of [-1, 1]) k.box(sx + o * sl * 0.27, ky + 0.06, sz, 0.02, 0.2, 0.02, TIMBER_DARK);
  const stripes = 7, yl = sl * 0.62;
  for (let i = 0; i < stripes; i++) k.box(sx - yl / 2 + (yl * (i + 0.5)) / stripes, ky + 0.26, sz, yl / stripes, 0.055, 0.06, i % 2 ? hex(0xf0e8d8) : hex(0xb8342a));
  // a stack of firewood by the far gable
  k.box(-L / 2 + 0.3, 0, dz + 0.16, 0.34, 0.12, 0.12, hex(0x9a7a50), hex(0x6a4a30));
};

const RUNE_GREY = hex(0x8a8c8a), RUNE_DARK = hex(0x6e706e), RUNE_RED = hex(0xb8322a), MOUND = hex(0x6f9a52);

/** A runestone: a tall rough slab with a red serpent looped over its face, on a low mound ringed with stones. */
const runestone: Draw = (k, W, D, _b, r) => {
  const s = Math.min(W, D);
  k.cyl(0, 0, 0, s * 0.42, 0.04, MOUND, 12);
  k.cyl(0, 0.04, 0, s * 0.31, 0.04, scale(MOUND, 1.06), 10);
  for (let i = 0; i < 11; i++) {
    const a = (i / 11) * TAU + 0.2, q = 0.05 + r() * 0.035;
    k.box(Math.cos(a) * s * 0.4, 0, Math.sin(a) * s * 0.4, q, q * 0.9, q, i % 2 ? RUNE_GREY : RUNE_DARK);
  }
  k.turned(0.12, () => {
    // the slab: broadest at the shoulder, leaning in to a lopsided top
    taper(k, 0, 0, 0.06, 0.16, 0.06, 0.005, 0, 0.62, 0.185, 0.055, RUNE_GREY);
    taper(k, 0.005, 0, 0.62, 0.185, 0.055, -0.03, 0, 0.98, 0.1, 0.045, RUNE_GREY, scale(RUNE_GREY, 1.1));
    // the serpent: up one edge, over the top, down the other and coiled in on itself
    const path: [number, number][] = [[-0.11, 0.16], [-0.135, 0.4], [-0.13, 0.62], [-0.085, 0.8], [-0.02, 0.87], [0.04, 0.79], [0.115, 0.62], [0.13, 0.4], [0.1, 0.2], [0.02, 0.19], [-0.05, 0.3], [-0.05, 0.46], [0.02, 0.55], [0.06, 0.45], [0.01, 0.37]];
    const fz = (y: number) => (y < 0.62 ? 0.06 - ((y - 0.06) / 0.56) * 0.005 : 0.055 - ((y - 0.62) / 0.36) * 0.01) + 0.004;
    for (let i = 0; i + 1 < path.length; i++) {
      const [x0, y0] = path[i], [x1, y1] = path[i + 1];
      k.bar([x0, y0, fz(y0)], [x1, y1, fz(y1)], 0.014, RUNE_RED);
    }
    k.box(0.01, 0.355, fz(0.37), 0.035, 0.035, 0.014, RUNE_RED);
  });
  // two lesser stones beside it
  k.turned(-0.3, () => taper(k, s * 0.27, -0.04, 0.03, 0.07, 0.04, s * 0.27, -0.04, 0.42, 0.045, 0.03, RUNE_DARK, RUNE_GREY));
  k.turned(0.5, () => taper(k, -s * 0.26, 0.1, 0.03, 0.065, 0.04, -s * 0.25, 0.1, 0.27, 0.04, 0.03, RUNE_GREY, scale(RUNE_GREY, 1.1)));
};

// ================================ Venice ================================

const VBRICK = hex(0xb4583e), VBRICK_DARK = hex(0x9a4834), ISTRIA = hex(0xf2eee2), VERDIGRIS = hex(0x6aa890);
const DOGE_PINK = hex(0xeab4a4), DOGE_CREAM = hex(0xf8ead8), LAGOON = hex(0x4f9c9c), PAVING = hex(0xd8d2c4);
const MARK_MARBLE = hex(0xeadfc8), MARK_SHADE = hex(0xcdbfa2), MARK_LEAD = hex(0x7e868c), MOSAIC = hex(0xd8a838), GOLD_GLOW = hex(0xffc850);
const PORPHYRY = hex(0x8a4848), VERDE = hex(0x587a68), BRONZE = hex(0xa8823a);

/**
 * St Mark's bell tower: a plain fluted shaft of red brick, the white arcaded belfry, a brick attic and
 * a steep green spire with a gold angel on its point. The little marble loggia stands at its foot.
 */
const campanile: Draw = (k, W, D) => {
  const s = Math.min(W, D), sw = s * 0.4, cz = -s * 0.09, shaft = 1.92;
  k.box(0, 0, cz, sw + 0.06, 0.08, sw + 0.06, ISTRIA);
  k.box(0, 0.08, cz, sw, shaft - 0.08, sw, VBRICK);
  around(k, 0, cz, sw, sw, (x0, zf, _span, f) => {
    // three shallow flutes up each face, and slit windows up the stair
    for (const o of [-1, 0, 1]) k.box(x0 + o * sw * 0.27, 0.22, zf + 0.003, sw * 0.13, shaft - 0.36, 0.006, VBRICK_DARK);
    if (f % 2 === 0) for (let i = 0; i < 4; i++) k.box(x0 + (i % 2 ? 1 : -1) * sw * 0.27, 0.45 + i * 0.36, zf + 0.008, 0.025, 0.07, 0.006, SHADOW);
  });
  // the belfry: four arches a side on white columns, the bells lit behind them
  const by = shaft, bh = 0.34;
  k.box(0, by, cz, sw + 0.08, 0.05, sw + 0.08, ISTRIA);
  k.glowBox(0, by + 0.05, cz, sw - 0.12, bh - 0.04, sw - 0.12, SHADOW, FLOOD, WARM_GLOW);
  k.box(0, by + 0.05, cz, 0.12, 0.16, 0.12, BRONZE);
  around(k, 0, cz, sw, sw, (x0, zf, span) => {
    const n = 4, bay = (span - 0.06) / n, xs = x0 - span / 2 + 0.03;
    for (let i = 0; i <= n; i++) k.box(xs + i * bay, by + 0.05, zf - 0.03, i % n ? 0.03 : 0.06, bh * 0.5, i % n ? 0.03 : 0.06, ISTRIA);
    for (let i = 0; i < n; i++) spandrel(k, xs + i * bay, xs + (i + 1) * bay, by + 0.05 + bh * 0.5, by + 0.05 + bh, zf - 0.015, ISTRIA, false);
  });
  k.box(0, by + bh + 0.05, cz, sw + 0.1, 0.05, sw + 0.1, ISTRIA);
  // the attic with its white relief on every face, the copper spire and the angel
  const ay = by + bh + 0.1, aw = sw - 0.03;
  k.box(0, ay, cz, aw, 0.32, aw, VBRICK);
  around(k, 0, cz, aw, aw, (x0, zf) => k.box(x0, ay + 0.08, zf + 0.004, aw * 0.42, 0.17, 0.008, ISTRIA));
  k.box(0, ay + 0.32, cz, sw + 0.05, 0.04, sw + 0.05, ISTRIA);
  const sy = ay + 0.36;
  k.hip(0, sy, cz, sw - 0.02, 0.8, sw - 0.02, VERDIGRIS);
  k.cyl(0, sy + 0.76, cz, 0.016, 0.12, GOLD, 5);
  k.box(0, sy + 0.86, cz, 0.1, 0.05, 0.016, GOLD);
  k.box(0, sy + 0.9, cz, 0.03, 0.04, 0.03, GOLD);
  // the loggetta: three arches between red marble columns under a balustraded attic
  const lz = cz + sw / 2 + 0.09, lw = sw + 0.16;
  k.box(0, 0, lz, lw, 0.25, 0.18, ISTRIA);
  for (const o of [-1, 0, 1]) archPanel(k, o * lw * 0.29, 0.03, lz + 0.094, lw * 0.19, 0.18, SHADOW);
  for (const o of [-1.5, -0.5, 0.5, 1.5]) k.box(o * lw * 0.29, 0.02, lz + 0.1, 0.028, 0.2, 0.024, PORPHYRY);
  k.box(0, 0.25, lz, lw + 0.03, 0.035, 0.21, ISTRIA);
  k.box(0, 0.285, lz - 0.01, lw - 0.04, 0.07, 0.14, scale(ISTRIA, 0.93));
  k.glowBox(0, 0.02, lz + 0.14, 0.08, 0.03, 0.04, DARK, FLOOD, WARM_GLOW);
};

/** A mooring pole in the lagoon: barber stripes and a gilded cap. */
function paline(k: Kit, x: number, z: number, h: number, col: RGB, y = 0): void {
  const n = 5;
  for (let i = 0; i < n; i++) k.cyl(x, y + 0.02 + (h * i) / n, z, 0.017, h / n, i % 2 ? WHITE : col, 5);
  k.cone(x, y + 0.02 + h, z, 0.026, 0.05, GOLD, 5);
}

/** A gondola lying along x: a slim black hull, the iron at the prow, a red seat. */
function gondola(k: Kit, x: number, z: number, dir: 1 | -1): void {
  const len = 0.66;
  hull(k, x, 0.022, z, len, 0.12, 0.045, 0.09, BLACK, hex(0x34343c), 6);
  k.box(x + dir * (len / 2 - 0.012), 0.12, z, 0.016, 0.085, 0.022, METAL);
  k.box(x - dir * 0.04, 0.06, z, 0.12, 0.028, 0.06, hex(0xb8342a));
  // the gondolier at the stern with his oar
  k.box(x - dir * 0.22, 0.075, z, 0.03, 0.1, 0.03, WHITE);
  k.box(x - dir * 0.22, 0.175, z, 0.04, 0.02, 0.04, hex(0xe8d8a0));
  k.bar([x - dir * 0.2, 0.17, z + 0.02], [x - dir * 0.34, 0.03, z + 0.1], 0.006, hex(0x8a6a48));
}

/**
 * The Doge's Palace: two storeys of open white Gothic arcade, a stout one and a lighter loggia of twice
 * the arches under a row of quatrefoils, carrying a tall flat wall of pink and white diamonds with a
 * lacy crest. Gondolas at their striped poles on the water along the front.
 */
const dogePalace: Draw = (k, W, D, _b, r) => {
  const w = W - 0.3, back = -D / 2 + 0.12, wz1 = D / 2 - 0.06, wz0 = wz1 - 0.46, fz = wz0 - 0.24, d = fz - back, cz = (fz + back) / 2;
  const g = 0.42, y2 = g + 0.37, up = 0.78, top = y2 + up;
  // the shadowed walls behind the arcades, the loggia's floor, the band of quatrefoils and the wall above
  k.box(0, 0, cz, w - 0.3, y2, d - 0.3, SHADOW);
  k.box(0, g - 0.03, cz, w, 0.03, d, ISTRIA);
  k.box(0, y2 - 0.085, cz, w, 0.085, d, ISTRIA);
  k.box(0, y2, cz, w, up, d, DOGE_PINK, hex(0x8a8078));
  around(k, 0, cz, w, d, (x0, zf, span, f) => {
    const n = Math.max(3, Math.round(span / 0.31)), bay = (span - 0.1) / n, xs = x0 - span / 2 + 0.05, sp = g * 0.58;
    // the crest along the roofline: a fringe of little spikes, a taller one at each corner
    for (let u = -span / 2 + 0.1, i = 0; u < span / 2 - 0.06; u += 0.105, i++) k.hip(x0 + u, top, zf - 0.03, 0.06, i % 2 ? 0.07 : 0.12, 0.05, ISTRIA);
    k.box(x0 - span / 2 + 0.03, top, zf - 0.03, 0.06, 0.1, 0.06, ISTRIA);
    k.hip(x0 - span / 2 + 0.03, top + 0.1, zf - 0.03, 0.07, 0.12, 0.07, ISTRIA);
    // the back is a plain wall on the yard
    if (f === 2) { k.box(x0, 0, zf - 0.09, span - 0.1, y2 - 0.085, 0.17, scale(DOGE_PINK, 0.92)); return; }
    // the ground arcade: stout columns and pointed arches
    for (let i = 0; i <= n; i++) {
      k.cyl(xs + i * bay, 0, zf - 0.05, 0.042, sp, ISTRIA, 6);
      k.box(xs + i * bay, sp - 0.03, zf - 0.05, 0.11, 0.03, 0.1, ISTRIA);
    }
    for (let i = 0; i < n; i++) spandrel(k, xs + i * bay, xs + (i + 1) * bay, sp, g - 0.03, zf - 0.012, ISTRIA, true);
    // the loggia: two arches to every one below, a balustrade, and a quatrefoil over every column
    const m = n * 2, lb = (span - 0.1) / m, ls = g + 0.16;
    for (let i = 0; i <= m; i++) {
      k.box(xs + i * lb, g, zf - 0.04, 0.03, ls - g, 0.03, ISTRIA);
      k.face(xs + i * lb, y2 - 0.045, zf + 0.004, 0.027, SHADOW, 6);
    }
    for (let i = 0; i < m; i++) spandrel(k, xs + i * lb, xs + (i + 1) * lb, ls, y2 - 0.085, zf - 0.012, ISTRIA, true);
    k.box(x0, g, zf - 0.035, span - 0.08, 0.055, 0.014, scale(ISTRIA, 0.95));
    // the diaper of the upper wall, and its few great pointed windows
    const I: P3 = [x0, y2, zf - 0.3], hw = 0.07, hh = 0.07, z = zf + 0.004;
    for (let j = 0, y = y2 + 0.1; y < top - 0.08; j++, y += 0.105) {
      for (let u = -span / 2 + 0.1 + (j % 2) * 0.095; u < span / 2 - 0.08; u += 0.19) {
        k.quad([x0 + u - hw, y, z], [x0 + u, y - hh, z], [x0 + u + hw, y, z], [x0 + u, y + hh, z], DOGE_CREAM, I);
      }
    }
    const wn = f === 0 ? 7 : 3;
    for (let i = 0; i < wn; i++) {
      const u = x0 - span / 2 + (span * (i + 0.5)) / wn, mid = f === 0 && i === 3;
      archWin(k, u, y2 + (mid ? 0.1 : 0.2), zf, mid ? 0.24 : 0.19, mid ? 0.5 : 0.36, ISTRIA, true, lit(r));
      k.face(u, top - 0.11, zf + 0.009, 0.035, SHADOW, 8);
      if (mid) {
        // the balcony in the middle of the front, under its own little gable
        k.box(u, y2 + 0.06, zf + 0.04, 0.4, 0.06, 0.08, ISTRIA);
        k.box(u, top, zf - 0.03, 0.3, 0.12, 0.07, ISTRIA);
        k.gable(u, top + 0.12, zf - 0.03, 0.3, 0.12, 0.07, ISTRIA, ISTRIA, true);
      }
    }
  });
  // the quay, the water, the poles and the gondolas
  k.box(0, 0, (fz + wz0) / 2, W - 0.16, 0.03, wz0 - fz, PAVING);
  k.box(0, 0, (wz0 + wz1) / 2, W - 0.16, 0.02, wz1 - wz0, LAGOON);
  const poles = Math.max(4, Math.round(W * 1.6));
  for (let i = 0; i < poles; i++) {
    paline(k, -W / 2 + 0.3 + ((W - 0.6) * i) / (poles - 1), wz0 + 0.07 + r() * 0.08, 0.26 + r() * 0.1, i % 2 ? hex(0x2f5a9a) : hex(0xc8352a));
  }
  gondola(k, -W * 0.2, wz0 + 0.3, 1);
  gondola(k, W * 0.22, wz0 + 0.27, -1);
  // the pink lamps of the quay
  for (const o of [-0.34, 0, 0.34]) {
    k.cyl(o * W, 0.03, wz0 - 0.05, 0.012, 0.26, IRON, 5);
    k.glowBox(o * W, 0.29, wz0 - 0.05, 0.05, 0.05, 0.05, hex(0xf0b8c0), LAMP, hex(0xffb0c0));
  }
};

/** A lead dome of St Mark's from its drum's foot at y: a bulb that swells past the drum, and an onion lantern with a gold cross. */
function leadDome(k: Kit, x: number, y: number, z: number, R: number): number {
  k.cyl(x, y, z, R * 0.92, R * 0.32, MARK_MARBLE, 12);
  const prof: [number, number][] = [[0.93, 0], [1.07, 0.3], [1.04, 0.62], [0.86, 0.95], [0.55, 1.2], [0.2, 1.36]];
  const yb = y + R * 0.32;
  for (let i = 0; i + 1 < prof.length; i++) k.band(x, z, yb + prof[i][1] * R, prof[i][0] * R, yb + prof[i + 1][1] * R, prof[i + 1][0] * R, 12, scale(MARK_LEAD, i % 2 ? 0.95 : 1.03));
  let t = yb + 1.36 * R;
  k.cyl(x, t, z, R * 0.12, R * 0.24, MARK_MARBLE, 6);
  t += R * 0.24;
  for (const [f, h] of [[0.2, 0.1], [0.26, 0.12], [0.16, 0.1]] as const) { k.cyl(x, t, z, R * f, R * h, MARK_LEAD, 6); t += R * h; }
  k.box(x, t, z, 0.016, R * 0.3, 0.016, GOLD);
  k.box(x, t + R * 0.16, z, R * 0.18, 0.016, 0.016, GOLD);
  return t + R * 0.3;
}

/** A gold mosaic in an arch head on a wall facing +z: three stepped panes that glow after dark. */
function mosaic(k: Kit, x: number, y: number, z: number, r: number, ry: number): void {
  const f = [0.88, 0.7, 0.4];
  for (let i = 0; i < 3; i++) k.pane(x, y + (ry * 0.9 * i) / 3, z, 2 * r * f[i], (ry * 0.9) / 3, 1, MOSAIC, FLOOD, GOLD_GLOW);
}

/**
 * St Mark's Basilica: five deep portals under gold mosaics across the west front, the four bronze horses
 * on the terrace over the middle one, a fringe of pinnacles and gold lunettes, and five lead domes in a cross.
 */
const marcoBasilica: Draw = (k, W, D) => {
  const w = W - 0.3, fz = D / 2 - 0.46, back = -D / 2 + 0.15, nd = 0.5, bz1 = fz - nd, bd = bz1 - back, bcz = (bz1 + back) / 2;
  const bh = 0.62, ch = 0.3, top = bh + ch;
  // the piazza's paving and its three flag masts
  k.box(0, 0, (fz + D / 2 - 0.06) / 2, W - 0.2, 0.025, D / 2 - 0.06 - fz, PAVING);
  for (const o of [-0.3, 0, 0.3]) {
    k.box(o * w, 0.025, fz + 0.3, 0.07, 0.07, 0.07, BRONZE);
    k.cyl(o * w, 0.095, fz + 0.3, 0.012, 0.85, hex(0x8a2a2a), 5);
    k.box(o * w + 0.06, 0.78, fz + 0.3, 0.12, 0.14, 0.008, o ? hex(0xb8342a) : GOLD);
  }
  // the body: the low aisles, and the cross of nave and transept standing out of them
  const z0 = bcz - bd * 0.04, arm = Math.min(w * 0.31, bd * 0.29), nw = w * 0.42;
  k.box(0, 0, bcz, w - 0.1, bh, bd, MARK_MARBLE, MARK_LEAD);
  k.box(0, bh, bcz, nw, ch, bd, MARK_MARBLE, MARK_LEAD);
  k.box(0, bh, z0, w - 0.14, ch, nw, MARK_MARBLE, MARK_LEAD);
  k.box(0, bh - 0.04, bcz, w - 0.06, 0.04, bd + 0.04, MARK_SHADE);
  around(k, 0, bcz, w - 0.1, bd, (x0, zf, span) => {
    const n = Math.max(3, Math.round(span / 0.5));
    for (let i = 0; i < n; i++) archPanel(k, x0 - span / 2 + (span * (i + 0.5)) / n, 0.06, zf + 0.004, (span / n) * 0.62, 0.42, MARK_SHADE);
  }, [1, 2, 3]);
  // the five domes
  leadDome(k, 0, top, z0, 0.36);
  leadDome(k, 0, top, z0 + arm, 0.31);
  leadDome(k, 0, top, z0 - arm, 0.29);
  for (const sx of [-1, 1]) leadDome(k, sx * arm, top, z0, 0.29);
  // the west front, lower register: five portals, each a dark recess under a gold half-dome, marble columns between
  const lh = 0.56, bay = w / 5;
  k.box(0, 0, fz - nd / 2, w, lh, nd, MARK_MARBLE, hex(0xd8d0bc));
  for (let i = -2; i <= 2; i++) {
    const pw = i ? bay * 0.62 : bay * 0.8, ph = i ? 0.43 : 0.51, x = i * bay;
    archPanel(k, x, -0.012, fz + 0.004, pw + 0.05, ph + 0.04, WHITE);
    archPanel(k, x, 0, fz + 0.008, pw, ph, SHADOW);
    k.box(x, 0, fz + 0.012, pw * 0.5, ph - pw / 2 - 0.02, 0.008, hex(0x5a4430));
    mosaic(k, x, ph - pw / 2, fz + 0.008, pw / 2, pw / 2);
  }
  for (let i = -3; i < 3; i++) {
    const x = (i + 0.5) * bay;
    k.box(x, 0, fz + 0.03, 0.08, 0.36, 0.06, i % 2 ? PORPHYRY : VERDE);
    k.box(x, 0.36, fz + 0.03, 0.1, 0.03, 0.07, WHITE);
  }
  // the terrace and its balustrade, and the four horses over the middle portal
  k.box(0, lh, fz - 0.015, w, 0.05, 0.03, WHITE);
  for (let i = 0; i < 4; i++) {
    const x = (i - 1.5) * 0.1, z = fz - 0.09;
    k.box(x, lh + 0.06, z, 0.04, 0.045, 0.12, BRONZE);
    k.box(x, lh, z + 0.04, 0.03, 0.06, 0.025, BRONZE);
    k.box(x, lh, z - 0.04, 0.03, 0.06, 0.025, BRONZE);
    k.box(x, lh + 0.09, z + 0.06, 0.03, 0.07, 0.035, BRONZE);
  }
  // the upper register: five lunettes, each the end of a lead barrel with an ogee point, pinnacles between
  const zu = fz - 0.19, uh = 0.2, uy = lh + uh;
  k.box(0, lh, zu - 0.15, w - 0.06, uh, 0.3, MARK_MARBLE);
  for (let i = -2; i <= 2; i++) {
    const x = i * bay, rr = i ? bay * 0.43 : bay * 0.5, ry = i ? rr * 0.95 : rr * 1.1;
    barrel(k, x, uy, zu - 0.32, zu, rr, ry, MARK_LEAD, i ? MARK_MARBLE : hex(0x34424c));
    if (i) mosaic(k, x, uy + 0.01, zu, rr * 0.86, ry * 0.86);
    else k.pane(x, uy - 0.12, zu, rr * 1.3, ry * 0.75 + 0.12, 1, hex(0x34424c), FLOOD, WARM_GLOW);
    k.hip(x, uy + ry - 0.03, zu - 0.03, 0.1, 0.2, 0.07, WHITE);
    k.box(x, uy + ry + 0.15, zu - 0.03, 0.02, 0.07, 0.02, i ? WHITE : GOLD);
  }
  for (let i = -3; i < 3; i++) {
    const x = Math.max(-w / 2 + 0.05, Math.min(w / 2 - 0.05, (i + 0.5) * bay));
    k.box(x, lh, zu + 0.02, 0.07, 0.4, 0.07, WHITE);
    k.hip(x, lh + 0.4, zu + 0.02, 0.095, 0.22, 0.095, WHITE);
  }
  k.glowBox(0, 0.025, fz + 0.18, 0.1, 0.03, 0.05, DARK, FLOOD, WARM_GLOW);
};

// ================================ London ================================

const BATH = hex(0xd8bc80), BATH_LIGHT = hex(0xe8d29c), BATH_DARK = hex(0xa88c58), SLATE = hex(0x3e444c), LAWN = hex(0x6fb04a);
const GHERKIN_A = hex(0x3f7a88), GHERKIN_B = hex(0x4a8a96), GHERKIN_DARK = hex(0x1f3a48);

/** A clock face in its black and gold frame on a wall facing +z, the hands turning with the day and the dial lit at night. */
function greatClock(k: Kit, x: number, y: number, z: number, r: number): void {
  k.box(x, y - r * 1.32, z + 0.006, r * 2.64, r * 2.64, 0.012, GOLD);
  k.box(x, y - r * 1.2, z + 0.01, r * 2.4, r * 2.4, 0.012, BLACK);
  k.face(x, y, z + 0.022, r, WHITE, 12);
  k.glowBox(x, y - r * 0.7, z + 0.026, r * 1.4, r * 1.4, 0.004, WHITE, [17.2, 30, 1.3], WARM_GLOW);
  k.spin(x, y, z + 0.036, 'z', 0, (h) => h.box(0, 0, 0, 0.024, r * 0.55, 0.004, BLACK), 'hour');
  k.spin(x, y, z + 0.044, 'z', 0, (h) => h.box(0, 0, 0, 0.016, r * 0.86, 0.004, BLACK), 'minute');
}

/**
 * Big Ben: the ribbed limestone clock tower at the front corner, a dial on each of its four sides under a
 * steep slate spire, and behind it a range of the Palace of Westminster in buttresses and pinnacles with
 * a square tower at its far end.
 */
const bigBen: Draw = (k, W, D, _b, r) => {
  const tw = 0.54, tx = W / 2 - 0.16 - tw / 2, tz = D / 2 - 0.16 - tw / 2;
  // the palace range running back from the tower
  const rw = Math.min(W - 0.75, 1.3), rcx = W / 2 - 0.2 - rw / 2, rz0 = -D / 2 + 0.14, rz1 = tz - tw / 2 + 0.04, rd = rz1 - rz0, rcz = (rz0 + rz1) / 2, rh = 0.8;
  k.box(rcx, 0, rcz, rw, rh, rd, BATH, SLATE);
  k.gable(rcx, rh, rcz, rw - 0.14, 0.3, rd - 0.1, SLATE, BATH, true);
  around(k, rcx, rcz, rw, rd, (x0, zf, span) => {
    const n = Math.max(2, Math.round(span / 0.24)), bay = span / n;
    k.box(x0, 0.37, zf + 0.006, span, 0.035, 0.012, BATH_LIGHT);
    k.box(x0, rh, zf - 0.02, span, 0.06, 0.04, BATH_LIGHT);
    for (let i = 0; i <= n; i++) {
      const u = x0 - span / 2 + i * bay;
      k.box(u, 0, zf + 0.012, 0.05, rh + 0.08, 0.045, BATH_LIGHT);
      k.hip(u, rh + 0.08, zf + 0.012, 0.06, 0.16, 0.055, BATH_LIGHT);
      if (i === n) break;
      k.pane(u + bay / 2, 0.1, zf, bay * 0.42, 0.22, 1, SHADOW, lit(r), WARM_GLOW);
      k.pane(u + bay / 2, 0.45, zf, bay * 0.42, 0.26, 1, SHADOW, lit(r), WARM_GLOW);
    }
  });
  // the lantern spire over the middle of the range
  k.cyl(rcx, rh + 0.22, rcz, 0.08, 0.22, BATH, 8);
  k.cone(rcx, rh + 0.44, rcz, 0.09, 0.5, SLATE, 8);
  // the square tower at the far end: corner turrets, tall windows, a flag
  const vw = 0.5, vx = rcx - rw / 2 + vw / 2 - 0.06, vz = rz0 + vw / 2 - 0.04, vh = 1.55;
  k.box(vx, 0, vz, vw, vh, vw, BATH, SLATE);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    k.box(vx + sx * (vw / 2 - 0.02), 0, vz + sz * (vw / 2 - 0.02), 0.1, vh + 0.16, 0.1, BATH_LIGHT);
    k.hip(vx + sx * (vw / 2 - 0.02), vh + 0.16, vz + sz * (vw / 2 - 0.02), 0.11, 0.2, 0.11, BATH_LIGHT);
  }
  around(k, vx, vz, vw, vw, (x0, zf) => {
    for (const o of [-0.08, 0.08]) k.box(x0 + o, vh - 0.62, zf + 0.004, 0.07, 0.46, 0.008, SHADOW);
    k.box(x0, vh - 0.04, zf + 0.004, vw - 0.2, 0.04, 0.012, BATH_LIGHT);
    k.pane(x0, 0.5, zf, 0.2, 0.3, 1, SHADOW, lit(r), WARM_GLOW);
  });
  k.cyl(vx, vh, vz, 0.012, 0.6, METAL, 5);
  k.box(vx + 0.09, vh + 0.46, vz, 0.18, 0.11, 0.008, hex(0x2f4a8a));
  k.box(vx + 0.09, vh + 0.5, vz, 0.18, 0.03, 0.012, hex(0xc8352a));
  // the yard beside the range: lawn behind iron railings
  const lx0 = -W / 2 + 0.1, lx1 = rcx - rw / 2 - 0.06;
  if (lx1 - lx0 > 0.2) {
    k.box((lx0 + lx1) / 2, 0, (rz0 + D / 2 - 0.1) / 2, lx1 - lx0, 0.025, D / 2 - 0.1 - rz0, LAWN);
    k.box((lx0 + lx1) / 2, 0, D / 2 - 0.1, lx1 - lx0, 0.14, 0.012, IRON);
    k.box(lx0, 0, (rz0 + D / 2 - 0.1) / 2, 0.012, 0.14, D / 2 - 0.1 - rz0, IRON);
  }

  // the clock tower: a ribbed shaft
  const sh = 2.45;
  k.box(tx, 0, tz, tw, sh, tw, BATH);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(tx + sx * (tw / 2 - 0.025), 0, tz + sz * (tw / 2 - 0.025), 0.08, sh, 0.08, BATH_LIGHT);
  for (const y of [0.3, 1.32, sh - 0.05]) k.box(tx, y, tz, tw + 0.05, 0.05, tw + 0.05, BATH_LIGHT);
  around(k, tx, tz, tw, tw, (x0, zf) => {
    for (let i = 0; i < 4; i++) {
      const u = x0 - 0.18 + i * 0.12;
      k.box(u, 0.38, zf + 0.004, 0.06, 0.9, 0.008, BATH_DARK);
      k.box(u, 1.41, zf + 0.004, 0.06, 0.96, 0.008, BATH_DARK);
    }
    k.pane(x0, 0.08, zf, 0.14, 0.18, 1, SHADOW, lit(r), WARM_GLOW);
  });
  // the clock stage, a dial to each side
  const cw = tw + 0.12;
  k.box(tx, sh, tz, cw, 0.62, cw, BATH);
  k.box(tx, sh, tz, cw + 0.05, 0.04, cw + 0.05, BATH_LIGHT);
  k.box(tx, sh + 0.6, tz, cw + 0.06, 0.035, cw + 0.06, GOLD);
  around(k, tx, tz, cw, cw, (x0, zf) => greatClock(k, x0, sh + 0.32, zf, 0.2));
  // the belfry over it, four pinnacles, the first pitch of the roof with its dormers, the lantern and the spire
  const by = sh + 0.635;
  k.box(tx, by, tz, tw + 0.02, 0.22, tw + 0.02, BATH);
  around(k, tx, tz, tw + 0.02, tw + 0.02, (x0, zf) => {
    for (let i = 0; i < 5; i++) k.box(x0 - 0.18 + i * 0.09, by + 0.04, zf + 0.004, 0.045, 0.14, 0.008, SHADOW);
  });
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    k.box(tx + sx * (cw / 2 - 0.03), by, tz + sz * (cw / 2 - 0.03), 0.06, 0.2, 0.06, BATH_LIGHT);
    k.hip(tx + sx * (cw / 2 - 0.03), by + 0.2, tz + sz * (cw / 2 - 0.03), 0.07, 0.16, 0.07, BATH_LIGHT);
  }
  const ry = by + 0.22;
  taper(k, tx, tz, ry, tw / 2 + 0.02, tw / 2 + 0.02, tx, tz, ry + 0.3, 0.17, 0.17, SLATE);
  around(k, tx, tz, 0.46, 0.46, (x0, zf) => {
    k.box(x0, ry + 0.07, zf - 0.03, 0.09, 0.1, 0.07, GOLD);
    k.gable(x0, ry + 0.17, zf - 0.03, 0.1, 0.06, 0.08, SLATE, GOLD, true);
  });
  const ly = ry + 0.3;
  k.box(tx, ly, tz, 0.3, 0.17, 0.3, BATH_LIGHT);
  k.glowBox(tx, ly + 0.04, tz, 0.32, 0.09, 0.32, hex(0x8a6a30), FLOOD, WARM_GLOW);
  k.box(tx, ly + 0.17, tz, 0.37, 0.03, 0.37, GOLD);
  k.hip(tx, ly + 0.2, tz, 0.34, 0.46, 0.34, SLATE);
  k.cyl(tx, ly + 0.62, tz, 0.014, 0.12, GOLD, 5);
  k.box(tx, ly + 0.74, tz, 0.045, 0.045, 0.045, GOLD);
};

/**
 * The Gherkin: a round glass tower that swells above its foot and tapers to a rounded point, dark
 * spirals wrapping up it, a clear dome at the top and a ring of crossed columns at the bottom.
 */
const gherkin: Draw = (k, W, D, b) => {
  const H = Math.max(30, b.floors) * FLOOR, R = Math.min(W, D) / 2 - 0.14, seg = 18, rings = 26, foot = 0.36;
  const prof = (t: number) => (t < 0.4 ? 0.74 + 0.26 * Math.sin((t / 0.4) * Math.PI / 2) : Math.pow(Math.cos(((t - 0.4) / 0.6) * Math.PI / 2), 0.5));
  const twist = (TAU / seg) * 0.6;
  const at = (j: number, s: number): P3 => {
    const t = j / rings, rr = j >= rings ? 0 : R * prof(t), a = (s / seg) * TAU + j * twist;
    return [Math.cos(a) * rr, foot + (H - foot) * t, Math.sin(a) * rr];
  };
  // the plaza, the dark lobby and the crossed columns round it
  k.cyl(0, 0, 0, R + 0.08, 0.03, hex(0xcfc8b8), seg);
  const rb = R * prof(0);
  k.cyl(0, 0.03, 0, rb * 0.8, foot - 0.03, hex(0x263038), 12);
  for (let s = 0; s < seg / 2; s++) {
    const a0 = (s / (seg / 2)) * TAU, a1 = ((s + 1) / (seg / 2)) * TAU;
    const p0: P3 = [Math.cos(a0) * rb, 0.03, Math.sin(a0) * rb], p1: P3 = [Math.cos(a1) * rb, 0.03, Math.sin(a1) * rb];
    k.bar(p0, [p1[0], foot, p1[2]], 0.022, WHITE);
    k.bar(p1, [p0[0], foot, p0[2]], 0.022, WHITE);
  }
  k.glowBox(0, 0.03, rb * 0.8 * Math.cos(Math.PI / 12), 0.22, 0.2, 0.012, GLASS_LIGHT, EVENING, WARM_GLOW);
  // the glass: every ring turned a little further than the one below, so the dark lightwells spiral
  for (let j = 0; j < rings; j++) {
    const cap = j >= rings - 2;
    for (let s = 0; s < seg; s++) {
      const col = cap ? GLASS_LIGHT : s % 3 === 0 ? GHERKIN_DARK : j % 2 ? GHERKIN_A : GHERKIN_B;
      k.quad(at(j, s), at(j, s + 1), at(j + 1, s + 1), at(j + 1, s), col, [0, foot + ((H - foot) * (j + 0.5)) / rings, 0]);
    }
  }
  // floors lit in bands after dark
  for (let j = 1; j < rings - 2; j += 3) {
    const t = (j + 0.5) / rings, rr = R * prof(t) * Math.cos(Math.PI / seg), y = foot + (H - foot) * t;
    const chord = 2 * R * prof(t) * Math.sin(Math.PI / seg);
    for (let s = 1; s < seg; s += 3) {
      const a = ((s + 0.5) / seg) * TAU + (j + 0.5) * twist;
      k.turned(Math.PI / 2 - a, () => k.glowBox(0, y - 0.055, rr + 0.008, chord * 0.9, 0.11, 0.012, scale(GHERKIN_B, 1.14), [17.5, 24 + (j % 4), 1.4], hex(0xd8f0ff)));
    }
  }
  k.glowBox(0, H - 0.01, 0, 0.04, 0.05, 0.04, hex(0xe2412f), [17, 31, 2.4], hex(0xff4a3a));
};

// ================================ New Orleans ================================

const QUARTER: readonly number[] = [0xd9a441, 0xe89890, 0x6fb8a0, 0xc86a4a];
const SHUTTER = hex(0x2f5a48), IRON_GREEN = hex(0x24382e), FERN = hex(0x4f9a48), WHITEWASH = hex(0xf0eee6), TOMB_GREY = hex(0xc4c4bc);
const SHELL = hex(0xe2dccb), TABLET = hex(0x6a6a68), OAK = hex(0x46703c), OAK_DARK = hex(0x3a5f34), MOSS = hex(0x9aa88c), BARK = hex(0x4a3a2c);

/**
 * A French Quarter corner house: stucco in a strong colour, tall shuttered doors, a deep iron gallery
 * wrapping the front and one side with ferns hung from it, and a pair of neon notes on the corner.
 */
const jazzClub: Draw = (k, W, D, b, r) => {
  const wall = hex(QUARTER[Math.floor(r() * QUARTER.length)]), trim = hex(0xf4ecd8);
  const gd = 0.18, x0 = -W / 2 + 0.06, z0 = -D / 2 + 0.06, bw = W - 0.14 - gd, bd = D - 0.14 - gd;
  const cx = x0 + bw / 2, cz = z0 + bd / 2, fh = FLOOR * 1.12, floors = Math.max(2, Math.min(3, b.floors)), h = floors * fh;
  const x1 = x0 + bw, z1 = z0 + bd;
  k.box(cx, 0, cz, bw, h, bd, wall);
  k.box(cx, 0, cz, bw + 0.012, 0.045, bd + 0.012, scale(wall, 0.78));
  k.box(cx, h, cz, bw + 0.06, 0.04, bd + 0.06, trim);
  k.hip(cx, h + 0.04, cz, bw + 0.02, 0.17, bd + 0.02, hex(0x565c66));
  k.box(x0 + 0.1, h, z0 + 0.1, 0.09, 0.26, 0.09, hex(0x9c4f3d), DARK);
  // tall french doors on both street fronts, every one between its shutters
  around(k, cx, cz, bw, bd, (u0, zf, span, f) => {
    const n = Math.max(2, Math.round(span / 0.25));
    for (let fl = 0; fl < floors; fl++) for (let i = 0; i < n; i++) {
      const u = u0 - span / 2 + (span * (i + 0.5)) / n, y = fl * fh + (fl ? 0.015 : 0.03), wh = fh * 0.68;
      const door = fl === 0 && f === 0 && i === n - 1;
      k.pane(u, y, zf, 0.075, wh, 1, door ? hex(0x4a3020) : hex(0x34424c), fl === 0 ? [17, 27, 1.5] : lit(r), WARM_GLOW);
      for (const s of [-1, 1]) k.box(u + s * 0.062, y, zf + 0.007, 0.042, wh, 0.014, SHUTTER);
      k.box(u, y + wh, zf + 0.006, 0.17, 0.02, 0.012, trim);
    }
  }, [0, 1]);
  for (let fl = 0; fl < floors; fl++) k.pane(x0, fl * fh + 0.1, cz, 0.12, fh * 0.45, 2, hex(0x34424c), lit(r), WARM_GLOW);
  // the gallery: a deck at every upper floor on thin posts, railed in iron
  const xe = x1 + gd - 0.02, ze = z1 + gd - 0.02;
  for (let fl = 1; fl < floors; fl++) {
    const y = fl * fh;
    k.box((x0 + x1 + gd) / 2, y - 0.025, z1 + gd / 2, bw + gd, 0.025, gd, IRON_GREEN, hex(0x8a8478));
    k.box(x1 + gd / 2, y - 0.025, cz, gd, 0.025, bd, IRON_GREEN, hex(0x8a8478));
    // the rails, their balusters, and the closed ends
    k.box((x0 + xe) / 2, y + 0.1, ze, xe - x0, 0.014, 0.014, IRON_GREEN);
    k.box(xe, y + 0.1, (z0 + ze) / 2, 0.014, 0.014, ze - z0, IRON_GREEN);
    k.box(x0 + 0.005, y + 0.1, (z1 + ze) / 2, 0.014, 0.014, ze - z1, IRON_GREEN);
    k.box((x1 + xe) / 2, y + 0.1, z0 + 0.005, xe - x1, 0.014, 0.014, IRON_GREEN);
    for (let x = x0 + 0.03; x < xe - 0.02; x += 0.05) k.box(x, y, ze, 0.009, 0.1, 0.009, IRON_GREEN);
    for (let z = z0 + 0.03; z < ze - 0.02; z += 0.05) k.box(xe, y, z, 0.009, 0.1, 0.009, IRON_GREEN);
    // a band of iron lace under the deck's edge
    k.box((x0 + xe) / 2, y - 0.07, ze, xe - x0, 0.045, 0.006, IRON_GREEN);
    k.box(xe, y - 0.07, (z0 + ze) / 2, 0.006, 0.045, ze - z0, IRON_GREEN);
  }
  const top = (floors - 1) * fh;
  const posts: [number, number][] = [];
  for (let i = 0; i <= 3; i++) posts.push([x0 + 0.01 + ((xe - x0 - 0.01) * i) / 3, ze]);
  for (let i = 0; i < 3; i++) posts.push([xe, z0 + 0.01 + ((ze - z0 - 0.01) * i) / 3]);
  for (const [px, pz] of posts) k.box(px, 0, pz, 0.02, top + 0.1, 0.02, IRON_GREEN);
  // ferns in baskets under the deck, between the posts
  for (let i = 0; i < 3; i++) {
    const fx = x0 + 0.01 + ((xe - x0 - 0.01) * (i + 0.5)) / 3;
    k.hip(fx, fh - 0.075, ze, 0.1, -0.1, 0.1, FERN);
    k.hip(fx, fh - 0.075, ze, 0.11, 0.04, 0.11, scale(FERN, 1.12));
  }
  for (let i = 0; i < 2; i++) {
    const fz = z0 + 0.01 + ((ze - z0 - 0.01) * (i + 0.5)) / 3;
    k.hip(xe, fh - 0.075, fz, 0.1, -0.1, 0.1, FERN);
    k.hip(xe, fh - 0.075, fz, 0.11, 0.04, 0.11, scale(FERN, 1.12));
  }
  // the sign on the corner: a pair of beamed notes in neon on an iron bracket
  const neon = r() < 0.5 ? hex(0xff4fa0) : hex(0x40d8f0), ny = top + 0.17, nx = xe + 0.03, nz = ze + 0.03, NEON: Sched = [17, 30.5, 1.9];
  k.bar([x1, ny + 0.27, z1], [nx, ny + 0.27, nz], 0.01, IRON);
  k.box(nx, ny + 0.2, nz, 0.012, 0.07, 0.012, IRON);
  k.turned(Math.PI / 4, () => {
    const lx = (nx - nz) * Math.SQRT1_2, lz = (nx + nz) * Math.SQRT1_2;
    for (const o of [-0.05, 0.05]) {
      k.glowBox(lx + o, ny + 0.03, lz, 0.022, 0.15, 0.022, neon, NEON, neon);
      k.glowBox(lx + o - 0.03, ny, lz, 0.07, 0.05, 0.03, neon, NEON, neon);
    }
    k.glowBox(lx, ny + 0.17, lz, 0.122, 0.03, 0.022, neon, NEON, neon);
  });
  // a gas lantern by the door
  k.box(x1 - 0.02, 0.24, z1 + 0.03, 0.012, 0.012, 0.06, IRON);
  k.glowBox(x1 - 0.02, 0.18, z1 + 0.06, 0.04, 0.06, 0.04, hex(0xe8c878), [17, 31, 2], WARM_GLOW);
};

/** One family tomb: a little plastered house on a step, gabled, barrel-topped or flat, a tablet in its front. */
function tomb(k: Kit, r: Rng, x: number, z: number, w: number, d: number, h: number, face: number, col: RGB): void {
  const kind = r(), y = 0.05 + h;
  k.box(x, 0.02, z, w + 0.04, 0.03, d + 0.04, scale(col, 0.86));
  k.box(x, 0.05, z, w, h, d, col);
  let top = y;
  if (kind < 0.42) { k.gable(x, y, z, w + 0.03, w * 0.36, d + 0.03, scale(col, 0.9), col, true); top = y + w * 0.36; }
  else if (kind < 0.78) { barrel(k, x, y, z - d / 2, z + d / 2, w / 2, w * 0.32, scale(col, 0.92), col, 5); top = y + w * 0.32; }
  else { k.box(x, y, z, w + 0.04, 0.03, d + 0.04, scale(col, 0.9)); k.box(x, y + 0.03, z, w * 0.62, 0.04, d * 0.62, col); top = y + 0.07; }
  k.box(x, 0.09, z + face * (d / 2 + 0.003), w * 0.56, h * 0.68, 0.006, TABLET);
  if (r() < 0.4) {
    k.box(x, top - 0.02, z + face * (d / 2 - 0.04), 0.018, 0.13, 0.018, col);
    k.box(x, top + 0.05, z + face * (d / 2 - 0.04), 0.07, 0.018, 0.018, col);
  }
}

/** A society tomb: tall, stepped and corniced, urns at its corners and a cross or an angel on top. */
function societyTomb(k: Kit, x: number, z: number, w: number, d: number, face: number, angel: boolean): void {
  const h = 0.46;
  k.box(x, 0.02, z, w + 0.06, 0.04, d + 0.06, TOMB_GREY);
  k.box(x, 0.06, z, w, h, d, WHITEWASH);
  k.box(x, 0.06 + h, z, w + 0.05, 0.035, d + 0.05, TOMB_GREY);
  k.box(x, 0.095 + h, z, w * 0.7, 0.07, d * 0.7, WHITEWASH);
  for (let i = 0; i < 3; i++) for (const o of [-0.28, 0, 0.28]) k.box(x + o * w, 0.1 + i * 0.14, z + face * (d / 2 + 0.003), w * 0.22, 0.1, 0.006, TABLET);
  for (const s of [-1, 1]) k.cyl(x + s * (w / 2 - 0.03), 0.095 + h, z + face * (d / 2 - 0.03), 0.028, 0.08, TOMB_GREY, 6);
  const y = 0.165 + h;
  if (angel) {
    k.cyl(x, y, z, 0.04, 0.15, WHITE, 6);
    k.box(x, y + 0.15, z, 0.045, 0.045, 0.045, WHITE);
    for (const s of [-1, 1]) k.bar([x + s * 0.02, y + 0.1, z - face * 0.02], [x + s * 0.09, y + 0.2, z - face * 0.05], 0.018, WHITE);
  } else {
    k.box(x, y, z, 0.025, 0.2, 0.025, WHITE);
    k.box(x, y + 0.11, z, 0.11, 0.025, 0.025, WHITE);
  }
}

/**
 * A city of the dead: rows of whitewashed family tombs along shell paths inside a wall, a few tall
 * society tombs among them, wall vaults across the back, an iron gate, and a mossy live oak in one corner.
 */
const tombYard: Draw = (k, W, D, _b, r) => {
  const w = W - 0.2, d = D - 0.2, wt = 0.07, wh = 0.24, gw = 0.5;
  k.box(0, 0, 0, w, 0.02, d, SHELL);
  // the wall, and the vaults built into the back of it
  for (const sx of [-1, 1]) {
    k.box(sx * (w / 2 - wt / 2), 0, 0, wt, wh, d, WHITEWASH, TOMB_GREY);
    k.box(sx * (gw / 2 + (w / 2 - gw / 2) / 2), 0, d / 2 - wt / 2, w / 2 - gw / 2, wh, wt, WHITEWASH, TOMB_GREY);
  }
  const vz = -d / 2 + 0.13;
  k.box(0, 0, vz, w - 2 * wt, 0.38, 0.26, WHITEWASH, TOMB_GREY);
  const vn = Math.max(4, Math.floor((w - 2 * wt - 0.1) / 0.25));
  for (let i = 0; i < vn; i++) for (let row = 0; row < 2; row++) {
    const x = -(w - 2 * wt - 0.1) / 2 + ((w - 2 * wt - 0.1) * (i + 0.5)) / vn;
    k.box(x, 0.05 + row * 0.16, vz + 0.133, 0.17, 0.12, 0.006, r() < 0.25 ? SHADOW : TABLET);
  }
  // the gate: two piers with urns, an iron arch between, the leaves standing open
  const gz = d / 2 - wt / 2;
  for (const sx of [-1, 1]) {
    k.box(sx * (gw / 2 + 0.06), 0, gz, 0.13, 0.44, 0.13, WHITEWASH);
    k.box(sx * (gw / 2 + 0.06), 0.44, gz, 0.16, 0.03, 0.16, TOMB_GREY);
    k.cyl(sx * (gw / 2 + 0.06), 0.47, gz, 0.035, 0.08, TOMB_GREY, 6);
    for (let i = 0; i < 4; i++) k.box(sx * (gw / 2 - 0.01), 0.02, gz - 0.09 - i * 0.06, 0.01, 0.3, 0.01, IRON);
    k.box(sx * (gw / 2 - 0.01), 0.27, gz - 0.18, 0.012, 0.012, 0.22, IRON);
  }
  for (let i = 0; i < 6; i++) {
    const a0 = (i / 6) * Math.PI, a1 = ((i + 1) / 6) * Math.PI, rr = gw / 2 + 0.06;
    k.bar([Math.cos(a0) * rr, 0.47 + Math.sin(a0) * 0.16, gz], [Math.cos(a1) * rr, 0.47 + Math.sin(a1) * 0.16, gz], 0.012, IRON);
  }
  k.box(0, 0.63, gz, 0.02, 0.1, 0.02, IRON);
  k.box(0, 0.68, gz, 0.07, 0.02, 0.02, IRON);
  // the live oak in the front corner, moss hanging from its boughs
  const ox = -w / 2 + 0.78, oz = d / 2 - 0.8;
  k.cyl(ox, 0.02, oz, 0.09, 0.36, BARK, 7);
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * TAU + 0.4;
    k.bar([ox, 0.34, oz], [ox + Math.cos(a) * 0.42, 0.56, oz + Math.sin(a) * 0.42], 0.03, BARK);
  }
  k.band(ox, oz, 0.5, 0.42, 0.62, 0.62, 9, OAK_DARK);
  k.band(ox, oz, 0.62, 0.62, 0.8, 0.5, 9, OAK);
  k.band(ox, oz, 0.8, 0.5, 0.92, 0.24, 9, scale(OAK, 1.1));
  k.cone(ox, 0.92, oz, 0.24, 0.05, scale(OAK, 1.16), 9);
  for (let i = 0; i < 11; i++) {
    const a = (i / 11) * TAU, rr = 0.45 + r() * 0.15, len = 0.12 + r() * 0.16;
    k.box(ox + Math.cos(a) * rr, 0.58 - len, oz + Math.sin(a) * rr, 0.03, len, 0.03, MOSS);
  }
  // the tombs: rows facing the cross paths, either side of the middle aisle
  const zA = vz + 0.13 + 0.42, zB = d / 2 - wt - 0.52, rows = Math.max(2, Math.round((zB - zA) / 0.72) + 1), pitch = (zB - zA) / (rows - 1);
  const avail = w / 2 - wt - 0.08 - 0.22, cols = Math.max(1, Math.floor(avail / 0.36)), cell = avail / cols;
  for (let j = 0; j < rows; j++) {
    const z = zA + j * pitch, face = j % 2 ? -1 : 1;
    for (const sx of [-1, 1]) for (let i = 0; i < cols; i++) {
      const x = sx * (0.22 + cell * (i + 0.5));
      if (Math.hypot(x - ox, z - oz) < 0.62) continue;
      if (i === 0 && ((j === 1 && sx > 0) || (j === rows - 2 && sx < 0) || (j === 0 && sx < 0 && rows > 3))) {
        societyTomb(k, x, z, cell - 0.06, 0.4, face, j === 1);
        continue;
      }
      const col = r() < 0.6 ? WHITEWASH : r() < 0.6 ? TOMB_GREY : hex(0xe6dcc4);
      tomb(k, r, x, z + (r() - 0.5) * 0.04, cell - 0.1 - r() * 0.05, 0.34 + r() * 0.08, 0.2 + r() * 0.12, face, col);
    }
  }
};

// ================================ Havana ================================

const HAVANA_YELLOW = hex(0xe8c874), HAVANA_TRIM = hex(0xf6f0e0), HAVANA_RED = hex(0x9a3a2e), CHROME = hex(0xd8dce0), TYRE = hex(0x26262a);
const MORRO = hex(0xd2b888), MORRO_SHADE = hex(0xbca070), MORRO_LIGHT = hex(0xe2cca0), MORRO_TOP = hex(0xc4ac80), ROCK = hex(0x6e685e);

/** A fifties American car lying along x: long and low, two-tone, tail fins, chrome at both ends. `dir` is the way it faces. */
function fiftiesCar(k: Kit, x: number, z: number, col: RGB, dir: 1 | -1): void {
  const L = 0.54, Wd = 0.2;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(x + sx * L * 0.3, 0, z + sz * (Wd / 2 - 0.014), 0.09, 0.075, 0.03, TYRE);
  k.box(x, 0.035, z, L, 0.075, Wd - 0.02, col);
  k.box(x, 0.068, z, L * 0.92, 0.012, Wd - 0.012, CHROME);
  k.box(x - dir * 0.035, 0.11, z, L * 0.4, 0.055, Wd - 0.055, GLASS_LIGHT, WHITE);
  for (const sz of [-1, 1]) {
    // the fins, rising to the tail, each with its red light
    const fx = x - dir * (L / 2 - 0.08), fz = z + sz * (Wd / 2 - 0.022);
    taper(k, fx, fz, 0.11, 0.08, 0.011, fx - dir * 0.03, fz, 0.16, 0.045, 0.009, col);
    k.box(x - dir * (L / 2 + 0.002), 0.105, fz, 0.012, 0.035, 0.022, hex(0xd8302a));
    k.box(x + dir * (L / 2 + 0.002), 0.07, fz, 0.012, 0.03, 0.035, hex(0xf8f0c8));
  }
  for (const e of [-1, 1]) k.box(x + e * (L / 2 + 0.006), 0.035, z, 0.016, 0.028, Wd + 0.004, CHROME);
}

/**
 * A grand old cigar factory: three storeys of faded yellow between white pilasters, tall arched windows,
 * an arcade along the pavement, the name painted on the parapet, and two fifties cars parked in front.
 */
const cigarFactory: Draw = (k, W, D, _b, r) => {
  const w = W - 0.24, z0 = -D / 2 + 0.1, bd = Math.min(D - 0.85, 1.25), fz = z0 + bd, cz = z0 + bd / 2;
  const g = 0.37, fh = 0.3, floors = 3, h = g + (floors - 1) * fh, pd = 0.2;
  // the ground floor set back behind the portales, and the two floors over them
  k.box(0, 0, cz - pd / 2, w, g, bd - pd, scale(HAVANA_YELLOW, 0.62));
  k.box(0, g, cz, w, h - g, bd, HAVANA_YELLOW);
  k.box(0, 0, fz - pd / 2 + 0.02, w, 0.025, pd + 0.04, hex(0xcfc4ac));
  const n = Math.max(3, Math.round(w / 0.3)), bay = (w - 0.08) / n, xs = -w / 2 + 0.04, sp = g * 0.6;
  for (let i = 0; i <= n; i++) {
    k.box(xs + i * bay, 0, fz - 0.045, 0.075, sp, 0.09, HAVANA_TRIM);
    k.box(xs + i * bay, sp - 0.025, fz - 0.045, 0.1, 0.025, 0.1, HAVANA_TRIM);
  }
  for (let i = 0; i < n; i++) {
    spandrel(k, xs + i * bay, xs + (i + 1) * bay, sp, g, fz - 0.004, HAVANA_YELLOW, false);
    if (i % 2 === 0) k.pane(xs + (i + 0.5) * bay, 0.03, fz - pd, bay * 0.5, 0.24, 1, hex(0x3a2a20), [17, 24, 1.3], WARM_GLOW);
  }
  for (const sx of [-1, 1]) k.box(sx * (w / 2 - 0.02), 0, fz - pd / 2, 0.04, g, pd, HAVANA_YELLOW);
  k.box(0, g - 0.012, cz, w + 0.04, 0.035, bd + 0.04, HAVANA_TRIM);
  // pilasters and arched windows up the front and both ends
  around(k, 0, cz, w, bd, (u0, zf, span) => {
    const m = Math.max(2, Math.round(span / 0.3)), b2 = (span - 0.08) / m, us = u0 - span / 2 + 0.04;
    for (let i = 0; i <= m; i++) k.box(us + i * b2, g + 0.023, zf + 0.012, 0.05, h - g - 0.023, 0.024, HAVANA_TRIM);
    for (let fl = 0; fl < floors - 1; fl++) for (let i = 0; i < m; i++) {
      archWin(k, us + (i + 0.5) * b2, g + fl * fh + 0.065, zf, b2 * 0.4, 0.2, HAVANA_TRIM, false, lit(r));
    }
    // where the paint has gone
    for (let i = 0; i < Math.round(span * 2.2); i++) {
      const pw = 0.1 + r() * 0.16, ph = 0.05 + r() * 0.1;
      k.box(u0 + (r() - 0.5) * (span - pw - 0.1), g + 0.04 + r() * (h - g - ph - 0.06), zf + 0.002, pw, ph, 0.004, scale(HAVANA_YELLOW, r() < 0.5 ? 0.86 : 1.1));
    }
  }, [0, 1, 3]);
  // the cornice, the parapet and the painted name panel in the middle of it
  k.box(0, h, cz, w + 0.1, 0.05, bd + 0.1, HAVANA_TRIM);
  k.box(0, h + 0.05, cz, w, 0.09, bd, HAVANA_YELLOW, hex(0x8a8074));
  const pz = fz - 0.04, pw = Math.min(1.3, w * 0.46);
  k.box(0, h + 0.05, pz, pw, 0.24, 0.08, HAVANA_RED);
  k.box(0, h + 0.29, pz, pw + 0.06, 0.035, 0.1, HAVANA_TRIM);
  k.box(0, h + 0.325, pz, pw * 0.5, 0.06, 0.08, HAVANA_TRIM);
  const letters = 9;
  for (let i = 0; i < letters; i++) k.box(-pw / 2 + 0.08 + ((pw - 0.16) * (i + 0.5)) / letters, h + 0.13, pz + 0.042, ((pw - 0.16) / letters) * 0.62, 0.09, 0.006, hex(0xf4e4b8));
  for (const sx of [-1, 1]) k.cyl(sx * (pw / 2 + 0.12), h + 0.14, pz, 0.035, 0.09, HAVANA_TRIM, 6);
  // the flag on the roof
  k.cyl(w * 0.3, h + 0.14, cz, 0.012, 0.5, METAL, 5);
  k.box(w * 0.3 + 0.09, h + 0.5, cz, 0.18, 0.11, 0.008, hex(0x2f4a9a));
  k.box(w * 0.3 + 0.09, h + 0.54, cz, 0.18, 0.025, 0.012, WHITE);
  k.box(w * 0.3 + 0.025, h + 0.525, cz, 0.05, 0.06, 0.014, hex(0xc8302a));
  // the cars at the kerb
  const kz = fz + (D / 2 - fz) * 0.55;
  fiftiesCar(k, -w * 0.22, kz, hex(0x3cc4bc), 1);
  fiftiesCar(k, w * 0.2, kz + 0.04, hex(0xf08cae), -1);
  k.glowBox(-w * 0.46, 0.3, fz + 0.01, 0.04, 0.05, 0.04, hex(0xe8c878), LAMP, WARM_GLOW);
  k.glowBox(w * 0.46, 0.3, fz + 0.01, 0.04, 0.05, 0.04, hex(0xe8c878), LAMP, WARM_GLOW);
};

/**
 * The harbour castle: thick battered walls of tan stone on the rocks in an irregular trace of angular
 * bastions, sentry boxes on the corners, cannon along the seaward parapet, a dry moat and a bridge on
 * the landward side, and the white lighthouse on the seaward bastion.
 */
const morroFort: Draw = (k, W, D, _b, r) => {
  const fx = W / 4, fzs = D / 4;
  const P: [number, number][] = ([[0.8, 0.85], [1.3, 1.3], [1.7, 0.85], [1.45, 0.25], [1.6, -0.7], [1.0, -1.3], [0.3, -1.62], [-0.5, -1.55],
    [-1.3, -1.1], [-1.65, -0.2], [-1.4, 0.4], [-1.7, 0.85], [-1.3, 1.3], [-0.8, 0.85]] as [number, number][]).map(([x, z]) => [x * fx, z * fzs]);
  const N = P.length, H = 0.62, batter = 0.1, C: P3 = [0, H, -0.1 * fzs];
  // the outward normal of every wall, and the foot of every corner pushed out by the batter
  const nrm = P.map((p, i) => {
    const q = P[(i + 1) % N], dx = q[0] - p[0], dz = q[1] - p[1], l = Math.hypot(dx, dz) || 1;
    return [-dz / l, dx / l] as [number, number];
  });
  const foot = P.map((p, i) => {
    const a = nrm[(i + N - 1) % N], b = nrm[i];
    let nx = a[0] + b[0], nz = a[1] + b[1];
    const l = Math.hypot(nx, nz) || 1;
    nx /= l; nz /= l;
    return [p[0] + nx * batter * 1.2, p[1] + nz * batter * 1.2] as [number, number];
  });
  // the rocks it stands on, round the seaward sides
  for (let i = 3; i < 10; i++) {
    const j = (i + 1) % N;
    for (const t of [0.15, 0.6]) {
      const x = foot[i][0] + (foot[j][0] - foot[i][0]) * t + nrm[i][0] * 0.06, z = foot[i][1] + (foot[j][1] - foot[i][1]) * t + nrm[i][1] * 0.06;
      const cxx = Math.max(-W / 2 + 0.2, Math.min(W / 2 - 0.2, x)), czz = Math.max(-D / 2 + 0.2, Math.min(D / 2 - 0.2, z));
      const q = 0.2 + r() * 0.16, hh = 0.07 + r() * 0.1;
      k.box(cxx, 0, czz, q, hh, q * (0.7 + r() * 0.5), ROCK, scale(ROCK, 1.15));
      if (r() < 0.6) k.hip(cxx + 0.03, hh, czz, q * 0.7, 0.06 + r() * 0.06, q * 0.6, scale(ROCK, 1.08));
    }
  }
  // the walls, the terreplein inside them and the parapet along the top
  for (let i = 0; i < N; i++) {
    const j = (i + 1) % N, p = P[i], q = P[j];
    const mx = (p[0] + q[0]) / 2, mz = (p[1] + q[1]) / 2;
    k.quad([foot[i][0], 0, foot[i][1]], [foot[j][0], 0, foot[j][1]], [q[0], H, q[1]], [p[0], H, p[1]], i % 2 ? MORRO : MORRO_SHADE, [mx - nrm[i][0] * 0.3, H / 2, mz - nrm[i][1] * 0.3]);
    k.tri(C, [p[0], H, p[1]], [q[0], H, q[1]], MORRO_TOP, [C[0], 0, C[2]]);
    k.bar([p[0], H + 0.04, p[1]], [q[0], H + 0.04, q[1]], 0.042, MORRO_LIGHT);
  }
  // the keep standing out of the middle, a barrack on it, and the flag
  const kx = 0.15 * fx, kz = 0.05 * fzs;
  taper(k, kx, kz, H, 0.62 * fx, 0.42 * fzs, kx, kz, H + 0.24, 0.56 * fx, 0.36 * fzs, MORRO, MORRO_TOP);
  k.box(kx + 0.1, H + 0.24, kz - 0.05, 0.5 * fx, 0.16, 0.26 * fzs, MORRO_LIGHT, hex(0xa86a4a));
  k.pane(kx + 0.1, H + 0.28, kz - 0.05 + 0.13 * fzs, 0.3 * fx, 0.08, 1, SHADOW, EVENING, WARM_GLOW);
  k.cyl(kx - 0.4 * fx, H + 0.24, kz, 0.014, 0.62, METAL, 5);
  k.box(kx - 0.4 * fx + 0.1, H + 0.72, kz, 0.2, 0.12, 0.008, hex(0x2f4a9a));
  k.box(kx - 0.4 * fx + 0.1, H + 0.765, kz, 0.2, 0.03, 0.012, WHITE);
  k.box(kx - 0.4 * fx + 0.03, H + 0.745, kz, 0.06, 0.07, 0.014, hex(0xc8302a));
  // garitas on the corners
  for (const i of [1, 2, 4, 5, 8, 9, 11, 12]) {
    const [x, z] = P[i];
    k.cyl(x, H - 0.1, z, 0.08, 0.27, MORRO_LIGHT, 8);
    k.dome(x, H + 0.17, z, 0.09, MORRO, 8, 3);
    k.cyl(x, H + 0.25, z, 0.014, 0.05, MORRO_LIGHT, 4);
  }
  // cannon along the seaward parapet
  for (const i of [4, 5, 7, 8]) {
    const j = (i + 1) % N;
    for (const t of [0.3, 0.7]) {
      const x = P[i][0] + (P[j][0] - P[i][0]) * t - nrm[i][0] * 0.13, z = P[i][1] + (P[j][1] - P[i][1]) * t - nrm[i][1] * 0.13;
      k.box(x, H, z, 0.08, 0.06, 0.08, hex(0x6a4a30));
      k.bar([x - nrm[i][0] * 0.04, H + 0.08, z - nrm[i][1] * 0.04], [x + nrm[i][0] * 0.2, H + 0.12, z + nrm[i][1] * 0.2], 0.02, IRON);
    }
  }
  // the landward side: the dry moat under the curtain, the glacis beyond it, the gatehouse and its bridge
  const zc = 0.85 * fzs, zo = D / 2 - 0.34, ze = D / 2 - 0.08, by = 0.15;
  k.box(0, 0, (zc + zo) / 2, W - 0.3, 0.02, zo - zc + 0.3, hex(0x8a7a5c));
  k.turned(Math.PI, () => k.wedge(0, 0, -(zo + ze) / 2, W - 0.3, by, ze - zo, hex(0xa89868)));
  k.box(0, 0, zc + 0.05, 0.52 * Math.min(1, fx), H + 0.16, 0.22, MORRO_LIGHT, MORRO_TOP);
  archPanel(k, 0, by, zc + 0.164, 0.2, 0.32, hex(0x3a2a20));
  k.box(0, by + 0.37, zc + 0.166, 0.1, 0.1, 0.012, WHITE);
  k.box(0, by - 0.03, (zc + 0.16 + zo + 0.04) / 2, 0.24, 0.03, zo + 0.04 - zc - 0.16, hex(0x8a6a48));
  for (const t of [0.35, 0.72]) k.box(0, 0.02, zc + 0.16 + (zo - zc - 0.16) * t, 0.2, by - 0.05, 0.08, MORRO_SHADE);
  for (const sx of [-1, 1]) k.box(sx * 0.115, by, (zc + 0.16 + zo + 0.04) / 2, 0.012, 0.05, zo + 0.04 - zc - 0.16, hex(0x6a4a30));
  for (const sx of [-1, 1]) k.glowBox(sx * 0.2, by + 0.2, zc + 0.17, 0.04, 0.05, 0.03, hex(0xe8c878), LAMP, WARM_GLOW);
  // the lighthouse on the seaward bastion
  const lx = -0.1 * fx, lz = -1.15 * fzs, ly = H;
  k.cyl(lx, ly, lz, 0.21, 0.1, MORRO_LIGHT, 10);
  k.band(lx, lz, ly + 0.1, 0.17, ly + 1.72, 0.115, 10, WHITE);
  k.band(lx, lz, ly + 0.62, 0.157, ly + 0.7, 0.155, 10, scale(WHITE, 0.86));
  k.band(lx, lz, ly + 1.22, 0.134, ly + 1.3, 0.132, 10, scale(WHITE, 0.86));
  k.cyl(lx, ly + 1.72, lz, 0.17, 0.04, hex(0x6e7278), 10);
  k.cyl(lx, ly + 1.76, lz, 0.075, 0.17, GLASS_LIGHT, 8);
  k.glowBox(lx, ly + 1.78, lz, 0.13, 0.13, 0.13, hex(0xf4e8b0), [17, 31, 2.8], hex(0xfff2b0));
  k.cone(lx, ly + 1.93, lz, 0.12, 0.13, hex(0x8a3a2e), 8);
  k.cyl(lx, ly + 2.05, lz, 0.01, 0.08, METAL, 4);
};

/** The models of the five styles' landmarks, by kind. */
/**
 * A gondola station on a canal-town quay (world/canals.ts): a strip of paving at the canal's edge, a
 * hut for the gondoliers with its striped awning, and below the quay wall, in the canal in front, a row
 * of striped poles with two gondolas tied up at them. The quay stands a step above the water, so the
 * poles and boats are drawn a step down and out past the front of the lot.
 */
const gondolaStation: Draw = (k, W, D, _b, r) => {
  const front = D / 2, water = -0.5;
  k.box(0, 0, 0, W - 0.04, 0.03, D - 0.04, hex(0xd8cdb4));
  // the quay's lip, in white Istrian stone
  k.box(0, 0.03, front - 0.04, W - 0.04, 0.025, 0.08, hex(0xf0ece2));
  // the gondoliers' hut at the back, under a striped awning, a lamp on a post beside it
  const hz = -D / 2 + 0.2;
  k.box(-0.2, 0.03, hz, 0.34, 0.26, 0.24, hex(0x8a5a3a));
  for (let i = 0; i < 4; i++) k.box(-0.2 - 0.15 + i * 0.1, 0.29, hz + 0.08, 0.1, 0.018, 0.34, i % 2 ? WHITE : hex(0xb8342a));
  k.pane(-0.2, 0.1, hz + 0.122, 0.12, 0.1, 1, GLASS_LIGHT, EVENING, WARM_GLOW);
  k.cyl(0.3, 0.03, hz, 0.012, 0.32, IRON, 5);
  k.glowBox(0.3, 0.35, hz, 0.05, 0.06, 0.05, hex(0xf6e6b8), LAMP, WARM_GLOW);
  // the poles and the gondolas in the canal in front, a step below
  for (let i = 0; i < 3; i++) paline(k, -W / 2 + 0.2 + ((W - 0.4) * i) / 2, front + 0.12 + r() * 0.05, 0.6 + r() * 0.1, i % 2 ? hex(0x2f5a9a) : hex(0xc8352a), water);
  gondolaAt(k, -0.06, front + 0.32, 1, water);
  gondolaAt(k, 0.08, front + 0.6, -1, water);
};

/** A gondola floating at height y (the water's surface, in the lot's frame). */
function gondolaAt(k: Kit, x: number, z: number, dir: 1 | -1, y: number): void {
  const len = 0.66;
  hull(k, x, y + 0.022, z, len, 0.12, 0.045, 0.09, BLACK, hex(0x34343c), 6);
  k.box(x + dir * (len / 2 - 0.012), y + 0.12, z, 0.016, 0.085, 0.022, METAL);
  k.box(x - dir * 0.04, y + 0.06, z, 0.12, 0.028, 0.06, hex(0xb8342a));
}

export const WORLD_B_DRAW: Partial<Record<ThemeKind, Draw>> = {
  longhouse, runestone, campanile, dogePalace, marcoBasilica, gondolaStation, bigBen, gherkin, jazzClub, tombYard, cigarFactory, morroFort,
};
