import { N, STEP, RoadType, World, heightAt, waterDepth, idx, type Arch, type Bridge, type RegionKind, type Road } from './tiles';
import { deckHeightAt, deckTiles, dirBetween, shapeOf } from './roads';

/**
 * What a bridge looks like, after some of the world's best-known crossings:
 *
 *   standard      the road type's own: a timber trestle, stone piers, a concrete girder, a twin viaduct
 *   suspension    the Golden Gate: two towers and a main cable slung between them
 *   harbourArch   Sydney Harbour: a steel through-arch the deck hangs from, granite pylons at each end
 *   towerBridge   Tower Bridge: two gothic stone towers joined by a high walkway, chains out to the banks
 *   cableStayed   Millau and Øresund: slender white pylons, straddling the deck, with fans of stays
 *   cantilever    the Forth Bridge: great red steel diamonds on stone piers, suspended spans between
 *   arcade        the Pont du Gard: tiers of round stone arches carrying the road over a deep valley
 *   covered       a New England covered bridge: a timber truss in a barn, shingled over, one lane wide
 */
export type BridgeDesign = 'standard' | 'suspension' | 'harbourArch' | 'towerBridge' | 'cableStayed' | 'cantilever' | 'arcade' | 'covered'
  // a Venice canal bridge: one low arch of white Istrian stone, a solid white balustrade along each side
  | 'venetian';

export const DESIGN_NAME: Record<BridgeDesign, string> = {
  standard: 'Bridge', suspension: 'Suspension bridge', harbourArch: 'Harbour arch', towerBridge: 'Tower bridge',
  cableStayed: 'Cable-stayed bridge', cantilever: 'Cantilever bridge', arcade: 'Stone arcade', covered: 'Covered bridge',
  venetian: 'Canal bridge',
};

/** What a bridge's place gives the choice to go on: its length and height, its road, and what stands around it. */
interface BridgeSite {
  /** Tiles of deck between the abutments. */
  len: number;
  /** The most air under the deck anywhere along it, in world units. */
  height: number;
  /** Whether any of it crosses open water. */
  water: boolean;
  /** The least air between the deck and the water under it, in world units (Infinity over dry ground). */
  waterAir: number;
  type: RoadType;
  /** The town it stands in or nearest to, if one is within reach, and that town's style and kind. */
  style: Arch | null;
  townKind: string | null;
  region: RegionKind | null;
  /** 0 frozen .. 1 tropical, from the tiles under it. */
  temp: number;
  /** A long span (a megalopolis's crossing, or one the player built big): only the grand designs. */
  big: boolean;
  /** In a town laid out to a GEN 53 city plan (world/plans), whose streets bridge its rivers and canals block by block. */
  planned?: boolean;
}

const HEAVY = (t: RoadType) => t === RoadType.TwoLane || t === RoadType.FourLane;
const LANE = (t: RoadType) => t === RoadType.Paved || t === RoadType.Brick || t === RoadType.Cobble;
const OLD: ReadonlySet<Arch> = new Set<Arch>(['gothic', 'victorian', 'tudor', 'medieval', 'classic', 'granite', 'dutch', 'budapest', 'russian', 'ottoman', 'maya', 'roman', 'chinese', 'seasia', 'sanfran', 'paris', 'capital',
  'mughal', 'moorish', 'andean', 'norse', 'sahel', 'himalayan', 'havana', 'venice', 'neworleans', 'london', 'shire', 'whitecity', 'spirit', 'steampunk', 'adriatic', 'onsen', 'leman', 'como']);
const SOUTH: ReadonlySet<Arch> = new Set<Arch>(['mediterranean', 'cycladic', 'adobe', 'classic', 'medieval', 'colonial', 'moorish', 'mughal', 'sahel', 'andean', 'venice', 'havana', 'adriatic', 'como']);
const MODERN: ReadonlySet<Arch> = new Set<Arch>(['modernist', 'postmodern', 'brutalist', 'deco', 'hongkong', 'vegas', 'dubai', 'solarpunk', 'cyberpunk', 'chicago']);
const DRY: ReadonlySet<RegionKind> = new Set<RegionKind>(['sands', 'whitewash', 'goldhills', 'veldt', 'terraces', 'redrock', 'saltpan', 'lavender']);
const NORTH: ReadonlySet<RegionKind> = new Set<RegionKind>(['icefield', 'heights', 'moors', 'fjords', 'firecoast', 'bigtimber', 'steppe']);

/**
 * How well each design suits a site: 0 where it cannot stand (too short, too low, the wrong road),
 * more where the place's own character asks for it. A design with a strong character of its own is
 * rare away from the country it belongs to, never impossible.
 */
function designWeights(s: BridgeSite): Partial<Record<BridgeDesign, number>> {
  const out: Partial<Record<BridgeDesign, number>> = {};
  const big = s.big;
  // every short crossing in a canal town is a stone arch over its canal, whatever road it carries
  if (s.style === 'venice' && !big && s.water && s.len <= 6) return { venetian: 1 };
  // and an Amsterdam's brick arches over its grachten
  if (s.style === 'dutch' && !big && s.water && s.len <= 5) return { venetian: 1 };
  // and an onsen town's little stone bridges over its stream (Kinosaki's)
  if (s.style === 'onsen' && !big && s.water && s.len <= 6) return { venetian: 1 };
  // a city plan's streets cross its water every block or two: a famous design now and then, a plain span or a stone
  // arch for most (else Paris or Stockholm would be a row of Tower Bridges)
  if (s.planned && !big && s.water && s.len <= 9) return { standard: 2, venetian: s.len <= 6 ? 1.2 : 0, towerBridge: 0.25, cableStayed: HEAVY(s.type) && s.len >= 7 ? 0.25 : 0 };
  const modern = (s.style && MODERN.has(s.style)) || s.townKind === 'mega' || s.townKind === 'metro';
  // the grand river designs stand their towers and arches in the water and need the deck well up off it:
  // one skimming the surface (a generated crossing level with its banks) would sink their piers and drag
  // the deck under where the river steps down
  const lofty = big || s.waterAir >= GRAND_AIR;
  // the road's own look: every ordinary bridge may keep it; a grand crossing never does
  if (!big) out.standard = s.len < 4 ? 1 : 1.2;
  if (s.len < 4) return out;
  // the Golden Gate: a long crossing over water on a proper road
  if (lofty && HEAVY(s.type) && s.water && s.len >= 8) out.suspension = (big ? 1.2 : 0.8) * (s.style === 'sanfran' ? 6 : s.style === 'newyork' ? 3 : 1);
  // Sydney: a long steel arch over a harbour, a city's pride
  if (lofty && HEAVY(s.type) && s.water && s.len >= 8) out.harbourArch = (s.region === 'shallows' || s.style === 'deco' || s.style === 'colonial' || s.style === 'classic' ? 2.5 : 0.8) * (big ? 1.2 : 1);
  // Tower Bridge: a river crossing in an old town, not too long for its walkway
  if (lofty && (HEAVY(s.type) || LANE(s.type)) && s.water && s.len >= 5 && s.len <= 14) out.towerBridge = s.style && OLD.has(s.style) ? 2.5 : 0.35;
  // Millau: modern and very tall, or simply modern and long
  if (HEAVY(s.type) && s.len >= 7) out.cableStayed = (s.height >= 3 ? 2 : 0.6) + (modern ? 1.2 : 0);
  // the Forth: a long heavy crossing in cold country
  if ((lofty || !s.water) && HEAVY(s.type) && s.len >= 9) out.cantilever = s.region && NORTH.has(s.region) ? 2.5 : s.temp < 0.35 ? 1.6 : (s.style === 'victorian' || s.style === 'granite') ? 1.4 : 0.4;
  // the Pont du Gard: a tall stone arcade on an old road, at home in dry southern country
  if (!big && !HEAVY(s.type) && s.height >= 1.5 && s.len <= 18) {
    const south = (s.region && DRY.has(s.region)) || (s.style && SOUTH.has(s.style)) || s.temp > 0.72;
    out.arcade = (south ? 2.5 : 0.5) + (s.height >= 3 ? 0.8 : 0);
  }
  // a covered bridge: a short country crossing over water, in timber country and in the cold, where
  // a roof over the deck is what kept the trusses from rotting
  if (!big && !HEAVY(s.type) && s.water && s.len >= 2 && s.len <= 8) {
    const north = (s.region && NORTH.has(s.region)) || s.temp < 0.45;
    const woody = s.style === 'timber' || s.style === 'chalet' || s.style === 'victorian' || s.style === 'colonial' || s.style === 'western';
    out.covered = (woody ? 2.4 : 0.5) + (north ? 1.2 : 0);
  }
  return out;
}

/** Air a grand river design needs between its deck and the water: a whole height step. */
const GRAND_AIR = STEP;

function hashOf(a: number, b: number, c: number): number {
  let h = Math.imul(a | 0, 374761393) ^ Math.imul(b | 0, 668265263) ^ Math.imul(c | 0, 2246822519);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

/** Pick among the designs that suit a site, in proportion to how well: a roll hashed from where it is, so it never changes. */
export function pickDesign(s: BridgeSite, roll: number): BridgeDesign {
  const w = designWeights(s);
  const list = Object.entries(w).filter(([, v]) => (v ?? 0) > 0) as [BridgeDesign, number][];
  if (!list.length) return s.big ? 'suspension' : 'standard';
  const total = list.reduce((t, [, v]) => t + v, 0);
  let r = roll * total;
  for (const [d, v] of list) { if ((r -= v) < 0) return d; }
  return list[list.length - 1][0];
}

/** What the place under and around a bridge offers the choice. */
export function siteOf(w: World, r: Road, br: Bridge): BridgeSite {
  const wide = shapeOf(r.type);
  const a = r.nodes[br.from], b = r.nodes[br.to];
  const d = dirBetween(a, r.nodes[br.from + 1]);
  const tiles = deckTiles(a, b, d, wide);
  const L = tiles.length ? tiles[0].L : 1;
  let height = 0, water = false, waterAir = Infinity, temp = 0, n = 0;
  let town = -1;
  for (const { tile, j } of tiles) {
    const x = tile % N, z = (tile - x) / N;
    const top = Number.isNaN(br.h0) ? 0 : deckHeightAt(br, L, j - 0.5);
    const g = w.water[tile] >= 0 && waterDepth(w, tile) > 0 ? w.water[tile] * STEP : heightAt(w, x + 0.5, z + 0.5);
    height = Math.max(height, top - g);
    if (waterDepth(w, tile) > 0) {
      water = true;
      // the low end of the tile's stretch of deck, over its water's surface
      if (!Number.isNaN(br.h0)) waterAir = Math.min(waterAir, Math.min(deckHeightAt(br, L, j - 1), deckHeightAt(br, L, j)) - w.water[tile] * STEP);
    }
    temp += w.temp[tile]; n++;
    if (town < 0 && w.townId[tile] >= 0) town = w.townId[tile];
  }
  // a bridge just outside a town still takes its style: look along the road at both ends
  if (town < 0) {
    for (const node of [a, b]) {
      const x = node % N, z = (node - x) / N;
      for (let rr = 1; rr <= 10 && town < 0; rr += 3) {
        for (const [dx, dz] of [[rr, 0], [-rr, 0], [0, rr], [0, -rr]]) {
          const tx = x + dx, tz = z + dz;
          if (tx < 0 || tz < 0 || tx >= N || tz >= N) continue;
          const t = w.townId[idx(tx, tz)];
          if (t >= 0) { town = t; break; }
        }
      }
    }
  }
  const t = town >= 0 ? w.towns.find((q) => q.id === town) ?? null : null;
  return {
    len: L, height, water, waterAir, type: r.type,
    style: t?.style ?? null, townKind: t?.kind ?? null, region: w.region ?? null,
    temp: n ? temp / n : 0.5, big: !!br.suspension,
    ...(t?.plan && t.plan !== 'grid' ? { planned: true } : {}),
  };
}

const chosen = new WeakMap<Bridge, { d: BridgeDesign; big: boolean }>();

/**
 * The design a bridge is drawn in. Worked out from its place the first time it is asked for and
 * kept, so the same bridge is always the same design: a generated one each time its county is
 * built, and one of the player's for as long as it stands. A span the builder turns into a long
 * one (or back) is looked at again, since only the grand designs suit a long span.
 */
/** Console and tests: draw this bridge in a given design until it is next looked at as a different span. */
function forceDesign(br: Bridge, d: BridgeDesign): void { chosen.set(br, { d, big: !!br.suspension }); }

export function designOf(w: World, r: Road, br: Bridge): BridgeDesign {
  if (br.tunnel || br.ramp || br.level) return 'standard';
  // a raised road's run between its platforms is plain viaduct, whatever famous bridge the place might suit
  if (r.bridges?.some((o) => o.level && (o.from === br.from || o.from === br.to))) return 'standard';
  const big = !!br.suspension;
  const have = chosen.get(br);
  if (have && have.big === big) return have.d;
  const site = siteOf(w, r, br);
  const d = pickDesign(site, hashOf(w.cx * 7919 + r.nodes[br.from], w.cz * 104729 + r.nodes[br.to], br.from));
  chosen.set(br, { d, big });
  return d;
}
