import { hex } from '../../world/biomes';
import { FLOOR } from '../../world/towns';
import type { LakeKind } from '../../world/lakeKinds';
import { Vis } from '../nightLights';
import { TAU, WARM_GLOW, WHITE, cur, pick, styleWall, win, type Draw, type Kit, type P3 } from './kit';
import { archPanel } from './worldStylesB';
import {
  IRON, LAMPS, PLANK, ROOMS, STONE, STONE_DARK, bench, cypress, lakeLamp, lakePalm, planeTree, riva,
  stroller, toWater,
} from './lakeKit';

/**
 * A lake town's landmarks (world/lakeKinds.ts), each centred on its lot, its front to +z (or, by the water, in the
 * frame `toWater` turns to):
 *
 * - **Amusement park** (Arnolds Park on West Okoboji): the white wooden coaster (the Legend) out and back over its
 *   trestles with a train running round it, the Ferris wheel turning, a carousel, the midway's striped booths and the
 *   arch over the gate.
 * - **Jet d'Eau**: the Jetée des Eaux-Vives running out into the lake, its little lighthouse at the end, and the jet
 *   itself beside it, a white column taller than anything in town falling back in a plume downwind; lit at night.
 * - **Flower clock** (the Horloge Fleurie in the Jardin Anglais): a clock face planted in flowers on a sloped bed, its
 *   hands telling the game's time.
 * - **Château de Chillon**: the castle on its rock just off the shore, the keep, its towers and their brown roofs, the
 *   covered bridge over to it.
 * - **Lakeside villa** (Lake Como): a pastel villa under a low hip with green shutters, a loggia on top, a terrace in
 *   front with its urns and two cypresses, and where the lake comes up to it, steps down to a launch.
 * - **Villa gardens** (Villa Carlotta, Balbianello): terraces stepping down to the lake behind balustrades, beds of
 *   azaleas, rows of cypress, the villa on the top terrace and the loggia on the point, the landing at the foot.
 * - **Lakeside church** (San Giorgio at Varenna, San Giacomo at Bellagio): a Romanesque nave of grey stone, its round
 *   window over the door, the tall square campanile with its belfry and pyramid roof.
 */

const RED = hex(0xc8323a), BLUE = hex(0x2f5f9a), YELLOW = hex(0xf2c14e), GREEN = hex(0x3f9b4a);
const BOOTHS = [RED, BLUE, YELLOW, GREEN];
const SPRAY = hex(0xffffff), SPRAY2 = hex(0xeaf6fa);

// ---- the amusement park -------------------------------------------------------------------------

/** The coaster's circuit: points round the lot's back half, with its hills (x, y, z). */
function coasterTrack(W: number, D: number): P3[] {
  const x0 = -W / 2 + 0.5, x1 = W / 2 - 0.6, zb = -D / 2 + 0.45, zf = -D / 2 + 1.25;
  const out: P3[] = [];
  const n = 24;
  // out along the back on the lift hill and its drops, then back along the front over the bunny hops
  for (let i = 0; i <= n; i++) {
    const t = i / n, x = x0 + (x1 - x0) * t;
    const y = t < 0.18 ? 0.12 + t / 0.18 * 0.62 : 0.15 + 0.5 * Math.max(0, Math.cos((t - 0.18) * 11)) * (1 - t * 0.6);
    out.push([x, y, zb]);
  }
  out.push([x1 + 0.3, 0.3, (zb + zf) / 2]);
  for (let i = 0; i <= n; i++) {
    const t = i / n, x = x1 - (x1 - x0) * t;
    out.push([x, 0.12 + 0.22 * Math.abs(Math.sin(t * Math.PI * 3)), zf]);
  }
  out.push([x0 - 0.3, 0.12, (zb + zf) / 2]);
  return out;
}

const amusementPark: Draw = (k, W, D, b, r) => {
  // the grounds, paths and the gate arch on the street side
  k.box(0, 0, 0, W - 0.06, 0.012, D - 0.06, hex(0x7aa85a));
  k.box(0, 0.012, D / 2 - 0.6, W - 0.4, 0.004, 0.4, hex(0xd8ccb0));
  k.box(-W / 2 + 1.7, 0.012, 0.2, 0.3, 0.004, D - 1.2, hex(0xd8ccb0));
  for (const sx of [-0.45, 0.45]) { k.box(sx, 0, D / 2 - 0.15, 0.08, 0.5, 0.08, WHITE); k.cone(sx, 0.5, D / 2 - 0.15, 0.07, 0.1, RED, 6); }
  k.box(0, 0.42, D / 2 - 0.15, 1.0, 0.1, 0.03, BLUE);
  for (let i = 0; i < 8; i++) k.glowBox(-0.42 + i * 0.12, 0.47, D / 2 - 0.13, 0.03, 0.03, 0.01, YELLOW, LAMPS, hex(0xfff0a0));
  // the coaster: white timber trestles under a track that climbs, drops and runs back
  const track = coasterTrack(W, D), white = hex(0xf2f0e8), rail = hex(0x8a7a6a);
  for (let i = 0; i < track.length; i++) {
    const a = track[i], c = track[(i + 1) % track.length];
    k.bar([a[0], a[1], a[2] - 0.05], [c[0], c[1], c[2] - 0.05], 0.01, rail);
    k.bar([a[0], a[1], a[2] + 0.05], [c[0], c[1], c[2] + 0.05], 0.01, rail);
    k.bar([a[0], a[1] - 0.02, a[2]], [c[0], c[1] - 0.02, c[2]], 0.025, white);
    if (i % 2 === 0) {
      for (const s of [-0.07, 0.07]) k.bar([a[0], 0.012, a[2] + s * 1.6], [a[0], a[1] - 0.03, a[2] + s], 0.008, white);
      if (a[1] > 0.25) k.bar([a[0] - 0.05, 0.02, a[2] - 0.1], [a[0] + 0.05, a[1] * 0.6, a[2] + 0.1], 0.006, white);
    }
  }
  // its train: five cars running the circuit, faster down the drops
  const lens: number[] = [0];
  for (let i = 0; i < track.length; i++) { const a = track[i], c = track[(i + 1) % track.length]; lens.push(lens[i] + Math.hypot(c[0] - a[0], c[1] - a[1], c[2] - a[2])); }
  const total = lens[track.length], top = Math.max(...track.map((p) => p[1]));
  const at = (s: number): [P3, P3] => {
    s = ((s % total) + total) % total;
    let i = 0;
    while (lens[i + 1] < s) i++;
    const a = track[i], c = track[(i + 1) % track.length], u = (s - lens[i]) / Math.max(1e-6, lens[i + 1] - lens[i]);
    return [[a[0] + (c[0] - a[0]) * u, a[1] + (c[1] - a[1]) * u, a[2] + (c[2] - a[2]) * u], [c[0] - a[0], c[1] - a[1], c[2] - a[2]]];
  };
  const cars = 5, gap = 0.13;
  const carParts = Array.from({ length: cars }, (_, i) => (sk: Kit) => {
    sk.box(0, 0.01, 0, 0.08, 0.04, 0.11, i === 0 ? RED : hex(0xc8a040));
    sk.box(0, 0.05, -0.015, 0.07, 0.025, 0.02, hex(0x2a2a2e));
    sk.box(0, 0.06, 0.02, 0.05, 0.02, 0.02, hex(0xe0b090));
  });
  let s = r() * total, v = 0.4;
  k.rig(0, 0, 0, carParts, (ps, dt) => {
    // speed from the height it has fallen: the chain lift drags it up the first hill at a crawl
    const [p0] = at(s);
    const lift = s < lens[Math.ceil(track.length * 0.18 / 2) * 2 - 1];
    v = lift ? 0.25 : Math.max(0.35, Math.sqrt(2 * 3.2 * Math.max(0, top + 0.08 - p0[1])));
    s += v * dt;
    for (let i = 0; i < ps.length; i++) {
      const [p, d] = at(s - i * gap);
      ps[i].position.set(p[0], p[1], p[2]);
      ps[i].rotation.set(-Math.atan2(d[1], Math.hypot(d[0], d[2])), Math.atan2(d[0], d[2]), 0, 'YXZ');
    }
  });
  // the Ferris wheel by the water, turning, its gondolas hanging level
  const fx = W / 2 - 0.85, fz = 0.35, R = 0.62, hub = R + 0.12;
  for (const sz of [-0.07, 0.07]) {
    k.bar([fx - 0.3, 0.012, fz + sz * 2], [fx, hub, fz + sz], 0.014, WHITE);
    k.bar([fx + 0.3, 0.012, fz + sz * 2], [fx, hub, fz + sz], 0.014, WHITE);
  }
  const gondolas = 10, gcol = BOOTHS;
  const wheel = (sk: Kit) => {
    for (const sz of [-0.06, 0.06]) sk.hoop(0, 0, sz, R, 0.008, hex(0xe8e4dc), 20, 'xy');
    for (let i = 0; i < gondolas; i++) { const a = (i / gondolas) * TAU; sk.bar([0, 0, 0], [Math.cos(a) * R, Math.sin(a) * R, 0], 0.005, hex(0xe8e4dc)); }
    for (let i = 0; i < 20; i++) { const a = (i / 20) * TAU; sk.glowBox(Math.cos(a) * R, Math.sin(a) * R, 0.065, 0.015, 0.015, 0.006, YELLOW, LAMPS, hex(0xfff0a0)); }
    sk.cyl(0, -0.02, 0, 0.035, 0.04, IRON, 8);
  };
  const parts = [wheel, ...Array.from({ length: gondolas }, (_, i) => (sk: Kit) => {
    sk.box(0, -0.09, 0, 0.08, 0.06, 0.07, gcol[i % gcol.length]);
    sk.box(0, -0.03, 0, 0.09, 0.012, 0.08, WHITE);
    sk.bar([0, -0.03, 0], [0, 0, 0], 0.004, IRON);
  })];
  let ang = r() * TAU;
  k.rig(fx, hub, fz, parts, (ps, dt) => {
    ang += dt * 0.12;
    ps[0].rotation.z = ang;
    for (let i = 0; i < gondolas; i++) {
      const a = ang + (i / gondolas) * TAU;
      ps[i + 1].position.set(Math.cos(a) * R, Math.sin(a) * R, 0);
    }
  });
  // the carousel: a striped canopy over horses going up and down as it turns
  const cx = -W / 2 + 0.8, cz = 0.55;
  k.cyl(cx, 0.012, cz, 0.42, 0.04, hex(0xe8e0c8), 12);
  k.spin(cx, 0.05, cz, 'y', 0.6, (sk) => {
    sk.cyl(0, 0, 0, 0.05, 0.36, hex(0xd8b048), 8);
    for (let i = 0; i < 12; i++) {
      const a0 = (i / 12) * TAU, a1 = ((i + 1) / 12) * TAU;
      sk.tri([0, 0.52, 0], [Math.cos(a0) * 0.44, 0.38, Math.sin(a0) * 0.44], [Math.cos(a1) * 0.44, 0.38, Math.sin(a1) * 0.44], i % 2 ? WHITE : RED, [0, 0.3, 0]);
      sk.box(Math.cos(a0) * 0.42, 0.33, Math.sin(a0) * 0.42, 0.04, 0.05, 0.01, i % 2 ? YELLOW : BLUE);
    }
    for (let i = 0; i < 8; i++) {
      const a = (i / 8) * TAU, x = Math.cos(a) * 0.32, z = Math.sin(a) * 0.32, y = 0.08 + (i % 2) * 0.05;
      sk.bar([x, 0, z], [x, 0.38, z], 0.005, hex(0xd8b048));
      sk.box(x, y, z, 0.04, 0.05, 0.1, i % 3 ? WHITE : hex(0x8a5a3a));
    }
  });
  // the midway: striped booths along the path, the crowd (in summer)
  for (let i = 0; i < 5; i++) {
    const bx = -W / 2 + 1.3 + i * 0.55, bz = D / 2 - 0.95, col = BOOTHS[i % BOOTHS.length];
    k.box(bx, 0.012, bz, 0.36, 0.2, 0.26, hex(0xf4f2ec));
    for (let j = 0; j < 4; j++) k.box(bx - 0.135 + j * 0.09, 0.212, bz + 0.03, 0.09, 0.012, 0.34, j % 2 ? WHITE : col);
  }
  k.tagged(Vis.Summer, () => { for (let i = 0; i < 14; i++) stroller(k, r, -W / 2 + 0.8 + r() * (W - 1.6), 0.016, D / 2 - 0.65 + (r() - 0.5) * 0.3); });
};

// ---- the Jet d'Eau ------------------------------------------------------------------------------

const jetDeau: Draw = (k, W, D, b, r) => {
  toWater(k, b, W, D, (L, Dp, wy, reach) => {
    const qz = Dp / 2, out = Math.max(1.4, Math.min(3.2, reach - 0.4));
    // the quay, its benches, and the jetty in grey stone out into the lake
    k.box(0, 0, 0, L - 0.04, 0.02, Dp - 0.04, STONE);
    k.box(0, wy, qz + 0.02, L - 0.04, -wy + 0.02, 0.04, STONE_DARK);
    const jx = -L * 0.18;
    k.box(jx, wy - 0.1, qz + out / 2, 0.3, -wy + 0.12, out, STONE_DARK);
    k.box(jx, 0.02, qz + out / 2, 0.3, 0.012, out, STONE);
    for (let i = 0; i < 6; i++) lakeLamp(k, 'leman', jx + 0.13, 0.03, qz + 0.2 + (i * (out - 0.4)) / 5);
    // the little lighthouse at its end, green and white
    const lz = qz + out - 0.1;
    k.cyl(jx, 0.03, lz, 0.07, 0.34, WHITE, 8);
    k.cyl(jx, 0.12, lz, 0.072, 0.06, hex(0x2f7a4a), 8);
    k.glowBox(jx, 0.37, lz, 0.08, 0.08, 0.08, hex(0xeef0e0), [18, 30, 1.6], hex(0xfff2c0));
    k.cone(jx, 0.45, lz, 0.08, 0.08, hex(0x2f7a4a), 8);
    bench(k, L * 0.2, 0.02, -Dp / 2 + 0.3, IRON);
    flagHere(k, L / 2 - 0.2, 0.02, qz - 0.15);
    // the jet: a column of white water from just off the jetty's end, its plume falling away downwind; floodlit after dark
    const sx = jx + 0.45, sz = lz - 0.15, H = 3.0;
    const segs = 10, drops = 22;
    const parts: ((sk: Kit) => void)[] = [];
    // the column: white water thickening into spray as it rises
    for (let i = 0; i < segs; i++) parts.push((sk) => {
      const rr = 0.06 + i * 0.008;
      sk.cyl(0, 0, 0, rr, H / segs + 0.02, i % 2 ? SPRAY : SPRAY2, 7);
      if (i > segs * 0.6) for (let j = 0; j < 3; j++) sk.dome(Math.cos(j * 2.1) * rr, 0.08 + j * 0.06, Math.sin(j * 2.1) * rr, rr * 0.9, SPRAY, 6, 2);
    });
    // the plume: spray leaving the top and falling away downwind
    for (let i = 0; i < drops; i++) parts.push((sk) => { sk.dome(0, -0.06, 0, 0.13, i % 3 ? SPRAY : SPRAY2, 7, 3); sk.dome(0.07, -0.03, 0.04, 0.1, SPRAY, 6, 2); sk.dome(-0.05, -0.02, -0.04, 0.09, SPRAY2, 6, 2); });
    // its foot: a ring of white water where it leaves the lake, floodlit after dark
    parts.push((sk) => { sk.cyl(0, -0.01, 0, 0.16, 0.03, SPRAY2, 10); sk.dome(0, 0.01, 0, 0.11, SPRAY, 8, 2); });
    k.glowBox(sx, wy + 0.01, sz, 0.14, 0.02, 0.14, hex(0xd8e8ee), [18, 30, 1.6], hex(0xffffff));
    let t = r() * 20;
    k.rig(sx, wy, sz, parts, (ps, dt) => {
      t += dt;
      // the column leans a little with the wind as it rises, and sways
      for (let i = 0; i < segs; i++) {
        const h = (i / segs) * H;
        ps[i].position.set(Math.sin(t * 0.9 + i * 0.4) * 0.004 * i + h * h * 0.012, h, 0);
      }
      // the plume: drops leaving the top and falling away along the wind, swelling and thinning as they go
      for (let i = 0; i < drops; i++) {
        const ph = (t * 0.2 + i / drops) % 1, o = ps[segs + i];
        const along = H * H * 0.012 + ph * 0.75, fall = ph * ph * H * 0.92;
        o.position.set(along, H + 0.15 - fall, Math.sin(i * 1.7) * 0.07 * (0.4 + ph));
        const g = (0.7 + ph * 0.9) * Math.sin(Math.PI * Math.min(1, ph * 1.02 + 0.04));
        o.scale.setScalar(Math.max(0.001, g));
        o.visible = g > 0.03;
      }
      ps[segs + drops].scale.set(1 + Math.sin(t * 2.3) * 0.08, 1, 1 + Math.cos(t * 2.1) * 0.08);
    });
  });
};

/** The Swiss flag on a staff (Léman's landmarks). */
function flagHere(k: Kit, x: number, y: number, z: number): void {
  k.cyl(x, y, z, 0.007, 0.55, hex(0xe8e8ea), 4);
  k.box(x + 0.07, y + 0.46, z, 0.14, 0.09, 0.004, hex(0xd8262a));
  k.box(x + 0.07, y + 0.499, z, 0.05, 0.012, 0.006, WHITE);
  k.box(x + 0.07, y + 0.48, z, 0.012, 0.05, 0.006, WHITE);
}

// ---- the flower clock ---------------------------------------------------------------------------

const flowerClock: Draw = (k, W, D, b, r) => {
  // the lawn, the sloped bed, the face planted in rings of flowers, the twelve marks in white
  k.box(0, 0, 0, W - 0.04, 0.012, D - 0.04, hex(0x6aa04a));
  const cx = 0, cz = -0.05, R = 0.42;
  k.cyl(cx, 0.012, cz, R + 0.04, 0.05, hex(0x5a8a3e), 16);
  const rings = [0xe2412f, 0xf2c14e, 0xe85a9a, 0x8e5cc7, 0xf4f2ec].map(hex);
  for (let i = 0; i < rings.length; i++) k.cyl(cx, 0.062 + i * 0.002, cz, R * (1 - i * 0.18), 0.002, rings[i], 16);
  for (let i = 0; i < 12; i++) { const a = (i / 12) * TAU; k.box(cx + Math.sin(a) * R * 0.86, 0.074, cz - Math.cos(a) * R * 0.86, 0.04, 0.008, 0.04, WHITE); }
  // its hands, telling the game's hour, and the second sweeping round
  k.spin(cx, 0.08, cz, 'y', 0, (sk) => sk.box(0, 0, -0.12, 0.03, 0.012, 0.26, hex(0x2a2a2e)), 'hour');
  k.spin(cx, 0.092, cz, 'y', 0, (sk) => sk.box(0, 0, -0.17, 0.02, 0.01, 0.36, hex(0x2a2a2e)), 'minute');
  k.cyl(cx, 0.08, cz, 0.025, 0.03, hex(0xd8b048), 8);
  // beds and benches round it, a plane tree
  for (const sx of [-1, 1]) { bench(k, sx * (W / 2 - 0.3), 0.012, D / 2 - 0.2, hex(0x3a5a3a)); planeTree(k, sx * (W / 2 - 0.15), 0.012, -D / 2 + 0.2, 1); }
  k.tagged(Vis.NotWinter, () => { for (let i = 0; i < 3; i++) stroller(k, r, -0.3 + i * 0.3, 0.012, D / 2 - 0.12); });
};

// ---- Chillon ------------------------------------------------------------------------------------

const chillon: Draw = (k, W, D, b, r) => {
  toWater(k, b, W, D, (L, Dp, wy, reach) => {
    const qz = Dp / 2, off = Math.min(0.9, Math.max(0.5, reach - 1.2)), cz = qz + off;
    const stone = hex(0xd8d0bc), stone2 = hex(0xc8bea8), roof = hex(0x8a5a3e), roof2 = hex(0x6e4a34);
    // the rock it stands on, out in the lake
    k.box(0, wy - 0.15, cz, L - 0.3, 0.22, 1.25, hex(0x8a8274));
    k.box(0.05, wy - 0.15, cz + 0.1, L - 0.6, 0.3, 0.9, hex(0x9a9284));
    // the curtain walls round the courts, crenellated, and the covered wooden bridge from the shore
    const y0 = wy + 0.12, wh = 0.45;
    k.box(0, y0, cz, L - 0.5, wh, 1.0, stone);
    for (let i = 0; i < 12; i++) k.box(-L / 2 + 0.3 + i * ((L - 0.6) / 11), y0 + wh, cz + 0.5, 0.06, 0.05, 0.05, stone2);
    for (let i = 0; i < 6; i++) win(k, b, r, -L / 2 + 0.6 + i * ((L - 1.2) / 5), y0 + 0.2, cz + 0.5, 0.06, 0.1, 1);
    k.box(0, y0 + wh, cz, L - 0.5, 0.012, 0.94, roof2);
    k.gable(0, y0 + wh, cz - 0.05, L - 0.55, 0.22, 0.7, roof, stone, false);
    k.box(-L / 2 + 0.4, 0.02, qz - 0.1, 0.3, 0.012, 0.3, STONE);
    k.box(-L / 2 + 0.4, 0.02, (qz + cz - 0.5) / 2 + 0.05, 0.16, 0.012, cz - 0.5 - qz + 0.3, PLANK);
    k.gable(-L / 2 + 0.4, 0.17, (qz + cz - 0.5) / 2 + 0.05, 0.2, 0.08, cz - 0.5 - qz + 0.3, roof2, PLANK, true);
    for (const sd of [-1, 1]) k.box(-L / 2 + 0.4 + sd * 0.08, 0.02, (qz + cz - 0.5) / 2 + 0.05, 0.01, 0.15, cz - 0.5 - qz + 0.3, PLANK);
    // the keep, tall and square under its hip
    const kx = 0.15, kzz = cz - 0.05, kh = 1.05;
    k.box(kx, y0, kzz, 0.42, kh, 0.42, stone2);
    k.box(kx, y0 + kh, kzz, 0.46, 0.06, 0.46, stone);
    k.hip(kx, y0 + kh + 0.06, kzz, 0.5, 0.36, 0.5, roof);
    for (const f of [0.4, 0.75]) win(k, b, r, kx, y0 + kh * f, kzz + 0.21, 0.06, 0.1, 1);
    // the round towers along the lake side and the square ones at the corners, under pointed roofs
    for (const [tx, tz, rr, h] of [[-L / 2 + 0.3, cz + 0.45, 0.13, 0.75], [L / 2 - 0.3, cz + 0.45, 0.13, 0.7], [-L * 0.1, cz + 0.52, 0.11, 0.62], [L * 0.25, cz + 0.52, 0.11, 0.6]] as const) {
      k.cyl(tx, y0, tz, rr, h, stone, 10);
      k.cone(tx, y0 + h, tz, rr + 0.04, 0.32, roof, 10);
    }
    for (const [tx, tz] of [[-L / 2 + 0.3, cz - 0.45], [L / 2 - 0.3, cz - 0.42]] as const) {
      k.box(tx, y0, tz, 0.24, 0.66, 0.24, stone);
      k.hip(tx, y0 + 0.66, tz, 0.28, 0.3, 0.28, roof2);
    }
    k.glowBox(kx, y0 + kh * 0.75, kzz + 0.215, 0.04, 0.06, 0.01, hex(0x3a4a56), ROOMS, WARM_GLOW);
    // on the shore: the path and the visitors
    k.box(0, 0, -0.1, L - 0.06, 0.012, Dp - 0.3, hex(0xd8ccb0));
    k.tagged(Vis.NotWinter, () => { for (let i = 0; i < 4; i++) stroller(k, r, -L / 2 + 0.2 + r() * (L - 0.4), 0.012, -0.2 + r() * 0.3); });
  });
};

// ---- the Como villa -----------------------------------------------------------------------------

const comoVilla: Draw = (k, W, D, b, r) => {
  const wall = styleWall(r), trim = hex(cur.trim), roof = pick(r, cur.roofs), floors = Math.max(2, b.floors);
  toWater(k, b, W, D, (L, Dp, wy, reach) => {
    const qz = Dp / 2, w = Math.min(L - 0.5, 1.3), d = Math.min(Dp - 0.85, 1.0), z = -Dp / 2 + 0.15 + d / 2, H = floors * FLOOR + 0.05;
    const wet = reach < 3 && wy > -2;
    // the house: a stone plinth, the stucco body, quoins and cornice, the low hip with wide eaves
    k.box(0, 0, z, w + 0.04, 0.08, d + 0.04, STONE);
    k.box(0, 0.08, z, w, H - 0.08, d, wall);
    for (const sx of [-1, 1]) k.detail(() => { for (let y = 0.1; y < H - 0.05; y += 0.09) k.box(sx * (w / 2 - 0.02), y, z + d / 2 + 0.004, 0.05, 0.045, 0.006, trim); });
    k.box(0, H, z, w + 0.06, 0.04, d + 0.06, trim);
    k.hip(0, H + 0.04, z, w + 0.24, 0.2, d + 0.24, roof);
    // the loggia on the top floor: three arches open to the lake
    const ly = H - FLOOR + 0.02;
    k.box(0, ly - 0.01, z + d / 2 - 0.02, w * 0.6, FLOOR - 0.04, 0.012, hex(0x5a4a40));
    for (let i = 0; i < 3; i++) archPanel(k, -w * 0.2 + i * w * 0.2, ly, z + d / 2 + 0.003, w * 0.16, FLOOR - 0.06, hex(0x4a3a30));
    k.box(0, ly - 0.01, z + d / 2 + 0.02, w * 0.62, 0.05, 0.04, trim);
    for (let f = 0; f < floors - 1; f++) for (let i = 0; i < 4; i++) win(k, b, r, -w / 2 + 0.18 + i * ((w - 0.36) / 3), 0.12 + f * FLOOR, z + d / 2, 0.1, 0.15, 1);
    for (let f = 0; f < floors; f++) for (const sd of [0, 2]) win(k, b, r, sd === 0 ? w / 2 : -w / 2, 0.12 + f * FLOOR, z, 0.1, 0.14, sd);
    // the terrace in front: balustrade, urns of lemons, a pair of cypress, a palm
    const tz = (z + d / 2 + qz) / 2;
    k.box(0, 0, tz, L - 0.1, 0.03, qz - z - d / 2 - 0.02, hex(0xe0d4bc));
    for (let i = 0; i <= 10; i++) k.cyl(-L / 2 + 0.08 + ((L - 0.16) * i) / 10, 0.03, qz - 0.06, 0.012, 0.07, WHITE, 4);
    k.box(0, 0.1, qz - 0.06, L - 0.12, 0.015, 0.035, WHITE);
    for (const sx of [-1, 1]) {
      k.cyl(sx * (L / 2 - 0.12), 0.115, qz - 0.06, 0.03, 0.04, hex(0xc8784a), 6);
      k.dome(sx * (L / 2 - 0.12), 0.155, qz - 0.06, 0.035, hex(0x4f8a3e), 6, 2);
      cypress(k, sx * (w / 2 + 0.15), 0.03, z + d / 2 - 0.05, 0.85);
    }
    if (r() < 0.5) lakePalm(k, -L / 2 + 0.2, 0.03, z - d / 2 + 0.1, 0.5, r);
    // the lake below: a stair down and the family's launch at its foot
    if (wet) {
      const px = L / 2 - 0.35;
      for (let i = 0; i < 5; i++) k.box(px, wy - 0.02, qz + 0.03 + i * 0.06, 0.24, (-wy + 0.02) * (1 - i / 5), 0.06, STONE_DARK);
      for (let s = 0; s < 4; s++) k.cyl(px - 0.2, wy - 0.05 + s * 0.08, qz + 0.5, 0.014, 0.08, s % 2 ? WHITE : hex(0x2a5aa8), 5);
      k.turned(Math.PI / 2, () => riva(k, -(qz + 0.45), wy, px + 0.05, 1));
    }
    k.glowBox(0, ly + 0.08, z + d / 2 + 0.03, 0.03, 0.03, 0.03, hex(0xf2ead6), LAMPS, WARM_GLOW);
  });
};

// ---- the villa gardens --------------------------------------------------------------------------

const villaGarden: Draw = (k, W, D, b, r) => {
  toWater(k, b, W, D, (L, Dp, wy, reach) => {
    const qz = Dp / 2, steps = 3, deep = Dp / steps;
    // the terraces, each a step up from the one below it, from the landing at the water to the villa's at the back
    for (let i = 0; i < steps; i++) {
      const tz = qz - deep * (i + 0.5), ty = i * 0.1;
      k.box(0, 0, tz, L - 0.04, ty + 0.03, deep, hex(0xd8ccb0));
      k.box(0, ty + 0.03, tz, L - 0.3, 0.004, deep - 0.2, hex(0x6aa04a));
      // its balustrade along the edge over the terrace below
      for (let j = 0; j <= 12; j++) k.cyl(-L / 2 + 0.06 + ((L - 0.12) * j) / 12, ty + 0.03, tz + deep / 2 - 0.03, 0.01, 0.06, WHITE, 4);
      k.box(0, ty + 0.09, tz + deep / 2 - 0.03, L - 0.1, 0.012, 0.03, WHITE);
      // beds of azaleas and rhododendrons, pink, red and white, and a row of cypress
      for (let j = 0; j < 7; j++) {
        const bx = -L / 2 + 0.3 + (j * (L - 0.6)) / 6;
        k.dome(bx, ty + 0.034, tz - 0.02, 0.07, pick(r, [0xe85a9a, 0xe2412f, 0xf4f2ec, 0xd84a7a, 0xf2a0c0]), 6, 2);
      }
      if (i > 0) for (const sx of [-1, 1]) cypress(k, sx * (L / 2 - 0.1), ty + 0.03, tz, 0.75 + i * 0.1);
    }
    // the stair up the middle through the terraces
    for (let i = 0; i < steps * 2; i++) k.box(0, 0, qz - 0.1 - i * (deep / 2), 0.26, 0.03 + Math.floor(i / 2) * 0.1 + 0.02, deep / 2, hex(0xe8e0cc));
    // the villa on the top terrace: Carlotta's white front, its clock pediment, the balustraded roof
    const vy = (steps - 1) * 0.1 + 0.03, vz = -Dp / 2 + 0.28, vw = Math.min(1.4, L - 0.8);
    k.box(0, vy, vz, vw, FLOOR * 3, 0.42, hex(0xf2ece0));
    for (let f = 0; f < 3; f++) for (let i = 0; i < 5; i++) win(k, b, r, -vw / 2 + 0.16 + i * ((vw - 0.32) / 4), vy + 0.06 + f * FLOOR, vz + 0.21, 0.09, 0.15, 1);
    k.box(0, vy + FLOOR * 3, vz, vw + 0.04, 0.04, 0.46, WHITE);
    for (let i = 0; i <= 12; i++) k.cyl(-vw / 2 + (vw * i) / 12, vy + FLOOR * 3 + 0.04, vz + 0.2, 0.01, 0.05, WHITE, 4);
    k.box(0, vy + FLOOR * 3 + 0.04, vz + 0.04, 0.3, 0.12, 0.3, hex(0xf2ece0));
    k.face(0, vy + FLOOR * 3 + 0.11, vz + 0.191, 0.04, hex(0x2a2a2e), 10);
    // the loggia on the point (Balbianello's): three arches over the lake, a statue on its parapet
    const lx = L / 2 - 0.45, lz = qz - 0.3;
    k.box(lx, 0.03, lz, 0.6, 0.02, 0.36, STONE);
    for (const sx of [-0.27, -0.09, 0.09, 0.27]) k.cyl(lx + sx, 0.05, lz, 0.018, 0.26, WHITE, 6);
    k.box(lx, 0.31, lz, 0.64, 0.05, 0.38, hex(0xf2ece0));
    k.hip(lx, 0.36, lz, 0.68, 0.1, 0.42, hex(0xb85a36));
    // the landing at the foot of the gardens, its iron gate, the launch tied up
    if (reach < 4) {
      k.box(-L / 2 + 0.5, wy - 0.03, qz + 0.12, 0.6, -wy + 0.03, 0.2, STONE_DARK);
      for (const sx of [-0.12, 0.12]) k.box(-L / 2 + 0.5 + sx, 0.03, qz - 0.05, 0.03, 0.2, 0.03, STONE);
      k.box(-L / 2 + 0.5, 0.03, qz - 0.05, 0.21, 0.16, 0.006, IRON);
      k.turned(Math.PI / 2, () => riva(k, -(qz + 0.4), wy, -L / 2 + 0.5, 1));
    }
    k.tagged(Vis.NotWinter, () => { for (let i = 0; i < 4; i++) stroller(k, r, -L / 2 + 0.3 + r() * (L - 0.6), 0.03 + Math.floor(r() * steps) * 0.1, qz - 0.2 - Math.floor(r() * steps) * deep); });
    for (const sx of [-1, 1]) lakeLamp(k, 'como', sx * 0.18, 0.03, qz - 0.12);
  });
};

// ---- the lakeside church ------------------------------------------------------------------------

const lakeChurch: Draw = (k, W, D, b, r) => {
  const stone = hex(0xb8b0a0), stone2 = hex(0xa49c8c), band = hex(0xe8e2d4), roof = hex(0xa85a3a);
  const w = Math.min(W - 0.4, 1.2), d = D - 0.6, z = -0.15, H = 0.9;
  // the nave, banded grey and white, its gable front to the square
  k.box(0, 0, z, w, H, d, stone);
  k.detail(() => { for (let y = 0.15; y < H; y += 0.18) k.box(0, y, z + d / 2 + 0.003, w, 0.03, 0.004, band); });
  k.gable(0, H, z, w + 0.06, 0.34, d + 0.06, roof, stone, true);
  // the door under its round arch and porch, the rose window, the little arcade under the eaves
  archPanel(k, 0, 0, z + d / 2 + 0.006, 0.22, 0.34, hex(0x4a3a2c));
  archPanel(k, 0, 0, z + d / 2 + 0.003, 0.3, 0.4, stone2);
  k.box(0, 0.4, z + d / 2 + 0.06, 0.36, 0.03, 0.12, stone2);
  k.face(0, H - 0.05, z + d / 2 + 0.006, 0.1, stone2, 12);
  k.face(0, H - 0.05, z + d / 2 + 0.01, 0.075, hex(0x8a3a5a), 12);
  for (let i = 0; i < 8; i++) archPanel(k, -w / 2 + 0.08 + i * ((w - 0.16) / 7), H + 0.02, z + d / 2 + 0.008, 0.07, 0.08, stone2);
  for (let i = 0; i < 4; i++) for (const sd of [0, 2]) {
    const zz = z - d / 2 + 0.3 + i * ((d - 0.6) / 3);
    win(k, b, r, sd === 0 ? w / 2 : -w / 2, 0.45, zz, 0.07, 0.22, sd);
  }
  // the campanile beside it, tall and square, its belfry open on every side, the pyramid on top and the cross
  const tx = w / 2 + 0.22, tz = z - d / 2 + 0.3, tw = 0.36, th = 1.75;
  k.box(tx, 0, tz, tw, th, tw, stone2);
  k.detail(() => { for (let y = 0.3; y < th; y += 0.3) k.box(tx, y, tz + tw / 2 + 0.003, tw, 0.025, 0.004, band); });
  for (let f = 0; f < 4; f++) {
    const a = (f * Math.PI) / 2;
    k.turned(a, () => { const lx = tx * Math.cos(a) - tz * Math.sin(a), lz = tx * Math.sin(a) + tz * Math.cos(a); archPanel(k, lx - 0.07, th - 0.3, lz + tw / 2 + 0.004, 0.1, 0.2, hex(0x2a2420)); archPanel(k, lx + 0.07, th - 0.3, lz + tw / 2 + 0.004, 0.1, 0.2, hex(0x2a2420)); });
  }
  k.box(tx, th, tz, tw + 0.04, 0.04, tw + 0.04, band);
  k.hip(tx, th + 0.04, tz, tw + 0.04, 0.42, tw + 0.04, roof);
  k.box(tx, th + 0.46, tz, 0.012, 0.12, 0.012, IRON);
  k.box(tx, th + 0.53, tz, 0.06, 0.012, 0.012, IRON);
  k.face(tx, th - 0.55, tz + tw / 2 + 0.004, 0.08, WHITE, 12);
  // the sagrato in front: paving, a cypress, the war memorial's column
  k.box(0, 0, D / 2 - 0.2, W - 0.1, 0.012, 0.36, hex(0xd8d0bc));
  cypress(k, -w / 2 - 0.15, 0.012, z + d / 2 - 0.05, 0.9);
  k.cyl(-w / 2 - 0.15, 0, D / 2 - 0.2, 0.03, 0.3, STONE, 6);
  k.glowBox(0, 0.42, z + d / 2 + 0.05, 0.03, 0.04, 0.03, hex(0xf2ead6), LAMPS, WARM_GLOW);
};

export const LAKE_LANDMARK_DRAW: Record<Extract<LakeKind, 'amusementPark' | 'jetDeau' | 'flowerClock' | 'chillon' | 'comoVilla' | 'villaGarden' | 'lakeChurch'>, Draw> = {
  amusementPark, jetDeau, flowerClock, chillon, comoVilla, villaGarden, lakeChurch,
};

