import { TRACK, TRACK_DONE, type Missions } from './missions/missions';

/**
 * Getting started, after the first drive (1 Oct 2026). The first drive teaches the car (a delivery and
 * nitrous, the handbrake and a drift: game/tutorial.ts); this carries on to the fleet, one locked mission
 * at a time, each offered when the player next stops:
 *
 *   first:car   own a second vehicle, bought at a dealer or won (Bram's Spare Wheels)
 *   first:crew  a hired driver out on the road in it (the starting house's one slot)
 *   first:hq    upgrade the HQ to a level 2 building, two slots (a new fleet starts owning its house, a
 *               level 1 HQ: game/firstStart.ts, 14 Oct 2026)
 *
 * A step the player has already made is passed over without a card. While the track lasts, one of the
 * player's two mission slots is kept for it (missions/wire.ts `activeCap`). At the end, a card: you have
 * a fleet, now grow it.
 */
interface FleetTrackHost {
  ms: Missions;
  /** A card, the journal or a menu is up: nothing new is put in front of it. */
  busy(): boolean;
  /** The fleet's HQ slots (0 without one), vehicles owned, and vehicles out with a hired driver. */
  hqSlots(): number;
  units(): number;
  driversOut(): number;
  /** The track is done: the "you have a fleet" card. */
  congrats(): void;
  /** The first drive is free to roam while the handbrake waits (game/tutorial.ts roaming): the track runs meanwhile. */
  roaming(): boolean;
}

/**
 * Seconds the HQ step waits once it is next (the user, 7 Nov 2026: two minutes later than it came), and since the
 * handbrake waits for a level 2 HQ, the track no longer waits for the whole first drive to be over.
 */
const HQ_DELAY = 120;

/** The track's last step is done when a hired driver is out on the road in one of the player's vehicles. */
export class FleetTrack {
  private wait = 0;
  /** Seconds of play this visit, and when the HQ step became next (-1: not yet). */
  private clock = 0;
  private hqFrom = -1;

  constructor(private host: FleetTrackHost) {}

  /** Has the player already done what step `id` asks? */
  private met(id: string): boolean {
    const h = this.host;
    if (id === 'first:hq') return h.hqSlots() >= 2;
    if (id === 'first:car') return h.units() >= 2;
    return h.driversOut() >= 1;
  }

  /** Once a second: begin the track after the first drive, offer its next step, or end it. */
  update(dt: number): void {
    const ms = this.host.ms;
    this.clock += dt;
    // during the first drive only while it roams before the handbrake (which now waits for the HQ step's level 2 HQ)
    if (ms.trackStep >= TRACK_DONE || (ms.intro > 0 && !this.host.roaming())) return;
    this.wait -= dt;
    if (this.wait > 0) return;
    this.wait = 1;
    if (this.host.busy()) return;
    if (ms.trackStep === 0) {
      // only after a first drive (a save from before the track has missions done, so it begins too)
      if (!ms.done.size) return;
      // a fleet already past every step (a save from before the track) is not taken back through it
      if (TRACK.every((id) => this.met(id))) { ms.trackStep = TRACK_DONE; return; }
      ms.trackStep = 1;
    }
    for (let k = ms.trackStep - 1; k < TRACK.length; k++) {
      const id = TRACK[k];
      const m = ms.list.find((q) => q.tpl === id && (q.state === 'offered' || q.state === 'active' || q.state === 'done'));
      if (ms.done.has(id) || m?.state === 'done') { ms.trackStep = k + 2; continue; }
      if (m) { ms.trackStep = k + 1; return; }
      if (this.met(id)) { ms.trackStep = k + 2; continue; }
      if (id === 'first:hq') {
        if (this.hqFrom < 0) this.hqFrom = this.clock;
        if (this.clock - this.hqFrom < HQ_DELAY) { ms.trackStep = k + 1; return; }
      }
      ms.force(id);
      const f = ms.list.find((q) => q.tpl === id && q.state === 'offered');
      // offered on its card the next time the player stops (Missions.maybeOffer)
      if (f) f.shown = false;
      ms.trackStep = k + 1;
      return;
    }
    // the "you have a fleet" card waits for the first drive to be over: it takes the tutorial's own card
    if (ms.intro > 0) return;
    ms.trackStep = TRACK_DONE;
    this.host.congrats();
  }
}
