import { hex, scale, type RGB } from '../../world/biomes';
import type { Building, Town, World } from '../../world/tiles';
import { hashString } from '../../world/rng';
import { tavernName } from '../../world/storefronts';
import type { Sched } from '../nightLights';
import { DARK, NEON_HOURS, type Kit, type P3 } from './kit';

/**
 * Neon and bulbs for the old-school places to go out (render/buildings/showbiz.ts, chicago.ts): a name
 * spelled down a vertical blade sign, letters standing on a rack over a roof, a fascia lettered across a
 * front, chaser bulbs round a marquee. The letters are the sign atlas's glyphs (signGlyphs.ts) tinted the
 * tube's colour, so they read in colour by day and stand out lit against the dark after it; the tubes and
 * bulbs round them are ordinary glowing boxes on the night schedule, so nothing here is a real light and
 * no shader is ever compiled for it (see the lag-spike notes: a light added or removed recompiles every lit
 * material). A derelict building's signs are dead: no letters, no glow.
 */

/** The colours a neon tube comes in. */
const NEON_TUBES = [0xff3a5a, 0x3ae0ff, 0xffd23a, 0xff7a2a, 0x7aff5a, 0xc05aff, 0xff4fb0, 0xf6f2e8] as const;
/** Bulbs: warm white, lit from dusk until the last show lets out. */
export const BULB = hex(0xfff0b8);
export const BULB_HOURS: Sched = [17, 24.6, 2.2];
/** A sign's dark backing, and a marquee's enamel. */
export const SIGN_BACK = hex(0x22242a), ENAMEL_RED = hex(0xb8262e), ENAMEL_CREAM = hex(0xf2e6c8);

export const tube = (r: () => number): RGB => hex(NEON_TUBES[Math.floor(r() * NEON_TUBES.length)]);

// ---- names ------------------------------------------------------------------------------------------

/** What a picture palace or a playhouse is called, if it is not called after its town. */
const PALACES = [
  'RIALTO', 'ROXY', 'ORPHEUM', 'PALACE', 'REGENT', 'ODEON', 'LYRIC', 'STRAND', 'EMPIRE', 'CAPITOL', 'MAJESTIC', 'ALHAMBRA',
  'BIJOU', 'GRAND', 'ROYAL', 'TIVOLI', 'APOLLO', 'AVALON', 'ORIENTAL', 'UPTOWN', 'RITZ', 'STATE', 'VOGUE', 'COLONIAL',
  'GRANADA', 'PLAZA', 'ROYALE', 'AZTEC', 'BEACON', 'CAMEO', 'COMET', 'DREAM', 'ELGIN', 'GAIETY', 'IMPERIAL', 'LIDO',
  'METRO', 'MOROCCO', 'NOVA', 'OPERA', 'PARADISE', 'PRINCE', 'REX', 'RIVIERA', 'SAVOY', 'STAR', 'TOWER', 'VARSITY', 'VICTORIA',
];
const DINERS = [
  'DINER', 'EAT', 'STARLITE', 'MOONBEAM', 'COMET', 'BLUEBIRD', "JOE'S", "MEL'S", "LULU'S", 'SILVER', 'ROCKET', 'JUKEBOX',
  'SKYLINE', 'ROUTE 9', 'ATOMIC', "DOT'S", 'MILLIE', 'FLYER', 'ORBIT', 'SUNRISE', 'HI-WAY', 'CHROME', 'STARDUST', 'EL RANCHO',
];
const BARS = [
  'BAR', 'LOUNGE', 'COCKTAILS', 'TAVERN', 'TAPROOM', 'BLUE NOTE', 'GOLD STAR', 'THE OWL', 'RED ROOM', 'NIGHTCAP', 'TIKI', 'MARTINI',
  'HIDEOUT', 'GREEN MILL', 'VELVET', 'LUCKY 7', 'ALIBI', 'NEON', 'SPEAKEASY', 'BOURBON', 'JAZZ', 'HIGHBALL', 'RUMBA', 'STARDUST',
];

/** A name trimmed to what fits on a sign: capitals, digits and the few marks the atlas has. */
function signText(s: string): string {
  return s.toUpperCase().replace(/[ÀÁÂÃÄÅ]/g, 'A').replace(/[ÈÉÊË]/g, 'E').replace(/[ÌÍÎÏ]/g, 'I').replace(/[ÒÓÔÕÖ]/g, 'O')
    .replace(/[ÙÚÛÜ]/g, 'U').replace(/Ñ/g, 'N').replace(/Ç/g, 'C').replace(/[^A-Z0-9&'.!\- ]/g, '').replace(/\s+/g, ' ').trim();
}

/** A town's name as its palace would spell it: "Tomato City" → TOMATO, or null if it is too long for a sign. */
function townWord(t: Town | null, most: number): string | null {
  if (!t) return null;
  const word = signText(t.name.replace(/\b(City|Town|Falls|Heights|Springs|Junction|Bay|Harbour|Port|On Sea)\b/gi, ''));
  return word.length >= 3 && word.length <= most && !word.includes(' ') ? word : null;
}

/**
 * The name over a place's door, always the same for the same building: a picture palace or a playhouse
 * often called after its town (as the Chicago is), a diner after its owner or the space age, a bar after
 * its tavern name if it is the county's tavern (world/storefronts.ts), else one of its sort's.
 */
export function venueName(b: Building, t: Town | null, sort: 'palace' | 'diner' | 'bar', most = 9, w?: World): string {
  const h = hashString(`venue|${b.kind}|${b.x},${b.z}|${b.seed}`);
  if (sort === 'palace') {
    const own = h % 4 === 0 ? townWord(t, most) : null;
    if (own) return own;
    const pool = PALACES.filter((n) => n.length <= most);
    return pool[(h >>> 3) % pool.length];
  }
  if (sort === 'bar' && b.storefront === 'tavern' && t && w) {
    // "The Crooked Lantern" over the door: the words that fit, without the article
    const words = signText(tavernName(w.seed, w, b, t)).replace(/^THE /, '').split(' ');
    let out = '';
    for (const wd of words) if ((out ? out.length + 1 : 0) + wd.length <= most) out = out ? `${out} ${wd}` : wd;
    if (out.length >= 3) return out;
  }
  const pool = (sort === 'diner' ? DINERS : BARS).filter((n) => n.length <= most);
  return pool[(h >>> 3) % pool.length];
}

// ---- letters ----------------------------------------------------------------------------------------

/**
 * Letters in a row on a face, read left to right: `at` the middle of the row's baseline, `right` the unit
 * direction (in the local x-z plane) a reader's right hand points, `h` the letter height. Spaces are gaps.
 * Returns the row's width.
 */
export function letters(k: Kit, text: string, at: P3, right: [number, number], h: number, col: RGB, cell = 0.66): number {
  if (k.mode === 'derelict') return 0;
  const chars = [...text], cw = h * cell, total = chars.length * cw;
  const [rx, rz] = right;
  for (let i = 0; i < chars.length; i++) {
    const ch = chars[i];
    if (ch === ' ') continue;
    const u0 = -total / 2 + i * cw, u1 = u0 + cw;
    const a: P3 = [at[0] + rx * u0, at[1], at[2] + rz * u0], b: P3 = [at[0] + rx * u1, at[1], at[2] + rz * u1];
    k.glyph(ch, a, b, [b[0], at[1] + h, b[2]], [a[0], at[1] + h, a[2]], col);
  }
  return total;
}

/**
 * A row of letters across a front facing +z at depth z, centred on x, standing on y: a fascia, a marquee's
 * name panel, a lettered parapet. Width is fixed by the height; returns it.
 */
export function frontText(k: Kit, text: string, x: number, y: number, z: number, h: number, col: RGB, cell = 0.66): number {
  return letters(k, text, [x, y, z + 0.003], [1, 0], h, col, cell);
}

/**
 * A vertical blade sign standing straight out from a front (the plane x = `x`, from the wall at z = `z` out
 * to z + `out`), the name spelled top to bottom on both faces, a tube outlining each face and a crown on
 * top: the Chicago's sign, the Rialto's, every picture palace's. `y0` is its foot; returns its top.
 */
export function bladeName(
  k: Kit, text: string, x: number, y0: number, z: number, out: number, cellH: number, back: RGB, letter: RGB, edge: RGB,
  opts: { bulbs?: boolean; crown?: 'fan' | 'star' | 'none'; thick?: number } = {},
): number {
  const chars = [...text.replace(/ /g, '')];
  const n = chars.length, pad = cellH * 0.35, h = n * cellH + pad * 2, t = opts.thick ?? 0.05;
  const zc = z + out / 2, y1 = y0 + h;
  // the steel arms that hold it off the wall, and the blade itself
  k.box(x, y0 + h * 0.2, z + 0.02, t * 0.5, 0.025, 0.04, DARK);
  k.box(x, y0 + h * 0.8, z + 0.02, t * 0.5, 0.025, 0.04, DARK);
  k.box(x, y0, zc, t, h, out, back);
  if (k.mode !== 'derelict') {
    // the tube round both faces: top and bottom rails, the outer edge (the wall edge stays dark)
    const g = 0.014;
    for (const sx of [1, -1]) {
      const fx = x + sx * (t / 2 + g / 2);
      k.glowBox(fx, y0 + 0.01, zc, g, g, out - 0.04, scale(edge, 0.6), NEON_HOURS, edge);
      k.glowBox(fx, y1 - 0.01 - g, zc, g, g, out - 0.04, scale(edge, 0.6), NEON_HOURS, edge);
    }
    k.glowBox(x, y0 + 0.01, z + out - 0.008, t + 0.03, h - 0.02, g, scale(edge, 0.6), NEON_HOURS, edge);
    if (opts.bulbs) {
      // bulbs down the outer edge, both faces
      const nb = Math.max(4, Math.round(h / 0.09));
      bulbRow(k, [x, y0 + 0.04, z + out - 0.03], [x, y1 - 0.04, z + out - 0.03], nb, BULB, BULB_HOURS, 'x', t / 2 + 0.006);
    }
    // the letters, one a cell from the top down, on each face, read from outside that face
    const za = z + out * 0.14, zb = z + out * 0.86, size = Math.min(cellH * 0.86, zb - za);
    for (let i = 0; i < n; i++) {
      const top = y1 - pad - i * cellH, yb = top - cellH + (cellH - size) / 2, yt = yb + size;
      const zm = (za + zb) / 2, hw = size * 0.42;
      for (const sx of [1, -1]) {
        const fx = x + sx * (t / 2 + 0.004);
        const [zl, zr] = sx > 0 ? [zm + hw, zm - hw] : [zm - hw, zm + hw];
        k.glyph(chars[i], [fx, yb, zl], [fx, yb, zr], [fx, yt, zr], [fx, yt, zl], letter);
      }
    }
  }
  // the crown: a fan of rays or a star over the top
  let top = y1;
  if (opts.crown === 'fan') {
    for (let i = 0; i < 5; i++) {
      const a = Math.PI * (0.15 + 0.7 * (i / 4)), L = out * 0.55;
      k.bar([x, y1, zc], [x, y1 + Math.sin(a) * L, zc + Math.cos(a) * L], 0.012, back);
      if (k.mode !== 'derelict') k.glowBox(x, y1 + Math.sin(a) * L - 0.015, zc + Math.cos(a) * L, 0.03, 0.03, 0.03, edge, NEON_HOURS, edge);
    }
    top = y1 + out * 0.55;
  } else if (opts.crown === 'star') {
    k.box(x, y1, zc, t, 0.06, out * 0.3, back);
    if (k.mode !== 'derelict') k.glowBox(x, y1 + 0.06, zc, 0.05, 0.12, 0.12, edge, NEON_HOURS, edge);
    top = y1 + 0.18;
  }
  return top;
}

/**
 * A name on a rack standing over a roof, facing +z: a dark board, the letters on it in neon, a tube along
 * its top and foot, two legs down to the roof at y.
 */
export function roofName(k: Kit, text: string, x: number, y: number, z: number, h: number, letter: RGB, edge: RGB, legs = 0.08): number {
  const w = [...text].length * h * 0.66 + h * 0.5;
  for (const sx of [-0.38, 0.38]) k.box(x + sx * w, y, z - 0.02, 0.025, legs + 0.02, 0.025, DARK);
  k.box(x, y + legs, z - 0.02, w, h * 1.3, 0.02, SIGN_BACK);
  frontText(k, text, x, y + legs + h * 0.15, z - 0.008, h, letter);
  if (k.mode !== 'derelict') {
    k.glowBox(x, y + legs - 0.004, z - 0.006, w, 0.014, 0.014, scale(edge, 0.6), NEON_HOURS, edge);
    k.glowBox(x, y + legs + h * 1.3 - 0.01, z - 0.006, w, 0.014, 0.014, scale(edge, 0.6), NEON_HOURS, edge);
  }
  return w;
}

/**
 * A row of bulbs from a to b, each its own little lamp, coming on in a ripple at dusk. `face` 'z' draws each
 * as one square facing +z (a marquee's front: two triangles a bulb rather than ten), 'x' as a square on
 * each side of a blade.
 */
export function bulbRow(k: Kit, a: P3, b: P3, n: number, col: RGB = BULB, s: Sched = BULB_HOURS, face: 'box' | 'z' | 'x' = 'box', spread = 0.011): void {
  if (k.mode === 'derelict' || n < 1) return;
  const h = 0.011;
  for (let i = 0; i < n; i++) {
    const f = n === 1 ? 0.5 : i / (n - 1);
    const x = a[0] + (b[0] - a[0]) * f, y = a[1] + (b[1] - a[1]) * f, z = a[2] + (b[2] - a[2]) * f;
    const sc: Sched = [s[0] + (i % 3) * 0.03, s[1] + (i % 2) * 0.05, s[2]];
    if (face === 'z') k.glowQuad([x - h, y - h, z], [x + h, y - h, z], [x + h, y + h, z], [x - h, y + h, z], [x, y, z - 0.05], col, sc, col);
    else if (face === 'x') {
      for (const sx of [1, -1]) {
        const fx = x + sx * spread;
        k.glowQuad([fx, y - h, z - h], [fx, y - h, z + h], [fx, y + h, z + h], [fx, y + h, z - h], [x, y, z], col, sc, col);
      }
    } else k.glowBox(x, y - h, z, 0.022, 0.022, 0.022, col, sc, col);
  }
}

/** A neon tube along a straight run: a thin glowing box from a to b (axis-aligned runs only). */
export function tubeRun(k: Kit, a: P3, b: P3, col: RGB, g = 0.014): void {
  if (k.mode === 'derelict') return;
  const w = Math.abs(b[0] - a[0]) || g, h = Math.abs(b[1] - a[1]) || g, d = Math.abs(b[2] - a[2]) || g;
  k.glowBox((a[0] + b[0]) / 2, Math.min(a[1], b[1]), (a[2] + b[2]) / 2, w, h, d, scale(col, 0.6), NEON_HOURS, col);
}

// ---- marquees ---------------------------------------------------------------------------------------

/**
 * Where a marquee's letter board stands, in the building's own frame (front +z): the middle of the board's
 * face, its size, and which way it faces (a yaw about y; 0 faces +z). The model draws a lit white board
 * there; game/screens.ts lays the day's titles over it, so what is playing changes every morning.
 */
export interface BoardSpot { x: number; y: number; z: number; w: number; h: number; yaw: number }

/** The lit board a marquee's letters are hung on (the titles themselves are laid over it at run time). */
export function board(k: Kit, s: BoardSpot, frame: RGB): void {
  k.turned(s.yaw, () => {
    // rotate the spot's centre into the turned frame: local (x, z) of a point p after a turn of yaw
    const c = Math.cos(s.yaw), sn = Math.sin(s.yaw);
    const lx = s.x * c - s.z * sn, lz = s.x * sn + s.z * c;
    k.box(lx, s.y - s.h / 2 - 0.02, lz - 0.012, s.w + 0.04, s.h + 0.04, 0.02, frame);
    k.glowBox(lx, s.y - s.h / 2, lz - 0.004, s.w, s.h, 0.008, ENAMEL_CREAM, [16.8, 25, 1.25], hex(0xfff6dc));
  });
}

/**
 * A marquee box over a front: a slab on the wall at y (its underside) and `d` deep, its fascia lettered
 * boards on the front and both ends (the spots given back for the titles), bulbs chasing round its edges and
 * a row of lights under its soffit over the pavement.
 */
export function marquee(k: Kit, x: number, y: number, z: number, w: number, h: number, d: number, frame: RGB, bulbs = true): BoardSpot[] {
  k.box(x, y, z + d / 2, w, h, d, frame);
  k.box(x, y + h, z + d / 2, w + 0.02, 0.02, d + 0.02, scale(frame, 0.8));
  const spots = marqueeBoards(x, y, z, w, h, d);
  for (const s of spots) board(k, s, frame);
  if (bulbs) {
    const n = Math.max(6, Math.round(w / 0.1));
    bulbRow(k, [x - w / 2, y + h - 0.012, z + d + 0.004], [x + w / 2, y + h - 0.012, z + d + 0.004], n, BULB, BULB_HOURS, 'z');
    bulbRow(k, [x - w / 2, y + 0.014, z + d + 0.004], [x + w / 2, y + 0.014, z + d + 0.004], n, BULB, BULB_HOURS, 'z');
  }
  // the soffit lights over the pavement
  if (k.mode !== 'derelict') k.glowBox(x, y - 0.012, z + d / 2, w - 0.06, 0.012, d - 0.06, BULB, BULB_HOURS, hex(0xffe8b0));
  return spots;
}

/** The letter boards of a marquee() with these measurements: its front, and its two ends when it is deep enough. */
export function marqueeBoards(x: number, y: number, z: number, w: number, h: number, d: number): BoardSpot[] {
  const bh = h * 0.62, by = y + h / 2;
  const spots: BoardSpot[] = [{ x, y: by, z: z + d + 0.001, w: w - 0.1, h: bh, yaw: 0 }];
  if (d >= 0.18) {
    spots.push({ x: x + w / 2 + 0.001, y: by, z: z + d / 2, w: d - 0.06, h: bh, yaw: Math.PI / 2 });
    spots.push({ x: x - w / 2 - 0.001, y: by, z: z + d / 2, w: d - 0.06, h: bh, yaw: -Math.PI / 2 });
  }
  return spots;
}
