import { hex, scale, type RGB } from '../../world/biomes';
import { FLOOR } from '../../world/towns';
import type { ThemeKind } from '../../world/tiles';
import type { Rng } from '../../world/rng';
import type { Sched } from '../nightLights';
import { COOL_GLOW, DARK, GLASS_LIGHT, METAL, NEON_HOURS, SHOP_GLOW, TAU, TRUNK, TV_GLOW, WARM_GLOW, WHITE, WOOD, type Draw, type Kit, type P3, type RigTick } from './kit';
import { BULB, BULB_HOURS, bulbRow, letters } from './neon';

/**
 * The signature landmarks of four town styles, each in a fixed palette of its own and standing on its lot
 * centred on the origin, its front to +z:
 *
 * - Hong Kong: the bank tower of four triangular shafts, and the walled city.
 * - Las Vegas: the black pyramid and its beam, the welcome sign, the needle tower, the resort on its lake, the Sphere.
 * - The Gulf: the supertall and the sail hotel.
 * - The Mother Road: the neon motor court, the wigwam motel and the twin arrows.
 */

type XZ = [number, number];

const EVENING: Sched = [18, 23.5, 1.4], ALL_NIGHT: Sched = [0, 36, 1.5], BEACON: Sched = [0, 36, 2.8], DARK_PANE: Sched = [99, 0, 0];
const RED_LAMP = hex(0xe2412f), RED_GLOW = hex(0xff4a3a);
const SAND = hex(0xe2cfa0), PALM = hex(0x4a9a4a), ASPHALT = hex(0x55575c), GRASS = hex(0x5fae4e), CYPRESS = hex(0x2f5a3a);
const PINK = hex(0xff4f9a), TURQ = hex(0x2ed8d0), NEON_YELLOW = hex(0xffd84a);

/** Where to draw, inside `k.turned(yaw)`, a part that should land at (X, Z) in the frame outside it. */
const into = (yaw: number, X: number, Z: number): XZ => [X * Math.cos(yaw) - Z * Math.sin(yaw), X * Math.sin(yaw) + Z * Math.cos(yaw)];

/** A four-sided tapering block from w0×d0 at y0 to w1×d1 at y1, capped if it is given a top. */
function frustum(k: Kit, x: number, z: number, y0: number, w0: number, d0: number, y1: number, w1: number, d1: number, col: RGB, top?: RGB): void {
  const I: P3 = [x, (y0 + y1) / 2, z];
  const c: XZ[] = [[-1, -1], [1, -1], [1, 1], [-1, 1]];
  const lo = (p: XZ): P3 => [x + (p[0] * w0) / 2, y0, z + (p[1] * d0) / 2], hi = (p: XZ): P3 => [x + (p[0] * w1) / 2, y1, z + (p[1] * d1) / 2];
  for (let i = 0; i < 4; i++) k.quad(lo(c[i]), lo(c[(i + 1) % 4]), hi(c[(i + 1) % 4]), hi(c[i]), col, I);
  if (top) k.quad(hi(c[0]), hi(c[1]), hi(c[2]), hi(c[3]), top, I);
}

/** A box standing `dep` proud of a wall that faces `face` (0 +x, 1 +z, 2 -x, 3 -z), `u` along the wall from (x, z). */
function proud(k: Kit, x: number, z: number, face: number, u: number, y: number, w: number, h: number, dep: number, col: RGB, lit?: [Sched, RGB]): void {
  const s = face === 1 || face === 0 ? 1 : -1;
  const [bx, bz, bw, bd] = face === 1 || face === 3 ? [x + u, z + (s * dep) / 2, w, dep] : [x + (s * dep) / 2, z + u, dep, w];
  if (lit) k.glowBox(bx, y, bz, bw, h, bd, col, lit[0], lit[1]);
  else k.box(bx, y, bz, bw, h, bd, col);
}

/** A palm: a leaning trunk and a crown of drooping fronds. */
function palm(k: Kit, x: number, y: number, z: number, h: number, turn = 0): void {
  const tx = x + 0.05, tz = z + 0.02;
  k.bar([x, y, z], [tx, y + h, tz], 0.02, TRUNK);
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * TAU + turn;
    k.bar([tx, y + h, tz], [tx + Math.cos(a) * 0.2, y + h - 0.07, tz + Math.sin(a) * 0.2], 0.026, i % 2 ? PALM : scale(PALM, 0.85));
  }
}

/** One of a short list of colours. */
const among = (r: Rng, cols: readonly RGB[]): RGB => cols[Math.floor(r() * cols.length) % cols.length];

// ================================ Hong Kong ================================

const BANK_GLASS = hex(0x203a5c), BANK_GLASS_HI = hex(0x3e6290), BANK_STONE = hex(0x8a8e94), BANK_BRACE = hex(0xe8eef2);

/**
 * The bank tower: a square of dark blue glass cut on its diagonals into four triangular shafts that stop
 * one after another, so the top climbs to a single point; white cross-bracing in big diamonds up every face.
 */
const bankTower: Draw = (k, W, D, b, r) => {
  const H = Math.max(50, b.floors) * FLOOR, w = Math.min(W, D) - 0.36, h = w / 2, base = 0.5;
  k.box(0, 0, 0, w + 0.18, base, w + 0.18, BANK_STONE, scale(BANK_STONE, 0.9));
  k.glowBox(0, 0.06, h + 0.095, w * 0.4, 0.26, 0.02, hex(0x50647a), EVENING, SHOP_GLOW);
  const corner: XZ[] = [[-h, h], [h, h], [h, -h], [-h, -h]];
  // how high each shaft's outer wall stands: the front one stops first, the back one carries on to the tip
  const stop = [0.36, 0.56, 0.9, 0.75], face = [1, 0, 3, 2];
  const edge = stop.map((s) => base + (H - base) * s);
  for (let i = 0; i < 4; i++) {
    const p = corner[i], q = corner[(i + 1) % 4], top = edge[i], tip = i === 2 ? H : top + H * 0.075;
    const mx = (p[0] + q[0]) / 3, mz = (p[1] + q[1]) / 3, I: P3 = [mx, (base + top) / 2, mz];
    const shade = i % 2 ? BANK_GLASS : scale(BANK_GLASS, 1.12);
    // the shaft's three walls, then its sloping glass roof up to the core
    k.quad([p[0], base, p[1]], [q[0], base, q[1]], [q[0], top, q[1]], [p[0], top, p[1]], shade, I);
    for (const e of [p, q]) k.quad([e[0], base, e[1]], [0, base, 0], [0, top, 0], [e[0], top, e[1]], shade, I);
    const J: P3 = [mx, top - 1, mz];
    k.tri([p[0], top, p[1]], [q[0], top, q[1]], [0, tip, 0], BANK_GLASS_HI, J);
    for (const e of [p, q]) k.tri([e[0], top, e[1]], [0, top, 0], [0, tip, 0], shade, J);
    // the bracing: a cross in every square of the face, standing a little off the glass
    const nx = Math.sign(p[0] + q[0]) * 0.02, nz = Math.sign(p[1] + q[1]) * 0.02;
    const n = Math.max(1, Math.round((top - base) / w)), mh = (top - base) / n;
    for (let m = 0; m < n; m++) {
      const y0 = base + m * mh, y1 = y0 + mh;
      k.bar([p[0] + nx, y0, p[1] + nz], [q[0] + nx, y1, q[1] + nz], 0.024, BANK_BRACE);
      k.bar([q[0] + nx, y0, q[1] + nz], [p[0] + nx, y1, p[1] + nz], 0.024, BANK_BRACE);
    }
    k.bar([p[0] + nx, top, p[1] + nz], [q[0] + nx, top, q[1] + nz], 0.024, BANK_BRACE);
    // a scatter of offices working late
    const fx = (p[0] + q[0]) / 2, fz = (p[1] + q[1]) / 2;
    for (let j = 0; j < 12; j++) {
      const u = (r() - 0.5) * (w - 0.5), y = base + 0.2 + r() * (top - base - 0.6);
      const horiz = face[i] === 1 || face[i] === 3;
      k.pane(horiz ? fx + u : fx, y, horiz ? fz : fz + u, 0.26, 0.14, face[i], scale(BANK_GLASS, 1.2), [17.5 + r() * 2, 23 + r() * 5, 1.1], r() < 0.5 ? COOL_GLOW : WARM_GLOW);
    }
  }
  // the corners, white by day and lines of light after dark, each as high as the taller shaft beside it
  for (let i = 0; i < 4; i++) {
    const c = corner[i], top = Math.max(edge[i], edge[(i + 3) % 4]);
    k.glowBox(c[0] + Math.sign(c[0]) * 0.012, base, c[1] + Math.sign(c[1]) * 0.012, 0.06, top - base, 0.06, BANK_BRACE, ALL_NIGHT, hex(0xdcecff));
  }
  k.glowBox(0, edge[0], 0, 0.05, H - edge[0] - 0.05, 0.05, BANK_BRACE, ALL_NIGHT, hex(0xdcecff));
  // the twin masts
  for (const [s, mh] of [[-1, 2.6], [1, 1.9]] as const) {
    k.cyl(s * 0.07, H - 0.9, -0.16, 0.02, mh + 0.9, WHITE, 6);
    k.glowBox(s * 0.07, H + mh, -0.16, 0.05, 0.05, 0.05, RED_LAMP, BEACON, RED_GLOW);
  }
};

const CITY_WALLS = [0x8e8c84, 0xa49a84, 0x7f8a7a, 0x9a9488, 0xb0a084, 0x76807a, 0x8a8478, 0x6f7670].map(hex);
const CITY_ROOF = hex(0x66645e), CITY_CAGE = [0x5a6a5a, 0x7a5a44, 0x4a5058, 0x6a7a8a].map(hex), CITY_PIPE = hex(0x4a4c4e);
const CITY_CLOTH = [0xd8d4c8, 0xc86a5a, 0x6a8ac0, 0xd8b85a, 0x8ab08a].map(hex), CITY_AC = hex(0xc8c6be);
const CITY_GLOWS = [WARM_GLOW, WARM_GLOW, COOL_GLOW, TV_GLOW, hex(0xc8ffd8), hex(0xffe0a0)];
const CITY_NEON = [0xff2e7a, 0x2ee0ff, 0xffd040, 0x4aff7a, 0xff4030, 0xb060ff].map(hex);

/** One street face of a walled-city tower: shopfront and neon at its foot, then windows, cages, boxes and pipes. */
function crust(k: Kit, r: Rng, x: number, z: number, width: number, h: number, face: number): void {
  const horiz = face === 1 || face === 3;
  proud(k, x, z, face, 0, 0.02, width * 0.92, 0.2, 0.012, hex(0x34363a));
  const c = among(r, CITY_NEON);
  proud(k, x, z, face, (r() - 0.5) * width * 0.2, 0.23, width * (0.45 + r() * 0.4), 0.09, 0.035, scale(c, 0.7), [NEON_HOURS, c]);
  if (r() < 0.6) {
    const c2 = among(r, CITY_NEON);
    proud(k, x, z, face, (r() < 0.5 ? -1 : 1) * width * 0.32, 0.38, 0.04, 0.26 + r() * 0.2, 0.13, scale(c2, 0.7), [NEON_HOURS, c2]);
  }
  const fl = 0.25, cols = 4, cell = width / cols, floors = Math.floor((h - 0.5) / fl);
  for (let f = 0; f < floors; f++) {
    const y = 0.46 + f * fl;
    for (let i = 0; i < cols; i++) {
      const u = -width / 2 + cell * (i + 0.5);
      if (r() < 0.74) {
        const s: Sched = r() < 0.72 ? [17.3 + r() * 2.5, 22 + r() * 8, 1.15] : DARK_PANE;
        k.pane(horiz ? x + u : x, y, horiz ? z : z + u, cell * 0.52, 0.11, face, hex(0x3e4a52), s, among(r, CITY_GLOWS));
      }
      const roll = r();
      if (roll < 0.18) proud(k, x, z, face, u, y - 0.05, cell * 0.78, 0.05, 0.06, among(r, CITY_CAGE));
      else if (roll < 0.33) proud(k, x, z, face, u + cell * 0.3, y - 0.04, 0.055, 0.045, 0.04, CITY_AC);
      else if (roll < 0.43) proud(k, x, z, face, u, y + 0.125, cell * 0.8, 0.035, 0.05, among(r, CITY_CLOTH));
    }
  }
  for (let p = 0; p < 2; p++) proud(k, x, z, face, (r() - 0.5) * width * 0.9, 0.3, 0.02, h - 0.34 - r() * 0.3, 0.02, CITY_PIPE);
}

/**
 * The walled city: sixteen thin towers of different heights jammed into one block with no street between
 * them, every face crusted with caged balconies, air conditioners, washing and pipes; aerials on the roofs.
 */
const walledCity: Draw = (k, W, D, b, r) => {
  const H = Math.max(10, b.floors) * FLOOR, n = 4, cw = (W - 0.24) / n, cd = (D - 0.24) / n;
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    // the outer towers stand back from the street by different amounts, so the front is not one plane
    const x = -W / 2 + 0.12 + cw * (i + 0.5) + (i === 0 ? 1 : i === n - 1 ? -1 : 0) * r() * 0.06;
    const z = -D / 2 + 0.12 + cd * (j + 0.5) + (j === 0 ? 1 : j === n - 1 ? -1 : 0) * r() * 0.06;
    const h = H * (0.8 + r() * 0.36), wall = among(r, CITY_WALLS);
    k.box(x, 0, z, cw + 0.005, h, cd + 0.005, wall, CITY_ROOF);
    if (i === n - 1) crust(k, r, x + cw / 2, z, cd, h, 0);
    if (i === 0) crust(k, r, x - cw / 2, z, cd, h, 2);
    if (j === n - 1) crust(k, r, x, z + cd / 2, cw, h, 1);
    if (j === 0) crust(k, r, x, z - cd / 2, cw, h, 3);
    // the roofscape: a shed or a tank, and the aerials
    if (r() < 0.6) k.box(x + (r() - 0.5) * cw * 0.4, h, z + (r() - 0.5) * cd * 0.4, 0.2, 0.1 + r() * 0.1, 0.16, among(r, CITY_WALLS), scale(CITY_ROOF, 0.85));
    else if (r() < 0.6) k.cyl(x + (r() - 0.5) * cw * 0.4, h, z + (r() - 0.5) * cd * 0.4, 0.07, 0.12, hex(0x5a6a7a), 6);
    for (let a = 0; a < 3; a++) {
      const ax = x + (r() - 0.5) * cw * 0.8, az = z + (r() - 0.5) * cd * 0.8, ah = 0.25 + r() * 0.4;
      k.box(ax, h, az, 0.014, ah, 0.014, DARK);
      k.box(ax, h + ah * 0.8, az, 0.13, 0.012, 0.012, DARK);
      if (a === 0) k.box(ax, h + ah * 0.6, az, 0.012, 0.012, 0.1, DARK);
    }
  }
};

// ================================ Las Vegas ================================

const PYR_A = hex(0x15130f), PYR_B = hex(0x231e17), PYR_EDGE = hex(0xe8d8a0), SPHINX = hex(0xd8b060), SPHINX_BLUE = hex(0x2a4aa8);
const SANDSTONE = hex(0xd0b080);

/**
 * The pyramid casino: black glass on four sides, its edges lit, a beam of light straight up from the tip;
 * a sphinx over the door, an obelisk sign and palms along the drive.
 */
const casinoPyramid: Draw = (k, W, D) => {
  const bw = Math.min(W - 1.2, D - 1.2), z0 = -D / 2 + 0.12 + bw / 2, PH = 2.75, tiers = 9;
  k.box(0, 0, z0, bw + 0.14, 0.03, bw + 0.14, SANDSTONE);
  for (let i = 0; i < tiers; i++) {
    const t0 = i / tiers, t1 = (i + 1) / tiers;
    frustum(k, 0, z0, 0.03 + t0 * PH, bw * (1 - t0), bw * (1 - t0), 0.03 + t1 * PH, bw * (1 - t1), bw * (1 - t1), i % 2 ? PYR_B : PYR_A);
  }
  // bulbs up the four edges, and the beam
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) for (let i = 0; i < 12; i++) {
    const t = (i + 0.5) / 12, e = (bw / 2) * (1 - t) + 0.005;
    k.glowBox(sx * e, 0.03 + t * PH - 0.015, z0 + sz * e, 0.045, 0.045, 0.045, PYR_EDGE, ALL_NIGHT, hex(0xfff0c0));
  }
  k.glowBox(0, PH, z0, 0.06, 7.5, 0.06, hex(0xdfe8f4), [0, 30, 2], hex(0xf4f8ff));
  k.glowBox(0, PH - 0.04, z0, 0.12, 0.1, 0.12, WHITE, [0, 30, 2], hex(0xf4f8ff));
  // the entrance in the front face, and the sphinx lying out from it
  const fz = z0 + bw / 2;
  k.box(0, 0.03, fz - 0.1, 0.9, 0.3, 0.3, PYR_B);
  k.glowBox(0, 0.06, fz + 0.055, 0.6, 0.18, 0.02, hex(0x6a5a3a), EVENING, SHOP_GLOW);
  const sz = fz + 0.12;
  k.box(0, 0, sz + 0.3, 0.5, 0.1, 0.95, SANDSTONE);                       // plinth
  k.box(0, 0.1, sz + 0.2, 0.3, 0.2, 0.62, SPHINX);                        // body
  k.box(0, 0.3, sz + 0.02, 0.26, 0.06, 0.2, SPHINX);                      // haunches
  for (const s of [-1, 1]) k.box(s * 0.11, 0.1, sz + 0.62, 0.08, 0.08, 0.26, SPHINX); // paws
  // the head and its striped headdress, gold and blue
  const hz = sz + 0.46;
  for (let i = 0; i < 5; i++) k.box(0, 0.26 + i * 0.05, hz - 0.03, 0.36 - i * 0.025, 0.05, 0.16, i % 2 ? SPHINX_BLUE : hex(0xe8c040));
  k.box(0, 0.51, hz - 0.03, 0.2, 0.04, 0.14, hex(0xe8c040));
  k.box(0, 0.3, hz + 0.06, 0.15, 0.19, 0.08, SPHINX);                     // face
  k.box(0, 0.24, hz + 0.09, 0.04, 0.07, 0.03, SPHINX_BLUE);               // beard
  for (const s of [-1, 1]) k.glowBox(s * 0.22, 0.1, sz + 0.7, 0.05, 0.03, 0.05, DARK, ALL_NIGHT, WARM_GLOW);
  // the drive across the front
  k.box(0, 0, D / 2 - 0.26, W - 0.2, 0.02, 0.3, ASPHALT);
  // the obelisk sign
  const ox = -W / 2 + 0.55, oz = D / 2 - 0.62;
  k.box(ox, 0, oz, 0.3, 0.08, 0.3, SANDSTONE);
  frustum(k, ox, oz, 0.08, 0.17, 0.17, 1.35, 0.11, 0.11, SANDSTONE);
  k.hip(ox, 1.35, oz, 0.11, 0.14, 0.11, hex(0xe8c040));
  k.glowBox(ox, 0.5, oz + 0.085, 0.09, 0.5, 0.012, hex(0x8a6a2a), NEON_HOURS, hex(0xffc850));
  // palms
  for (const [px, pz, ph] of [[W / 2 - 0.4, D / 2 - 0.65, 0.75], [W / 2 - 0.3, D / 2 - 1.3, 0.62], [-W / 2 + 0.3, D / 2 - 1.3, 0.68], [0.75, D / 2 - 0.62, 0.6], [-0.8, D / 2 - 0.62, 0.66]] as const) {
    palm(k, px, 0, pz, ph, px * 3);
  }
};

const SIGN_BLUE = hex(0x2a5ab8), SIGN_RED = hex(0xd8202a);

/**
 * The welcome sign: a stretched diamond on two posts, seven white discs across the top, a red star above,
 * yellow bulbs chasing round the edge.
 */
const welcomeSign: Draw = (k, W, D) => {
  const z = -D / 2 + 0.3, t = 0.03, zf = z + t, zb = z - t;
  k.box(0, 0, z, W - 0.24, 0.03, 0.4, GRASS);
  for (const s of [-1, 1]) k.box(s * 0.17, 0, z, 0.045, 0.62, 0.045, WHITE);
  // the board: six corners, wide and low
  const pts: [number, number][] = [[-0.45, 0.66], [-0.22, 0.4], [0.22, 0.4], [0.45, 0.66], [0.22, 0.92], [-0.22, 0.92]];
  const I: P3 = [0, 0.66, z];
  for (let i = 0; i < 6; i++) {
    const p = pts[i], q = pts[(i + 1) % 6];
    k.tri([0, 0.66, zf], [p[0], p[1], zf], [q[0], q[1], zf], WHITE, I);
    k.tri([0, 0.66, zb], [p[0], p[1], zb], [q[0], q[1], zb], hex(0xe4e2dc), I);
    k.quad([p[0], p[1], zb], [q[0], q[1], zb], [q[0], q[1], zf], [p[0], p[1], zf], hex(0xd8d6d0), I);
    // the bulbs along this edge
    for (let j = 0; j < 5; j++) {
      const u = j / 5;
      k.glowBox(p[0] + (q[0] - p[0]) * u, p[1] + (q[1] - p[1]) * u - 0.014, z, 0.03, 0.028, t * 2 + 0.03, hex(0xf2c83a), NEON_HOURS, hex(0xffe060));
    }
  }
  // the lit face: the row of discs with a red letter on each, a blue line, the name in red, the blue band below
  k.glowBox(0, 0.5, zf + 0.004, 0.62, 0.3, 0.008, hex(0xfaf8f2), NEON_HOURS, hex(0xfff8e8));
  for (let i = 0; i < 7; i++) {
    const x = (i - 3) * 0.078;
    k.face(x, 0.855, zf + 0.012, 0.036, hex(0xfcfcfa), 10);
    k.glowBox(x, 0.83, zf + 0.013, 0.05, 0.05, 0.006, hex(0xfcfcfa), NEON_HOURS, hex(0xfff8e8));
    k.glowBox(x, 0.84, zf + 0.018, 0.024, 0.03, 0.006, SIGN_RED, NEON_HOURS, hex(0xff3040));
  }
  k.glowBox(0, 0.745, zf + 0.01, 0.34, 0.035, 0.008, SIGN_BLUE, NEON_HOURS, hex(0x4a8aff));
  for (let i = 0; i < 8; i++) {
    if (i === 3) continue;
    k.glowBox((i - 3.5) * 0.072 , 0.59, zf + 0.01, 0.05, 0.12, 0.008, SIGN_RED, NEON_HOURS, hex(0xff3040));
  }
  k.glowBox(0, 0.455, zf + 0.01, 0.4, 0.085, 0.008, SIGN_BLUE, NEON_HOURS, hex(0x4a8aff));
  // the star: eight red points on a short mast
  k.box(0, 0.92, z, 0.025, 0.08, 0.025, WHITE);
  const sy = 1.06;
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU, R = i % 2 ? 0.075 : 0.13, wd = 0.035;
    const tip: P3 = [Math.cos(a) * R, sy + Math.sin(a) * R, z];
    const l: P3 = [Math.cos(a + 1.57) * wd, sy + Math.sin(a + 1.57) * wd, z], rr: P3 = [Math.cos(a - 1.57) * wd, sy + Math.sin(a - 1.57) * wd, z];
    k.tri(l, rr, tip, SIGN_RED, [0, sy, z - 0.1]);
    k.tri(l, rr, tip, SIGN_RED, [0, sy, z + 0.1]);
  }
  k.glowBox(0, sy - 0.03, z, 0.06, 0.06, 0.05, SIGN_RED, NEON_HOURS, hex(0xff3040));
};

const CONCRETE = hex(0xeceae4), CONCRETE_DARK = hex(0xcfccc4), POD_GLASS = hex(0x3a4a5a);

/** A ring of lit glazing round the origin, radius R, in twelve flat panes over a dark drum. */
function glazedRing(k: Kit, y: number, R: number, h: number, glow: RGB): void {
  k.cyl(0, y, 0, R, h, POD_GLASS, 12);
  const dist = R * Math.cos(Math.PI / 12) + 0.004, wide = 2 * R * Math.tan(Math.PI / 12) * 0.8;
  for (let i = 0; i < 12; i++) {
    k.turned(((i + 0.5) / 12) * TAU, () => k.glowBox(0, y + h * 0.15, dist, wide, h * 0.7, 0.012, hex(0x7a96aa), [17, 30, 1.3], glow));
  }
}

/**
 * The needle tower: three splayed concrete legs drawing together into one slim shaft, a saucer of glazed
 * rings near the top, a needle with a red light, and a thrill ride's arm out over the edge.
 */
const needleTower: Draw = (k, W, D) => {
  const R0 = Math.min(W, D) / 2 - 0.12;
  // the casino drum at its foot
  k.cyl(0, 0, 0, R0, 0.2, hex(0xd8c8a8), 16, hex(0xb8a888));
  k.glowBox(0, 0.06, R0 * 0.98, 0.5, 0.1, 0.03, hex(0x8a6a3a), NEON_HOURS, hex(0xffc850));
  // the legs: wide apart on the ground, closing on the shaft
  const prof: [number, number][] = [[R0 - 0.12, 0.1], [0.44, 1.2], [0.22, 2.5], [0.13, 4.7]];
  for (let j = 0; j < 3; j++) {
    const a = Math.PI / 2 + (j / 3) * TAU, c = Math.cos(a), s = Math.sin(a);
    for (let i = 0; i < prof.length - 1; i++) {
      const [r0, y0] = prof[i], [r1, y1] = prof[i + 1];
      k.bar([c * r0, y0, s * r0], [c * r1, y1, s * r1], 0.1 - i * 0.02, i === 2 ? CONCRETE : CONCRETE);
    }
  }
  k.hoop(0, 1.2, 0, 0.42, 0.03, CONCRETE_DARK, 12, 'xz');
  k.cyl(0, 0.2, 0, 0.1, 4.55, CONCRETE_DARK, 8);
  // the pod: a flare, three glazed rings between slabs, and a cap
  k.band(0, 0, 4.55, 0.14, 4.85, 0.5, 12, CONCRETE);
  glazedRing(k, 4.85, 0.52, 0.13, hex(0xffe8b0));
  k.cyl(0, 4.98, 0, 0.58, 0.05, CONCRETE, 12);
  glazedRing(k, 5.03, 0.5, 0.13, hex(0xfff4d8));
  k.cyl(0, 5.16, 0, 0.53, 0.04, CONCRETE, 12);
  glazedRing(k, 5.2, 0.4, 0.11, hex(0xffe8b0));
  k.cyl(0, 5.31, 0, 0.43, 0.03, CONCRETE, 12);
  k.band(0, 0, 5.34, 0.4, 5.62, 0.1, 12, CONCRETE_DARK);
  // the needle and its light
  k.cyl(0, 5.62, 0, 0.1, 0.06, CONCRETE, 8);
  k.cyl(0, 5.62, 0, 0.03, 0.8, WHITE, 6);
  k.box(0, 5.9, 0, 0.12, 0.05, 0.12, RED_LAMP);
  k.glowBox(0, 6.42, 0, 0.06, 0.06, 0.06, RED_LAMP, BEACON, RED_GLOW);
  // the ride: an arm out over the edge and the car hanging from it
  const ax = 0.62, az = 0.62;
  k.bar([0.22, 5.38, 0.22], [ax, 5.5, az], 0.028, hex(0xe2412f));
  k.bar([0.3, 5.2, 0.3], [ax * 0.8, 5.45, az * 0.8], 0.018, hex(0xe2412f));
  k.bar([ax, 5.5, az], [ax, 5.32, az], 0.012, DARK);
  k.box(ax, 5.24, az, 0.12, 0.08, 0.12, hex(0xf2c14e));
};

const RESORT = hex(0xeadfc4), RESORT_DARK = hex(0xd8caa8), TERRACOTTA = hex(0xb8603a), LAKE = hex(0x3a8ac8), JET = hex(0xe4f4fc);
const VILLAGE = [0xe8c890, 0xe0a890, 0xf0dcb0, 0xd89870].map(hex);

/**
 * The fountain resort: a cream hotel in three wings bent round a lake, a low dome over the middle, and
 * the fountains in a long arc across the water; an Italian village climbs one side.
 */
const fountainResort: Draw = (k, W, D, _b, r) => {
  const hx = -0.4, hz = -D / 2 + 0.5, cw = 1.5, wl = 1.35, wd = 0.5, bend = 0.42, HH = 2.6;
  // one wing, drawn in its own turned frame: walls, a window to every room front and back, the cornice
  const wing = (yaw: number, X: number, Z: number, len: number, h: number) => {
    const [x, z] = into(yaw, X, Z);
    k.turned(yaw, () => {
      k.box(x, 0, z, len, h, wd, RESORT, RESORT_DARK);
      const floors = Math.floor((h - 0.45) / FLOOR), n = Math.round(len / 0.19), cell = len / n;
      for (let f = 0; f < floors; f++) for (let i = 0; i < n; i++) {
        const u = x - len / 2 + cell * (i + 0.5), y = 0.42 + f * FLOOR;
        k.pane(u, y, z + wd / 2, cell * 0.5, 0.14, 1, hex(0x6a7a86), r() < 0.7 ? [17.5 + r() * 2, 23 + r() * 5, 1.25] : DARK_PANE, WARM_GLOW);
        if ((i + f) % 2) k.pane(u, y, z - wd / 2, cell * 0.5, 0.14, 3, hex(0x6a7a86), [18 + r() * 2, 23 + r() * 4, 1.2], WARM_GLOW);
      }
      k.box(x, h - 0.05, z, len + 0.06, 0.07, wd + 0.08, TERRACOTTA);
      k.box(x, h + 0.02, z, len - 0.06, 0.05, wd - 0.06, RESORT, RESORT_DARK);
      k.box(x, 0.3, z, len + 0.02, 0.04, wd + 0.03, RESORT_DARK);
    });
  };
  wing(0, hx, hz, cw, HH + 0.22);
  const ex = cw / 2 - 0.08, ox = (wl / 2) * Math.cos(bend), oz = (wl / 2) * Math.sin(bend);
  wing(-bend, hx + ex + ox, hz + oz + 0.02, wl, HH);
  wing(bend, hx - ex - ox, hz + oz + 0.02, wl, HH);
  // the dome and cupola over the middle
  const top = HH + 0.29;
  k.cyl(hx, top, hz, 0.24, 0.1, RESORT, 12);
  k.dome(hx, top + 0.1, hz, 0.22, hex(0xa8c4b4), 12, 3);
  k.cyl(hx, top + 0.3, hz, 0.05, 0.08, RESORT, 8);
  k.cone(hx, top + 0.38, hz, 0.06, 0.1, TERRACOTTA, 8);
  // the casino hall along the foot of the middle wing, tiled, and the porch on its columns
  const pz = hz + wd / 2 + 0.2;
  k.box(hx, 0, pz, cw + 0.5, 0.34, 0.42, RESORT, RESORT_DARK);
  k.hip(hx, 0.34, pz, cw + 0.56, 0.14, 0.48, TERRACOTTA);
  k.glowBox(hx, 0.06, pz + 0.215, 0.7, 0.2, 0.012, hex(0x8a7a5a), EVENING, SHOP_GLOW);
  for (const s of [-1, 1]) k.cyl(hx + s * 0.3, 0, pz + 0.36, 0.03, 0.26, WHITE, 6);
  k.box(hx, 0.26, pz + 0.3, 0.76, 0.04, 0.22, TERRACOTTA);
  // the lake: a stone rim and the water inside it
  const lx0 = -W / 2 + 0.12, lx1 = W / 2 - 1.12, lz0 = -0.62, lz1 = D / 2 - 0.12;
  const lcx = (lx0 + lx1) / 2, lcz = (lz0 + lz1) / 2, lw = lx1 - lx0, ld = lz1 - lz0;
  k.box(lcx, 0, lcz, lw, 0.05, ld, hex(0xd8d0bc));
  k.box(lcx, 0.05, lcz, lw - 0.12, 0.012, ld - 0.12, LAKE);
  const wy = 0.062;
  // the fountains: a long arc of jets, tall in the middle, lit from below, and a few that burst now and then
  const n = 13;
  for (let i = 0; i < n; i++) {
    const u = (i / (n - 1)) * 2 - 1, x = lcx + u * (lw / 2 - 0.4), z = lcz + 0.42 - 0.5 * (1 - u * u);
    const h = 0.45 + 0.95 * (1 - u * u) * (i % 2 ? 0.72 : 1);
    k.glowBox(x, wy, z, 0.035, h, 0.035, JET, NEON_HOURS, hex(0xfff2d0));
    k.cone(x, wy, z, 0.07, h * 0.45, JET, 6);
    k.glowBox(x, wy, z + 0.09, 0.07, 0.02, 0.05, WHITE, NEON_HOURS, hex(0xffe8b0));
  }
  for (const [u, sp] of [[-0.55, 3], [0, 17], [0.55, 31]] as const) {
    k.spin(lcx + u * (lw / 2 - 0.4), wy, lcz + 0.7, 'y', sp, (s) => {
      s.cyl(0, 0, 0, 0.06, 1.6, JET, 6);
      s.cone(0, 1.6, 0, 0.1, 0.35, JET, 6);
    }, 'geyser');
  }
  // the village terraces down the right-hand side, under their tiled roofs, and cypresses between
  const vx = W / 2 - 0.58;
  k.box(vx, 0, 0.35, 0.88, 0.04, D - 1.5, hex(0xd8c8a0));
  const houses: [number, number, number, number, number][] = [[0.1, -0.55, 0.46, 0.62, 0.4], [-0.14, 0.0, 0.36, 0.44, 0.34], [0.16, 0.46, 0.42, 0.52, 0.36], [-0.1, 0.98, 0.4, 0.36, 0.34], [0.2, 1.45, 0.34, 0.3, 0.3]];
  houses.forEach(([dx, z, w, h, d], i) => {
    k.box(vx + dx, 0.04, z, w, h, d, VILLAGE[i % VILLAGE.length]);
    k.hip(vx + dx, 0.04 + h, z, w + 0.06, 0.12, d + 0.06, TERRACOTTA);
    k.pane(vx + dx - w / 2, 0.04 + h * 0.5, z, d * 0.4, 0.1, 2, hex(0x6a7a86), EVENING, WARM_GLOW);
    k.pane(vx + dx, 0.04 + h * 0.5, z + d / 2, w * 0.4, 0.1, 1, hex(0x6a7a86), EVENING, WARM_GLOW);
  });
  // the campanile
  k.box(vx + 0.24, 0.04, -0.12, 0.16, 0.95, 0.16, VILLAGE[2]);
  k.hip(vx + 0.24, 0.99, -0.12, 0.2, 0.18, 0.2, TERRACOTTA);
  for (const [cx, cz] of [[vx - 0.34, -0.4], [vx - 0.36, 0.3], [vx - 0.34, 0.72], [vx + 0.34, 0.9], [vx - 0.3, 1.3], [hx - cw / 2 - 0.5, hz + 0.95], [hx + cw / 2 + 0.5, hz + 0.95]] as const) {
    k.cone(cx, 0.02, cz, 0.065, 0.5, CYPRESS, 6);
  }
};

// ================================ the Gulf ================================

const GULF_GLASS = hex(0x9fb4c8), GULF_GLASS_2 = hex(0x8aa2ba), GULF_STEEL = hex(0xd4dce4), GULF_BAND = hex(0x5e7488);

/**
 * The supertall: three glass wings round a six-sided core, each stepping back in turn as the tower climbs
 * so the setbacks wind round it in a spiral, up to a slim spire with a line of light and a red beacon.
 */
const supertall: Draw = (k, W, D, b) => {
  const H = Math.max(100, b.floors) * FLOOR, body = H * 0.8, tiers = 27, th = body / tiers;
  const R0 = Math.min(W, D) / 2 - 0.1;
  k.cyl(0, 0, 0, R0, 0.1, hex(0xdcd6c8), 18);
  const LIT: Sched = [17, 30, 1.2], glow = hex(0xf0f6ff);
  for (let j = 0; j < 3; j++) {
    k.turned((j / 3) * TAU, () => {
      let y0 = 0.1;
      for (let s = 0; s < 9; s++) {
        const y1 = th * (3 * s + j + 1), wd = 0.42 - s * 0.02, L = R0 - wd / 2 - 0.02 - s * 0.066, h = y1 - y0;
        const col = s % 2 ? GULF_GLASS_2 : GULF_GLASS;
        // the wing and its rounded nose, a dark plant floor at its top and a terrace over that
        k.box(0, y0, L / 2, wd, h, L, col, GULF_STEEL);
        k.cyl(0, y0, L, wd / 2, h, col, 8, GULF_STEEL);
        k.cyl(0, y1 - 0.16, L, wd / 2 + 0.012, 0.1, GULF_BAND, 8);
        k.box(0, y1 - 0.16, L / 2, wd + 0.024, 0.1, L, GULF_BAND);
        // a steel fin up the nose, lit, and a line of light along the terrace edge
        k.glowBox(0, y0, L + wd / 2, 0.035, h - 0.2, 0.03, GULF_STEEL, LIT, glow);
        k.glowBox(0, y1, L + wd / 2 - 0.05, wd * 0.5, 0.035, 0.03, WHITE, LIT, hex(0xffe8c0));
        y0 = y1;
      }
    });
  }
  // the core, and the spire in narrowing drums
  k.cyl(0, 0.1, 0, 0.3, body - 0.1, GULF_GLASS_2, 6, GULF_STEEL);
  const steps: [number, number][] = [[0.22, 0.87], [0.15, 0.92], [0.09, 0.96], [0.04, 1]];
  let y = body;
  for (const [rad, t] of steps) {
    k.cyl(0, y, 0, rad, H * t - y, rad > 0.1 ? GULF_GLASS : GULF_STEEL, 6, GULF_STEEL);
    for (let j = 0; j < 3; j++) {
      k.turned((j / 3) * TAU + Math.PI / 6, () => k.glowBox(0, y, rad * 0.87 + 0.004, 0.035, H * t - y, 0.02, WHITE, ALL_NIGHT, glow));
    }
    y = H * t;
  }
  k.glowBox(0, H, 0, 0.07, 0.07, 0.07, RED_LAMP, BEACON, RED_GLOW);
};

const SEA = hex(0x4aa0c8), SAIL_GLASS = hex(0x3a7ab8), SAIL_GLASS_2 = hex(0x4a8ac8), SAIL_WHITE = hex(0xf6f6f2);

/**
 * The sail hotel: on its own round island off the shore, two white masts spread in a V from the spine
 * at the back and a white sail bellied out between them, blue glass down the sides, a helipad high on one
 * side; washed in colour after dark.
 */
const sailHotel: Draw = (k, W, D) => {
  k.box(0, 0, 0.12, W - 0.1, 0.02, D - 0.34, SEA);
  k.box(0, 0, -D / 2 + 0.2, W - 0.1, 0.06, 0.3, SAND);
  const cz = 0.3, R = Math.min(W, D) / 2 - 0.5;
  k.cyl(0, 0, cz, R, 0.08, SAND, 18);
  k.cyl(0, 0.08, cz, R * 0.78, 0.015, hex(0xe8e2d4), 18);
  // the hotel: the spine at the back, the masts curving up from the front corners to meet it at the top
  const H = 4.9, y00 = 0.09, zb = cz - 0.62, dep = 1.22, n = 16;
  const depth = (t: number) => dep * Math.pow(1 - t * t, 0.55), half = (t: number) => 0.06 + 0.52 * Math.pow(1 - t * t, 0.55);
  const wash = (t: number): RGB => [0.35 + 0.5 * t, 0.45 - 0.15 * t, 1];
  for (let i = 0; i < n; i++) {
    const t0 = i / n, t1 = (i + 1) / n, tm = (t0 + t1) / 2, ya = y00 + t0 * H, yb = y00 + t1 * H;
    const d0 = depth(t0), d1 = depth(t1), h0 = half(t0), h1 = half(t1), dm = depth(tm), hm = half(tm);
    const I: P3 = [0, (ya + yb) / 2, zb + dm / 2];
    const col = i % 2 ? SAIL_GLASS_2 : SAIL_GLASS;
    for (const s of [-1, 1]) {
      k.quad([0, ya, zb], [s * h0, ya, zb + d0], [s * h1, yb, zb + d1], [0, yb, zb], col, I);
      k.bar([s * h0, ya, zb + d0], [s * h1, yb, zb + d1], 0.04, SAIL_WHITE);
    }
    // the sail, a course at a time, bellying forward in the middle
    const thick = Math.min(0.14, dm * 0.8);
    k.glowBox(0, ya, zb + dm + 0.01 - thick / 2, hm * 2, yb - ya, thick, SAIL_WHITE, [17.5, 30, 1.0], wash(tm));
    if (dm > 0.3) k.glowBox(0, ya, zb + dm + 0.03, hm * 1.2, yb - ya, 0.1, SAIL_WHITE, [17.5, 30, 1.0], wash(tm));
    k.quad([-h1, yb, zb + d1], [h1, yb, zb + d1], [0, yb, zb], [0, yb, zb], SAIL_WHITE, [0, ya, zb + d1 / 2]);
  }
  // the great trusses across each glass side
  for (const s of [-1, 1]) for (const [ta, tb] of [[0.02, 0.3], [0.3, 0.55], [0.55, 0.76]] as const) {
    k.bar([s * 0.03, y00 + ta * H, zb + 0.02], [s * (half(tb) + 0.0), y00 + tb * H, zb + depth(tb)], 0.03, SAIL_WHITE);
  }
  k.box(0, 0, zb - 0.03, 0.12, y00 + H, 0.1, SAIL_WHITE);
  k.cyl(0, y00 + H, zb - 0.03, 0.022, 0.75, SAIL_WHITE, 6);
  k.glowBox(0, y00 + H + 0.75, zb - 0.03, 0.05, 0.05, 0.05, RED_LAMP, BEACON, RED_GLOW);
  // the helipad, held out from the spine
  const py = y00 + H * 0.8, px = 0.5, pz = zb - 0.22;
  k.cyl(px, py, pz, 0.27, 0.035, hex(0x4a8a5a), 14, hex(0x4a8a5a));
  k.cyl(px, py + 0.035, pz, 0.2, 0.008, WHITE, 14);
  k.cyl(px, py + 0.043, pz, 0.15, 0.008, hex(0x4a8a5a), 14);
  k.bar([0, py - 0.45, zb - 0.03], [px, py, pz], 0.025, SAIL_WHITE);
  k.bar([0, py + 0.01, zb - 0.03], [px - 0.2, py + 0.01, pz + 0.05], 0.03, SAIL_WHITE);
  // the door under the sail, the palms, and the causeway curving in from the shore
  k.box(0, 0.09, zb + dep + 0.1, 0.5, 0.14, 0.16, SAIL_WHITE);
  k.glowBox(0, 0.1, zb + dep + 0.185, 0.36, 0.09, 0.012, hex(0x6a8aa0), EVENING, SHOP_GLOW);
  for (const a of [0.5, 1.2, 1.95, 2.65]) palm(k, Math.cos(a) * R * 0.84, 0.08, cz + Math.sin(a) * R * 0.84, 0.5, a * 2);
  const way: XZ[] = [[-W / 2 + 0.62, -D / 2 + 0.3], [-W / 2 + 0.26, -D / 2 + 0.72], [-W / 2 + 0.24, -0.25], [-R * 0.9, cz - 0.22]];
  for (let i = 0; i < way.length - 1; i++) {
    const p = way[i], q = way[i + 1];
    k.bar([p[0], 0.11, p[1]], [q[0], 0.11, q[1]], 0.065, hex(0xe8e6e0));
    k.cyl(q[0], 0, q[1], 0.05, 0.1, hex(0xc8c6c0), 6);
  }
};

// ================================ the Mother Road ================================

const MOTEL_WALL = hex(0xf2e6d0), MOTEL_DOORS = [0x2ec4c0, 0xff6a8a, 0xf2c14e, 0xf08040].map(hex), POOL = hex(0x40d0d8);
const PASTELS = [0x8ad8d0, 0xf4a8b8, 0xf6e08a, 0xa8c8f0, 0xb8e0a0, 0xf0b890, 0xd8b8e8].map(hex);

/** A car of the fifties: a long low body, a white roof, chrome at both ends and a pair of tail fins. */
function fifties(k: Kit, x: number, z: number, alongX: boolean, col: RGB, nose = 1): void {
  const box = (u: number, y: number, v: number, l: number, h: number, w: number, c: RGB, top?: RGB) =>
    alongX ? k.box(x + u * nose, y, z + v, l, h, w, c, top) : k.box(x + v, y, z + u * nose, w, h, l, c, top);
  box(0, 0.015, 0, 0.3, 0.04, 0.17, DARK);
  box(0, 0.04, 0, 0.4, 0.07, 0.18, col);
  box(-0.03, 0.11, 0, 0.17, 0.055, 0.15, GLASS_LIGHT, WHITE);
  for (const s of [-1, 1]) box(-0.17, 0.11, s * 0.075, 0.08, 0.035, 0.02, col);
  box(0.205, 0.05, 0, 0.015, 0.03, 0.18, METAL);
  box(-0.205, 0.05, 0, 0.015, 0.03, 0.18, METAL);
}

/**
 * The neon motel: a row of rooms with bright doors and a carport between each pair under a flat roof with
 * a zigzag edge, the office at one end, a kidney pool at the other, and the googie sign out front.
 */
const neonMotel: Draw = (k, W, D, _b, r) => {
  k.box(0, 0, 0, W - 0.1, 0.02, D - 0.1, hex(0x6a6a6c));
  const rd = 0.36, zc = -D / 2 + 0.1 + rd / 2, zf = zc + rd / 2, rh = 0.27;
  // the office, a little taller, with its plate window
  const ow = 0.46, ox = -W / 2 + 0.1 + ow / 2;
  k.box(ox, 0, zc + 0.06, ow, 0.34, rd + 0.12, MOTEL_WALL);
  k.pane(ox - 0.04, 0.07, zf + 0.12, 0.28, 0.2, 1, GLASS_LIGHT, [17, 30, 1.3], SHOP_GLOW);
  k.box(ox + 0.17, 0.02, zf + 0.125, 0.07, 0.2, 0.01, MOTEL_DOORS[0]);
  k.box(ox, 0.34, zc + 0.1, ow + 0.1, 0.035, rd + 0.3, hex(0x2ec4c0), WHITE);
  k.glowBox(ox, 0.375, zf + 0.2, 0.3, 0.07, 0.025, scale(PINK, 0.8), NEON_HOURS, PINK);
  // the rooms in pairs with a carport between each pair
  const rw = 0.23, cp = 0.27, x0 = ox + ow / 2 + 0.04;
  let x = x0, door = 0;
  for (let pair = 0; pair < 3; pair++) {
    for (let i = 0; i < 2; i++) {
      const cx = x + rw / 2;
      k.box(cx, 0, zc, rw, rh, rd, pair % 2 ? hex(0xf6d8c8) : MOTEL_WALL);
      const ds = i ? -1 : 1;
      k.box(cx + ds * 0.055, 0.02, zf + 0.006, 0.065, 0.17, 0.012, MOTEL_DOORS[door++ % MOTEL_DOORS.length]);
      k.pane(cx - ds * 0.05, 0.1, zf, 0.08, 0.09, 1, hex(0x6a7a86), r() < 0.75 ? [18, 23 + r() * 3, 1.3] : DARK_PANE, WARM_GLOW);
      x += rw;
    }
    if (pair < 2) {
      k.box(x + cp / 2, 0, zc - rd / 2 + 0.02, cp, rh, 0.04, MOTEL_WALL);
      if (pair === 0) fifties(k, x + cp / 2, zc + 0.06, false, PASTELS[1], -1);
      x += cp;
    }
  }
  const x1 = x, len = x1 - x0, mid = (x0 + x1) / 2;
  k.box(mid, rh, zc + 0.05, len + 0.06, 0.035, rd + 0.12, WHITE, hex(0xe8e4dc));
  // the zigzag along the roof's front edge, and a line of neon under it
  const teeth = 14, tw = (len + 0.06) / teeth, ez = zc + 0.05 + (rd + 0.12) / 2, ty = rh + 0.035;
  for (let i = 0; i < teeth; i++) {
    const a = mid - (len + 0.06) / 2 + i * tw;
    k.quad([a, ty, ez], [a + tw, ty, ez], [a + tw / 2, ty, ez + 0.1], [a + tw / 2, ty, ez + 0.1], hex(0x2ec4c0), [a + tw / 2, ty - 0.2, ez]);
    k.quad([a, ty - 0.03, ez], [a + tw / 2, ty - 0.03, ez + 0.1], [a + tw / 2, ty, ez + 0.1], [a, ty, ez], hex(0x24a8a4), [a + tw / 2, ty - 0.015, ez]);
    k.quad([a + tw, ty - 0.03, ez], [a + tw / 2, ty - 0.03, ez + 0.1], [a + tw / 2, ty, ez + 0.1], [a + tw, ty, ez], hex(0x24a8a4), [a + tw / 2, ty - 0.015, ez]);
  }
  k.glowBox(mid, rh - 0.02, ez + 0.006, len, 0.02, 0.012, scale(PINK, 0.8), NEON_HOURS, PINK);
  // the pool, a kidney of two rounds in a pale deck
  const px = (x1 + W / 2) / 2 + 0.02;
  k.box(px, 0.02, zc + 0.02, W / 2 - x1 - 0.14, 0.015, rd + 0.04, hex(0xe8e0d0));
  k.cyl(px - 0.07, 0.035, zc + 0.04, 0.13, 0.008, POOL, 12);
  k.cyl(px + 0.08, 0.036, zc - 0.02, 0.1, 0.008, POOL, 12);
  // the sign: a leaning pylon carrying five lit blocks, VACANCY under them, an arrow swooping at the rooms
  // and a starburst on top
  const sx = W / 2 - 0.42, sz = D / 2 - 0.2;
  k.bar([sx - 0.1, 0, sz], [sx + 0.08, 1.62, sz], 0.035, hex(0x2ec4c0));
  k.bar([sx + 0.2, 0, sz], [sx + 0.1, 1.05, sz], 0.025, hex(0x2ec4c0));
  for (let i = 0; i < 5; i++) {
    const c = i % 2 ? TURQ : PINK, y = 1.3 - i * 0.155;
    k.glowBox(sx + 0.045 + (y - 0.9) * 0.1, y, sz, 0.2, 0.135, 0.11, scale(c, 0.78), NEON_HOURS, c);
  }
  k.glowBox(sx + 0.03, 0.5, sz, 0.34, 0.075, 0.1, hex(0xe8dcc0), NEON_HOURS, NEON_YELLOW);
  // the arrow: a shaft sweeping down from the right and a head pointing in at the court
  const ay = 0.36;
  k.bar([sx + 0.3, 1.0, sz + 0.05], [sx + 0.26, ay + 0.12, sz + 0.05], 0.025, hex(0xf2c14e));
  k.bar([sx + 0.26, ay + 0.12, sz + 0.05], [sx - 0.12, ay, sz + 0.05], 0.025, hex(0xf2c14e));
  for (const zz of [sz + 0.025, sz + 0.075]) {
    k.tri([sx - 0.12, ay + 0.1, zz], [sx - 0.12, ay - 0.1, zz], [sx - 0.3, ay, zz], hex(0xf2c14e), [sx - 0.18, ay, sz + 0.05]);
  }
  for (let i = 0; i < 5; i++) k.glowBox(sx - 0.08 + i * 0.075, ay + 0.012 + i * 0.024, sz + 0.08, 0.03, 0.03, 0.02, hex(0xf8e8a0), NEON_HOURS, NEON_YELLOW);
  const by = 1.76, bx = sx + 0.095;
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * Math.PI, R = i % 2 ? 0.13 : 0.2;
    k.bar([bx - Math.cos(a) * R, by - Math.sin(a) * R, sz], [bx + Math.cos(a) * R, by + Math.sin(a) * R, sz], 0.014, hex(0xf2c14e));
  }
  k.glowBox(bx, by - 0.04, sz, 0.08, 0.08, 0.08, hex(0xf8e8a0), NEON_HOURS, NEON_YELLOW);
};

const TEEPEE = hex(0xf2eee4), TEEPEE_RED = hex(0xc8382a), GRAVEL = hex(0xb8ac98);

/** A concrete teepee cabin with its door toward (dx, dz): a red zigzag round the foot, a red tip, poles out of the top. */
function teepee(k: Kit, x: number, z: number, dx: number, dz: number): void {
  const R = 0.23, H = 0.98, y0 = 0.02, seg = 10;
  const rad = (y: number) => R * (1 - (y - y0) / H);
  k.cone(x, y0, z, R, H, TEEPEE, seg);
  k.band(x, z, 0.1, rad(0.1) + 0.006, 0.16, rad(0.16) + 0.006, seg, TEEPEE_RED);
  for (let s = 0; s < seg * 2; s++) {
    const a0 = (s / (seg * 2)) * TAU, a1 = ((s + 1) / (seg * 2)) * TAU, am = (a0 + a1) / 2;
    const r0 = rad(0.16) + 0.008, r1 = rad(0.25) + 0.008;
    k.tri([x + Math.cos(a0) * r0, 0.16, z + Math.sin(a0) * r0], [x + Math.cos(a1) * r0, 0.16, z + Math.sin(a1) * r0], [x + Math.cos(am) * r1, 0.25, z + Math.sin(am) * r1], TEEPEE_RED, [x, 0.2, z]);
  }
  k.cone(x, y0 + H * 0.84, z, rad(y0 + H * 0.84) + 0.008, H * 0.16 + 0.01, TEEPEE_RED, seg);
  for (let i = 0; i < 3; i++) {
    const a = (i / 3) * TAU + 0.4;
    k.bar([x - Math.cos(a) * 0.035, y0 + H - 0.1, z - Math.sin(a) * 0.035], [x + Math.cos(a) * 0.07, y0 + H + 0.16, z + Math.sin(a) * 0.07], 0.01, WOOD);
  }
  // the door in a little porch, and a lamp over it
  const px = x + dx * (R - 0.09), pz = z + dz * (R - 0.09);
  k.box(px, y0, pz, 0.12, 0.2, 0.12, TEEPEE);
  k.box(px + dx * 0.035, y0, pz + dz * 0.035, 0.07, 0.16, 0.07, hex(0x6a3a2a));
  k.glowBox(px + dx * 0.04, y0 + 0.2, pz + dz * 0.04, 0.035, 0.03, 0.035, hex(0xe8dcc0), EVENING, WARM_GLOW);
  // a diamond window round to one side
  const wa = Math.atan2(dz, dx) + 1.15, wy = 0.42, rr = rad(wy) + 0.012, up = 0.07, side = 0.045;
  const on = (a: number, y: number): P3 => [x + Math.cos(a) * (rad(y) + 0.012), y, z + Math.sin(a) * (rad(y) + 0.012)];
  k.quad(on(wa, wy - up), on(wa + side / rr, wy), on(wa, wy + up), on(wa - side / rr, wy), hex(0x3a4a5a), [x, wy, z]);
}

/**
 * The wigwam motel: white concrete teepees in an arc round a gravel court, a car of the fifties at each,
 * and a little office with its sign by the road.
 */
const wigwamMotel: Draw = (k, W, D, _b, r) => {
  k.box(0, 0, 0, W - 0.1, 0.02, D - 0.1, GRAVEL);
  const n = 7, cz = D / 2 - 0.62, rx = W / 2 - 0.34, rz = D - 0.98;
  for (let i = 0; i < n; i++) {
    const a = Math.PI + 0.12 + (i / (n - 1)) * (Math.PI - 0.24);
    const x = Math.cos(a) * rx, z = cz + Math.sin(a) * rz;
    // the door looks in at the middle of the court
    const tx = -x * 0.5, tz = cz + 0.1 - z, tl = Math.hypot(tx, tz) || 1, dx = tx / tl, dz = tz / tl;
    teepee(k, x, z, dx, dz);
    const alongX = Math.abs(dx) > Math.abs(dz) * 1.3;
    const px = x + dx * 0.5, pz = z + dz * 0.5;
    fifties(k, px, pz, alongX, PASTELS[i % PASTELS.length], alongX ? -Math.sign(dx) : -1);
  }
  // the office by the road, and the sign: a teepee in lights on a post
  const ox = 0.3, oz = D / 2 - 0.3;
  k.box(ox, 0.02, oz, 0.46, 0.26, 0.3, hex(0xf2e6d0));
  k.gable(ox, 0.28, oz, 0.52, 0.14, 0.36, TEEPEE_RED, hex(0xf2e6d0));
  k.pane(ox - 0.08, 0.09, oz + 0.15, 0.2, 0.13, 1, GLASS_LIGHT, [17, 30, 1.3], SHOP_GLOW);
  k.box(ox + 0.14, 0.02, oz + 0.155, 0.07, 0.17, 0.01, hex(0x2ec4c0));
  const sx = -0.55, sz = D / 2 - 0.22;
  k.box(sx, 0, sz, 0.04, 0.95, 0.04, WOOD);
  k.glowBox(sx, 0.52, sz, 0.42, 0.13, 0.05, hex(0xf2c14e), NEON_HOURS, hex(0xffd050));
  k.glowBox(sx, 0.4, sz, 0.3, 0.07, 0.05, scale(hex(0xff4030), 0.8), NEON_HOURS, hex(0xff5040));
  k.hip(sx, 0.67, sz, 0.22, 0.3, 0.06, TEEPEE);
  k.glowBox(sx, 0.95, sz, 0.05, 0.05, 0.05, hex(0xf8e8a0), NEON_HOURS, NEON_YELLOW);
  void r;
};

const ARROW_YELLOW = hex(0xe8b830), ARROW_RED = hex(0xc8382a), SHACK = hex(0x9a8468);

/**
 * The twin arrows: two giant arrows shot into the desert, yellow shafts with red heads in the ground and
 * red and yellow feathers high in the air, a derelict trading post and its faded sign beside them.
 */
const giantArrows: Draw = (k, W, D) => {
  const arrows: [P3, P3][] = [
    [[-W / 2 + 0.22, 0, 0.0], [0.2, 2.1, 0.14]],
    [[-0.12, 0, 0.26], [0.4, 2.0, -0.12]],
  ];
  for (const [a, b] of arrows) {
    const d: P3 = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], len = Math.hypot(d[0], d[1], d[2]);
    const u: P3 = [d[0] / len, d[1] / len, d[2] / len];
    const at = (t: number, off: P3 = [0, 0, 0], o = 0): P3 => [a[0] + d[0] * t + off[0] * o, a[1] + d[1] * t + off[1] * o, a[2] + d[2] * t + off[2] * o];
    k.bar(a, b, 0.035, ARROW_YELLOW);
    // the head, all but buried: the barbs' backs stand out of a mound of earth
    k.cone(a[0], 0, a[2], 0.2, 0.06, hex(0xb89870), 8);
    k.bar(at(0.0), at(0.1), 0.085, ARROW_RED);
    k.bar(at(0.1), at(0.13), 0.055, ARROW_RED);
    // the feathers: four fins round the shaft, swept back, red with a yellow root
    const p: P3 = [-u[2], 0, u[0]], pl = Math.hypot(p[0], p[2]) || 1;
    p[0] /= pl; p[2] /= pl;
    const q: P3 = [u[1] * p[2] - u[2] * p[1], u[2] * p[0] - u[0] * p[2], u[0] * p[1] - u[1] * p[0]];
    for (const [f, sgn] of [[p, 1], [p, -1], [q, 1], [q, -1]] as [P3, number][]) {
      const fin = (o0: number, o1: number, col: RGB) => {
        const A = at(0.76, f, sgn * o0), B = at(0.95, f, sgn * o0), C = at(1.0, f, sgn * o1), E = at(0.81, f, sgn * o1);
        const other: P3 = f === p ? q : p;
        for (const side of [-1, 1]) k.quad(A, B, C, E, col, at(0.88, other, side));
      };
      fin(0.03, 0.09, ARROW_YELLOW);
      fin(0.09, 0.2, ARROW_RED);
    }
  }
  // the trading post, boarded up, and the sign nobody has repainted
  const sx = W / 2 - 0.3, sz = -D / 2 + 0.26;
  k.box(sx, 0, sz, 0.36, 0.2, 0.26, SHACK);
  k.box(sx, 0.2, sz + 0.02, 0.42, 0.025, 0.34, hex(0x7a6a58));
  k.box(sx - 0.06, 0.02, sz + 0.135, 0.07, 0.14, 0.01, hex(0x5a4a3a));
  k.box(sx + 0.09, 0.08, sz + 0.135, 0.09, 0.07, 0.01, hex(0x4a4640));
  k.box(sx + 0.09, 0.1, sz + 0.142, 0.11, 0.015, 0.008, hex(0xb09a78));
  const bx = W / 2 - 0.26, bz = D / 2 - 0.2;
  for (const s of [-1, 1]) k.box(bx + s * 0.12, 0, bz, 0.025, 0.34, 0.025, WOOD);
  k.box(bx, 0.2, bz, 0.32, 0.16, 0.02, hex(0xd8ccb0));
  k.box(bx, 0.25, bz + 0.012, 0.22, 0.05, 0.006, hex(0xc89080));
};

// ---- the Sphere ----

const PODIUM = hex(0x3a3c44), PODIUM_TOP = hex(0x4a4c54), PLAZA = hex(0xcfc8b8), SPHERE_BACK = hex(0x22242c);

/** What the Sphere's skin shows: a colour for each point of the ball (unit x, y, z; +z faces the Strip). */
type Show = (x: number, y: number, z: number) => number;

/** Hue (0..1) to a saturated colour. */
function hueOf(h: number): number {
  const f = (n: number) => {
    const k = (n + h * 6) % 6;
    return Math.round(255 * Math.max(0, Math.min(1, Math.min(k, 4 - k))));
  };
  return (f(5) << 16) | (f(3) << 8) | f(1);
}

const SHOWS: Show[] = [
  // the eye: a blue iris round its pupil, looking out over the Strip, white all round it
  (x, y, z) => {
    const a = Math.acos(Math.max(-1, Math.min(1, z)));
    if (a < 0.2) return 0x101018;
    if (a < 0.48) return Math.sin(Math.atan2(y, x) * 14) > 0 ? 0x2a7aff : 0x5ad0ff;
    if (a < 0.53) return 0x0a2a6a;
    return z < -0.2 && Math.sin(Math.atan2(y, x) * 9 + z * 6) > 0.92 ? 0xd84a4a : 0xf6f4f0;
  },
  // the world: blue sea, green and tan land, white at the poles
  (x, y, z) => {
    if (Math.abs(y) > 0.86) return 0xf4f8ff;
    const n = Math.sin(x * 3.1 + 0.7) * Math.sin(y * 2.3 + 1.9) + Math.sin(z * 2.7 + x * 1.3) * 0.7 + Math.sin(y * 5.1 - z * 3.3) * 0.35;
    return n > 0.62 ? 0xc8a860 : n > 0.3 ? 0x3aa84a : 0x1a5ad8;
  },
  // a rainbow, band over band
  (_x, y) => hueOf(((y + 1) / 2) * 0.85),
  // a smiling face, yellow, out over the Strip
  (x, y, z) => {
    if (z > 0.3) {
      if (Math.hypot(Math.abs(x) - 0.3, y - 0.25) < 0.11) return 0x1a1a1a;
      const m = Math.hypot(x, y - 0.12);
      if (y < -0.08 && m > 0.44 && m < 0.56) return 0x1a1a1a;
    }
    return 0xffd23a;
  },
  // fireworks: bursts of colour on the night sky
  (x, y, z) => {
    const bursts: [number, number, number, number][] = [[0.3, 0.5, 0.81, 0xff4ab0], [-0.6, 0.2, 0.77, 0x2ee0ff], [0.7, -0.2, 0.68, 0xffc83a], [-0.2, -0.4, -0.89, 0x6aff5a], [0.1, 0.7, -0.7, 0xff5a2a]];
    for (const [bx, by, bz, col] of bursts) {
      const d = Math.hypot(x - bx, y - by, z - bz);
      if (d < 0.38 && Math.sin(Math.atan2(y - by, x - bx) * 10) > 0.2 - d) return col;
    }
    return 0x0c1030;
  },
];

/** How long each show runs, seconds. */
const SHOW_SECS = 9;

/**
 * The Sphere: a theatre that is one great ball, a ninth sunk into a low dark podium on its plaza, its whole skin
 * a screen. By day it shows its pictures as colour; after dark they glow, and the show changes every few seconds
 * (an eye, the world turning, a rainbow, a smiling face, fireworks), each turning slowly (Kit.rig).
 */
const sphereTheatre: Draw = (k, W, D, b) => {
  const PH = 0.2, R = Math.min(W, D) / 2 - 0.36, cy = PH + R * 0.84;
  // the plaza, the podium and its lit band, the doors at the front under their canopy
  k.box(0, 0, 0, W - 0.12, 0.025, D - 0.12, PLAZA);
  k.box(0, 0.025, 0, W - 0.5, PH - 0.025, D - 0.5, PODIUM, PODIUM_TOP);
  k.glowBox(0, PH - 0.06, (D - 0.5) / 2 + 0.005, W - 0.62, 0.035, 0.012, hex(0x5a6a8a), NEON_HOURS, hex(0x8ab8ff));
  const dz = (D - 0.5) / 2;
  k.glowBox(0, 0.04, dz + 0.004, 1.1, 0.11, 0.012, hex(0x6a5a3a), [17, 30, 1.3], SHOP_GLOW);
  k.box(0, 0.15, dz + 0.14, 1.3, 0.025, 0.28, SPHERE_BACK);
  for (const s of [-1, 1]) k.box(s * 0.6, 0.025, dz + 0.26, 0.025, 0.125, 0.025, METAL);
  if (k.mode !== 'derelict') bulbRow(k, [-0.62, 0.143, dz + 0.282], [0.62, 0.143, dz + 0.282], 18, BULB, BULB_HOURS, 'z');
  letters(k, 'LIVE TONIGHT', [0, 0.178, dz + 0.282], [1, 0], 0.07, hex(0xff4ab0));
  // the ball: a dark shell under the screen (the screen glows; the shell is what stands when it is off)
  const rings = 9, seg = 20, lat0 = Math.asin(-0.84);
  for (let j = 0; j < rings; j++) {
    const p0 = lat0 + ((Math.PI / 2 - lat0) * j) / rings, p1 = lat0 + ((Math.PI / 2 - lat0) * (j + 1)) / rings;
    const r0 = Math.cos(p0) * R * 0.985, r1 = Math.cos(p1) * R * 0.985, y0 = cy + Math.sin(p0) * R * 0.985, y1 = cy + Math.sin(p1) * R * 0.985;
    for (let s = 0; s < seg; s++) {
      const a0 = (s / seg) * TAU, a1 = ((s + 1) / seg) * TAU;
      k.quad([Math.sin(a0) * r0, y0, Math.cos(a0) * r0], [Math.sin(a1) * r0, y0, Math.cos(a1) * r0], [Math.sin(a1) * r1, y1, Math.cos(a1) * r1], [Math.sin(a0) * r1, y1, Math.cos(a0) * r1], SPHERE_BACK, [0, cy, 0]);
    }
  }
  // the screen: one skin a show, the rig showing one at a time and turning it slowly
  const skin = (show: Show) => (s: Kit) => {
    for (let j = 0; j < rings; j++) {
      const p0 = lat0 + ((Math.PI / 2 - lat0) * j) / rings, p1 = lat0 + ((Math.PI / 2 - lat0) * (j + 1)) / rings;
      const r0 = Math.cos(p0) * R, r1 = Math.cos(p1) * R, y0 = Math.sin(p0) * R, y1 = Math.sin(p1) * R;
      const pm = (p0 + p1) / 2;
      for (let q = 0; q < seg; q++) {
        const a0 = (q / seg) * TAU, a1 = ((q + 1) / seg) * TAU, am = (a0 + a1) / 2;
        const col = hex(show(Math.cos(pm) * Math.sin(am), Math.sin(pm), Math.cos(pm) * Math.cos(am)));
        s.glowQuad([Math.sin(a0) * r0, y0, Math.cos(a0) * r0], [Math.sin(a1) * r0, y0, Math.cos(a1) * r0], [Math.sin(a1) * r1, y1, Math.cos(a1) * r1], [Math.sin(a0) * r1, y1, Math.cos(a0) * r1],
          [0, 0, 0], scale(col, 0.8), NEON_HOURS, col);
      }
    }
  };
  // each Sphere starts its programme at a point of its own, so two never show the same thing at once
  let t = ((b.seed >>> 0) % 997) / 997 * SHOW_SECS * SHOWS.length;
  const tick: RigTick = (parts, dt) => {
    t += dt;
    const on = Math.floor(t / SHOW_SECS) % parts.length;
    parts.forEach((p, i) => { p.visible = i === on; });
    parts[on].rotation.y = Math.sin(t * 0.07) * 0.9;
  };
  k.rig(0, cy, 0, SHOWS.map(skin), tick);
  // palms round the plaza
  for (const [px, pz] of [[-W / 2 + 0.2, D / 2 - 0.2], [W / 2 - 0.2, D / 2 - 0.2], [-W / 2 + 0.2, -D / 2 + 0.2], [W / 2 - 0.2, -D / 2 + 0.2]] as const) palm(k, px, 0.025, pz, 0.62, px * 2 + pz);
};

export const WORLD_C_DRAW: Partial<Record<ThemeKind, Draw>> = {
  bankTower, walledCity, casinoPyramid, welcomeSign, needleTower, fountainResort, sphereTheatre, supertall, sailHotel,
  neonMotel, wigwamMotel, giantArrows,
};
