import { hex, scale, type RGB } from '../../world/biomes';
import { FLOOR } from '../../world/towns';
import type { Rng } from '../../world/rng';
import type { Sched } from '../nightLights';
import { DARK, GLASS_LIGHT, TAU, WARM_GLOW, WHITE, row, type Draw, type Kit, type P3 } from './kit';

/**
 * The landmarks of three capitals, swapped in by their town styles (STYLE_SWAPS in world/towns.ts). Each
 * stands on its lot centred on the origin, its front to +z.
 *
 * Paris (`paris`): the **Eiffel Tower** (for a clock tower), the **Arc de Triomphe** (memorial, plaza
 * steps), **Notre-Dame** (church, cathedral), the **Louvre** round its glass pyramid (museum) and
 * **Sacré-Cœur** on the town's highest ground (sculpture park).
 *
 * New York (`newyork`): the **Empire State** (skyscraper), the **Chrysler Building** (tower block), the
 * **Flatiron** (hotel) and the **Statue of Liberty** on her star fort by the water (memorial).
 *
 * Washington (`capital`): the **Capitol** (city hall), the **Washington Monument** (clock tower), the
 * **Lincoln Memorial** (memorial, plaza steps), the **White House** (courthouse) and the **Jefferson
 * Memorial** by its basin under cherry trees (formal garden).
 */

const IRON_BROWN = hex(0x6a5a48), PARIS_STONE = hex(0xe8e0cc), PARIS_STONE_DARK = hex(0xcfc4ac), ZINC = hex(0x6e7a82);
const GOTHIC_STONE = hex(0xd8ccb0), GOTHIC_DARK = hex(0xa89c84), LEAD = hex(0x5a6268), LOUVRE_GLASS = hex(0x9cc4d8);
const TRAVERTINE = hex(0xf6f4ee), WATER = hex(0x6fb8e0), EMPIRE_STONE = hex(0xcfc8b8), EMPIRE_DARK = hex(0x8a8a88);
const CHRYSLER_BRICK = hex(0xe6e4de), STEEL = hex(0xc8ccd0), FLATIRON_STONE = hex(0xe0d4bc), COPPER = hex(0x6aa08a);
const GRANITE = hex(0x9a968e), GRANITE_LIGHT = hex(0xb8b2a6), MARBLE = hex(0xf6f4ee), MARBLE_SHADE = hex(0xdedad2);
const BRONZE = hex(0x6a5236), BLOSSOM = hex(0xf4b8c8), LAWN = hex(0x6fb04a), GOLD = hex(0xe8c040);
/** Floodlit from dusk to the small hours; beacons all night. */
const FLOOD: Sched = [18, 25.5, 1.3], BEACON: Sched = [0, 36, 2.8];

// ---- shared pieces ----

/** A row of n columns from x0 to x1 at z, standing on y, h tall. */
function colonnade(k: Kit, x0: number, x1: number, z: number, y: number, h: number, n: number, col: RGB, r = 0.035): void {
  for (let i = 0; i < n; i++) k.cyl(x0 + ((x1 - x0) * i) / Math.max(1, n - 1), y, z, r, h, col, 6);
}

/** The same along z. */
function colonnadeZ(k: Kit, z0: number, z1: number, x: number, y: number, h: number, n: number, col: RGB, r = 0.035): void {
  for (let i = 0; i < n; i++) k.cyl(x, y, z0 + ((z1 - z0) * i) / Math.max(1, n - 1), r, h, col, 6);
}

/** A pediment facing +z over a portico: a low gable end-on to the front. */
function pediment(k: Kit, x: number, y: number, z: number, w: number, d: number, h: number, col: RGB): void {
  k.gable(x, y, z, w, h, d, col, col, true);
}

/** A frustum of four faces from a square of half-width a at y0 to half-width b at y1 (an obelisk's shaft). */
function frustum(k: Kit, x: number, z: number, y0: number, y1: number, a: number, b: number, col: RGB): void {
  const I: P3 = [x, (y0 + y1) / 2, z];
  const c0 = (sx: number, sz: number): P3 => [x + sx * a, y0, z + sz * a];
  const c1 = (sx: number, sz: number): P3 => [x + sx * b, y1, z + sz * b];
  k.quad(c0(-1, 1), c0(1, 1), c1(1, 1), c1(-1, 1), col, I);
  k.quad(c0(-1, -1), c0(1, -1), c1(1, -1), c1(-1, -1), col, I);
  k.quad(c0(1, -1), c0(1, 1), c1(1, 1), c1(1, -1), col, I);
  k.quad(c0(-1, -1), c0(-1, 1), c1(-1, 1), c1(-1, -1), col, I);
}

/** Vertical window strips up every face of a block: the dark piers between a tall tower's windows. */
function ribs(k: Kit, x: number, y: number, z: number, w: number, d: number, h: number, col: RGB, gap = 0.13): void {
  for (let o = -w / 2 + gap / 2; o < w / 2; o += gap) {
    k.box(x + o, y + 0.05, z + d / 2 + 0.004, 0.04, h - 0.1, 0.008, col);
    k.box(x + o, y + 0.05, z - d / 2 - 0.004, 0.04, h - 0.1, 0.008, col);
  }
  for (let o = -d / 2 + gap / 2; o < d / 2; o += gap) {
    k.box(x + w / 2 + 0.004, y + 0.05, z + o, 0.008, h - 0.1, 0.04, col);
    k.box(x - w / 2 - 0.004, y + 0.05, z + o, 0.008, h - 0.1, 0.04, col);
  }
}

/** Rows of windows round a block, every other storey. */
function glazed(k: Kit, b: Parameters<Draw>[3], r: Rng, x: number, y: number, z: number, w: number, d: number, floors: number, glass: RGB): void {
  const nx = Math.max(1, Math.round(w / 0.22)), nz = Math.max(1, Math.round(d / 0.22));
  for (let f = 0; f < floors; f++) {
    const fy = y + f * FLOOR + 0.07;
    row(k, b, r, x, fy, z + d / 2, w - 0.04, 0.11, nx, 1, glass);
    row(k, b, r, x, fy, z - d / 2, w - 0.04, 0.11, nx, 3, glass);
    row(k, b, r, x + w / 2, fy, z, d - 0.04, 0.11, nz, 0, glass);
    row(k, b, r, x - w / 2, fy, z, d - 0.04, 0.11, nz, 2, glass);
  }
}

// ================================ Paris ================================

/** One section of the tower: four corner members from half-width h0 at y0 to h1 at y1, braced across every face. */
function lattice(k: Kit, y0: number, y1: number, h0: number, h1: number, n: number, rr: number, col: RGB): void {
  const at = (sx: number, sz: number, t: number): P3 => {
    const h = h0 + (h1 - h0) * t;
    return [sx * h, y0 + (y1 - y0) * t, sz * h];
  };
  const C: [number, number][] = [[1, 1], [1, -1], [-1, -1], [-1, 1]];
  for (const [sx, sz] of C) k.bar(at(sx, sz, 0), at(sx, sz, 1), rr, col);
  for (let f = 0; f < 4; f++) {
    const [ax, az] = C[f], [bx, bz] = C[(f + 1) % 4];
    for (let i = 0; i < n; i++) {
      const t0 = i / n, t1 = (i + 1) / n;
      k.bar(at(ax, az, t0), at(bx, bz, t1), rr * 0.4, col);
      k.bar(at(bx, bz, t0), at(ax, az, t1), rr * 0.4, col);
    }
  }
}

const eiffelTower: Draw = (k, W, D) => {
  const base = Math.min(W, D) / 2 - 0.2;
  // the four legs, each its own column of lattice leaning in to the first platform
  const p1 = 1.5, h1 = base * 0.56;
  for (const [sx, sz] of [[1, 1], [1, -1], [-1, -1], [-1, 1]] as const) {
    const foot: P3 = [sx * base, 0, sz * base], top: P3 = [sx * h1, p1, sz * h1];
    const inset = 0.18;
    const footIn: P3 = [sx * (base - inset), 0, sz * (base - inset)], topIn: P3 = [sx * (h1 - inset * 0.6), p1, sz * (h1 - inset * 0.6)];
    k.bar(foot, top, 0.05, IRON_BROWN);
    k.bar(footIn, topIn, 0.04, IRON_BROWN);
    k.bar([sx * base, 0, sz * (base - inset)], [sx * h1, p1, sz * (h1 - inset * 0.6)], 0.035, IRON_BROWN);
    k.bar([sx * (base - inset), 0, sz * base], [sx * (h1 - inset * 0.6), p1, sz * h1], 0.035, IRON_BROWN);
    k.box(sx * (base - inset / 2), 0, sz * (base - inset / 2), 0.3, 0.08, 0.3, PARIS_STONE_DARK);
  }
  // the arches between the legs, under the first platform
  for (let f = 0; f < 4; f++) {
    k.turned((f * Math.PI) / 2, () => {
      const seg = 8, zz = h1 + (base - h1) * 0.35, span = h1 + (base - h1) * 0.35;
      for (let i = 0; i < seg; i++) {
        const a0 = (i / seg) * Math.PI, a1 = ((i + 1) / seg) * Math.PI;
        k.bar([Math.cos(a0) * span, 0.35 + Math.sin(a0) * 0.8, zz], [Math.cos(a1) * span, 0.35 + Math.sin(a1) * 0.8, zz], 0.025, IRON_BROWN);
      }
    });
  }
  // the first platform, the second section, the second platform, the long third section and the top
  k.box(0, p1, 0, h1 * 2 + 0.2, 0.14, h1 * 2 + 0.2, IRON_BROWN);
  const p2 = 3.4, h2 = 0.34;
  lattice(k, p1 + 0.14, p2, h1 * 0.86, h2, 3, 0.045, IRON_BROWN);
  k.box(0, p2, 0, h2 * 2 + 0.18, 0.1, h2 * 2 + 0.18, IRON_BROWN);
  const p3 = 8.2;
  lattice(k, p2 + 0.1, p3, h2 * 0.9, 0.07, 7, 0.035, IRON_BROWN);
  k.box(0, p3, 0, 0.24, 0.26, 0.24, IRON_BROWN);
  k.cyl(0, p3 + 0.26, 0, 0.03, 0.8, IRON_BROWN, 6);
  // lit gold at night: the platforms' rims and a beacon
  for (const [y, h] of [[p1 + 0.14, h1 + 0.1], [p2 + 0.1, h2 + 0.09]] as const) {
    for (const s of [-1, 1]) {
      k.glowBox(0, y, s * h, h * 2, 0.03, 0.02, IRON_BROWN, FLOOD, GOLD);
      k.glowBox(s * h, y, 0, 0.02, 0.03, h * 2, IRON_BROWN, FLOOD, GOLD);
    }
  }
  k.glowBox(0, p3 + 0.2, 0, 0.1, 0.08, 0.1, IRON_BROWN, BEACON, hex(0xfff0c0));
  void W; void D;
};

const arcDeTriomphe: Draw = (k, W, D) => {
  const w = Math.min(W - 0.3, 1.7), d = Math.min(D - 0.4, 1.0), h = 1.1, attic = 0.36;
  // four piers, leaving the great arch through the front and the smaller one through the sides
  const pw = w * 0.3, pd = d * 0.3;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    k.box(sx * (w / 2 - pw / 2), 0, sz * (d / 2 - pd / 2), pw, h, pd, PARIS_STONE);
    // the sculpture groups on the front piers
    if (sz > 0) k.box(sx * (w / 2 - pw / 2), 0.2, d / 2 + 0.02, pw * 0.6, 0.36, 0.03, PARIS_STONE_DARK);
  }
  // the vault over the arch and the attic storey above it, corniced
  k.box(0, h * 0.78, 0, w - pw * 1.6, h * 0.22, d, PARIS_STONE);
  k.box(0, h, 0, w + 0.06, 0.05, d + 0.06, PARIS_STONE_DARK);
  k.box(0, h + 0.05, 0, w, attic, d, PARIS_STONE);
  k.box(0, h + 0.05 + attic, 0, w + 0.06, 0.04, d + 0.06, PARIS_STONE_DARK);
  // the frieze of shields under the cornice, and the flag hanging in the arch
  for (let i = 0; i < 8; i++) k.box(-w / 2 + (w / 8) * (i + 0.5), h + attic * 0.5, d / 2 + 0.01, 0.06, 0.06, 0.02, PARIS_STONE_DARK);
  for (const [c, x] of [[0x2f4a8a, -0.07], [0xf4f2ec, 0], [0xd8303a, 0.07]] as const) k.box(x, h * 0.35, 0, 0.07, h * 0.42, 0.01, hex(c));
  // floodlit
  k.glowBox(0, 0.02, d / 2 + 0.2, 0.1, 0.04, 0.06, DARK, FLOOD, WARM_GLOW);
};

const notreDame: Draw = (k, W, D, _b, r) => {
  const nw = Math.min(W - 1.2, 1.2), fd = D - 0.3, nh = 1.4, front = fd / 2;
  // the nave and choir under a steep lead roof, the rounded apse at the east end
  k.box(0, 0, -0.1, nw, nh, fd - 0.9, GOTHIC_STONE);
  k.gable(0, nh, -0.1, nw + 0.06, 0.55, fd - 0.9, LEAD, GOTHIC_STONE, true);
  const az = -0.1 - (fd - 0.9) / 2;
  k.cyl(0, 0, az, nw / 2, nh, GOTHIC_STONE, 10);
  k.cone(0, nh, az, nw / 2 + 0.03, 0.45, LEAD, 10);
  // the transept across it, and the spire over the crossing
  k.box(0, 0, -0.35, nw + 0.9, nh * 0.96, 0.6, GOTHIC_STONE);
  k.gable(0, nh * 0.96, -0.35, nw + 0.9, 0.5, 0.62, LEAD, GOTHIC_STONE);
  k.cyl(0, nh + 0.5, -0.35, 0.09, 0.3, LEAD, 8);
  k.cone(0, nh + 0.8, -0.35, 0.09, 1.1, LEAD, 8);
  // flying buttresses down both sides
  for (const sx of [-1, 1]) for (let i = 0; i < 4; i++) {
    const z = front - 1.1 - i * 0.42;
    if (z < az + 0.1) continue;
    k.box(sx * (nw / 2 + 0.36), 0, z, 0.1, nh * 0.8, 0.1, GOTHIC_DARK);
    k.bar([sx * (nw / 2 + 0.36), nh * 0.8, z], [sx * (nw / 2), nh * 0.98, z], 0.025, GOTHIC_DARK);
    k.cone(sx * (nw / 2 + 0.36), nh * 0.8, z, 0.05, 0.16, GOTHIC_DARK, 6);
  }
  // the west front: two square towers, the gallery of kings, the rose and the three portals
  const fz = front - 0.35, tw = 0.62, th = 2.5;
  for (const sx of [-1, 1]) {
    k.box(sx * (nw / 2 + tw / 2 - 0.2), 0, fz, tw, th, 0.7, GOTHIC_STONE);
    k.box(sx * (nw / 2 + tw / 2 - 0.2), th, fz, tw + 0.04, 0.04, 0.74, GOTHIC_DARK);
    // the belfry's tall lancets
    for (const o of [-0.13, 0.13]) k.box(sx * (nw / 2 + tw / 2 - 0.2) + o, th - 0.75, fz + 0.36, 0.08, 0.55, 0.01, DARK);
  }
  const mid = nw - 0.4 + tw * 2 - 0.4;
  k.box(0, 0, fz, mid, nh + 0.2, 0.7, GOTHIC_STONE);
  k.box(0, nh * 0.5, fz + 0.36, mid, 0.05, 0.01, GOTHIC_DARK);
  k.face(0, nh * 0.78, fz + 0.36, 0.2, scale(GOTHIC_DARK, 0.8), 12);
  k.glowBox(0, nh * 0.7, fz + 0.365, 0.28, 0.18, 0.005, hex(0x5a4a8a), FLOOD, hex(0xb89aff));
  for (const o of [-0.45, 0, 0.45]) k.box(o, 0, fz + 0.36, o ? 0.2 : 0.26, 0.42, 0.01, DARK);
  void r;
};

const louvrePyramid: Draw = (k, W, D, b, r) => {
  const w = W - 0.3, d = D - 0.3, depth = 0.6, h = 0.9;
  // the palace: a wing across the back and one down each side, round the Cour Napoléon
  k.box(0, 0, -d / 2 + depth / 2, w, h, depth, PARIS_STONE);
  for (const sx of [-1, 1]) k.box(sx * (w / 2 - depth / 2), 0, depth / 2 * 0.5, depth, h, d - depth, PARIS_STONE);
  // their mansards, and a taller pavilion at each corner and in the middle of the back
  k.hip(0, h, -d / 2 + depth / 2, w + 0.04, 0.3, depth + 0.04, ZINC);
  for (const sx of [-1, 1]) k.hip(sx * (w / 2 - depth / 2), h, depth / 4, depth + 0.04, 0.3, d - depth + 0.04, ZINC);
  for (const [x, z] of [[-1, -1], [1, -1], [0, -1], [-1, 1], [1, 1]] as const) {
    const px = x * (w / 2 - depth / 2), pz = z < 0 ? -d / 2 + depth / 2 : d / 2 - depth / 2;
    k.box(px, 0, pz, depth + 0.1, h + 0.12, depth + 0.1, PARIS_STONE);
    k.hip(px, h + 0.12, pz, depth + 0.14, 0.42, depth + 0.14, ZINC);
  }
  glazed(k, b, r, 0, 0, -d / 2 + depth / 2, w, depth, 3, GLASS_LIGHT);
  // the glass pyramid in the court, three small ones round it and the pools
  const cz = d * 0.12, pr = Math.min(w, d) * 0.18;
  k.box(0, 0, cz, pr * 3.4, 0.02, pr * 3.4, hex(0xd8d2c4));
  for (const [x, z] of [[-1, 0], [1, 0], [0, 1]] as const) k.box(x * pr * 1.4, 0.02, cz + z * pr * 1.4, pr * 0.8, 0.012, pr * 0.8, WATER);
  // a square pyramid is a four-sided cone turned an eighth: in the turned frame a point (x, z) of the
  // lot lies at ((x - z) / sqrt2, (x + z) / sqrt2)
  const at = (x: number, z: number): [number, number] => [(x - z) * Math.SQRT1_2, (x + z) * Math.SQRT1_2];
  k.turned(Math.PI / 4, () => {
    const [mx, mz] = at(0, cz);
    k.cone(mx, 0.02, mz, pr * 1.41, pr * 1.3, LOUVRE_GLASS, 4);
    for (const [x, z] of [[-1, 1], [1, 1], [0, -1]] as const) {
      const [lx, lz] = at(x * pr * 1.9, cz + z * pr * 1.9);
      k.cone(lx, 0.02, lz, pr * 0.34, pr * 0.3, LOUVRE_GLASS, 4);
    }
  });
  k.glowBox(0, 0.05, cz, pr * 0.9, pr * 0.5, pr * 0.9, LOUVRE_GLASS, FLOOD, hex(0xe8f4ff));
};

const sacreCoeur: Draw = (k, W, D) => {
  const w = Math.min(W, D) - 0.5;
  // the steps up the hill, the basilica's white body and its porch of three arches
  for (let i = 0; i < 4; i++) k.box(0, 0, w / 2 - 0.1 + i * 0.08, w * 0.7, 0.05 * (4 - i), 0.1, TRAVERTINE);
  k.box(0, 0, -0.1, w * 0.8, 0.9, w * 0.62, TRAVERTINE);
  k.box(0, 0, w * 0.27, w * 0.5, 0.62, 0.26, TRAVERTINE);
  for (const o of [-0.22, 0, 0.22]) k.box(o * w, 0, w * 0.27 + 0.13, 0.12, 0.4, 0.01, hex(0x8a8478));
  k.gable(0, 0.62, w * 0.27, w * 0.5, 0.12, 0.26, TRAVERTINE, TRAVERTINE, true);
  // the great dome on its drum, the little domes round it and the campanile behind
  k.cyl(0, 0.9, -0.1, w * 0.18, 0.5, TRAVERTINE, 14);
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * TAU;
    k.box(Math.cos(a) * w * 0.18, 1.0, -0.1 + Math.sin(a) * w * 0.18, 0.03, 0.3, 0.03, hex(0xd8d4c8));
  }
  k.dome(0, 1.4, -0.1, w * 0.19, TRAVERTINE, 14, 5);
  k.cyl(0, 1.4 + w * 0.17, -0.1, 0.05, 0.14, TRAVERTINE, 8);
  k.cone(0, 1.54 + w * 0.17, -0.1, 0.06, 0.16, TRAVERTINE, 8);
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    const x = sx * w * 0.3, z = -0.1 + sz * w * 0.2;
    k.cyl(x, 0.9, z, 0.1, 0.18, TRAVERTINE, 10);
    k.dome(x, 1.08, z, 0.11, TRAVERTINE, 10, 3);
  }
  const cz = -0.1 - w * 0.36;
  k.box(0, 0, cz, 0.32, 1.8, 0.32, TRAVERTINE);
  k.cyl(0, 1.8, cz, 0.13, 0.12, TRAVERTINE, 10);
  k.dome(0, 1.92, cz, 0.13, TRAVERTINE, 10, 3);
  k.glowBox(0, 0.02, w / 2 + 0.25, 0.1, 0.04, 0.06, DARK, FLOOD, WARM_GLOW);
};

// ================================ New York ================================

const empireState: Draw = (k, W, D, b, r) => {
  const w = Math.min(W, D) - 0.12;
  // the five-storey base filling its block, then the setbacks, the long shaft and the mooring mast
  const tiers: [number, number][] = [[w, 5 * FLOOR], [w * 0.8, 1.6], [w * 0.62, 7.4], [w * 0.5, 8.0], [w * 0.38, 8.5]];
  let y = 0;
  for (const [tw, top] of tiers) {
    k.box(0, y, 0, tw, top - y, tw * 0.85, EMPIRE_STONE, scale(EMPIRE_STONE, 0.95));
    ribs(k, 0, y, 0, tw, tw * 0.85, top - y, EMPIRE_DARK);
    y = top;
  }
  glazed(k, b, r, 0, 0, 0, w, w * 0.85, 5, GLASS_LIGHT);
  // the mast in tapering drums, the antenna, and the floodlit crown in colour
  let R = w * 0.15;
  for (let i = 0; i < 4; i++) { k.cyl(0, y, 0, R, 0.22, EMPIRE_STONE, 8); y += 0.22; R *= 0.82; }
  k.glowBox(0, 8.5, 0, w * 0.4, 0.4, w * 0.34, EMPIRE_STONE, FLOOD, hex(0xf4d060));
  k.cyl(0, y, 0, 0.02, 1.0, STEEL, 6);
  k.glowBox(0, y + 1.0, 0, 0.05, 0.05, 0.05, hex(0xe2412f), BEACON, hex(0xff4a3a));
};

const chryslerBuilding: Draw = (k, W, D, b, r) => {
  const w = Math.min(W, D) - 0.3, shaft = 5.6;
  k.box(0, 0, 0, w + 0.2, 5 * FLOOR, w + 0.2, hex(0x3a3a3e));
  k.box(0, 5 * FLOOR, 0, w, shaft - 5 * FLOOR, w, CHRYSLER_BRICK);
  glazed(k, b, r, 0, 5 * FLOOR, 0, w, w, Math.floor((shaft - 5 * FLOOR) / FLOOR), hex(0x5a6a78));
  // the eagle gargoyles at the corners of the sixty-first floor
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) k.box(sx * (w / 2 + 0.04), shaft - 0.6, sz * (w / 2 + 0.04), 0.1, 0.05, 0.1, STEEL);
  // the crown: arched terraces of stainless steel, each with its sunburst of triangular windows, lit at night
  let y = shaft, cw = w * 0.9;
  for (let i = 0; i < 6; i++) {
    const h = 0.34;
    k.box(0, y, 0, cw, h, cw, STEEL);
    for (const s of [-1, 1]) {
      for (let j = -1; j <= 1; j++) {
        k.glowBox(j * cw * 0.28, y + 0.06, s * (cw / 2 + 0.004), 0.06, 0.16, 0.006, hex(0x3a4450), FLOOD, hex(0xfff0d0));
        k.glowBox(s * (cw / 2 + 0.004), y + 0.06, j * cw * 0.28, 0.006, 0.16, 0.06, hex(0x3a4450), FLOOD, hex(0xfff0d0));
      }
    }
    y += h;
    cw *= 0.8;
  }
  // and the needle
  k.cone(0, y, 0, cw * 0.6, 1.6, STEEL, 8);
};

const flatironBuilding: Draw = (k, W, D, b, r) => {
  // a narrow triangle on its block: the prow to the front, the broad back to the rear
  const bw = W - 0.2, back = -D / 2 + 0.1, prow = D / 2 - 0.12, H = 22 * FLOOR;
  const A: [number, number] = [-bw / 2, back], B: [number, number] = [bw / 2, back], C: [number, number] = [0, prow];
  const I: P3 = [0, H / 2, back + 0.3];
  const wall = (p: [number, number], q: [number, number], col: RGB, y0: number, y1: number, out = 0) => {
    const nx = q[1] - p[1], nz = -(q[0] - p[0]), n = Math.hypot(nx, nz) || 1, ox = (nx / n) * out, oz = (nz / n) * out;
    k.quad([p[0] + ox, y0, p[1] + oz], [q[0] + ox, y0, q[1] + oz], [q[0] + ox, y1, q[1] + oz], [p[0] + ox, y1, p[1] + oz], col, I);
  };
  for (const [p, q] of [[A, B], [B, C], [C, A]] as const) {
    wall(p, q, FLATIRON_STONE, 0, H);
    // a band of shadow for every storey's windows, and the cornice
    for (let f = 1; f < 22; f += 1) wall(p, q, scale(FLATIRON_STONE, 0.72), f * FLOOR + 0.06, f * FLOOR + 0.16, 0.004);
    wall(p, q, scale(FLATIRON_STONE, 0.85), H - 0.02, H + 0.08, 0.03);
  }
  // the flat roof, a little cupola at the prow, and the shopfronts round the ground floor
  k.tri([A[0], H + 0.08, A[1]], [B[0], H + 0.08, B[1]], [C[0], H + 0.08, C[1]], scale(FLATIRON_STONE, 0.8), [0, 0, 0]);
  k.cyl(C[0], 0, C[1] - 0.06, 0.08, H, FLATIRON_STONE, 8);
  for (const [p, q] of [[B, C], [C, A]] as const) wall(p, q, hex(0x2e3a44), 0.02, 0.2, 0.006);
  void b; void r;
};

const statueLiberty: Draw = (k, W, D) => {
  // Fort Wood: an eight-pointed star of granite walls, then the pedestal, then the lady
  const R = Math.min(W, D) / 2 - 0.15;
  for (const a of [0, Math.PI / 4]) k.turned(a, () => k.box(0, 0, 0, R * 1.5, 0.22, R * 1.5, GRANITE));
  k.box(0, 0.22, 0, R * 0.8, 0.12, R * 0.8, GRANITE_LIGHT);
  frustum(k, 0, 0, 0.34, 1.35, R * 0.36, R * 0.26, GRANITE_LIGHT);
  k.box(0, 1.35, 0, R * 0.6, 0.08, R * 0.6, GRANITE);
  // the robe, the shoulders, the head and its crown of rays
  const y = 1.43;
  k.cyl(0, y, 0, 0.17, 0.6, COPPER, 10, COPPER, 0.14);
  k.cyl(0, y + 0.6, 0, 0.12, 0.28, COPPER, 10);
  k.dome(0, y + 0.88, 0.01, 0.075, COPPER, 8, 3);
  for (let i = 0; i < 7; i++) {
    const a = -Math.PI * 0.4 + (i / 6) * Math.PI * 0.8;
    k.bar([0, y + 0.95, 0.02], [Math.sin(a) * 0.12, y + 1.02, 0.02 + Math.cos(a) * 0.12], 0.008, COPPER);
  }
  // the raised arm and the torch, lit all night; the tablet held on the other arm
  k.bar([0.1, y + 0.8, 0], [0.16, y + 1.28, 0.02], 0.028, COPPER);
  k.cyl(0.16, y + 1.28, 0.02, 0.035, 0.07, GOLD, 8);
  k.glowBox(0.16, y + 1.35, 0.02, 0.06, 0.07, 0.06, GOLD, BEACON, hex(0xffc040));
  k.box(-0.14, y + 0.5, 0.06, 0.05, 0.2, 0.1, COPPER);
  k.glowBox(0, 0.36, R * 0.4, 0.12, 0.04, 0.06, DARK, FLOOD, WARM_GLOW);
};

// ================================ Washington ================================

const capitolBuilding: Draw = (k, W, D, b, r) => {
  const w = W - 0.3, d = Math.min(D - 0.4, 2.0), h = 0.8;
  // the long white range: the old centre and its two wings, each wing with its own portico
  k.box(0, 0, -0.1, w, h, d * 0.6, MARBLE, MARBLE_SHADE);
  k.box(0, h, -0.1, w + 0.04, 0.05, d * 0.6 + 0.04, MARBLE_SHADE);
  for (const sx of [-1, 1]) {
    const cx = sx * w * 0.34;
    colonnade(k, cx - 0.35, cx + 0.35, d * 0.2 + 0.12, 0.12, h - 0.12, 8, MARBLE);
    k.box(cx, 0, d * 0.2 + 0.12, 0.8, 0.12, 0.3, MARBLE_SHADE);
    pediment(k, cx, h, d * 0.2 + 0.06, 0.8, 0.26, 0.16, MARBLE);
    k.box(cx, h, d * 0.2 + 0.06, 0.8, 0.02, 0.26, MARBLE);
  }
  glazed(k, b, r, 0, 0, -0.1, w, d * 0.6, 3, hex(0x6a7a86));
  // the central portico, the steps, and the dome on its colonnaded drum
  colonnade(k, -0.45, 0.45, d * 0.2 + 0.2, 0.18, h - 0.18, 8, MARBLE);
  for (let i = 0; i < 4; i++) k.box(0, 0, d * 0.2 + 0.28 + i * 0.07, 1.2 - i * 0.1, 0.18 - i * 0.045, 0.07, MARBLE_SHADE);
  pediment(k, 0, h, d * 0.2 + 0.12, 1.0, 0.3, 0.2, MARBLE);
  const dz = -0.1;
  k.cyl(0, h + 0.05, dz, 0.5, 0.35, MARBLE, 16);
  for (let i = 0; i < 20; i++) {
    const a = (i / 20) * TAU;
    k.cyl(Math.cos(a) * 0.53, h + 0.05, dz + Math.sin(a) * 0.53, 0.02, 0.35, MARBLE, 5);
  }
  k.cyl(0, h + 0.4, dz, 0.56, 0.05, MARBLE_SHADE, 16);
  k.cyl(0, h + 0.45, dz, 0.42, 0.25, MARBLE, 16);
  k.dome(0, h + 0.7, dz, 0.42, MARBLE, 16, 6);
  k.cyl(0, h + 1.1, dz, 0.07, 0.16, MARBLE, 8);
  k.dome(0, h + 1.26, dz, 0.07, MARBLE, 8, 3);
  k.box(0, h + 1.33, dz, 0.025, 0.1, 0.025, BRONZE);
  // floodlit white all night, as it is
  k.glowBox(0, h + 0.46, dz + 0.43, 0.3, 0.2, 0.01, MARBLE, FLOOD, hex(0xfff8e8));
};

const washingtonMonument: Draw = (k, W, D) => {
  const R = Math.min(W, D) / 2;
  // the lawn round the foot, the ring of flags, the shaft and its pyramidion
  k.box(0, 0, 0, R * 1.4, 0.02, R * 1.4, hex(0xd8d2c4));
  for (let i = 0; i < 16; i++) {
    const a = (i / 16) * TAU, x = Math.cos(a) * R * 0.6, z = Math.sin(a) * R * 0.6;
    k.box(x, 0, z, 0.012, 0.45, 0.012, hex(0xd8dcdc));
    k.box(x + 0.035, 0.37, z, 0.07, 0.05, 0.004, i % 2 ? hex(0xd8303a) : hex(0x2f4a8a));
  }
  frustum(k, 0, 0, 0.02, 5.6, 0.2, 0.13, MARBLE);
  k.box(0, 1.6, 0, 0.36, 0.01, 0.36, MARBLE_SHADE);  // the line where building stopped and started again
  k.cone(0, 5.6, 0, 0.18, 0.4, MARBLE, 4);
  for (const s of [-1, 1]) k.glowBox(s * 0.13, 5.45, 0, 0.02, 0.03, 0.02, hex(0xe2412f), BEACON, hex(0xff4a3a));
  k.glowBox(0, 0.02, R * 0.4, 0.1, 0.04, 0.06, DARK, FLOOD, hex(0xfff8e8));
};

const lincolnMemorial: Draw = (k, W, D) => {
  const w = Math.min(W - 0.3, 2.4), d = Math.min(D - 0.3, 1.5), h = 0.7;
  // the podium and its broad steps up from the front
  k.box(0, 0, -0.08, w + 0.1, 0.18, d, MARBLE_SHADE);
  for (let i = 0; i < 4; i++) k.box(0, 0, d / 2 - 0.08 + i * 0.06, w * 0.6, 0.18 - i * 0.045, 0.06, MARBLE_SHADE);
  // the chamber, the peristyle of columns all the way round, the attic with its frieze
  k.box(0, 0.18, -0.08, w - 0.4, h, d - 0.4, MARBLE);
  colonnade(k, -w / 2 + 0.08, w / 2 - 0.08, d / 2 - 0.12, 0.18, h, 12, MARBLE);
  colonnade(k, -w / 2 + 0.08, w / 2 - 0.08, -d / 2 - 0.04, 0.18, h, 12, MARBLE);
  for (const sx of [-1, 1]) colonnadeZ(k, -d / 2 - 0.04, d / 2 - 0.12, sx * (w / 2 - 0.08), 0.18, h, 5, MARBLE);
  k.box(0, 0.18 + h, -0.08, w, 0.08, d, MARBLE_SHADE);
  k.box(0, 0.26 + h, -0.08, w - 0.2, 0.14, d - 0.2, MARBLE);
  for (let i = 0; i < 12; i++) k.box(-w / 2 + 0.2 + i * ((w - 0.4) / 11), 0.3 + h, d / 2 - 0.17, 0.05, 0.04, 0.01, hex(0xb8b4aa));
  // Lincoln in his chair, lit within after dark
  k.box(0, 0.18, -0.08, 0.3, 0.4, 0.24, MARBLE_SHADE);
  k.glowBox(0, 0.2, d / 2 - 0.3, w - 0.5, 0.5, 0.01, MARBLE, FLOOD, hex(0xfff0d0));
};

const whiteHouse: Draw = (k, W, D) => {
  const w = Math.min(W - 1.4, 2.2), d = Math.min(D - 1.0, 1.1), h = 0.72;
  // the lawn to the fence along the front, with the fountain in the middle of it
  for (let x = -W / 2 + 0.15; x <= W / 2 - 0.15; x += 0.12) k.box(x, 0, D / 2 - 0.1, 0.012, 0.16, 0.012, DARK);
  k.cyl(0, 0, D / 2 - 0.55, 0.22, 0.04, MARBLE_SHADE, 12);
  k.cyl(0, 0.04, D / 2 - 0.55, 0.19, 0.005, WATER, 12);
  // the house: its balustraded roof, its windows, the north portico and the round south one
  k.box(0, 0, -0.1, w, h, d, MARBLE, MARBLE_SHADE);
  k.box(0, h, -0.1, w + 0.04, 0.05, d + 0.04, MARBLE_SHADE);
  k.box(0, h + 0.05, -0.1, w, 0.06, d, MARBLE);
  for (let i = 0; i < 9; i++) for (const y of [0.12, 0.42]) {
    k.box(-w / 2 + 0.14 + i * ((w - 0.28) / 8), y, -0.1 + d / 2 + 0.005, 0.08, 0.16, 0.01, hex(0x3a4450));
  }
  colonnade(k, -0.3, 0.3, d / 2 + 0.12 - 0.1, 0, h, 4, MARBLE);
  pediment(k, 0, h, d / 2 + 0.02 - 0.1, 0.72, 0.28, 0.16, MARBLE);
  for (let i = 0; i < 6; i++) {
    const a = Math.PI + (i / 5) * Math.PI;
    k.cyl(Math.cos(a) * 0.36, 0, -0.1 - d / 2 + Math.sin(a) * 0.3, 0.03, h, MARBLE, 6);
  }
  k.cyl(0, h, -0.1 - d / 2, 0.38, 0.05, MARBLE_SHADE, 12);
  // the low wings either side, and the flag over the middle
  for (const sx of [-1, 1]) k.box(sx * (w / 2 + 0.45), 0, -0.1, 0.9, 0.34, d * 0.55, MARBLE, MARBLE_SHADE);
  k.box(0, h + 0.11, -0.1, 0.012, 0.3, 0.012, hex(0xd8dcdc));
  for (let i = 0; i < 3; i++) k.box(0.05, h + 0.35 - i * 0.025, -0.1, 0.1, 0.02, 0.004, i % 2 ? WHITE : hex(0xd8303a));
  k.box(0.02, h + 0.34, -0.1, 0.04, 0.03, 0.006, hex(0x2f4a8a));
  k.glowBox(0, 0.02, d / 2 + 0.3, 0.1, 0.04, 0.06, DARK, FLOOD, hex(0xfff8e8));
};

const jeffersonMemorial: Draw = (k, W, D) => {
  const R = Math.min(W, D) * 0.2, cz = -D * 0.12;
  // the tidal basin in front, the cherry trees round it
  k.box(0, 0, D / 2 - 0.55, W - 0.5, 0.012, 0.8, WATER);
  for (let i = 0; i < 7; i++) {
    const x = -W / 2 + 0.35 + i * ((W - 0.7) / 6), z = D / 2 - 0.12;
    k.cyl(x, 0, z, 0.02, 0.14, hex(0x5a4030), 5);
    k.dome(x, 0.12, z, 0.15, BLOSSOM, 8, 3);
  }
  for (const sx of [-1, 1]) for (const z of [cz - R, cz]) {
    k.cyl(sx * (W / 2 - 0.3), 0, z, 0.02, 0.14, hex(0x5a4030), 5);
    k.dome(sx * (W / 2 - 0.3), 0.12, z, 0.15, BLOSSOM, 8, 3);
  }
  // the terraced podium, the ring of columns, the shallow dome and the portico to the water
  k.cyl(0, 0, cz, R + 0.3, 0.1, MARBLE_SHADE, 20);
  k.cyl(0, 0.1, cz, R + 0.15, 0.08, MARBLE_SHADE, 20);
  for (let i = 0; i < 18; i++) {
    const a = (i / 18) * TAU;
    k.cyl(Math.cos(a) * R, 0.18, cz + Math.sin(a) * R, 0.035, 0.62, MARBLE, 6);
  }
  k.cyl(0, 0.8, cz, R + 0.06, 0.1, MARBLE, 20);
  k.cyl(0, 0.9, cz, R * 0.92, 0.08, MARBLE_SHADE, 20);
  k.dome(0, 0.98, cz, R * 0.9, MARBLE, 20, 5);
  colonnade(k, -R * 0.6, R * 0.6, cz + R + 0.18, 0.18, 0.62, 6, MARBLE);
  k.box(0, 0.8, cz + R + 0.14, R * 1.4, 0.08, 0.3, MARBLE);
  pediment(k, 0, 0.88, cz + R + 0.14, R * 1.4, 0.3, 0.18, MARBLE);
  for (let i = 0; i < 4; i++) k.box(0, 0, cz + R + 0.36 + i * 0.06, R * 1.2, 0.18 - i * 0.045, 0.06, MARBLE_SHADE);
  // Jefferson standing within, and the lamps along the basin
  k.box(0, 0.18, cz, 0.08, 0.3, 0.08, BRONZE);
  k.glowBox(0, 0.3, cz, R * 0.5, 0.4, R * 0.5, MARBLE, FLOOD, hex(0xfff0d0));
  void LAWN;
};

